window.WALWIL={"updated": "2026-11-26", "updatedKR": "2026년 11월 26일", "updatedEN": "26 November 2026", "total": 237, "top": [{"date": "2026-11-26", "tag": "WWL 항로", "tagEN": "WWL network", "k": "WWL, 2027년 일본→오세아니아 로로 서비스 중단 — 선복 압박에 따른 네트워크 재편", "e": "WWL suspends Japan-Oceania RoRo for 2027 - network reshaped under capacity pressure", "url": "https://rnz.co.nz/news/business/2788927/why-buying-a-used-ev-could-get-harder-next-year"}, {"date": "2026-11-25", "tag": "호르무즈", "tagEN": "Hormuz", "k": "이란, 호르무즈 남쪽 통항로 이용 선박 지원 예인선 26척 블랙리스트 — 걸프 항만 예인 지연 대비", "e": "Iran blacklists 26 tugs that assisted ships on the southern Hormuz route - plan for tug delays in Gulf ports", "url": "https://safety4sea.com/iran-adds-26-tugboats-to-strait-of-hormuz-blacklist/"}, {"date": "2026-11-24", "tag": "미 서부 황천", "tagEN": "US West storm", "k": "미 서부 오리건·북캘리포니아 연안 폭풍 경보 — 파고 7~8.5m, 25일 오후까지; 타코마·포틀랜드 입출항 자동차선 고박·입항 시각 점검", "e": "Storm warnings off Oregon/N. California - seas 23-28 ft until 25 Nov afternoon; check lashings and arrival times for car carriers bound for Tacoma/Portland", "url": "https://govonestop.com/nws/moderate-hazardous-seas-warning-effective-11242026-0046-0"}, {"date": "2026-11-23", "tag": "영국 ETS", "tagEN": "UK ETS", "k": "영국·EU 배출권거래제 연계 — 2028년부터 영국 탄소가격이 국제 해운까지, 영국 기항 자동차선 비용 영향 점검", "e": "UK-EU ETS link - UK carbon pricing extends to international shipping from 2028; check the cost impact on UK calls", "url": "https://safety4sea.com/"}, {"date": "2026-11-22", "tag": "보안", "tagEN": "Security", "k": "핀란드만 러시아 화물선 Sparta II 무인기 피격·밤새 화재(16명 대피), 벵가지항에선 무인 수상정 공격 — 발트해·지중해 항만도 위험 해역, 선장 지침·전쟁위험 보험 점검", "e": "Drones hit Russian cargo ship Sparta II in the Gulf of Finland (16 evacuated) and USVs strike in Benghazi - Baltic and Mediterranean ports are now risk areas; check masters' instructions and war-risk cover", "url": "https://gcaptain.com/russian-cargo-ship-still-on-fire-off-finland-after-attack/"}, {"date": "2026-11-22", "tag": "신조", "tagEN": "Newbuilds", "k": "Singapore Shipping Corp, 7,000 CEU LNG 자동차선 2척 약 2억 1,000만 달러 발주(2척 옵션) — 비운항 선주의 LNG 자동차선 신조 확산", "e": "Singapore Shipping Corp orders two 7,000 CEU LNG car carriers for about USD 210 million with two options - LNG car carrier newbuilds spread to non-operating owners", "url": "https://www.theedgesingapore.com/news/contracts/singapore-shipping-corp-orders-two-new-car-carriers-us210-mil-may-add-another-two"}, {"date": "2026-11-20", "tag": "서비스", "tagEN": "Services", "k": "Wallenius Wilhelmsen, 2027년 일본발 호주·뉴질랜드·피지·뉴칼레도니아 서비스 중단 확인 — '로로 선복 압박으로 정시성 보장 불가'", "e": "Wallenius Wilhelmsen confirms 2027 suspension of Japan-Australia, New Zealand, Fiji and New Caledonia services - 'RoRo capacity pressure means reliability cannot be assured'", "url": "https://autotalk.co.nz/wallenius-wilhelmsen-confirms-2027-japan-oceania-suspension/"}, {"date": "2026-11-20", "tag": "선대", "tagEN": "Fleet", "k": "현대글로비스 PCTC 96척→2029년 말 139척, 세계 PCTC 800척 중 200척이 25년 초과 — 노후선 연장 운항과 신조 인수를 같은 기간에 계획", "e": "Hyundai Glovis PCTCs to grow from 96 to 139 by end-2029 while 200 of 800 PCTCs are over 25 - plan life extension and newbuild take-overs together", "url": "https://www.fnnews.com/news/202611200829194982"}], "groups": [{"code": "FLEET", "kTitle": "신조·선대", "eTitle": "Newbuildings & Fleet", "items": [{"code": "FLEET", "date": "2026-11-25", "src": "Riviera", "title": "회그 오토라이너스 첫 암모니아 추진 9,100CEU PCTC용 이중구(bilobe) Type C 연료탱크 조선소 인도 — 길이 40.5m, TGE 연료공급장치·7S60ME-LGIA 엔진", "eTitle": "Engine and Bilobe Fuel Tank Delivered for Höegh Autoliners' First Ammonia-Fuelled 9,100 CEU PCTC - 40.5 m IMO Type C Tank, TGE Fuel Gas Supply", "kSum": "회그 오토라이너스의 첫 암모니아 추진 9,100CEU급 PCTC에 설치할 이중구(bilobe) IMO Type C 연료탱크가 11월 11일 중국 CMHI 장쑤 조선소에 인도됐다고 Riviera가 11월 25일 전했다. 탱크는 길이 40.5m, 폭 13m, 높이 8m로 시내버스 세 대를 이은 것보다 길다. 암모니아 연료가스 공급장치(AFGSS)는 TGE Marine이 공급하며, 이 선박은 Everllence B&W 7S60ME-LGIA 이중연료 엔진을 다는 Aurora급 4척 가운데 첫 척이다. 앞선 8척은 DNV '암모니아 레디' 표기를 받았다.", "eSum": "A bilobe IMO Type C fuel tank (40.5 m x 13 m x 8 m) was delivered on 11 November to CMHI Jiangsu for Höegh Autoliners' first ammonia-fuelled 9,100 CEU PCTC, Riviera reported on 25 November; TGE Marine supplies the ammonia fuel gas supply system, and it is the first of four Aurora-class ships with Everllence B&W 7S60ME-LGIA dual-fuel engines; the first eight carry DNV ammonia-ready notations.", "kImp": "암모니아 PCTC가 실제 건조 단계에 들어섰다. 독성 연료 취급 교육·누출 대응·PPE 기준을 신조 관리 계획에 넣을 준비를 시작할 것.", "eImp": "Ammonia PCTCs are now under construction. Start preparing toxic-fuel training, leak response and PPE standards for newbuilding management plans.", "url": "https://rivieramm.com/news-content-hub/engine-and-bilobe-fuel-tank-delivered-for-hoegh-autoliners-historic-ammonia-fuelled-car-carrier-90691", "prio": 2}, {"code": "FLEET", "date": "2026-11-26", "src": "Splash247·Baird Maritime", "title": "암모니아 추진 자동차운반선 4척과 연료 공급망 — '누가 비용을 대나' 문제 제기; 일본 7개사, 2030년 인도 목표", "eTitle": "Four Ammonia Car Carriers and a Fuel Chain - but Who Signs the Cheque? Seven Japanese Companies Target 2030 Delivery", "kSum": "Splash247은 11월 26일 기고에서 일본의 암모니아 추진 자동차운반선 4척과 연료 공급망 구상을 두고 비용을 누가 부담할지 질문을 던졌다. Baird Maritime에 따르면 일본 7개사는 10월 27일 주부 지역 중심의 암모니아 연료 공급망을 구축하고 암모니아 연료 자동차운반선 4척을 건조하기로 합의했으며, 4척 모두 2030년 완공 예정이다. 신쿠루시마조선이 기본설계를 맡고 이마바리조선·일본조선소가 공동 설계·건조에 참여하며, 연료탱크는 암모니아만으로 태평양을 횡단할 수 있는 크기다. 안전장치로 누출 방지·감지와 누출 시 중화 설비를 갖춘다.", "eSum": "A Splash247 contribution on 26 November asks who will pay for Japan's four ammonia-fuelled car carriers and their fuel chain. Baird Maritime reported that seven Japanese companies agreed on 27 October to build four ammonia-fuelled car carriers, all due in 2030, and an ammonia supply chain centred on the Chubu region; Shin Kurushima leads basic design with Imabari and Nihon Shipyard, tanks are sized for trans-Pacific voyages on ammonia alone, and safety systems include leak prevention, detection and neutralisation.", "kImp": "암모니아 추진 PCTC는 독성 연료 관리라는 새 역량을 요구한다. 향후 관리 대상이 될 수 있는 만큼 암모니아 누출 대응, 개인보호장비, 승무원 교육 기준(IGF 개정 동향)을 미리 파악해 둘 것.", "eImp": "Ammonia PCTCs require a new competence in toxic-fuel handling. Track ammonia leak response, PPE and crew training standards (IGF developments) ahead of possible management.", "url": "https://bairdmaritime.com/shipping/dry-cargo/pcc-pctc/ammonia-fuelled-car-carriers-2030", "prio": 3}, {"code": "FLEET", "date": "2026-11-22", "src": "The Edge Singapore·MiniChart", "title": "싱가포르 Singapore Shipping Corp, 7,000 CEU급 LNG 추진 자동차운반선 2척 발주 — 약 2억 1,000만 달러, 2척 추가 옵션", "eTitle": "Singapore Shipping Corp Orders Two 7,000 CEU LNG-Fuelled Car Carriers for About USD 210 Million, With an Option for Two More", "kSum": "싱가포르 증시 상장사 Singapore Shipping Corporation(SingShipping)이 7,000 CEU급 LNG 추진 자동차운반선(PCTC) 2척을 약 2억 1,000만 달러에 발주했고, 2척을 더 발주할 수 있다고 현지 매체들이 11월 22일 전했다. 일부 보도는 신조선 2척 매입 대금을 1억 8,700만 달러로 적고, 싱가포르거래소(SGX)로부터 관련 규정 적용을 면제받았다고 전했다. 건조 조선소와 인도 시기는 검색 결과 요약에 나오지 않았다.", "eSum": "Singapore-listed Singapore Shipping Corporation (SingShipping) has ordered two 7,000 CEU LNG-fuelled pure car and truck carriers for about USD 210 million and may add two more, local outlets reported on 22 November. One report puts the purchase price of the two newbuildings at USD 187 million and says the company obtained a waiver from the Singapore Exchange. The yard and delivery dates were not given in the search summaries.", "kImp": "소형 상장 선주까지 LNG 추진 자동차선 신조에 들어온다. 선박관리사는 비운항 선주의 신조 발주를 신조 감독·LNG 연료 계통 운영 수요로 보고, 해당 선형의 기술관리 제안을 준비할 것.", "eImp": "Even small listed owners are now ordering LNG-fuelled car carriers. Managers should read non-operating owners' newbuild orders as demand for site supervision and LNG fuel system operation, and prepare technical management proposals for the type.", "url": "https://www.theedgesingapore.com/news/contracts/singapore-shipping-corp-orders-two-new-car-carriers-us210-mil-may-add-another-two", "prio": 2}, {"code": "FLEET", "date": "2026-11-18", "src": "New-Ships.com", "title": "1만 800 CEU LNG 이중연료 'Glovis Noble' 계약보다 4개월 일찍 인도 — 한국해양진흥공사 소유, 6척 용선 패키지의 두 번째", "eTitle": "10,800 CEU LNG Dual-Fuel Glovis Noble Delivered Four Months Early - Owned by KOBC, the Second of a Six-Ship Charter Package", "kSum": "중국 상하이 와이가오차오조선(SWS)이 1만 800 CEU급 LNG 이중연료 자동차운반선 Glovis Noble을 계약보다 4개월 앞당겨 한국해양진흥공사에 인도했다. 현대글로비스가 용선해 운항하며, 주기관은 LNG와 일반 선박유를 모두 쓰는 Everllence B&W 8S60ME-C GI다. 이 선박은 6척 용선 패키지(Seaspan 4척, 한국해양진흥공사 2척)의 두 번째 배로, 건조는 SWS와 광저우조선(GSI)이 나눠 맡았다. 첫 한국해양진흥공사 선박 Glovis Nova는 7월 GSI에서 인도됐다.", "eSum": "Shanghai Waigaoqiao Shipbuilding delivered the 10,800 CEU LNG dual-fuel car carrier Glovis Noble to Korea Ocean Business Corporation four months ahead of schedule. Hyundai Glovis will operate it on charter; the main engine is an Everllence B&W 8S60ME-C GI able to burn LNG or conventional fuel. It is the second of six ships in a charter package (four for Seaspan, two for KOBC), with construction split between SWS and Guangzhou Shipyard International. The first KOBC ship, Glovis Nova, was delivered by GSI in July.", "kImp": "중국 조선소의 조기 인도가 잇따르며 인수 일정이 앞당겨진다. 선박관리사는 신조 인수 계획에 조기 인도 시나리오를 넣고, LNG 이중연료 주기관 경험 사관을 미리 확보할 것.", "eImp": "Early deliveries from Chinese yards keep pulling take-over dates forward. Managers should build an early-delivery scenario into take-over plans and secure officers experienced on dual-fuel LNG engines in advance.", "url": "https://new-ships.com/ns/news/7932", "prio": 2}, {"code": "FLEET", "date": "2026-11-19", "src": "쉬핑뉴스넷", "title": "세계 최대 1만 800 CEU급 LNG 이중연료 자동차운반선 명명 — 상하이 와이가오차오조선 건조, 척당 1억 2,500만 달러. 2028년까지 21척 인도 계획", "eTitle": "The World's Largest Car Carrier Class, 10,800 CEU and LNG Dual-Fuel, Is Named - Built at Shanghai Waigaoqiao at USD 125 Million a Ship; 21 to Be Delivered by 2028", "kSum": "자동차 1만 대 이상을 싣는 현존 최대 규모인 1만 800 CEU급 LNG 이중연료 자동차운반선의 명명식이 11월 16일 중국 상하이 와이가오차오조선소에서 열렸다. 선주는 한국해양진흥공사이고 국내 자동차선사가 운항한다. 증권가 참석기에 따르면 같은 계획의 선박이 2026년 8척, 2027년 10척, 2028년 나머지 3척 인도될 예정이며 척당 가격은 1억 2,500만 달러다. 운항사는 중국발 완성차 수출 증가를 자동차선 사업의 성장 기회로 보고 있다.", "eSum": "A naming ceremony was held at Shanghai Waigaoqiao Shipbuilding on 16 November for a 10,800 CEU LNG dual-fuel car carrier, the largest class afloat with room for more than 10,000 cars. The owner is Korea Ocean Business Corporation and a Korean car carrier operator will run it. According to a brokerage analyst who attended, ships in the programme are due eight in 2026, ten in 2027 and the remaining three in 2028, at USD 125 million each. The operator sees rising vehicle exports from China as a growth opportunity for its car carrier business.", "kImp": "1만 CEU가 넘는 초대형선이 2년 사이 20척 넘게 나온다. 자동차선 관리사는 초대형 자동차선의 접안 가능 부두와 램프 하중, 풍압에 따른 예인선 소요, LNG 연료 계통 자격 선원 확보를 인수 준비 항목으로 잡을 것.", "eImp": "More than 20 ships of over 10,000 CEU arrive within two years. Car carrier managers should plan take-over around which berths can accept them, ramp loads, tug needs given windage and crew qualified for LNG fuel systems.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=73104", "prio": 3}, {"code": "FLEET", "date": "2026-11-19", "src": "gCaptain", "title": "미국 ARC, 미국 선적 자동차·트럭운반선 ARC United 추가 — 약 8,000 CEU·갑판 13층·선미 램프 320톤, 해사안보프로그램(MSP)에서 퇴역선 대체", "eTitle": "ARC Adds the US-Flag Car and Truck Carrier ARC United - Nearly 8,000 CEU, 13 Decks and a 320-Tonne Stern Ramp, Replacing a Retiring Ship in the Maritime Security Program", "kSum": "미국 로로 선사 American Roll-On/Roll-Off Carrier Group(ARC)이 길이 757피트의 대형 자동차·트럭운반선 ARC United(IMO 9505053)를 미국 선적 선대에 넣었다. 갑판은 13층이고 그중 5층은 높이를 조절할 수 있으며 약 8,000 CEU를 싣는다. 선미 램프는 320톤까지 견뎌 육상 크레인 없이 중장비를 싣고 내린다. 이 배는 전시·비상시 군 해상 수송에 쓰이는 연방 해사안보프로그램(MSP)에 들어가며, 퇴역하는 ARC Resolve를 대체한다. 대형 군용 항공기를 실을 수 있는 ARC의 아홉 번째 선박이다.", "eSum": "American Roll-On/Roll-Off Carrier Group has added the 757-foot large car and truck carrier ARC United (IMO 9505053) to its US-flag fleet. It has 13 cargo decks, five of them hoistable, capacity for nearly 8,000 CEU and a stern ramp rated for rolling loads of up to 320 tonnes, so heavy equipment can be worked without shore cranes. The ship enters the federal Maritime Security Program, which keeps commercial US-flag ships available for military sealift, replacing the retiring ARC Resolve. It is ARC's ninth ship able to carry large military aircraft.", "kImp": "기존 대형 자동차선이 국적을 바꿔 미국 선적으로 들어가는 흐름이 이어진다. 자동차선 관리사는 국적 변경 선박의 인수 때 기국 검사 체계와 선원 국적 요건, 고하중 램프·가동 갑판의 정비 이력을 먼저 확인할 것.", "eImp": "Existing large car carriers continue to reflag into the US fleet. When taking over a reflagged ship, car carrier managers should first check the flag's inspection regime, crew nationality rules and the maintenance history of heavy ramps and hoistable decks.", "url": "https://gcaptain.com/arc-adds-another-u-s-flag-ro-ro-ship-to-strengthen-military-sealift-capacity/", "prio": 2}, {"code": "FLEET", "date": "2026-11-04", "src": "Wallenius Wilhelmsen (Q3 report)", "title": "WW 3분기 보고서의 선대 변화: 129척 유지·자사선 93척, 리스선 1척 구매옵션 행사, 29년 된 7,900CEU 선박 제3자 매각(약 4천만 달러 이익), 정부부문 이전 추가 1척", "eTitle": "WW's Q3 Report Shows Fleet Moves: 129 Ships With 93 Owned, a Purchase Option Declared on a Leased Ship, a 29-Year-Old 7,900 CEU Ship Sold to a Third Party for an Expected USD 40m Gain and One More Ship Moving to Government Services", "kSum": "통제 선대는 129척(해운 118·정부 11)으로 전분기와 같지만 자사선이 91척에서 93척으로 늘었다 — 리스선 1척(약 15년, 7,600CEU)의 구매옵션을 행사해 자사선으로 바꿨고 장기용선은 1척, 단기용선은 1척(2척으로) 줄었다(보고서 본문 35척·표 34척으로 불일치). 3분기에 1척을 해운에서 정부서비스 부문으로 넘겼고(부문 이익 1,700만 달러, 그룹 내 상계) 4분기에 1척을 더 넘기며, 선령 29년 7,900CEU 선박 1척을 제3자에 팔아 4분기 인도 때 약 4,000만 달러 이익을 예상한다(장부가 1,200만 달러). 셰이퍼급은 13척이 건조 중이며 로열 턴(10/20 인도)을 포함해 4분기 2척 인도 예정이고 잔여 신조 capex는 12억 달러다; 2027~2031년 구매옵션·의무가 총 12척(2027년 2척, 2028년 2척, 2029년 4척, 2030년 2척, 2031년 2척) 있다. 업계 발주잔량은 3분기 49척 추가 발주로 선대 대비 26.4%(189척)로 높아졌고 회사는 신규 발주는 2030년 이전 인도가 어렵다고 봤다.", "eSum": "The controlled fleet stayed at 129 ships (118 Shipping, 11 Government) but owned tonnage rose from 91 to 93: a purchase option was declared on a leased ship (about 15 years old, 7,600 CEU), while long-term charters fell by one (the report says 35 in the text and 34 in the table) and short-term charters by one to two. One ship moved from Shipping to Government services in Q3 (a USD 17m segment gain eliminated at group level) and another will follow in Q4, while a 29-year-old 7,900 CEU ship has been sold to a third party for delivery in Q4 at an expected gain of about USD 40m against a USD 12m book value. Thirteen Shaper Class ships are under construction, with two deliveries in Q4 including Royal Tern on 20 October, and USD 1.2bn of newbuild capex remains; purchase options and obligations cover 12 ships from 2027 to 2031 (2, 2, 4, 2 and 2 a year). The industry orderbook climbed to 26.4% of the fleet (189 ships) after 49 orders in Q3, and the company says new orders are unlikely to deliver before 2030.", "kImp": "노후선 매각·정부부문 이전과 구매옵션 행사가 겹치면서 선박 인수인계(소유·기국·관리 변경)가 4분기~2027년에 이어질 수 있어 선박관리사는 인수인계 점검·문서 이관 절차를 미리 준비할 필요가 있다.", "eImp": "Ageing-ship sales, transfers to Government services and declared purchase options point to a run of vessel handovers (ownership, flag or management changes) from Q4 into 2027, so ship managers should prepare take-over and hand-over inspection and document-transfer routines early.", "url": "https://www.walleniuswilhelmsen.com/storage/downloads/Wallenius-Wilhelmsen-Quarterly-report-Q3-2026.pdf", "prio": 3}, {"code": "FLEET", "date": "2026-10-30", "src": "MacGregor (PR Newswire)", "title": "맥그리거, 왈레니우스 윌헬름센 PCTC 35척의 쿼터 램프 PLC 개조 수주…운항 일정 맞춰 순차 시행, 교체 PLC는 선내 예비품으로", "eTitle": "MacGregor Wins PLC Retrofit Projects for the Quarter Ramps of 35 Wallenius Wilhelmsen PCTCs, to Be Carried Out Around Each Ship's Sailing Schedule", "kSum": "맥그리거(MacGregor)는 10월 30일 왈레니우스 윌헬름센(WW)의 순수 자동차·트럭 운반선(PCTC) 35척에 대한 PLC(프로그래머블 로직 컨트롤러) 개조 프로젝트를 수주했다고 발표했다. 선박 쿼터 램프(quarter ramp)의 제어 PLC를 업그레이드하는 작업으로, 각 선박의 운항 일정과 가용 시점에 맞춰 진행되며 계약 금액은 공개되지 않았고 맥그리거의 2026년 3분기 수주에 반영됐다. 교체된 기존 PLC는 선내에 보관해 남은 RoRo 장비나 같은 장비를 쓰는 다른 선박의 예비품으로 쓰며, 맥그리거는 이들 선박의 설계·신조 단계에서 장비를 공급했다. WW 기술해양운항관리 부문의 톰 포레스터-콜스(Tom Forrester-Coles) 선대 매니저는 단종(obsolescence) 관리와 시스템 최신화로 운항 차질을 줄이고 고객에게 높은 신뢰성을 제공하겠다고 말했다.", "eSum": "MacGregor said on 30 October it has received PLC (programmable logic controller) retrofit projects for 35 Wallenius Wilhelmsen pure car and truck carriers. The work upgrades the PLCs of the ships' quarter ramps and will be scheduled around each vessel's sailing programme and availability; the value was not disclosed and the order was booked in MacGregor's Q3 2026 order intake. The replaced PLCs will be kept on board as spares for the remaining RoRo equipment or for other vessels with the same equipment, and MacGregor supplied the equipment when the ships were designed and built. Tom Forrester-Coles, Fleet Manager in WW's Technical Marine Operations Management, tied the project to obsolescence management and keeping systems up to date in order to reduce operational disruptions and keep reliability high for customers.", "kImp": "쿼터 램프는 하역의 핵심 설비여서 제어 PLC가 단종되면 고장 때 예비품을 구하기 어려워 하역 중단과 안전 위험으로 번질 수 있다. 35척 일괄 개조는 노후 선대의 제어계통 단종 관리를 운항 일정에 맞춰 계획적으로 처리하는 사례로, 선박관리사는 개조 시기와 계획정비 일정, 작업 후 기능시험·승무원 숙지 교육, 보관 PLC 예비품 관리를 함께 챙길 필요가 있다.", "eImp": "The quarter ramp is central to cargo operations, and once its control PLC becomes obsolete a fault can mean a long outage because spares are hard to find, halting cargo work and creating safety risk. Retrofitting 35 ships as one programme shows obsolescence of ageing control systems being managed around trading schedules; ship managers should align the work with planned maintenance, post-retrofit function tests, crew familiarisation and control of the retained PLC spares.", "url": "https://www.prnewswire.com/news-releases/macgregor-to-retrofit-plcs-on-35-vessels-for-wallenius-wilhelmsen-302924756.html", "prio": 2}, {"code": "FLEET", "date": "2026-10-28", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "WalWil, 中 진링조선에 9,900CEU급 LNG 이중연료 PCTC 4척 확정 발주…2031~32년 옵션 8척 포함 최대 12척·약 15억 달러, 신조 프로그램 26척", "eTitle": "Wallenius Wilhelmsen Orders Four 9,900 CEU LNG Dual-Fuel PCTCs at China's Jinling Shipyard for Delivery From Mid-2030, With Options for Eight More in 2031-32 and Capex of About USD 1.5bn", "kSum": "WalWil은 10월 28일 중국 장쑤성 진링조선소에 9,900CEU급 LNG 이중연료 자동차운반선(PCTC) 4척을 발주하고 2031년 4척·2032년 4척 등 최대 8척의 옵션을 확보했다고 공시했다. 확정 4척은 2030년 중반부터 인도되며, 옵션을 모두 행사하면 총 투자비(capex)는 약 15억 달러이고 2023년 시작한 셰이퍼급 선대 교체 프로그램은 옵션 포함 26척이 된다. 10월 초 3억 달러 사모발행에 이은 결정으로, 자비에 르루아(Xavier Leroi) 해운서비스 COO는 '고객과 함께 계속 성장하기 위해 지금 투자한다'고 밝혔다. Shippax에 따르면 신조선은 CMS 진링 이정(Yizheng) 야드에서 건조되는 개량 셰이퍼급으로, 길이 228m·폭 38m에 아틱 턴(9,300CEU)보다 1개 많은 13개 카데크와 Everllence B&W 7S60ME-C GI 이중연료 주기관을 갖춘다.", "eSum": "Wallenius Wilhelmsen announced on 28 October that it has ordered four 9,900 CEU LNG dual-fuel PCTCs at Jinling Shipyard in Jiangsu, China, and secured options for up to eight more, four for 2031 and four for 2032. The firm ships deliver from mid-2030, total capex is expected at about USD 1.5bn if all options are exercised, and the Shaper Class fleet renewal programme launched in 2023 now totals 26 vessels including options. The order follows the USD 300m private placement earlier in October, and Xavier Leroi, COO Shipping Services, said the company is 'investing now to ensure we can continue to grow with our customers'. Shippax reports the ships are a modified Shaper design to be built at CMS Jinling's Yizheng yard, measuring 228 m by 38 m with 13 car decks, one more than the 9,300 CEU Arctic Tern, and an Everllence B&W 7S60ME-C GI dual-fuel main engine.", "kImp": "그룹 신조 선대는 메탄올 이중연료(9,300CEU 7척)와 LNG 이중연료(11,700CEU 7척, 9,900CEU 최대 12척)로 나뉘어 2032년까지 인도가 이어진다. 두 연료 체계를 모두 다룰 IGF Code 자격 선원 양성과 LNG 벙커링 절차·위험성평가를 인도 일정에 맞춰 단계적으로 준비해야 한다.", "eImp": "The group's newbuild fleet will split between methanol dual-fuel (seven 9,300 CEU ships) and LNG dual-fuel (seven 11,700 CEU ships and up to 12 of 9,900 CEU), with deliveries running to 2032. Ship managers should build IGF Code-qualified crews able to handle both fuels and prepare LNG bunkering procedures and risk assessments in step with the delivery schedule.", "url": "https://newsweb.oslobors.no/message/684950", "prio": 3}, {"code": "FLEET", "date": "2026-10-28", "src": "Shippax", "title": "WW 신조 9,900CEU 4척 사양 공개: CMS 진링 이정(Yizheng) 야드 건조, 228×38m·차량 갑판 13층, LNG 이중연료 B&W 7S60ME-C GI 주기관", "eTitle": "Shippax Details WW's New 9,900 CEU PCTCs: Built at CMS Jinling's Yizheng Yard, 228 x 38 m With 13 Car Decks and an LNG Dual-Fuel Everllence B&W 7S60ME-C GI Main Engine", "kSum": "Shippax에 따르면 WW가 10월 28일 확정 발주한 4척은 중국 장쑤성 China Merchants Shipbuilding Jinling의 이정(Yizheng) 야드에서 건조되며 2030년 중반부터 인도된다. 길이 228.0m·폭 38.0m의 개량 셰이퍼급 설계로 적재능력은 9,900CEU이며, 최근 인도된 아틱 턴(9,300CEU, 87,688GT)의 근접 자매선이지만 차량 갑판이 12층에서 13층으로 늘었다. LNG 탱크와 Everllence(옛 MAN Energy Solutions) B&W 7S60ME-C GI 이중연료 주기관을 탑재한다. 4척씩 두 차례의 옵션(2031·2032년 인도)을 모두 행사하면 시리즈는 12척, 기존 14척을 포함한 신조 프로그램은 2032년까지 26척이 된다.", "eSum": "According to Shippax, the four PCTCs Wallenius Wilhelmsen firmly ordered on 28 October will be built at China Merchants Shipbuilding Jinling's Yizheng yard in Jiangsu, with deliveries from mid-2030. The modified Shaper Class design measures 228.0 m by 38.0 m with an intake of 9,900 CEU; the ships will be close sisters of the recently delivered Arctic Tern (9,300 CEU, 87,688 GT) but with 13 car decks instead of 12. They will have LNG tanks and an Everllence B&W 7S60ME-C GI dual-fuel main engine. Two options for four ships each, for 2031 and 2032 delivery, could take the series to 12 and the whole newbuilding programme, including the current 14 ships, to 26 by 2032.", "kImp": "메탄올 이중연료인 셰이퍼급 14척과 달리 이번 시리즈는 LNG(고압 가스분사 ME-GI) 연료여서, 그룹 선대는 메탄올·LNG 두 가지 대체연료 체계를 함께 운영하게 된다. 선박관리 측면에서는 2030년 첫 인도 전에 IGF Code 기반 LNG 벙커링·가스 안전 절차와 IGF 교육을 이수한 선원 확보 계획을 미리 준비할 필요가 있다.", "eImp": "Unlike the 14 methanol dual-fuel Shaper Class ships, this series burns LNG through high-pressure gas injection (ME-GI), so the group fleet will run two alternative-fuel systems side by side. Ship managers should prepare IGF Code LNG bunkering and gas-safety procedures and a pool of IGF-trained crew well before the first delivery in 2030.", "url": "https://www.shippax.com/en/news/wwl-confirms-new-contracts-with-cms-jinling.aspx", "prio": 2}, {"code": "FLEET", "date": "2026-10-20", "src": "Baird Maritime", "title": "EUKOR용 셰이퍼급 2번선 '로열 턴' 인도…진링 메탄올선 7척 중 2번째, 잔여 5척 2027년 4분기까지", "eTitle": "Wallenius Wilhelmsen Takes Delivery of Royal Tern, the Second Methanol Dual-Fuel Shaper Class PCTC, for Operation by EUKOR", "kSum": "왈레니우스 윌헬름센이 중국 CMHI 진링에서 셰이퍼급 2번선 '로열 턴(Royal Tern)'을 인수했으며 자회사 EUKOR가 운항한다. 9,300CEU·87,700GT, 길이 228m·폭 38m, 12개 데크(가동 4개), 선미램프 SWL 480톤, 항해속력 17.4노트, 메탄올 이중연료(암모니아 전환 대비)에 마셜제도 기국이며 공기윤활·배터리·육상전원·2개 화물 화재구역을 갖췄다. 진링에 발주한 메탄올선 7척 중 2번째로 나머지 5척은 2027년 4분기까지, 11,700CEU급 LNG 이중연료선 7척(108,900GT)은 2028년 4분기까지 인도되고, WW는 11,700CEU급 최소 4척 추가를 협상 중이다(Shippax 10월 19일 보도 포함).", "eSum": "Wallenius Wilhelmsen took delivery of Royal Tern, the second Shaper Class ship, from CMHI Jinling in China for operation by its subsidiary EUKOR. The 9,300 CEU, 87,700 GT ship is 228 m by 38 m with 12 decks (four movable), a 480-tonne stern ramp, a 17.4-knot service speed, methanol dual-fuel engines prepared for ammonia, the Marshall Islands flag, air lubrication, batteries, shore power and two cargo fire zones. She is the second of seven methanol ships at Jinling, with five more due by Q4 2027 and seven 11,700 CEU LNG dual-fuel ships (108,900 GT) by Q4 2028, while WW negotiates at least four more 11,700 CEU units (Shippax reported the delivery on 19 October).", "kImp": "아틱 턴 인도 3개월 만에 2번선이 들어오고 2027년까지 메탄올선 인도가 이어지므로, 메탄올 연료 취급 자격을 갖춘 사관·기관사를 꾸준히 확보하고 인수 점검·보증기간 결함 관리 절차를 연속 인도 일정에 맞춰 반복 가능한 형태로 운영해야 한다.", "eImp": "With the second ship arriving three months after Arctic Tern and methanol deliveries continuing into 2027, managers need a steady pipeline of methanol-qualified officers and engineers and a repeatable delivery inspection and guarantee-period defect routine.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/wallenius-wilhelmsen-receives-royal-tern", "prio": 3}, {"code": "FLEET", "date": "2026-10-08", "src": "Shippax", "title": "노르웨이 NOCC, 7,100CEU 이중연료 PCTC 4척 추가 발주…인도 완료된 2척은 WWL·EUKOR에 용선 중", "eTitle": "Norwegian Car Carriers Orders Four More 7,100 CEU Dual-Fuel PCTCs, as Its Delivered NOCC Pacific and NOCC Adriatic Trade on Charter to WWL and EUKOR", "kSum": "JP모건 소유의 노르웨이 자동차선 선주 NOCC(Norwegian Car Carriers)가 중국 CIMC 라플스(롱커우) 조선소에 SDARI 설계 7,100CEU급 이중연료 PCTC 4척을 추가 발주했다고 쉽팩스가 10월 8일 보도했다. 이미 인도된 6만8,903GT급 'NOCC 퍼시픽'과 'NOCC 아드리아틱'은 WWL(왈레니우스 윌헬름센)과 EUKOR에 용선돼 있고, 동형선 'NOCC 카테가트'와 'NOCC 스카게락'은 2027년 상반기 인도 예정이다. 새 4척은 2030년~2031년 초 인도되며, NOCC는 선박 대선 전문 선주로 미국 모회사가 리버티 마리타임 등 미국 국적선사와 긴밀한 관계다.", "eSum": "J.P. Morgan-owned Norwegian Car Carriers (NOCC) has ordered four more SDARI-designed dual-fuel 7,100 CEU PCTCs from CIMC Raffles in Longkou for delivery in 2030 and early 2031, Shippax reported on 8 October. The 68,903 GT NOCC Pacific and NOCC Adriatic are already delivered and on charter to WWL and EUKOR, while sisters NOCC Kattegat and NOCC Skagerrak are due in the first half of 2027. NOCC is a tonnage provider, and its US parent has close links with US-flag owners such as Liberty Maritime.", "kImp": "그룹이 셰이퍼급 신조와 별도로 외부 선주의 이중연료 PCTC를 용선해 선복을 보강하고 있어, 용선선의 연료 체계·안전관리 수준을 그룹 기준에 맞추는 용선 전 점검(vetting)과 운항·화물 인터페이스 관리가 중요해진다.", "eImp": "Alongside its Shaper Class newbuilds the group is adding capacity through dual-fuel PCTCs chartered from outside owners, which puts weight on pre-charter vetting of fuel systems and safety management against group standards and on the operational and cargo interface with these ships.", "url": "https://www.shippax.com/en/news/nocc-boosts-orderbook-by-four-vessels.aspx", "prio": 2}, {"code": "FLEET", "date": "2026-10-07", "src": "Splash247", "title": "WalWil, 대형 LNG 이중연료 자동차선 최대 12척 추진…신조 프로그램 26척으로 확대", "eTitle": "Wallenius Wilhelmsen Eyes Up to 12 More Large LNG Dual-Fuel Car Carriers, Taking Its Newbuild Programme to as Many as 26 Ships", "kSum": "WalWil은 사모발행으로 조달한 약 3억 달러(NOK 28.8억, 1,714만5천 주·주당 NOK 168)와 차입을 합쳐 대형 LNG 이중연료 자동차선 4척(2030년 인도)과 동일 조건 옵션 8척(2031년부터 분기별 인도)을 발주할 계획이다. 조선소들과 '고급 단계 협의' 중이지만 조선소·선형(CEU)·선가는 공개되지 않았고 건조계약도 아직 체결되지 않았다. 옵션을 모두 행사하면 신조 프로그램은 2026년 3분기~2032년 인도의 26척이 되며, 기존 오더북은 CMHI 진링의 셰이퍼급 14척(11,700CEU 대형화 선박 포함, 메탄올 이중연료·암모니아 대비 설계)이다.", "eSum": "Wallenius Wilhelmsen plans to use about USD 300m (NOK 2.88bn; 17.145m shares at NOK 168) from a private placement, plus debt, to order four large LNG dual-fuel car carriers for 2030 delivery, with options for eight more on similar terms delivering quarterly from 2031. It is in advanced discussions with shipyards, but no yard, capacity or price has been disclosed and no contracts have been signed. If all options are declared the programme reaches 26 ships delivering from Q3 2026 to 2032, on top of an existing 14-ship Shaper Class orderbook at CMHI Jinling that includes units upsized to 11,700 CEU.", "kImp": "2030년 이후 신조 연료가 LNG로 다변화되면서 LNG 이중연료선 운항 역량(IGF Code 교육, 가스 벙커링·안전관리, 메탄 슬립 관리)이 중장기 인력 요건이 된다. 선령 30년 도래선 교체가 2030년대 초 일정으로 구체화되는 신호다.", "eImp": "With LNG joining methanol as a newbuild fuel from 2030, LNG dual-fuel competence (IGF Code training, gas bunkering and safety, methane-slip control) becomes a medium-term crewing requirement. It also signals that replacement of ships reaching 30 years of age is being scheduled for the early 2030s.", "url": "https://splash247.com/wallenius-wilhelmsen-eyes-up-to-12-more-car-carriers/", "prio": 3}, {"code": "FLEET", "date": "2026-09-25", "src": "Maritime Executive", "title": "WalWil 자회사 ARC, 옛 '피가로'를 'ARC Freedom'으로 美 국적 편입…MSP 선대 10척", "eTitle": "WalWil's ARC Reflags the Former Figaro as ARC Freedom Under the US Flag and Enrols It in the Maritime Security Program", "kSum": "WalWil 자회사 American Roll-on Roll-off Carrier(ARC)가 Wallenius Marine이 운항하던 2011년 대우조선해양 건조 PCTC 'Figaro'(231m, 31,143dwt, 약 8천 대 적재)를 6월 인수해 'ARC Freedom'으로 개명하고 스웨덴 선적에서 미국 선적으로 옮겼다. 13개 차량갑판(승강식 5개), 6.5m 주갑판 도어, 320톤 선미램프로 V-22·CH-47 등 군 화물을 실을 수 있으며 MARAD 해상안보프로그램(MSP)에 편입됐다. 이로써 ARC의 미 국적 선대는 10척이 됐고, Baird(9/28)에 따르면 모두 MSP에 등록돼 있다.", "eSum": "WalWil subsidiary American Roll-on Roll-off Carrier (ARC) took over the 2011 DSME-built PCTC Figaro (231 m, 31,143 dwt, about 8,000 units), previously operated by Wallenius Marine, in June, renamed her ARC Freedom and moved her from the Swedish to the US register. With 13 vehicle decks (five hoistable), a 6.5 m main deck door and a 320-tonne stern ramp she can carry military cargo such as V-22 and CH-47 aircraft, and she has joined MARAD's Maritime Security Program. ARC's US-flag fleet now numbers 10 ships, all enrolled in the MSP according to Baird Maritime on 28 September.", "kImp": "그룹 내 중고 대형선이 미국 정부화물(군수) 선대로 이동하는 사례로, 국적 변경 시 기국 요건·선원 자격 체계가 바뀌므로 인수인계 과정의 증서·문서 전환 관리가 중요하다.", "eImp": "The transfer shows government (military) cargo providing a home for large mid-life group tonnage. Reflagging changes flag requirements and crew certification regimes, so certificate and document transition must be managed carefully at handover.", "url": "https://maritime-executive.com/article/us-adds-large-vehicle-carrier-to-support-maritime-security-program", "prio": 2}, {"code": "FLEET", "date": "2026-07-31", "src": "Splash247", "title": "Wallenius SOL, 와겐보르그 내빙 로로선 2척 인수…스머핏웨스트록 장기 COA도 승계", "eTitle": "Wallenius SOL Buys Wagenborg's Two Ice-Class Ro-Ros and Takes Over Its Long-Term Smurfit Westrock Contract", "kSum": "네덜란드 Royal Wagenborg가 순수 로로 사업에서 철수하며 2004년 건조 내빙 1A급 자매선 Bothniaborg·Balticborg(각 10,254dwt, 약 1,635 레인미터)를 Wallenius SOL에 매각하고 스머핏웨스트록과의 장기 화물운송계약(COA)도 넘겼다. 두 척은 스웨덴 피테오 크라프트라이너 공장(연 70만 톤) 산림제품을 보스니아만~유럽 대륙 간 운송해 왔으며, Wallenius SOL은 기존 서비스를 유지하다 북유럽 네트워크에 통합하고 카세트 하역으로 전환한 뒤 차세대 신조선을 투입할 계획이다. 가격은 비공개이며, Wallenius Lines는 5월 SOL 그룹 지분 인수를 마쳐 Wallenius SOL의 단독 소유주가 됐다.", "eSum": "Royal Wagenborg is leaving pure ro-ro shipping by selling its 2004-built ice class 1A sisters Bothniaborg and Balticborg (10,254 dwt and about 1,635 lane metres each) to Wallenius SOL, together with its long-term contract of affreightment with Smurfit Westrock. The ships carry forest products from the 700,000 t/yr Piteå kraftliner mill between the Bay of Bothnia and continental Europe; Wallenius SOL will keep the service running, fold the volumes into its northern European network, shift to cassette handling and later deploy next-generation newbuilds. Terms were not disclosed, and Wallenius Lines completed its buyout of SOL Group's stake in May to become sole owner of Wallenius SOL.", "kImp": "WalWil의 북유럽 연계 파트너인 Wallenius SOL의 선대·화물 기반이 커져, 보스니아만 등 결빙 해역 연계 수송의 안정성이 높아질 수 있다.", "eImp": "Wallenius SOL, WalWil's partner for northern European feeder trades, is growing its fleet and cargo base, which may make ice-season links in the Gulf of Bothnia more reliable.", "url": "https://splash247.com/wagenborg-exits-roros-with-wallenius-sol-ship-sale/", "prio": 1}, {"code": "FLEET", "date": "2026-07-14", "src": "Wallenius Wilhelmsen", "title": "WalWil '셰이퍼급을 만든 사람들'…화재구역 확대·CO2 소화용량 규정의 2배·이중 연료계통", "eTitle": "Behind the Build: Wallenius Wilhelmsen's Shaper Class Team on More Fire Zones, Double CO2 Capacity and Dual Fuel Systems", "kSum": "WalWil은 Arctic Tern 인도를 계기로 4~5년에 걸쳐 셰이퍼급을 설계한 신조·프로젝트 팀(Lars Dessen 부사장 등)을 소개했다. 셰이퍼급은 이전 세대(Hero급)보다 적재량이 크고 전기차 등 중량화물에 맞춰 설계됐으며, 화재구역 수를 늘리고 CO2 소화 용량을 규정의 2배로 높였고, 메탄올 이중연료를 위해 주기관 연료공급 계통과 연료탱크를 2세트씩 갖췄다. 선원들은 조선소에서 교육을 받은 뒤 처녀항해에 나섰으며 이전에 운항한 어떤 배와도 다르다고 평가했다.", "eSum": "Marking Arctic Tern's delivery, Wallenius Wilhelmsen introduced the newbuilding and projects team, led by VP Lars Dessen, that spent four to five years designing the Shaper Class. The class carries more than earlier generations such as the Hero class and is designed for heavier cargo including EVs, with more fire zones, CO2 firefighting capacity at double the regulatory requirement, and two fuel supply systems and two sets of fuel tanks for methanol dual-fuel operation. The crew trained at the shipyard before the maiden voyage and described the ship as unlike anything they had operated before.", "kImp": "화재 대응 설계 강화(구역 분할·CO2 용량)에 맞춰 선상 소화 절차와 훈련 시나리오를 신형 설비 기준으로 다시 써야 하며, 이중 연료계통 운용 교육이 인수 단계의 핵심이다.", "eImp": "Upgraded fire design (more zones, larger CO2 capacity) means onboard firefighting procedures and drill scenarios must be rewritten for the new systems, and dual fuel-system training is central at take-over.", "url": "https://www.walleniuswilhelmsen.com/insights/behind-the-build-meet-the-people-that-shaped-our-new-vessel-class", "prio": 2}, {"code": "FLEET", "date": "2026-07-09", "src": "Wallenius Wilhelmsen", "title": "WalWil, 셰이퍼급 1번선 '아틱 턴' 인수…메탄올 이중연료 9,300CEU, 아시아-유럽 투입", "eTitle": "Wallenius Wilhelmsen Takes Delivery of Arctic Tern, the First Shaper Class Methanol Dual-Fuel PCTC, for Asia-Europe Service", "kSum": "WalWil은 7월 9일 셰이퍼급 첫 선박 Arctic Tern을 인수해 EUKOR를 통해 아시아-유럽 항로에 바로 투입했으며, 철새 이름을 따는 새 명명 전통을 시작했다. Baird 선박 리뷰(7/23)에 따르면 CMHI 진링 건조, 9,300CEU·12개 갑판, 길이 228m·폭 38m, 87,688GT, 마셜제도 기국·DNV 선급으로 메탄올/VLSFO 이중연료(향후 암모니아 전환 가능)이며, 공기윤활·배터리·태양광·육전 설비와 규정(1개)보다 많은 화물구역 화재구역 2개를 갖췄다. Wallenius Marine이 조선소 현장 감독을, Wilhelmsen Ship Management가 인도 후 선박관리를 맡았다.", "eSum": "Wallenius Wilhelmsen took delivery of Arctic Tern, the first Shaper Class ship, on 9 July and put her straight into Asia-Europe service through EUKOR, starting a new tradition of naming ships after migratory birds. According to Baird Maritime's vessel review (23 July), the CMHI Jinling-built ship has 9,300 CEU on 12 decks, measures 228 m by 38 m (87,688 GT), flies the Marshall Islands flag with DNV class, burns methanol or VLSFO with future ammonia conversion possible, and has air lubrication, batteries, solar panels, shore power and two cargo fire zones against one required. Wallenius Marine oversaw work at the yard and Wilhelmsen Ship Management took over ship management after delivery.", "kImp": "그룹 첫 메탄올 이중연료 PCTC가 상업 운항에 들어가 메탄올 연료 운용 경험이 실선에서 쌓이기 시작했다. 후속 13척 인수를 위한 체크리스트·교육 표준화에 초기 운항 교훈을 반영할 시점이다.", "eImp": "The group's first methanol dual-fuel PCTC is now in commercial service, so methanol operating experience is building on a real ship. Lessons from early operation should feed into standard take-over checklists and training for the remaining 13 sisters.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-takes-delivery-of-first-shaper-class-vessel-marking-a-new-chapter-in-sustainable-shipping", "prio": 3}, {"code": "FLEET", "date": "2026-07-02", "src": "Wallenius Wilhelmsen", "title": "WalWil '티라나' 윙세일 설치 완료·해상인수시험 통과…로로선 풍력추진 실선 평가 착수", "eTitle": "Wallenius Wilhelmsen Completes the Wing Sail Installation on Tirranna and Passes the Sea Acceptance Test", "kSum": "WalWil 선박 Tirranna(230m)에 Oceanbird 윙세일 설치가 6월 22~24일 로테르담 Damen 조선소에서 이뤄졌고, 항만인수시험에 이어 7월 1일 해상인수시험(SAT)을 통과했다. Alfa Laval에 따르면 'Wing560'은 높이 40m·폭 14m로 6월 초 DNV 설계 인증을 받았으며 자동차선 분야 첫 풍력추진 실선 시제품이다. 선박은 정상 상업운항을 하며 성능 데이터를 수집·평가하고, 이번 설치는 11개 파트너가 참여하는 EU 지원 Orcelle Horizon 프로젝트의 이정표다.", "eSum": "The Oceanbird wing sail was installed on Wallenius Wilhelmsen's Tirranna (230 m) at Damen Shipyard in Rotterdam on 22-24 June, and after a harbour acceptance test the ship passed its sea acceptance test on 1 July. According to Alfa Laval, the Wing560 is 40 m tall and 14 m wide, received a DNV design certificate in early June and is the first onboard wind-propulsion prototype in the car carrier segment. The ship will trade normally while performance data is collected and evaluated, a milestone for the EU-funded, eleven-partner Orcelle Horizon project.", "kImp": "상업 운항 중 윙세일 운용 데이터가 쌓이면서 풍력보조 장치의 운항 절차(강풍 시 접기, 입항 시 공기흘수·시야 관리) 표준화가 필요해진다.", "eImp": "As operating data from a wing sail in commercial service accumulates, standard procedures for wind-assist devices (stowing in high winds, air draft and bridge visibility in port) will be needed.", "url": "https://www.walleniuswilhelmsen.com/news/with-wind-in-her-sail-tirrannas-wing-sail-installation-completed", "prio": 2}, {"code": "FLEET", "date": "2026-03-19", "src": "Wallenius Wilhelmsen", "title": "WalWil 2025 연차보고서: 선대 127척·셰이퍼급 14척 건조 중(잔여 투자 15억 달러)…31년 된 선박 재활용 매각", "eTitle": "Wallenius Wilhelmsen 2025 Annual Report: 127 Ships, 14 Shaper Class Under Construction With USD 1.5bn Capex Left, and a 31-Year-Old Ship Sold for Recycling", "kSum": "2025년 연차보고서에 따르면 WalWil은 연말 127척(소유 91척, 장기용선 33척, 단기용선 3척)을 운항했고, 셰이퍼급 14척 건조의 잔여 투자액은 15억 달러이며 11척은 인도 후 금융을 확보했다. 2025년 약 30년 된 선박 2척을 매각했고 31년 된 1척은 재활용용으로 매각해 2026년 1분기에 인도했으며, 30년 넘은 선박은 시장이 타이트해도 네트워크 투입이 어렵다고 밝혔다. 2025년 매출 52억4천만 달러, 조정 EBITDA 18억1,100만 달러, 순이익 11억400만 달러, 계약잔고 100억 달러 이상을 기록했고, 중대 사고는 없었으나 해상 LTIF는 0.6(2024년 0.41)으로 높아졌다.", "eSum": "The 2025 annual report shows Wallenius Wilhelmsen operating 127 ships at year-end (91 owned, 33 on long-term and 3 on short-term charter), with USD 1.5bn of capex remaining on the 14 Shaper Class ships under construction and post-delivery financing secured for 11. Two ships of about 30 years were sold in 2025 and a 31-year-old ship was sold for recycling and delivered in Q1 2026, the report noting that ships above 30 are hard to deploy even in a tight market. 2025 revenue was USD 5,240m, adjusted EBITDA USD 1,811m, net profit USD 1,104m and the contract backlog above USD 10bn; there were no serious accidents, but ocean LTIF rose to 0.6 from 0.41.", "kImp": "선령 30년이 사실상 운항 한계로 제시돼 고선령선의 처분·재활용 시점 관리가 중요해졌으며, 해상 LTIF 상승은 선상 안전관리 강화 필요성을 보여준다.", "eImp": "Thirty years is presented as the practical limit for deployment, making disposal and recycling timing for ageing ships important, and the rise in ocean LTIF signals a need to tighten onboard safety management.", "url": "https://www.walleniuswilhelmsen.com/storage/images/Investor-relations/2025-Annual-report-document.pdf", "prio": 2}, {"code": "FLEET", "date": "2026-02-19", "src": "Wallenius Marine", "title": "왈레니우스 마린, WW 셰이퍼급 신조 14척 중 7척 선박관리 수주…2027년 2분기부터 순차 인도, 몰타 기국", "eTitle": "Wallenius Marine Wins Ship Management of Seven of Wallenius Wilhelmsen's 14 Shaper Class Newbuildings, Delivering From Q2 2027 Under the Maltese Flag", "kSum": "왈레니우스 마린은 WW가 중국 CMHI 진링에 발주한 셰이퍼급 로로 신조 14척 가운데 7척의 선박관리(기술관리·선원 배승·조달·운항 지원) 계약을 따냈다고 밝혔다. 7척은 모두 이중연료 주기관을 갖추며 3척은 메탄올, 4척은 LNG용이고 몰타 기국으로 운항하며, 2027년 2분기부터 짧은 기간에 걸쳐 순차 인도된다. 왈레니우스 마린은 이와 별도로 14척 전체의 건조 현장감독도 맡고 있다.", "eSum": "Wallenius Marine said it will manage seven of the 14 Shaper Class ro-ro newbuildings Wallenius Wilhelmsen has ordered at China's CMHI Jinling, covering technical management, crewing, procurement and operational support. All seven have dual-fuel main engines, three prepared for methanol and four for LNG, will fly the Maltese flag and deliver in quick succession from Q2 2027. Separately, Wallenius Marine supervises construction of all 14 ships.", "kImp": "셰이퍼급 14척의 관리가 그룹 내 여러 선박관리사로 나뉘는 만큼, 메탄올·LNG 이중연료선 선원 교육과 운항 절차, 몰타 기국 요건을 관리사 간에 일관되게 맞추는 협업 체계가 필요하다.", "eImp": "With management of the 14 Shaper Class ships split across group ship managers, crew training and operating procedures for methanol and LNG dual-fuel ships, as well as Maltese flag requirements, should be aligned between managers.", "url": "https://www.walleniusmarine.com/blog/pressrelerase/wallenius-marine-awarded-ship-management-contract-for-seven-newbuildings/", "prio": 2}]}, {"code": "OPS", "kTitle": "운항·항로", "eTitle": "Operations & Deployment", "items": [{"code": "OPS", "date": "2026-11-26", "src": "Splash247", "title": "아부다비, 걸프 안보 우려 속 주요 석유·가스 수출시설 인근 유조선 이동 대폭 제한", "eTitle": "Abu Dhabi Restricts Tanker Movements Near Its Main Oil and Gas Export Facilities Amid Mounting Gulf Security Concerns", "kSum": "아부다비가 걸프 지역 안보 우려가 커지는 가운데 주요 석유·가스 수출시설 인근의 유조선 이동을 광범위하게 제한했다고 Splash247이 11월 26일 전했다. 같은 날 이란은 호르무즈 남쪽 통항로를 이용한 선박을 지원했다는 이유로 예인선 26척을 블랙리스트에 올린 바 있다.", "eSum": "Abu Dhabi has imposed sweeping restrictions on tanker movements near its principal oil and gas export facilities amid mounting Gulf security concerns, Splash247 reported on 26 November.", "kImp": "UAE 항만 기항 일정이 예고 없이 바뀔 수 있다. 걸프 기항선은 대리점·항만 공지로 이동 제한 구역과 투묘 지정 해역을 매일 확인하고, ISPS 보안등급 변화에 대비할 것.", "eImp": "UAE port calls may change at short notice. Ships in the Gulf should check restricted zones and designated anchorages daily via agents and port notices, and be ready for ISPS level changes.", "url": "https://splash247.com/#abu-dhabi-tanker-restrictions", "prio": 3}, {"code": "OPS", "date": "2026-11-26", "src": "Splash247", "title": "일본 컨테이너터미널 혼잡 심각 — 접안 후에도 하역 시작까지 며칠 대기, 남는 선복 흡수해 고용선료 지지", "eTitle": "Japanese Port Congestion Leaves Boxships Stranded at Berth - Days of Waiting After Berthing Absorb Excess Capacity and Support Charter Rates", "kSum": "일본 컨테이너터미널 혼잡이 심해져 일부 선박은 접안한 뒤에도 하역을 시작하기까지 며칠을 기다려야 한다고 Splash247이 11월 26일 전했다. 지속된 항만 혼잡은 올해 컨테이너선 과잉 선복을 흡수하는 역할을 해, 대규모 선대 증가와 수에즈 운하 복귀에도 역사적으로 높은 용선료를 떠받치고 있다.", "eSum": "Congestion at Japanese container terminals is so acute that some ships wait several days after berthing before cargo operations start, Splash247 reported on 26 November; persistent congestion has absorbed excess containership capacity this year, sustaining high charter rates despite fleet growth and the gradual return to Suez.", "kImp": "일본 항만의 하역 인력·장비 부족은 자동차 부두에도 번질 수 있다. 일본 기항 PCTC는 선석 대기·하역 지연을 반영한 항해 계획과 정박 중 당직 계획을 세울 것.", "eImp": "Labour and equipment shortages at Japanese ports may spill over to car terminals. Plan Japan PCTC calls for berth waits and cargo delays, including in-port watch planning.", "url": "https://splash247.com/japanese-port-congestion-leaves-boxships-stranded-at-berth/", "prio": 2}, {"code": "OPS", "date": "2026-11-26", "src": "NWS(미 국립기상청)", "title": "미 워싱턴~오리건 북부 연안 강풍·위험해상 경보 갱신 — 파고 18~21피트, 남서풍 30~40kt(돌풍 47kt), 27일 새벽까지", "eTitle": "Gale and Hazardous Seas Warnings Renewed off Washington and Northern Oregon - Seas 18-21 ft, SW Winds 30-40 kt Gusting 47 kt Until Early 27 November", "kSum": "미 국립기상청 포틀랜드 지청은 11월 26일 케이프 쇼얼워터(워싱턴주)부터 케이프 팔콘(오리건주)까지 연안에 강풍·위험해상 경보를 갱신했다. 강풍 경보 구역은 주기 15초 파고 18~21피트, 남서풍 30~40노트(돌풍 47노트), 위험해상 경보는 주기 13초의 가파른 파고 14~18피트로 27일 새벽 1시(태평양 표준시)까지이며, 이후 27일 새벽부터 28일 새벽까지 소형선 주의보로 이어진다.", "eSum": "NWS Portland renewed Gale and Hazardous Seas Warnings on 26 November for waters from Cape Shoalwater, WA, to Cape Falcon, OR: seas 18-21 ft at 15 s with SW winds 30-40 kt gusting 47 kt, and very steep seas 14-18 ft at 13 s until 01:00 PST on 27 November, followed by a Small Craft Advisory to early 28 November.", "kImp": "컬럼비아강 바 통과선은 27일까지 통과 제한·지연에 대비할 것. 미 서부 북상·남하 선박은 해안 접근 항로를 피하고 화물 고박을 재점검할 것.", "eImp": "Ships crossing the Columbia River bar should expect restrictions and delays to 27 November; ships along the US West Coast should keep off the coast and recheck lashings.", "url": "https://govonestop.com/nws/moderate-hazardous-seas-warning-effective-11262026-0025-0", "prio": 2}, {"code": "OPS", "date": "2026-11-25", "src": "SAFETY4SEA", "title": "이란, 호르무즈 '비협조 선박' 지원 예인선 26척 블랙리스트 추가 — 남쪽 통항로 이용 선박 지원 이유", "eTitle": "Iran Adds 26 Tugboats to Its Strait of Hormuz Blacklist - For Assisting Ships Using a Southern Route Tehran Deems Unauthorised", "kSum": "이란 페르시아만해협청(PGSA)은 11월 24일 호르무즈 해협 통항 요건을 어긴 선박을 도운 혐의로 예인선 26척을 '비준수 목록(NCL)'에 올렸다고 발표했다. 이란은 해협 남쪽 통항로를 무단 항로로 보고 있으며, 인접국 시민 제보와 자체 감시 정보로 대상을 가려냈다고 밝혔다.", "eSum": "Iran's Persian Gulf Strait Authority (PGSA) announced on 24 November that 26 tugboats had been added to its Non-Compliance List for serving vessels on a southern transit route it considers unauthorised, identified from tips by citizens of neighbouring countries and its own monitoring.", "kImp": "걸프 항만의 예인·도선 지원이 이란 단속 대상이 되고 있다. 걸프 기항선은 예인선 확보가 늦어질 수 있음을 전제로 입출항 계획을 세우고, 통항 전 JMIC·UKMTO 권고와 선주 지시를 다시 확인할 것.", "eImp": "Towage and pilotage in Gulf ports are now targets of Iranian enforcement. Plan Gulf calls assuming tug delays and recheck JMIC/UKMTO advice and owner instructions before transit.", "url": "https://safety4sea.com/iran-adds-26-tugboats-to-strait-of-hormuz-blacklist/", "prio": 3}, {"code": "OPS", "date": "2026-11-24", "src": "The Maritime Executive", "title": "사우디-후티 교전 — 리야드·호데이다·라스타누라 피격, 후티 '사우디 홍해 항만 대피' 경고", "eTitle": "Riyadh, Hodeidah and Ras Tanura Hit in a Saudi-Houthi Exchange of Fire - Houthis Order Evacuation of Saudi Red Sea Ports", "kSum": "사우디와 후티 반군이 공격을 주고받으면서 리야드, 예멘 호데이다항, 사우디 라스타누라가 피격됐다고 The Maritime Executive가 전했다. 사우디군은 인명 피해를 줄이려 공격 전 호데이다항 대피를 명령했고, 후티 지도부는 보복 공격을 예고하며 사우디 홍해 항만 대피를 지시했다.", "eSum": "Riyadh, the Yemeni port of Hodeidah and Saudi Arabia's Ras Tanura were hit in an exchange of fire between Saudi Arabia and the Houthis, The Maritime Executive reported. Saudi officials ordered Hodeidah evacuated before the strike; Houthi leaders responded by ordering the evacuation of Saudi Red Sea ports and threatening counterstrikes.", "kImp": "홍해 양안 항만 모두 공격 위협을 받고 있다. 제다·얀부 등 사우디 홍해 항만 기항선은 선주·보안 담당과 위험 평가를 다시 하고, 항만 정박 중 대피·소화 준비를 확인할 것.", "eImp": "Ports on both sides of the Red Sea now face attack threats. Ships calling at Saudi Red Sea ports such as Jeddah and Yanbu should redo risk assessments with owners and security and confirm evacuation and firefighting readiness while in port.", "url": "https://maritime-executive.com/article/riyadh-hodeidah-and-ras-tanura-hit-in-saudi-houthi-exchange-of-fire", "prio": 3}, {"code": "OPS", "date": "2026-11-25", "src": "NWS(미 국립기상청)", "title": "미 오리건 연안 강풍·위험해상 경보 이어져 — 파고 16~21피트·남풍 30~40kt(돌풍 45kt), 27일 새벽까지", "eTitle": "Gale and Hazardous Seas Warnings Continue off Oregon - Seas 16-21 ft, South Winds 30-40 kt Gusting 45 kt Until Early 27 November", "kSum": "미 국립기상청 포틀랜드 지청은 11월 25일 케이프 풀웨더~플로렌스 연안(60해리까지)에 강풍·위험해상 경보를 냈다. 강풍 경보 구역은 주기 16초 파고 16~21피트, 남풍 30~40노트(돌풍 45노트)이고, 위험해상 경보는 주기 13초의 가파른 파고 13~17피트로 26일 오전 10시부터 27일 새벽 1시(태평양 표준시)까지다.", "eSum": "NWS Portland issued Gale and Hazardous Seas Warnings on 25 November for waters from Cape Foulweather to Florence, Oregon, out to 60 nm: seas 16-21 ft at 16 s with south winds 30-40 kt gusting 45 kt, and very steep seas 13-17 ft at 13 s from 10:00 on 26 November to 01:00 PST on 27 November.", "kImp": "미 서부 연안 황천이 이틀 넘게 이어지고 있다. 컬럼비아강·퓨젓사운드 입출항선은 바 통과 제한과 입항 지연 가능성을 대리점과 확인하고 화물 고박을 재점검할 것.", "eImp": "West Coast heavy weather has lasted more than two days. Ships entering or leaving the Columbia River or Puget Sound should check bar restrictions and delays with agents and recheck lashings.", "url": "https://govonestop.com/nws/moderate-hazardous-seas-warning-effective-11252026-1315-0", "prio": 2}, {"code": "OPS", "date": "2026-11-25", "src": "The Maritime Executive", "title": "미 체서피크만교 앞서 컨테이너선 GSL NICOLETTA 조타 상실 — 앵커로 교량 8선장 앞 정지", "eTitle": "Boxship GSL NICOLETTA Loses Steering Near Maryland's Chesapeake Bay Bridge - Anchors Stop Her About Eight Ship Lengths Away", "kSum": "컨테이너선 GSL NICOLETTA가 조타 이상을 보고한 뒤 감속하고 앵커를 투하해 체서피크만교에서 약 1.5마일(약 8선장) 앞에서 멈췄다고 The Maritime Executive가 전했다. 메릴랜드 교통당국은 해안경비대와 연락했고, 약 8분 뒤 해안경비대가 상황이 통제됐다며 교량 폐쇄가 필요 없다고 알렸다.", "eSum": "Containership GSL NICOLETTA slowed and dropped anchors after reporting a steering problem, stopping about 1.5 miles, or roughly eight ship lengths, from the Chesapeake Bay Bridge, The Maritime Executive reported; after about eight minutes the Coast Guard said the situation was under control and the bridge need not close.", "kImp": "교량·협수로 접근 시 조타 상실은 앵커 즉시 사용 준비가 승부를 가른다. 교량 통과 전 투묘 준비(선수 대기)·비상 조타 전환 절차를 브리핑하고 미국 항만 VTS 보고 절차를 확인할 것.", "eImp": "Immediate anchor readiness decides the outcome when steering fails near a bridge. Brief anchors-ready forward and emergency steering changeover before bridge passages and confirm US VTS reporting.", "url": "https://maritime-executive.com/article/brief-scare-as-boxship-loses-steering-control-near-maryland-bridge", "prio": 2}, {"code": "OPS", "date": "2026-11-24", "src": "gCaptain", "title": "호르무즈서 선박 4척 추가 피격, 일주일 새 유조선 공격 10건 — 이란, 단속 대상을 '비협조 선박' 지원 예인선 등 해사 서비스 업체로 확대", "eTitle": "Four More Ships Attacked as Iran Widens Its Hormuz Crackdown to Tugboats - Ten Reported Tanker Strikes in a Single Week", "kSum": "호르무즈 해협과 주변 해역에서 상선 4척이 추가로 공격을 받아 한 주 사이 보고된 유조선 피격이 10건으로 늘었다고 gCaptain이 11월 24일 보도했다. 합동해사정보센터(JMIC)는 11월 22일 권고문에서 11월 16일 이후 해협에서 유조선 7척이 피격됐다고 집계했고, 이후 3건이 더 보고됐다. 11월 21일에는 유조선 TORKEL과 ARINA가 공격을 받았다. 이란은 자국이 '비협조'로 보는 선박을 돕는 예인선 등 해사 서비스 업체까지 단속 대상으로 넓히고 있다.", "eSum": "Four more merchant ships were attacked in and around the Strait of Hormuz, taking reported tanker strikes to ten in a single week, gCaptain reported on 24 November. JMIC's 22 November advisory counted seven tankers struck since 16 November; three more have been reported since, including TORKEL and ARINA on 21 November. Iran is extending its crackdown to tugs and other service providers assisting ships it regards as non-compliant.", "kImp": "공격 대상이 유조선에서 예인선·서비스 업체로 넓어졌다. 걸프 기항선은 항만 예인·도선·급유 서비스가 갑자기 끊길 수 있음을 전제로 입출항 계획을 세우고, 통항 직전 JMIC·UKMTO 최신 권고와 선주·용선주 지시를 다시 확인할 것.", "eImp": "The target set now includes tugs and service providers, not only tankers. Ships calling in the Gulf should plan for sudden loss of towage, pilotage or bunkering, and recheck the latest JMIC/UKMTO advisories and owner/charterer instructions just before transit.", "url": "https://gcaptain.com/four-more-ships-attacked-as-iran-widens-hormuz-crackdown-to-tugboats/", "prio": 2}, {"code": "OPS", "date": "2026-11-24", "src": "NWS(미 국립기상청)", "title": "미 서부 오리건·북캘리포니아 연안 폭풍·위험해상 경보 — 풍속 40~50노트·돌풍 65노트, 파고 23~28피트(약 7~8.5m), 25일 오후까지", "eTitle": "Storm and Hazardous Seas Warnings off Oregon and Northern California - Winds 40-50 kt, Gusts to 65 kt, Seas 23-28 ft Until the Afternoon of 25 November", "kSum": "미 국립기상청(NWS) 메드퍼드 지청은 11월 24일 오리건 남부 연안 전 해역에 폭풍 경보와 위험해상 경보를 냈다. 남풍 40~50노트, 돌풍 55~65노트에 파고 23~28피트(약 7~8.5m)의 가파르고 불규칙한 바다가 예보됐고, 바람이 약해진 뒤에도 주기 17초의 긴 너울로 19~24피트 파고가 25일 오후 4시(태평양 표준시)까지 이어질 것으로 봤다. 유레카 지청도 포인트 세인트조지~케이프 멘도시노 10~60해리 해역에 폭풍 경보(돌풍 60노트, 파고 19~23피트)를 냈다.", "eSum": "The NWS office in Medford issued Storm and Hazardous Seas Warnings on 24 November for all waters off southern Oregon: winds 40-50 kt with gusts to 55-65 kt and chaotic seas of 23-28 ft, with a heavy long-period swell keeping seas at 19-24 ft (17 s) until 16:00 PST on 25 November. The Eureka office warned of 35-45 kt winds, gusts to 60 kt and 19-23 ft seas from Pt. St. George to Cape Mendocino, 10-60 nm offshore.", "kImp": "미 서부 연안(시애틀·타코마·포틀랜드) 입출항선은 경보 해제 전 입항 시각 조정, 화물·차량 고박 재점검, 갑판 작업 금지와 황천 항해 당직 강화를 지시할 것. 긴 주기 너울은 자동차선 횡동요를 키우므로 선속·침로 조정 기준을 미리 정할 것.", "eImp": "Ships arriving at or leaving US West Coast ports (Seattle, Tacoma, Portland) should adjust arrival times until the warnings lift, recheck cargo and vehicle lashings, stop deck work and reinforce heavy-weather watches. Long-period swell increases rolling on car carriers, so set speed/course adjustment criteria in advance.", "url": "https://govonestop.com/nws/moderate-hazardous-seas-warning-effective-11242026-0046-0", "prio": 3}, {"code": "OPS", "date": "2026-11-23", "src": "gCaptain", "title": "미 재무부, 이란 유조선대·원유 거래 뒤 '금융망' 제재 — 22개 기관·8명, 이란국영유조선(NITC) 결제 중개사까지 겨냥", "eTitle": "US Treasury Targets the Financial Networks Behind Iran's Tanker Fleet and Oil Trade - 22 Entities and 8 Individuals, Including Firms Paying for NITC", "kSum": "미국 재무부는 11월 23일(월) '경제적 추방 작전(Operation Economic Outcast)'에 따라 이란 원유 수출과 유조선 운항을 뒷받침하는 금융망을 겨냥한 새 제재를 발표했다. 대상은 22개 기관과 8명으로, 이란국영유조선(NITC)에 대한 대금 결제를 중개한 회사와 이란군과 연결된 운송 계약 관계자가 포함됐다. 이들은 이란의 국제 금융망을 통해 수십억 달러를 옮긴 것으로 지목됐다. 그동안 제재가 유조선과 선사에 집중됐던 것과 달리, 이번에는 모든 거래가 거치는 금융 인프라 자체를 겨냥했다는 점이 다르다.", "eSum": "The US Treasury announced on Monday 23 November new sanctions under Operation Economic Outcast targeting the financial networks supporting Iran's oil exports and tanker operations: 22 entities and eight individuals, including companies accused of facilitating payments for the National Iranian Tanker Company (NITC) and shipping arrangements linked to the Iranian military. They are accused of moving billions of dollars through Iran's international financial networks. Unlike earlier rounds aimed at tankers and shipping companies, this one targets the financial infrastructure behind them.", "kImp": "제재 범위가 선박에서 결제·중개 회사로 넓어졌다. 연료 공급업체·대리점·용선 중개인과의 거래에서 대금 지급 경로가 제재 대상과 겹치지 않는지 확인하고, 선주와 계약 상대방 심사(KYC)를 다시 점검할 것.", "eImp": "Sanctions now reach payment and brokerage firms, not only ships. Check that payment routes with bunker suppliers, agents and brokers do not cross sanctioned parties, and recheck KYC on counterparties.", "url": "https://gcaptain.com/u-s-targets-financial-networks-behind-irans-tanker-fleet-and-oil-trade/", "prio": 2}, {"code": "OPS", "date": "2026-11-20", "src": "AutoTalk", "title": "Wallenius Wilhelmsen, 2027년 일본발 호주·뉴질랜드·피지·뉴칼레도니아 서비스 중단 확인 — '로로 시장 선복 압박으로 정시성 보장 어려워'", "eTitle": "Wallenius Wilhelmsen Confirms It Will Suspend Japan-Australia, New Zealand, Fiji and New Caledonia Services in 2027 - 'Capacity Pressure in the RoRo Market Means We Cannot Assure Reliability'", "kSum": "뉴질랜드 자동차 매체 AutoTalk에 따르면 Wallenius Wilhelmsen은 일본에서 호주·뉴질랜드·피지·뉴칼레도니아로 가는 해상 서비스를 2027년 한 해 중단한다고 확인했다. 회사는 항로망과 가용 선복을 검토한 결과이며, 세계 로로 시장의 '상당한 선복 압박' 때문에 필요한 서비스 정시성을 제공할 수 없다고 설명했다. 시장 상황에 따라 서비스 구성을 계속 검토하겠다고 덧붙였다. 앞서 NCC Car Carriers가 중고차 수입업체에 중단 사실을 알렸는데, 이 항로는 닛산 리프를 뺀 중고 전기차를 실을 수 있는 유일한 로로 선택지였다. 업계에 따르면 이 시기 컨테이너 운송비는 대당 6,000~7,000뉴질랜드달러로 로로선(약 2,500달러)의 두 배를 넘는다.", "eSum": "According to New Zealand motoring outlet AutoTalk, Wallenius Wilhelmsen has confirmed it will suspend its ocean services from Japan to Australia, New Zealand, Fiji and New Caledonia for 2027. The company said the decision followed a review of its network and available capacity and that 'significant capacity pressure' in the global RoRo market means it cannot provide the service reliability required. It will keep its service offering under review as market conditions evolve. NCC Car Carriers had earlier told used vehicle importers of the suspension; the line was the only RoRo option for used battery EVs other than the Nissan Leaf. Industry sources put container shipping at NZD 6,000-7,000 a car at this time of year, against about 2,500 by RoRo.", "kImp": "선복이 모자라면 운항사는 단거리·저수익 항로부터 접는다. 자동차선 관리사는 배선 변경으로 선박의 기항지·항로가 바뀔 때 항만 정보, 기국·PSC 이력, 선원 교대 항구 계획을 미리 갱신할 것.", "eImp": "When capacity is short operators drop shorter, lower-yield trades first. Car carrier managers should update port information, flag and PSC history and crew change port plans in advance when redeployment changes a ship's calls and routes.", "url": "https://autotalk.co.nz/wallenius-wilhelmsen-confirms-2027-japan-oceania-suspension/", "prio": 3}, {"code": "OPS", "date": "2026-11-22", "src": "gCaptain(Reuters)", "title": "핀란드만에서 러시아 화물선 Sparta II 무인기 피격 — 밤새 화재, 선원 16명 대피. 에스토니아 해군 '추가 공격 배제 못 해'", "eTitle": "Russian Cargo Ship Sparta II Hit by Drones in the Gulf of Finland - Fire Burns Overnight and 16 Crew Evacuated; Estonia's Navy Says More Attacks Cannot Be Ruled Out", "kSum": "미국 제재 대상인 러시아 국적 화물선 Sparta II(길이 121m, 러시아 국방부 물류회사 소유)가 11월 21일 상트페테르부르크에서 칼리닌그라드로 가던 중 핀란드만 고글란드섬 서쪽 공해에서 무인기 공격을 받았다. 갑판 위 컨테이너에 불이 붙어 밤새 탔고, 선원 16명은 인근 러시아 선박으로 대피했다. 선박은 핀란드 영해로 표류해 정박 중이다. 핀란드군은 우크라이나 소행일 가능성이 높다고 했고, 에스토니아 해군 사령관은 핀란드만에서 추가 공격을 배제할 수 없다고 말했다.", "eSum": "The US-sanctioned Russian-flagged cargo ship Sparta II (121 m, owned by a Russian Defence Ministry logistics company) was hit by drones on 21 November in international waters west of Gogland island in the Gulf of Finland while sailing from St Petersburg to Kaliningrad. Deck-stowed containers caught fire and burned overnight, and the 16 crew were evacuated to a nearby Russian ship. The vessel drifted into Finnish waters and is at anchor. Finland's military said Ukraine was likely responsible, and Estonia's navy commander said further attacks in the Gulf of Finland cannot be ruled out.", "kImp": "발트해 동부도 무력 공격 위험 해역이 되고 있다. 발트해 기항 선박의 관리사는 핀란드만 통항 시 러시아 관련 선박과의 근접 회피, 견시·소화 준비 강화를 선장 지침에 넣고 전쟁위험 보험 조건을 확인할 것.", "eImp": "The eastern Baltic is becoming an armed-attack risk area. Managers of ships calling in the Baltic should add to masters' instructions keeping clear of Russian-linked ships in the Gulf of Finland and heightened lookout and firefighting readiness, and check war-risk cover terms.", "url": "https://gcaptain.com/russian-cargo-ship-still-on-fire-off-finland-after-attack/", "prio": 2}, {"code": "OPS", "date": "2026-11-22", "src": "The Maritime Executive", "title": "리비아 벵가지항에서 러시아 코르벳·군수 화물선 피격 — 무인 수상정 최대 6척 추정, 지중해로 번진 해상 공격", "eTitle": "A Russian Corvette and Military Cargo Ships Are Struck in Benghazi, Libya - Up to Six Uncrewed Surface Vessels Suspected as Maritime Attacks Spread to the Mediterranean", "kSum": "11월 21일 리비아 벵가지항에서 러시아 해군 코르벳 Merkury가 폭발 뒤 옆으로 누운 채 가라앉았고, 이어 제재 대상 러시아 군수 화물선 Ascalon과 몰타 선적 선박 1척도 공격받은 것으로 전해졌다. 폭발물을 실은 무인 수상정 최대 6척이 쓰인 것으로 추정되며 공격 주체는 확인되지 않았다. Ascalon 등은 10월 31일 칼리닌그라드를 떠나 AIS를 끈 채 항해해 왔다. 리비아 앞바다에서는 앞서 유조선 Qendil과 화물선 Lady Mariia도 공격받았다.", "eSum": "On 21 November the Russian Navy corvette Merkury sank on its side after an explosion in Benghazi harbour, and the sanctioned Russian military cargo ship Ascalon and a Maltese-flagged vessel were reportedly also attacked. Up to six explosive-laden uncrewed surface vessels are suspected and the attacker has not been confirmed. Ascalon and another ship left Kaliningrad on 31 October and had sailed without AIS. Earlier attacks off Libya hit the tanker Qendil and the cargo ship Lady Mariia.", "kImp": "러시아 관련 선박을 노린 공격이 지중해 항만 안까지 들어왔다. 선박관리사는 리비아 등 해당 항만 기항 전 같은 부두의 정박 선박을 확인하고, 항만 내 정박 중 보안 경계 수준을 높일 것.", "eImp": "Attacks on Russian-linked ships have reached inside Mediterranean ports. Before calling at Libya or similar ports, managers should check which ships share the berth area and raise security watch levels while alongside or at anchor.", "url": "https://maritime-executive.com/article/massive-attack-on-russian-shipping-in-benghazi", "prio": 1}, {"code": "OPS", "date": "2026-11-18", "src": "Deccan Chronicle", "title": "인도, 선박 운항 연령 상한 완화 — 20년 넘은 유조선도 개별 면제 신청 가능, 2029년 3월 퇴출 시한 폐지", "eTitle": "India Relaxes Ship Age Limits - Tankers Over 20 Years Old May Seek Case-by-Case Exemptions and the March 2029 Phase-Out Deadline Is Scrapped", "kSum": "인도 해사청(Directorate General of Maritime Administration)은 11월 18일자 명령으로 선박 운항 연령 상한을 개별 면제 제도로 바꿨다. 20년이 넘은 유조선과 25년이 넘은 가스·케미컬 운반선도 면제를 신청할 수 있고, 5명의 기술위원회가 권고하면 당국이 수용·거부·수정한다. 기존 선박이 연령 기준을 맞춰야 했던 2029년 3월 시한도 없앴다. 적용 대상은 인도 선적선과 인도에서 영업 허가가 필요한 외국 선박이다. 당국은 미·이란 전쟁에 따른 유조선 부족과 높은 운임, 자국 선대 확대를 이유로 들었다. 등록 요건도 바뀌어 15년 미만 선박은 IACS 선급이 아니어도 되고, 15~20년 유조선은 조건부 등록, 그 이상은 당국 평가를 받는다.", "eSum": "In an order dated 18 November India's Directorate General of Maritime Administration replaced hard age limits with case-by-case exemptions. Oil tankers over 20 years old and gas or chemical carriers over 25 may apply, and a five-member technical committee makes recommendations that the regulator can accept, reject or modify. The March 2029 deadline for existing ships to comply was scrapped. The rules cover Indian-flagged ships and foreign ships that need Indian operating licences. The regulator cited a tanker shortage tied to the US-Iran war, high freight rates and plans to expand the domestic fleet. Registration rules also change: ships under 15 years no longer need IACS class, tankers aged 15-20 can register under conditions and older ones need a regulatory assessment.", "kImp": "고령선 인도 영업 길이 다시 열렸지만 면제는 개별 심사다. 인도 용선·기항이 있는 고령 유조선·가스선 관리사는 면제 신청에 필요한 선체 두께 계측·검사 이력·PSC 기록을 미리 정리하고, IACS 비회원 선급 선박의 인도 등록 요건 변화도 확인할 것.", "eImp": "Older ships can trade to India again, but each exemption is assessed individually. Managers of older tankers and gas carriers chartered to or calling in India should prepare thickness measurements, survey history and PSC records for an application, and check the changed rules for ships classed outside IACS.", "url": "https://www.deccanchronicle.com/business/india-relaxes-age-limits-on-ships-as-freight-markets-tighten-2005883", "prio": 2}, {"code": "OPS", "date": "2026-11-20", "src": "The Maritime Executive", "title": "아덴만 발할 남동 60해리서 소형선이 벌크선에 총격 — 무장 경비원 경고 사격, 11월 17일에 이은 해적 활동 재개 신호", "eTitle": "Skiff Opens Fire on a Bulker 60 Miles South-East of Balhaf in the Gulf of Aden - Armed Guards Fire Warning Shots; a Second Incident After 17 November Signals Renewed Piracy", "kSum": "11월 20일 예멘 발할 남동쪽 약 60해리 아덴만에서 소형선(스키프)이 약 100m까지 접근해 벌크선에 총격을 가했다. 승선한 무장 경비원이 경고 사격을 하자 소형선은 물러났다. 11월 17일에도 비슷한 접근 사건이 있었다.", "eSum": "On 20 November a skiff closed to about 100 metres of a bulker some 60 nautical miles south-east of Balhaf, Yemen, in the Gulf of Aden, and fired on it. Armed guards on board fired warning shots and the skiff withdrew. A similar approach was reported on 17 November.", "kImp": "홍해·아덴만 해적 위협이 다시 커지고 있다. 아덴만 통항선은 BMP 해적 대응 조치(견시 증원·시타델·속력 유지)를 다시 점검하고, 무장 경비원 승선 여부를 통항 전 위험평가로 결정할 것.", "eImp": "The piracy threat in the Red Sea and Gulf of Aden is rising again. Ships transiting the Gulf of Aden should recheck BMP counter-piracy measures (extra lookouts, citadel, speed) and decide on armed guards through a pre-transit risk assessment.", "url": "https://maritime-executive.com/article/skiff-shoots-at-bulker-as-pirates-renewed-efforts-in-gulf-of-aden", "prio": 2}, {"code": "OPS", "date": "2026-11-21", "src": "Jerusalem Post(UKMTO)·Al Jazeera", "title": "호르무즈 하사브 앞에서 출항 유조선 2척 50분 간격 피격 — 선미·기관실에 미확인 발사체, 이란 해군은 '제한 수역서 기뢰 접촉 유조선 화재' 주장", "eTitle": "Two Outbound Tankers Hit 50 Minutes Apart off Khasab in the Strait of Hormuz - Unidentified Projectiles Strike a Stern and an Engine Room; Iran's Navy Claims a Tanker Caught Fire After Hitting a Mine in a Restricted Area", "kSum": "영국 해사무역기구(UKMTO)에 따르면 11월 21일 오전 5시쯤(UTC) 호르무즈 해협을 빠져나가던 유조선 1척이 오만 하사브 북쪽 약 11해리에서 선미에 미확인 발사체를 맞았다. 약 50분 뒤인 05시 50분에는 하사브 동쪽 17해리에서 또 다른 출항 유조선이 기관실에 피격됐다(UKMTO 경보 215-26). 두 건 모두 사상자는 보고되지 않았으나 환경 피해 여부는 확인되지 않았다. 하루 전인 11월 20일에도 하사브 북쪽 8해리에서 출항 유조선이 발사체를 맞아 화재가 났다고 회사 보안책임자(CSO)가 보고했다. 이란 해군은 해협 동쪽 제한 수역에서 유조선이 기뢰에 닿아 불이 났다고 주장했다. 같은 해역에서 11월 16일 TARA GAS, 17일 Navig8 Messi에 이어 닷새 동안 피격이 이어지고 있다.", "eSum": "According to UKMTO, at about 05:00 UTC on 21 November a tanker sailing outbound through the Strait of Hormuz was hit on its stern by an unidentified projectile about 11 nautical miles north of Khasab, Oman. About 50 minutes later, at 05:50 UTC, a second outbound tanker was hit in its engine room 17 nautical miles east of Khasab (UKMTO warning 215-26). No casualties were reported in either case; environmental impact is unconfirmed. On 20 November another outbound tanker was struck 8 nautical miles north of Khasab and its company security officer reported a fire on board. Iran's navy claims a tanker caught fire after hitting a naval mine in a restricted area east of the strait. Attacks in these waters have now continued for five days, following TARA GAS on 16 November and Navig8 Messi on 17 November.", "kImp": "피격이 하사브 북쪽 8~17해리, 출항 통항선에 집중되고 있다. 선박관리사는 호르무즈 출항 통항을 계획한 선박에 대해 통항 시각(새벽 시간대 집중)과 항로를 다시 검토하고, 기관실·선미 피격을 가정한 손상통제와 기관실 퇴거 훈련, UKMTO 보고 절차를 통항 전에 확인할 것. 기뢰 주장이 나온 만큼 제한 수역 경계를 해도에 반영했는지도 점검할 것.", "eImp": "Attacks are concentrating on outbound transits 8-17 nautical miles off Khasab. Managers should review the timing (attacks cluster around dawn) and routing of planned outbound Hormuz transits, confirm damage control and engine-room evacuation drills for a stern or engine-room hit and the UKMTO reporting procedure before transit, and, given the mine claim, check that restricted-area limits are plotted on the charts.", "url": "https://www.jpost.com/middle-east/article-915628", "prio": 3}, {"code": "OPS", "date": "2026-11-19", "src": "Iran International·Anadolu(이란 혁명수비대 발표)", "title": "이란 혁명수비대 '초대형 유조선 2척이 호르무즈 제한 항로에서 기뢰에 접촉해 폭발' 주장 — 원유 400만 배럴 이상 적재, 선주·기국 확인은 아직 없어", "eTitle": "Iran's Revolutionary Guards Claim Two Supertankers Hit Mines and Exploded on a 'Restricted Route' in Hormuz - More Than 4 Million Barrels of Crude on Board; No Confirmation Yet From Owners or Flag States", "kSum": "이란 혁명수비대 해군 공보실은 11월 19일 초대형 유조선 2척이 호르무즈 해협의 '제한 항로'를 몰래 지나려다 기뢰에 접촉해 폭발했다고 발표했다. 두 선박은 합쳐 400만 배럴이 넘는 원유를 실었고 해협 남쪽 해안 가까이에서 불타고 있으며 선원들은 배를 버렸다고 주장했다. 미군 전투기와 무인기의 지원을 받고 있었다는 주장도 덧붙였다. 선박 이름은 공개되지 않았고, 보도 시점 기준으로 선주·기국·서방 해군의 확인은 나오지 않았다. 시장 분석 매체는 혁명수비대 발표가 나중에 확인된 사실과 달랐던 전례가 있다고 짚었다.", "eSum": "The public relations office of the IRGC Navy said on 19 November that two supertankers struck naval mines and exploded while trying to pass covertly through a 'restricted route' in the Strait of Hormuz. It claimed the ships carried more than 4 million barrels of crude between them, were burning near the strait's southern coast and had been abandoned, and that they had support from US fighter jets and surveillance drones. The ships were not named, and at the time of reporting there was no confirmation from owners, flag states or Western navies. A market news service noted that IRGC statements have at times diverged from what was later confirmed.", "kImp": "확인되지 않은 주장이지만 기뢰 위험이 공식 발표에 등장한 것 자체가 변화다. 선박관리사는 통항 항로가 권고 통항로 안인지 다시 확인하고, 기뢰 접촉에 대비한 수밀 구획 폐쇄·선수 견시·손상 통제 훈련을 통항 전 점검표에 넣을 것. 사실 여부는 UKMTO와 JMIC 공지로 확인할 것.", "eImp": "The claim is unverified, but the appearance of a mine threat in an official statement is itself a change. Managers should re-check that planned tracks stay within recommended transit corridors and add watertight closure, bow lookout and damage control drills for a mine strike to pre-transit checklists. Verify the facts through UKMTO and JMIC advisories.", "url": "https://www.iranintl.com/en/202611195706", "prio": 3}, {"code": "OPS", "date": "2026-11-19", "src": "The Maritime Executive", "title": "미 의회 자문위 '중국의 파나마 선적선 집중 점검은 경제적 강압' — 월 21건에서 5월 140건으로 급증, 약 500척 점검. 제재 권한 부여 권고", "eTitle": "US Congressional Commission Calls China's Inspection Drive Against Panama-Flagged Ships 'Economic Coercion' - Inspections Rose From About 21 a Month to 140 in May, Roughly 500 Ships in All; Sanctions Authority Recommended", "kSum": "미·중 경제안보검토위원회가 11월 18일 의회에 낸 705쪽 연례 보고서에서 중국의 파나마 선적선 점검을 '경제적 강압'으로 규정했다. 점검은 평소 월 21건쯤에서 2026년 5월 140건으로 늘었고, 중국이 파나마와 협의한 뒤 7월에 조용히 끝낼 때까지 약 500척이 점검받았다. 중국은 파나마 대법원이 CK허치슨의 발보아·크리스토발 터미널 운영권을 무효로 한 데 대한 보복이라는 해석을 부인하고 어선 충돌 같은 안전사고를 이유로 들었다. 이 기간 파나마 등록을 떠난 선박은 4월 80척 이상, 5월 150척이었다. 위원회는 연방해사위원회(FMC)가 조사해 90일 안에 보고하고, 대통령에게 경제 조치와 제재로 대응할 권한을 주라고 권고했다.", "eSum": "The US-China Economic and Security Review Commission's 705-page annual report, delivered to Congress on 18 November, describes China's inspections of Panama-flagged ships as 'economic coercion'. Inspections rose from about 21 a month to 140 in May 2026, and roughly 500 ships were inspected before China quietly ended the effort in July after talks with Panama. China denied it was retaliation for the Panamanian Supreme Court's annulment of CK Hutchison's concession for the Balboa and Cristobal terminals, citing safety incidents such as collisions with fishing vessels. More than 80 ships left Panama's registry in April and another 150 in May. The commission recommends a Federal Maritime Commission investigation reporting within 90 days and authority for the president to respond with economic measures and sanctions.", "kImp": "항만국통제가 외교 분쟁의 수단이 될 수 있음을 보여 준 사례다. 선박관리사는 기국 선택과 변경을 검토할 때 기국의 PSC 성적뿐 아니라 주요 기항국과의 정치적 관계를 위험 요인으로 넣고, 특정 기국 선박에 점검이 몰릴 때는 결함 지적 내용을 선대 전체에 바로 공유할 것.", "eImp": "The episode shows port state control being used as a tool in a diplomatic dispute. When reviewing a choice or change of flag, managers should weigh the flag's political relations with major port states alongside its PSC record, and share findings across the fleet at once when inspections concentrate on one flag.", "url": "https://maritime-executive.com/article/us-committee-urges-sanctions-over-china-s-detention-of-panama-flagged-ships", "prio": 3}, {"code": "OPS", "date": "2026-11-18", "src": "The Maritime Executive(UKMTO)", "title": "호르무즈에서 ADNOC 제품운반선 Navig8 Messi 피격 — 선원 1명 실종·11명 부상, 전쟁 이후 ADNOC 선박 피격 최소 20척", "eTitle": "ADNOC Product Tanker Navig8 Messi Struck Near Hormuz - One Crew Member Missing and 11 Injured; at Least 20 ADNOC Vessels Hit Since the Conflict Began", "kSum": "아부다비 국영 석유회사 계열 ADNOC Logistics & Services는 자사 운항 제품운반선 Navig8 Messi(7만 5,681 dwt, 2011년 건조, 라이베리아 선적)가 11월 17일 밤 호르무즈 해협 근처에서 피격돼 선원들이 배를 버렸다고 확인했다. 영국 해사무역기구(UKMTO)는 위치를 오만 하사브 북쪽 약 13해리로 전했고 화재는 꺼졌다고 밝혔다. 선원 1명이 실종돼 수색이 진행 중이며 11명이 다쳐 치료를 받고 있다. 이 배는 8월 중순에도 피격된 적이 있는 것으로 전해졌다. ADNOC 선박은 전쟁이 시작된 뒤 최소 20척이 공격받았다. 하루 전 같은 해역에서 LPG선 TARA GAS가 두 차례 피격됐다.", "eSum": "ADNOC Logistics & Services confirmed that the product tanker Navig8 Messi (75,681 dwt, built 2011, Liberian-registered) was struck overnight on 17 November while outbound near the Strait of Hormuz and that the crew abandoned ship. UKMTO placed it about 13 nautical miles north of Khasab, Oman, and said the fire was extinguished. One crew member is missing and a search is under way; eleven others were injured and are being treated. The ship was reportedly also struck in mid-August. At least 20 ADNOC vessels have been hit since the conflict began. A day earlier the LPG tanker TARA GAS was hit twice in the same waters.", "kImp": "같은 해역에서 이틀 연속 선원이 실종됐다. 선박관리사는 호르무즈 통항선의 인원 확인(머스터) 방식과 실종자 발생 때의 수색·보고 순서, 부상자 다수 발생에 대비한 선내 응급 처치 물자와 오만 측 의료 이송 연락망을 통항 전 점검할 것.", "eImp": "Seafarers have gone missing in the same waters on two consecutive days. Before a Hormuz transit managers should check the muster and head-count method, the search and reporting sequence for a missing person, first-aid supplies for multiple casualties and contacts for medical evacuation to Oman.", "url": "https://maritime-executive.com/article/seafarer-is-missing-as-iran-continues-attacks-on-adnoc-tankers", "prio": 3}, {"code": "OPS", "date": "2026-11-19", "src": "쉬핑뉴스넷(KMI)", "title": "KMI 주간 집계: 호르무즈 통항 83회로 평시의 9.8% — AIS 끈 통항 55.4%, 선박 피격 7건, 오만만 대기 원유선 197척(개전 전의 1.9배)", "eTitle": "KMI Weekly Count: 83 Hormuz Transits, 9.8% of Normal - 55.4% With AIS Off, Seven Ships Struck and 197 Crude Tankers Waiting in the Gulf of Oman, 1.9 Times the Pre-War Average", "kSum": "한국해양수산개발원(KMI) 주간 보고서에 따르면 11월 7~13일 호르무즈 해협 통항은 83회로 전주보다 32.0% 줄어 평시의 9.8% 수준에 그쳤다. 원유운반선 통항은 4회에서 7회로, 컨테이너선은 5회에서 7회로 늘었다. AIS를 끈 채 지나간 경우가 46회로 전체의 55.4%였다. 선박 피격은 7건으로 전주보다 늘었고 그중 4건은 해협 안에서 일어났다. 오만만에서 기다리는 원유운반선은 197척으로 개전 전 평균의 약 1.9배다.", "eSum": "The Korea Maritime Institute's weekly report counts 83 transits of the Strait of Hormuz in 7-13 November, down 32.0% on the previous week and just 9.8% of normal. Crude tanker transits rose from four to seven and container ship transits from five to seven. Forty-six transits, 55.4% of the total, were made with AIS switched off. Seven ships were struck, more than the week before, four of them inside the strait. There were 197 crude tankers waiting in the Gulf of Oman, about 1.9 times the pre-war average.", "kImp": "통항의 절반 이상이 AIS를 끄고 이뤄진다. 선박관리사는 AIS 정지 운항을 할 때 기국·보험자 통보와 항해기록 유지, 주변 선박과의 충돌 예방 조치(레이더 감시 강화, VHF 호출)를 통항 절차에 적어 둘 것.", "eImp": "More than half of transits are made with AIS off. Managers should set out in transit procedures the notifications to flag and insurers, record-keeping and collision-avoidance measures, such as closer radar watch and VHF calls, that apply when AIS is switched off.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=73111", "prio": 2}, {"code": "OPS", "date": "2026-11-17", "src": "Lloyd's Register", "title": "로이드선급, 자동차운반선 전기차 화재용 선급부호 'FIRE (EV)' 신설 — 감지·구조 방화·통풍·소화·소방 장비를 설계 단계에서 요구", "eTitle": "Lloyd's Register Introduces the FIRE (EV) Notation for Electric Vehicle Fires on Car Carriers - Detection, Structural Fire Protection, Ventilation, Suppression and Firefighting Equipment Set at the Design Stage", "kSum": "로이드선급(LR)이 전기차 화재가 시작된 구역 밖으로 번지지 않게 하는 설계 요건을 담은 특수 선급부호 'FIRE (EV)'를 내놨다. 화재 감지, 구조 방화, 통풍, 소화, 소방 장비·설비를 다루며 로로선, 로팩스선, 자동차운반선(PCC), 자동차·트럭운반선(PCTC)에 적용한다. 요건은 2026년 7월판 LR 선급규칙 6편 6장에 들어갔다. LR은 리튬이온 배터리가 고장 나면 열폭주로 진화가 어려운 화재가 나고 독성·부식성 가스가 나온다는 점을 근거로 들었다. 선원 교육은 이 부호의 범위 밖이다. 신조선과 현존선 중 어디에 적용하는지는 발표문에 없다.", "eSum": "Lloyd's Register has introduced the FIRE (EV) special feature notation, with design requirements to stop an electric vehicle fire spreading beyond the space where it starts. It covers fire detection, structural fire protection, ventilation, suppression and firefighting equipment and systems, and applies to RoRo and RoPax ships, PCCs and PCTCs. The requirements sit in Part 6, Chapter 6 of LR's July 2026 Rules. LR cites thermal runaway in lithium-ion batteries, which produces fires that are hard to control and release toxic and corrosive gases. Crew training is outside the notation's scope, and the announcement does not say whether it is aimed at newbuildings, existing ships or both.", "kImp": "선급이 전기차 화재를 '설계 요건'으로 묶기 시작했다. 자동차선 관리사는 관리선의 현재 설비(감지기 종류와 배치, 갑판 구획, 통풍 차단, 고정식 소화설비, 전기차 화재 장비)를 이 부호의 항목과 나란히 놓아 차이를 정리해 두고, 신조·개조 협의와 용선자 질의에 쓸 것. 설비와 별개로 선원 훈련은 계속 관리사 몫이다.", "eImp": "Class is starting to treat EV fires as a design requirement. Car carrier managers should set each ship's current outfit (detector types and layout, deck subdivision, ventilation shutdown, fixed systems, EV firefighting gear) against the notation's headings and keep the gap list for newbuilding and retrofit talks and charterer questions. Crew training remains the manager's job regardless of the notation.", "url": "https://allaboutshipping.co.uk/2026/11/17/lloyds-register-introduces-new-notation-to-tackle-ev-fire-risks-on-car-carriers/", "prio": 3}, {"code": "OPS", "date": "2026-11-17", "src": "gCaptain(UKMTO)", "title": "[후속] 호르무즈 피격 LPG선은 파나마 선적 TARA GAS — 두 번째 타격 뒤 선원 25명 퇴선, 인도 선원 1명 실종·2명 부상", "eTitle": "[Follow-up] The LPG Tanker Hit in Hormuz Is the Panama-Flagged TARA GAS - 25 Crew Abandon Ship After a Second Strike, One Indian Seafarer Missing and Two Injured", "kSum": "11월 16일 오만 하사브 북쪽 약 7해리에서 공격받아 기관실 화재로 멈춰 섰던 선박은 파나마 선적 LPG 운반선 TARA GAS로 확인됐다. 영국 해사무역기구(UKMTO)는 17일 경보 208-26을 갱신해 이 선박이 두 번째 타격을 받았다고 알렸다. 첫 공격은 16일 19시(UTC)쯤이었다. 선원 25명은 배를 버리고 내렸고, 인도 선원 1명이 실종됐으며 다친 인도 선원 2명은 병원으로 옮겨졌다. 인도 외교부와 항만해운수로부가 자국 선원 피해를 확인했다. 공격 주체는 특정되지 않았다.", "eSum": "The ship left disabled by an engine-room fire about seven nautical miles north of Khasab, Oman, on 16 November has been named as the Panama-flagged LPG tanker TARA GAS. UKMTO updated Warning 208-26 on 17 November to report a second strike on the vessel; the first came at about 1900 UTC on the 16th. The 25 crew abandoned ship. One Indian seafarer is missing and two injured Indian crew were taken to hospital, India's foreign and shipping ministries confirmed. No attribution has been made.", "kImp": "멈춰 선 배가 다시 맞았다. 선박관리사는 호르무즈 통항선에 대해 피격 뒤 '배에 남아 버틸 것인가, 퇴선할 것인가'의 판단 기준(화재 통제 여부, 추진 상실, 재피격 위험)과 퇴선 집결·인원 확인 절차를 선장과 미리 맞추고, 가스선은 화물 구역 살수·비상 차단 절차를 통항 전 점검할 것.", "eImp": "A disabled ship was hit again. Managers should agree with masters, before a Hormuz transit, the criteria for staying aboard or abandoning after a strike (fire control, loss of propulsion, risk of a second hit) and the muster and head-count routine; on gas carriers, check cargo-area water spray and emergency shutdown before transit.", "url": "https://gcaptain.com/second-strike-on-lpg-tanker-in-strait-of-hormuz-leaves-one-missing-two-injured/", "prio": 3}, {"code": "OPS", "date": "2026-11-17", "src": "The Maritime Executive", "title": "흑해 불가리아 앞바다에서 LPG선 Gas Husky 침몰 — 필리핀 선원 19명 헬기로 전원 구조, 7월 중순 이후 서부 흑해 피격 최소 17척", "eTitle": "LPG Carrier Gas Husky Sinks off Bulgaria in the Black Sea - All 19 Filipino Crew Rescued by Helicopter; at Least 17 Ships Struck in the Western Black Sea Since Mid-July", "kSum": "라이베리아 선적 LPG 운반선 Gas Husky(7,218 dwt, 2012년 건조, 그리스 선주·Stealth Gas 운항)가 11월 17일 불가리아 중부 비알라 동쪽 약 50해리에서 침몰했다. 자정 직후 레이더에서 사라졌고, 필리핀 선원 19명은 불가리아 공군 헬기로 모두 구조돼 병원으로 옮겨졌으며 상태는 양호하다. 불가리아 당국은 원인을 밝히지 않았으나 루마니아 해사당국은 무인기 공격으로 추정된다고 알렸다. 불가리아는 10월 초 이후 자국 배타적경제수역에서 피격된 일곱 번째 상선으로 집계했고, 보안업체 Diaplous는 7월 중순 이후 서부 흑해에서 최소 17척이 공격받았다고 본다. 루마니아는 다뉴브 삼각주 앞 정박지를 피하라고 권고했다.", "eSum": "The Liberian-flagged LPG carrier Gas Husky (7,218 dwt, built 2012, Greek-owned and operated by Stealth Gas) sank on 17 November about 50 nautical miles east of Byala on Bulgaria's central coast. It vanished from radar shortly after midnight; all 19 Filipino crew were lifted off by Bulgarian Air Force helicopter and taken to hospital in good condition. Bulgarian officials did not give a cause, but Romania's maritime authority reported a suspected drone strike. Bulgaria counts it as the seventh merchant ship struck in its EEZ since early October, and the security firm Diaplous counts at least 17 ships attacked in the western Black Sea since mid-July. Romania urges ships to avoid the anchorage off the Danube Delta.", "kImp": "서부 흑해는 이제 정박 중인 배뿐 아니라 항해 중인 배도 잃는 해역이 됐다. 선박관리사는 루마니아·불가리아 기항선의 정박 대기를 줄이는 도착 시각 조정, 야간 등화·AIS 운용 방침, 퇴선 훈련 주기를 다시 보고, 전쟁위험 추가 보험료와 선원 동의 절차를 선주·용선자와 확인할 것.", "eImp": "The western Black Sea now costs ships under way as well as at anchor. Managers should review arrival timing to cut waiting at anchor for Romanian and Bulgarian calls, lighting and AIS policy at night and abandon-ship drill intervals, and confirm additional war-risk premiums and crew consent with owners and charterers.", "url": "https://maritime-executive.com/article/crew-rescued-from-sinking-lpg-tanker-off-bulgaria-as-pace-of-attacks-grows", "prio": 2}, {"code": "OPS", "date": "2026-11-16", "src": "Baird Maritime", "title": "[후속] 마이애미에서 PSC 출항정지됐던 크루즈선 MSC Poesia — 미 당국자 '기름 배출 의혹 형사 수사 중', 일부 선원은 조사 위해 마이애미에 남아", "eTitle": "[Follow-up] MSC Poesia, Detained Under PSC in Miami - a US Official Says a Criminal Probe Into Alleged Oil Discharges Is Under Way and Some Crew Stayed in Miami for Questioning", "kSum": "미 해안경비대 마이애미 지구 항만국통제팀이 11월 1일 점검 뒤 출항정지한 크루즈선 MSC Poesia와 관련해, 미 당국자가 기름 배출 의혹에 대한 형사 수사가 진행 중이라고 밝혔다. 해안경비대는 출항정지 사유였던 안전·환경 결함이 고쳐진 것을 확인한 뒤 출항을 허가했고 배는 카리브해 운항을 다시 시작했다. 다만 선원 여러 명은 조사를 받기 위해 마이애미에 남은 것으로 전해졌다. 출항정지 당시 배에는 2,000명 넘게 타고 있었고 운항사는 항차 하나를 취소했다. 해안경비대는 구체적인 결함 내용은 밝히지 않고 있다.", "eSum": "A US official says a criminal investigation is under way into alleged oil discharges from the cruise ship MSC Poesia, which a Coast Guard Sector Miami port state control team detained after an inspection on 1 November. The Coast Guard released the ship once it confirmed the safety and environmental deficiencies had been corrected, and it has resumed Caribbean sailings, but several crew members reportedly stayed in Miami for questioning. More than 2,000 people were on board when the ship was detained and the operator cancelled a voyage. The Coast Guard has not described the deficiencies.", "kImp": "미국에서 MARPOL 결함은 출항정지로 끝나지 않고 형사 사건과 선원 억류로 이어진다. 선박관리사는 미국 기항 전 기름기록부와 유수분리기 작동 기록·봉인 상태, 슬러지 수지를 대조하고, 조사 때 선원의 진술·변호인 조력 절차를 선내 지침으로 갖출 것.", "eImp": "In the United States a MARPOL deficiency does not end with detention; it becomes a criminal case with crew held ashore. Before US calls managers should reconcile the oil record book with oily water separator operating records, seals and the sludge balance, and have onboard guidance on crew statements and access to counsel during an investigation.", "url": "https://www.bairdmaritime.com/passenger/cruise/msc-poesia-oil-discharge-investigation", "prio": 2}, {"code": "OPS", "date": "2026-11-18", "src": "Cyprus Shipping News(Sogese)", "title": "소제세 보고서: 선사들의 11월 운임 인상, 일부만 관철될 듯 — 상하이~제노바 +12.7%·로테르담 +8.3%에도 인상 고시액에 못 미쳐, 북유럽 항만은 선박 몰림 대비", "eTitle": "Sogese Report: Carriers Are Likely to Secure Only Part of Their November Rate Increases - Shanghai-Genoa +12.7% and Shanghai-Rotterdam +8.3% Still Sit Below the Filed Rates; North European Ports Brace for Bunching", "kSum": "컨테이너 임대사 소제세(Sogese)의 유럽 컨테이너 시장 보고서는 선사들이 11월에 고시한 운임 인상분을 일부만 받아낼 것으로 봤다. 드류리 평가로 상하이~제노바 운임은 10월 8일~11월 5일 사이 12.7%, 상하이~로테르담은 8.3% 올랐지만 MSC와 CMA CGM이 11월용으로 고시한 일괄 운임에는 못 미친다. 드류리 세계 컨테이너 지수는 11월 5일 4,389달러로 10월 22일 고점 4,585달러보다 4.3% 낮다. 플렉스포트 자료로는 45주차(11월 2~8일)부터 평소의 129%에 해당하는 선복이 북유럽에 도착하고 있어, 수에즈 복귀와 맞물려 항만 혼잡이 예상된다.", "eSum": "Container lessor Sogese's reading of the European container market expects carriers to secure only part of the rate increases announced for November. On Drewry's assessments Shanghai-Genoa rose 12.7% between 8 October and 5 November and Shanghai-Rotterdam 8.3%, but both remain below the FAK rates filed by MSC and CMA CGM for November. Drewry's World Container Index stood at USD 4,389 on 5 November, 4.3% below its 22 October peak of USD 4,585. Flexport data show 129% of normal capacity arriving in North Europe from week 45 (2-8 November), pointing to bunching at ports as services return to Suez.", "kImp": "수에즈 복귀 초기에는 북유럽 항만에 배가 한꺼번에 몰린다. 선박관리사는 북유럽 기항선의 정박 대기 증가를 전제로 선원 교대·보급·검사 예약을 조정하고, 대기 중 연료·청수 재고 기준을 확인할 것.", "eImp": "In the first weeks of a return to Suez, ships arrive in North Europe in clusters. Managers should adjust crew changes, stores and survey bookings for longer waiting at North European ports and check fuel and fresh water reserves for time at anchor.", "url": "https://cyprusshippingnews.com/2026/11/18/carriers-may-secure-only-part-of-their-november-rate-increases-as-suez-returns-and-north-european-ports-brace-for-bunching-sogese-report-says/", "prio": 2}, {"code": "OPS", "date": "2026-11-17", "src": "The Maritime Executive(EUNAVFOR)", "title": "아덴만에서 해적 의심 접근 잇따라 — 무칼라 남서쪽 50해리에서 무장 경비원이 경고 사격, 소코트라 동쪽 430해리에서는 유조선이 회피", "eTitle": "Suspected Pirate Approaches Continue in the Gulf of Aden - Armed Guards Fire a Warning Shot 50 Miles Off Al Mukalla, and a Tanker Evades a Skiff 430 Miles East of Socotra", "kSum": "11월 17일 예멘 무칼라 남서쪽 약 50해리에서 화물선에 무기와 사다리를 실은 소형 보트가 접근하자 승선 무장 경비원이 경고 사격을 했고 보트는 모선으로 돌아갔다. 하루 전인 16일에는 소코트라 동쪽 약 430해리에서 유조선이 무장한 4명과 사다리가 보이는 보트의 접근 가능성을 보고하고 회피했다. 유럽연합 해군(EUNAVFOR) 아탈란타 작전은 10월 중순 이후 해적 활동이 다시 늘었다고 본다. 10월 작전으로 납치 선박은 7월 17일 나포된 한 척을 빼고 모두 풀려났다.", "eSum": "On 17 November armed guards on a cargo ship about 50 nautical miles south-west of Al Mukalla, Yemen, fired a warning shot at a skiff carrying weapons and ladders, which turned back to its mothership. A day earlier a tanker about 430 nautical miles east of Socotra reported a possible approach by a skiff with four armed people and a ladder, and evaded. EUNAVFOR's Operation Atalanta has noted renewed activity since mid-October. October operations freed all but one seized vessel, taken on 17 July.", "kImp": "모선을 쓰는 해적이 해안에서 430해리 밖까지 나온다. 선박관리사는 아덴만·소말리아 분지 통항선의 BMP 조치(철조망, 물대포, 대피소)와 무장 경비 승선 구간을 인도양 쪽으로 넓게 잡고, 접근 보고 양식과 보고처를 선교에 붙여 둘 것.", "eImp": "Pirates using motherships are operating 430 miles offshore. Managers should extend BMP measures (razor wire, water cannon, citadel) and armed guard coverage further into the Indian Ocean for Gulf of Aden and Somali Basin transits, and post the approach-report format and contacts on the bridge.", "url": "https://maritime-executive.com/article/security-guards-fire-warning-shot-to-stop-boarding-in-gulf-of-aden", "prio": 2}, {"code": "OPS", "date": "2026-11-17", "src": "코리아쉬핑가제트(Port of Gothenburg)", "title": "예테보리항 1~9월 물동량 '안정' — 신차 물량 14% 증가, 에너지 제품 10% 증가", "eTitle": "Port of Gothenburg Reports Stable Freight Flows for January-September - New Car Volumes Up 14% and Energy Products Up 10%", "kSum": "스칸디나비아 최대 항만인 예테보리항이 2026년 1~9월 화물 흐름이 안정적이었다고 밝혔다. 품목별로는 신차 물량이 지난해 같은 기간보다 14% 늘었고 에너지 제품이 10% 늘었다. 기사는 그 밖의 세부 수치를 전하지 않았다. 예테보리는 북유럽 완성차 수출입의 주요 거점이며, 2027년 2분기부터 대규모 액화바이오가스(LBG) 벙커링을 시작할 예정이다.", "eSum": "The Port of Gothenburg, Scandinavia's largest, reported stable freight flows for January-September 2026. New car volumes rose 14% on the same period last year and energy products rose 10%; the report gave no further detail. Gothenburg is a main gateway for Nordic vehicle exports and imports and plans to start large-scale liquefied biogas bunkering in the second quarter of 2027.", "kImp": "북유럽 완성차 물량이 늘고 있다. 자동차선 관리사는 예테보리 기항선의 겨울철 준비(결빙·저온 운용, 램프·유압 장비 예열)와 육상전원·대체연료 벙커링 요건을 기항 전 확인할 것.", "eImp": "Nordic vehicle volumes are rising. Car carrier managers should confirm winter readiness for Gothenburg calls (ice and low-temperature operation, pre-heating of ramps and hydraulics) and shore-power and alternative-fuel bunkering requirements before arrival.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=148516", "prio": 2}, {"code": "OPS", "date": "2026-11-16", "src": "gCaptain", "title": "머스크·하파그로이드, 제미니 협력 아시아-유럽 3개 노선 추가로 수에즈 복귀 — AE2 12월 4일, AE3 12월 20일, AE1 2027년 1월 14일", "eTitle": "Maersk and Hapag-Lloyd Return Three More Gemini Asia-Europe Services to the Suez Canal - AE2 on 4 December, AE3 on 20 December and AE1 on 14 January 2027", "kSum": "머스크와 하파그로이드가 제미니 협력의 아시아-유럽 노선 AE1·AE2·AE3를 희망봉 우회에서 수에즈 운하 통과로 되돌린다. AE2는 12월 4일, AE3는 12월 20일, AE1은 2027년 1월 14일부터다. 두 선사는 수에즈 경유가 항해 거리와 연료 소모를 줄이고 운송 시간을 앞당긴다고 설명했다. 다만 복귀는 '지역 안보 상황에 달려 있다'고 조건을 달았고 중동 정세를 계속 지켜보겠다고 했다. 구체적인 호송·경비 조치는 밝히지 않았다.", "eSum": "Maersk and Hapag-Lloyd will move the Gemini Cooperation's AE1, AE2 and AE3 Asia-Europe services from the Cape of Good Hope back to the Suez Canal: AE2 from 4 December, AE3 from 20 December and AE1 from 14 January 2027. The carriers cite shorter voyages, lower fuel use and faster transits, but say the return depends on regional security conditions and that they will keep monitoring the Middle East. No specific security arrangements were described.", "kImp": "대형 선사의 수에즈 복귀가 넓어지면 희망봉 우회로 묶였던 선복이 풀린다. 선박관리사는 홍해 통항 재개 선박의 보안 평가(BMP 적용, 무장 경비 여부, 통항 시간대)와 선원 동의 절차를 갱신하고, 우회 기준으로 짠 정비·교대 일정을 다시 맞출 것.", "eImp": "A wider return to Suez by the largest carriers releases tonnage tied up on the Cape route. Managers should refresh security assessments for ships resuming Red Sea transits (BMP measures, armed guards, transit timing) and crew consent, and re-align maintenance and crew-change plans built around the Cape routing.", "url": "https://gcaptain.com/maersk-hapag-lloyd-expand-suez-canal-return-with-three-more-gemini-services/", "prio": 2}, {"code": "OPS", "date": "2026-11-16", "src": "gCaptain(UKMTO)", "title": "UKMTO: 호르무즈 해협에서 하루 유조선 2척 피격 — 두 척 모두 기관실 화재, 한 척은 하사브 북쪽 7해리에서 항행 불능. 11월 들어 무산담 앞바다 공격 5건", "eTitle": "UKMTO: Two Tankers Attacked in the Strait of Hormuz in One Day - Engine-Room Fires on Both, One Left Disabled Seven Miles North of Khasab; Five Attacks off Musandam Since 1 November", "kSum": "영국 해사무역기구(UKMTO)는 11월 16일 호르무즈 해협에서 유조선 2척이 공격받았다고 각각 경보를 냈다. 첫 번째 선박은 협정세계시(UTC) 05시 58분쯤 해협을 빠져나오던 중 미확인 발사체에 맞아 기관실에 불이 났고, 선원은 모두 무사하다. 두 번째 선박은 19시(UTC)쯤 오만 하사브 북쪽 약 7해리에서 공격받아 기관실 화재로 항행 불능이 됐으며 선원은 안전하다고 보고됐다. 선명과 선적은 공개되지 않았고 공격 주체도 특정되지 않았다. 합동해사정보센터(JMIC)는 11월 1일 이후 무산담 앞바다에서 5건의 공격이 있었다고 집계했다.", "eSum": "UKMTO issued separate warnings on 16 November for two tankers attacked in the Strait of Hormuz. The first, outbound at about 0558 UTC, was hit by an unidentified projectile that started an engine-room fire; all crew are accounted for. The second was attacked at about 1900 UTC roughly seven nautical miles north of Khasab, Oman, and left disabled with an engine-room fire; its crew were reported safe. Names and flags were not given and no attribution has been made. JMIC counts five attacks off Musandam since 1 November.", "kImp": "기관실을 노린 피격이 하루 두 번 나왔다. 선박관리사는 호르무즈 통항선의 기관실 화재 대응(고정식 소화설비 작동 준비, 비상 조타·예인 준비, 기관실 최소 인원 배치)과 통항 전후 보고 절차를 다시 확인하고, 전쟁위험 보험 통지 요건을 선주와 점검할 것.", "eImp": "Two strikes on engine rooms in one day. Managers should re-check engine-room fire readiness for Hormuz transits (fixed systems ready, emergency steering and towing prepared, minimum manning below), the reporting routine before and after transit, and war-risk notification terms with owners.", "url": "https://gcaptain.com/ukmto-reports-two-tanker-attacks-in-strait-of-hormuz/", "prio": 3}, {"code": "OPS", "date": "2026-11-17", "src": "Hellenic Shipping News(NAPA)", "title": "NAPA 기고: '화물 고박 준수는 매뉴얼이 아니라 갑판에서 시작된다' — PSC는 화물고박지침서, 선원 숙지도, 장비 상태, 기록, 황천 절차를 본다", "eTitle": "NAPA: 'Cargo Securing Compliance Starts on Deck, Not in the Manual' - Inspectors Check the Cargo Securing Manual, Crew Familiarity, Equipment Condition, Records and Heavy-Weather Procedures", "kSum": "NAPA Safety Solutions의 토미 비하바이넨과 사미 코포넨은 화물 고박 실패가 선원·선박·환경을 위험하게 하고, 결함 지적은 선박 위험도를 높이거나 출항정지로 이어질 수 있다고 썼다. 핵심 문제는 '승인된 절차서'와 선원이 실제로 하는 일 사이의 간격이다. 검사관은 SOLAS 준수 여부를 화물고박지침서(CSM), 선원의 숙지 정도, 고박 장비 상태, 기록, 황천 대비 절차로 확인한다. 저자들은 고박 절차를 일상 업무에 넣고, 조치를 한 그 시점에 기록하며, 황천 절차를 안전관리체제에 남기라고 권고했다(자사 체크리스트·로그북 제품 소개 포함).", "eSum": "Tommi Vihavainen and Sami Koponen of NAPA Safety Solutions write that securing failures endanger crews, ships and the environment, and that deficiencies can raise a ship's risk profile or lead to detention. The core gap is between an approved procedure on paper and what crews actually do. Inspectors verify SOLAS compliance through the Cargo Securing Manual, crew familiarity, equipment condition, documentation and heavy-weather procedures. The authors advise building securing into daily routines, recording actions as they happen and logging heavy-weather procedures in the SMS; the piece also promotes the company's checklist and logbook products.", "kImp": "자동차선은 래싱 수가 많아 '기록과 실제의 차이'가 가장 쉽게 드러나는 선종이다. 자동차선 관리사는 항차별 래싱 점검 기록(구역·시각·담당자), 황천 전 재점검 기록, 래싱 장비 폐기 기준을 PSC 사전 점검 항목에 넣을 것.", "eImp": "Car carriers, with their sheer number of lashings, are where a gap between records and reality shows first. Car carrier managers should add per-voyage lashing check records (zone, time, person), pre-heavy-weather re-checks and discard criteria for lashing gear to their pre-PSC checks.", "url": "https://www.hellenicshippingnews.com/cargo-securing-compliance-starts-on-deck-not-in-the-manual/", "prio": 3}, {"code": "OPS", "date": "2026-11-12", "src": "Marine Insight(파나마운하청)", "title": "[기관 공지] 파나마 운하, 하루 통항 34회로 늘리고 네오파나막스 최대 흘수 50피트 복원 — 수위 회복, 9월 감축 이전 수준에는 아직 못 미쳐", "eTitle": "[Institution notice] Panama Canal Raises Daily Transits to 34 and Restores the 50-Foot Neopanamax Draft - Lake Levels Recover but Slots Remain Below the Level Before September's Cuts", "kSum": "파나마운하청(ACP)은 11월 9일 공지로 하루 통항 가능 횟수를 33회에서 34회로 늘리고 네오파나막스 갑문 최대 흘수를 50피트로 올렸다(즉시 시행, 추후 공지 때까지). 호수 수위 개선, 양호한 수문 전망, 갑문의 절수 조치가 배경이다. 슈퍼급 선박 예약 슬롯이 1개 늘어 하루 19개가 됐고 파나막스 갑문은 24개, 네오파나막스 갑문은 10개다. 2026년은 5~8월 강수량이 평년에 못 미쳐 9월에 슬롯을 줄였고 10월 15일 33회로 되돌렸지만 9월 감축 이전보다는 여전히 적다. 운하청은 예약 없이 도착하면 지연이 클 수 있다며 사전 예약을 당부했다.", "eSum": "In an advisory of 9 November the Panama Canal Authority raised daily transit capacity from 33 to 34 slots and lifted the maximum draught for the Neopanamax locks to 50 feet, effective immediately until further notice, citing better lake levels, favourable hydrological forecasts and water-saving measures at the locks. Super-category vessels gain one slot, to 19 a day; the Panamax locks have 24 booking slots and the Neopanamax locks 10. After below-average rain from May to August, slots were cut in September and returned to 33 on 15 October, and the canal still has fewer than before the cuts. The authority urges advance booking, warning of significant delays for ships arriving without a reservation.", "kImp": "슬롯이 늘었어도 예약 없는 통항은 여전히 위험하다. 선박관리사는 파나마 통과 항차의 예약 확보 여부와 흘수 제한을 출항 전 운항사와 확인하고, 대기 시 선원 교대·연료·주부식 여유를 계획에 넣을 것.", "eImp": "More slots do not make an unbooked transit safe. Managers should confirm booking status and draught limits with operators before sailing on Panama voyages and allow for crew changes, fuel and provisions if a wait is likely.", "url": "https://www.marineinsight.com/panama-canal-raises-daily-transits-to-34-and-restores-50-foot-neopanamax-draft-as-water-levels-recover/", "prio": 2}, {"code": "OPS", "date": "2026-11-10", "src": "BIMCO", "title": "[기관 지침] BIMCO, IMDG 코드 43-26 개정의 차량·배터리 규정 안내 — 2027년 1월 1일 자발 적용·2028년 1월 1일 의무, 선적 전 차량 평가와 면제 규정 개정", "eTitle": "[Institution guidance] BIMCO Issues Guidance on IMDG Code Amendment 43-26 for Vehicles and Batteries - Voluntary From 1 January 2027, Mandatory From 1 January 2028, With Pre-Shipment Vehicle Assessments and Revised Exemptions", "kSum": "BIMCO가 11월 10일 IMDG 코드 43-26 개정 가운데 차량 운송과 배터리 화물에 관한 변경 사항을 정리한 지침을 냈다. 개정은 2027년 1월 1일부터 주관청이 전부 또는 일부를 자발적으로 적용할 수 있고 2028년 1월 1일부터 의무다. 차량 부문은 선적 전 차량 평가, 면제 규정 개정, 컨테이너 표찰 요건이 바뀐다. 배터리 부문은 컨테이너형 배터리 전력 시스템, 하이브리드 배터리, 재사용 배터리에 대한 규정이 새로 들어간다. BIMCO는 전기차 운송용 계약 조항을 2027년 1월까지 내고 배터리 단독 조항도 이어서 만들 예정이다. 지침 전문은 회원 전용이다.", "eSum": "On 10 November BIMCO issued guidance on the parts of IMDG Code Amendment 43-26 that cover vehicle shipments and battery cargoes. Administrations may apply the amendment in whole or in part voluntarily from 1 January 2027 and it becomes mandatory on 1 January 2028. For vehicles the changes include pre-shipment vehicle assessments, revised exemptions and container placarding requirements; for batteries, new provisions on containerised battery power systems, hybrid batteries and battery reuse. BIMCO is also developing a contract clause for carrying electric vehicles, expected by January 2027, with a standalone battery clause to follow. The full guidance is for members.", "kImp": "자동차선의 화물 인수 기준이 바뀐다. 선박관리사는 화주·운항사와 함께 선적 전 차량 평가 결과를 누가 어떤 서식으로 본선에 주는지 정하고, 화물 인수 절차·위험물 적하목록·선원 교육을 2027년 1월 전에 개정할 것.", "eImp": "Cargo acceptance rules for car carriers are changing. Managers should agree with shippers and operators who gives the ship the pre-shipment vehicle assessment and in what form, and revise cargo acceptance procedures, dangerous goods manifests and crew training before January 2027.", "url": "https://www.bimco.org/news-insights/bimco-news/2026/11/10-ev-imdg/", "prio": 3}, {"code": "OPS", "date": "2026-11-14", "src": "gCaptain(Reuters)", "title": "이란 해군 '호르무즈 동부에서 유조선이 기뢰에 접촉해 화재' — 전날 LNG선 폭발 발표에 이어 이틀 연속 기뢰 피해 주장, 이란은 바레인의 미군 레이더도 타격", "eTitle": "Iran's Navy Says an Oil Tanker Is on Fire After Hitting a Mine in the Eastern Strait of Hormuz - a Second Mine Claim in Two Days as Iran Also Says It Hit a US Radar in Bahrain", "kSum": "이란 국영 매체는 11월 14일 오전 호르무즈 해협 동부에서 유조선 1척이 기뢰에 접촉한 뒤 불이 났다고 이란 해군을 인용해 보도했다. 선명과 인명 피해는 공개되지 않았고 로이터는 이를 독자적으로 확인하지 못했다. 전날 혁명수비대 해군은 LNG 운반선이 '허가받지 않은 위험한 항로'에서 기뢰에 접촉해 폭발했다고 발표했다. 혁명수비대는 13일 호르모즈간주 통신탑 공습에 대한 보복이라며 바레인의 미군 조기경보 레이더를 겨냥했다고도 밝혔는데, 걸프 국가 안의 미군 자산 공격 주장은 9월 초 이후 처음이다. 이란은 해협 통항을 제한하고 규정을 어겼다고 판단한 선박을 공격해 왔다.", "eSum": "Iranian state media, citing the navy, said an oil tanker caught fire on the morning of 14 November after hitting a naval mine in the eastern Strait of Hormuz. No ship name or casualty figure was given and Reuters could not verify the report. A day earlier the Revolutionary Guards navy said an LNG carrier struck a mine and exploded on an 'unauthorised and dangerous route'. The Guards also said on 13 November that they targeted a US early-warning radar in Bahrain in retaliation for an air strike on a telecoms tower in Hormozgan, their first claimed attack on US assets in a Gulf state since early September. Iran restricts transit and has attacked ships it says broke its rules.", "kImp": "기뢰 피해 주장이 이틀 연속 나왔다. 선박관리사는 걸프 기항선의 항차 위험평가에 기뢰 항목(선수 견시, 수밀문 폐쇄, 침수·화재 동시 대응, 기관실 무인화 중지)을 넣고, 항로 선택의 근거와 전쟁위험 보험 통지 내용을 문서로 남길 것.", "eImp": "Mine damage has now been claimed on two consecutive days. Managers should add a mine section to voyage risk assessments for Gulf calls (bow lookout, watertight doors closed, combined flooding and fire response, engine room manned) and document the basis for route choice and war-risk notifications.", "url": "https://gcaptain.com/oil-tanker-on-fire-after-hitting-mine-in-hormuz/", "prio": 2}, {"code": "OPS", "date": "2026-11-14", "src": "쉬핑뉴스넷", "title": "파나마운하, 하루 예약 슬롯 34척으로 확대·네오파나막스 최대 흘수 15.24m로 상향 — 9월 32척까지 줄였다가 수위 회복으로 복원", "eTitle": "Panama Canal Raises Daily Booking Slots to 34 and the Neopanamax Maximum Draft to 15.24 m - Restoring Capacity Cut to 32 Slots in September as Water Levels Recover", "kSum": "파나마운하청이 하루 통항 예약 슬롯을 33척에서 34척으로 늘렸다. 강수 부족으로 9월에 32척까지 줄였던 것을 수위 회복에 맞춰 되돌리는 조치다. 네오파나막스 갑문의 최대 허용 흘수는 14.94m에서 15.24m(50피트)로 올랐다. 추가된 슬롯 하나는 슈퍼 선형 선박에 배정되며, 11월 12~17일분은 경매, 18~23일분은 특별 경쟁, 24일 이후는 일반 예약으로 나온다.", "eSum": "The Panama Canal Authority has raised daily booking slots from 33 to 34, restoring capacity that was cut to 32 in September for lack of rain as water levels recover. The maximum draft for the Neopanamax locks has been lifted from 14.94 m to 15.24 m (50 ft). The extra slot is for Super-size vessels and is being offered by auction for 12-17 November, by special competition for 18-23 November and through regular booking from 24 November.", "kImp": "파나마 통항 자동차선은 흘수 여유(15.24m)보다 슬롯 확보가 관건이다. 11월 24일 이후 일반 예약으로 바뀌는 추가 슬롯을 포함해 예약 상태와 도착 시각 요건을 운항사와 맞출 것.", "eImp": "For car carriers transiting Panama the issue is slots rather than draft (15.24 m). Align booking status and arrival-time requirements with the operator, including the extra slot that moves to regular booking from 24 November.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=73012", "prio": 2}, {"code": "OPS", "date": "2026-11-13", "src": "gCaptain", "title": "CMA CGM 3분기 순이익 23.2억 달러(3배)·하팍로이드 9.99억 달러 — 하팍로이드 연간 전망 세 번째 상향, 제미니 수에즈 복귀 8개 서비스로 확대", "eTitle": "CMA CGM Q3 Net Profit Triples to USD 2.32bn and Hapag-Lloyd Earns USD 999m - Hapag-Lloyd Lifts Guidance a Third Time as Gemini Suez Routings Grow to Eight Services", "kSum": "CMA CGM의 3분기 순이익은 23.2억 달러로 전년 동기(7.6억 달러)의 약 3배였다. 매출은 184억 달러(+31.1%), EBITDA는 47.8억 달러(+61.6%, 마진 25.9%), 물동량은 650만 TEU(+5.5%), TEU당 평균 수입은 1,891달러(+30%)였다. 하팍로이드는 매출 68.8억 달러(+26%), EBIT 10.9억 달러(전년 2.28억 달러), 순이익 9.99억 달러를 기록했고 평균 운임은 TEU당 1,808달러(+28%), 물동량은 338만 TEU로 보합이었다. 하팍로이드는 연간 EBITDA 전망을 46~50억 달러로 올해 세 번째 상향했다. 제미니 파트너 머스크와 함께 극동–남유럽 5개, 극동–북유럽 1개, 인도–유럽 2개 서비스가 수에즈를 이용하며, ME1/IOS 인도–유럽 서비스는 11월 12~13일 탕헤르 출항분부터 희망봉에서 수에즈로 바꿨다.", "eSum": "CMA CGM's third-quarter net profit was USD 2.32bn, about three times the USD 760m of a year earlier, on revenue of USD 18.4bn (+31.1%), EBITDA of USD 4.78bn (+61.6%, margin 25.9%), volumes of 6.5m TEU (+5.5%) and average revenue of USD 1,891 per TEU (+30%). Hapag-Lloyd reported revenue of USD 6.88bn (+26%), EBIT of USD 1.09bn (USD 228m a year earlier) and net profit of USD 999m, with an average freight rate of USD 1,808 per TEU (+28%) on flat volumes of 3.38m TEU, and raised full-year EBITDA guidance to USD 4.6-5.0bn, its third increase this year. With Gemini partner Maersk, five Far East-South Europe, one Far East-North Europe and two India-Europe services now use Suez; the ME1/IOS India-Europe service switched from the Cape with a first eastbound departure from Tangier on 12-13 November.", "kImp": "컨테이너 선사의 수에즈 복귀가 넓어지고 있다. 자동차선도 홍해 통항 재개 논의가 나올 수 있어 보안 절차·전쟁위험 조건·선원 동의 절차를 미리 점검해 둘 필요가 있다.", "eImp": "Liner returns to Suez are widening. Car carriers may face the same question, so security procedures, war-risk terms and crew consent arrangements should be checked in advance.", "url": "https://gcaptain.com/hapag-lloyd-profit-surges-as-freight-rates-rise-red-sea-services-return/", "prio": 1}, {"code": "OPS", "date": "2026-11-13", "src": "SAFETY4SEA(NTSB)", "title": "NTSB 조사: 강풍 속 볼티모어 던독 터미널에서 자동차운반선이 부두 접촉 후 좌초 — 원인은 도선사의 '대안 접안 방식 검토 거부', 피해 140만 달러", "eTitle": "NTSB: Vehicle Carrier Strikes the Dock and Grounds at Baltimore's Dundalk Terminal in Gale-Force Winds - Probable Cause Is the Pilots' Reluctance to Consider an Alternative, Damage USD 1.4m", "kSum": "NTSB는 2024년 12월 5일 09:45께 볼티모어 파탑스코강 던독 마린 터미널에서 일어난 자동차운반선(RoRo) 부두 접촉 사고 보고서를 냈다. 선박은 강한 서풍 속에 도선사 승선 하에 예인선 2척을 쓰며 선회장에서 돌아 13번 선석에 후진 접안하려 했으나, 바람이 정횡으로 바뀌자 예인선과 본선 모두 횡방향 압류를 막지 못해 부두에 닿고 좌초했다. 선장은 다른 선석을 요청했지만 도선사는 원래 계획을 고수했고 선장은 대리점과 연락이 닿지 않았다. NTSB는 예상보다 강한 바람에도 도선사들이 대안 접안 방식을 검토하기를 꺼린 것을 추정 원인으로 지목했다. 인명 피해와 오염은 없었고 선박·시설 피해는 140만 달러였다.", "eSum": "The NTSB has reported on the 5 December 2024 dock strike by a ro-ro vehicle carrier at Dundalk Marine Terminal on the Patapsco River, Baltimore, at about 09:45. Under pilotage in gale-force westerly winds and with two assist tugs, the ship turned in the basin to back into berth 13; when the wind came onto the beam, tugs and ship could not control the sideways drift and the vessel contacted the dock and grounded. The master had asked for a different berth but the pilots kept the original plan and he could not reach his agent. The NTSB found the probable cause to be the pilots' reluctance to consider an alternative approach when stronger-than-expected winds appeared. No injuries or pollution; damage to vessel and facility was USD 1.4m.", "kImp": "자동차선은 선석별 풍속 한계와 필요 예인선 수(마력)를 포트 어세스먼트에 수치로 두고, 한계 초과 시 대기 묘박·선석 변경·좌현 접안 등 대안을 선장이 도선사에게 요구하고 기록(Master-Pilot Exchange)할 것. 선장의 중단 권한을 회사가 문서로 뒷받침할 것", "eImp": "For car carriers, set berth-specific wind limits and required tug numbers and power in the port assessment; when limits are exceeded the master should demand and record alternatives with the pilot (wait at anchor, another berth, the other side alongside), with the company backing the master's authority to stop in writing", "url": "https://safety4sea.com/ntsb-investigation-roro-strikes-terminal-dock-in-port-of-baltimore/", "prio": 3}, {"code": "OPS", "date": "2026-11-10", "src": "gCaptain · SAFETY4SEA · 쉬핑뉴스넷", "title": "[후속] 미 USTR, 중국 선박 입항료 유예 연장을 연방관보로 공식화 — 2027년 1월 9일까지, 의견 약 60건 '영구 중단' vs '조선업 위해 유지' 갈려; WSC 등 250여 단체는 영구 중단 요구", "eTitle": "[Follow-up] USTR Formalises the Extension of the China Ship Port Fee Suspension to 9 January 2027 - About 60 Comments Split Between a Permanent End and Keeping the Fees for US Shipbuilding; the WSC and 250 Groups Ask for a Permanent End", "kSum": "USTR이 11월 10일 연방관보 공고로 무역법 301조에 따른 중국 건조·운항 선박 입항료 유예를 2027년 1월 9일 23:59(미 동부)까지 연장했고, 중국도 미국 관련 선박 특별 입항료와 해운·조선 공급망 안보 조사를 1월 10일까지 중단한다. 중국산 STS 크레인 등 하역장비 추가관세 유예도 유지된다. 연장안에는 약 60건의 의견이 들어왔다. 찬성 측은 운임 상승과 상업적 혼란을 피하고 협상 시간을 벌 수 있다며 일부 수수료(Annex III)의 영구 중단을 요구했고, 반대 측은 수수료가 미국 조선·컨테이너 제조업 육성에 필요하다고 주장했다. WSC를 포함한 250여 단체는 10월 30일 영구 중단을 요구하는 공동 서한을 냈으며 RoRo 조항이 우방국 선사에도 영향을 준다고 지적했다. USTR은 1월 시한 전에 재검토할 권한을 유지하고 있다.", "eSum": "USTR's Federal Register notice of 10 November extends the suspension of Section 301 port fees on Chinese-built and Chinese-operated ships to 23:59 ET on 9 January 2027; China keeps its special port fees on US-linked ships and its shipping and shipbuilding supply-chain security probe paused to 10 January. Extra duties on Chinese ship-to-shore cranes and other cargo-handling gear also stay suspended. About 60 comments were filed: supporters said the pause avoids higher freight costs and disruption and buys negotiating time, and some asked for a permanent end to certain fees (Annex III); opponents said the fees are needed to build up US shipbuilding and container manufacturing. More than 250 groups including the World Shipping Council asked on 30 October for a permanent end, noting the ro-ro provisions also hit carriers from allied countries. USTR keeps the right to reconsider before the January deadline.", "kImp": "미국 기항 자동차선에 대한 입항료는 1월 9일까지 유예된다. 250여 단체 서한이 RoRo 조항이 우방국 선사에도 미친다고 지적한 만큼, 1월 10일 재부과 가능성과 비용 부담 주체를 선주·용선주와 미리 정리해야 한다.", "eImp": "Port fees on car carriers calling the US stay suspended to 9 January. With the 250-group letter flagging that the ro-ro provisions also hit allied carriers, settle now who bears any fee that resumes on 10 January.", "url": "https://gcaptain.com/u-s-formalizes-two-month-extension-of-china-ship-port-fee-suspension/", "prio": 3}, {"code": "OPS", "date": "2026-11-09", "src": "China Daily", "title": "미·중, 해운 301조 입항료 유예 2개월 연장 확정 — 미국 2027년 1월 9일, 중국 1월 10일까지", "eTitle": "US and China Both Extend Their Port-Fee Suspensions by Two Months, With USTR's Section 301 Maritime Actions on Hold Until 9 January 2027 and China's Special Fees Until 10 January", "kSum": "USTR가 중국 해운·물류·조선 부문 대상 301조 조치(외국 건조 자동차운반선 입항료 포함 해상운송 서비스 수수료, 중국산 안벽크레인 등 하역장비 관세)의 유예를 2개월 더 연장해 미 동부시간 2027년 1월 9일 23:59까지 효력을 정지한다고 발표했다. 중국 교통운수부도 11월 9일 국무원 승인을 거쳐 미국 관련 선박에 대한 특별 항만수수료와 징수 규정, 자국 해운·조선 영향 조사의 유예를 2027년 1월 10일까지 연장했다. 양측 모두 제8차 미·중 경제무역 협의 결과를 이행하는 조치이며, 2025년 11월 10일 시작된 1년 유예(11/9 만료)를 이어받는다. Xinde Marine News는 USTR이 이번 연장안에 약 60건의 고유 의견을 받았다고 전했다.", "eSum": "USTR announced a further two-month suspension of its Section 301 actions against China's maritime, logistics and shipbuilding sectors, including the vessel service fees that cover foreign-built vehicle carriers and duties on Chinese ship-to-shore cranes, running through 11:59 pm ET on 9 January 2027. China's Ministry of Transport, with State Council approval, on 9 November extended its suspension of special port fees on US-linked ships, the related collection rules and its impact investigation to 10 January 2027. Both moves implement the eighth round of US-China trade consultations and follow the one-year suspension that began on 10 November 2025. Xinde Marine News reported that USTR received about 60 unique comments on the proposal.", "kImp": "11/10 입항료 재개 위험은 사라졌으나 유예가 2개월 단위로 짧아져 1월 초 다시 결정 시점이 온다. 미국 기항 자동차선 배선과 비용 전망은 1월 9일 전후 결정을 계속 지켜봐야 한다.", "eImp": "The risk of fees restarting on 10 November is gone, but the suspension now runs in two-month steps, so another decision point arrives in early January. US-calling car carrier deployment and cost planning should keep tracking the decision around 9 January.", "url": "https://www.chinadaily.com.cn/a/202611/09/WS6af17adae4b03ebf8519b4c0.html", "prio": 3}, {"code": "OPS", "date": "2026-11-09", "src": "Mitsui O.S.K. Lines (IR)", "title": "MOL 상반기 실적 — 자동차선 사업 이익 감소, 페르시아만 배선 중단·연료비·항만 혼잡 탓; 하반기도 호르무즈 폐쇄 영향", "eTitle": "MOL's First-Half Results Show Lower Car-Carrier Profit on Suspended Persian Gulf Deployments, Higher Fuel Costs and Port Congestion, With the Hormuz Closure Weighing on the Second Half", "kSum": "일본 MOL이 11월 9일 발표한 2026회계연도 2분기(4~9월) 실적 자료에서 자동차선 사업은 물동량이 견조했지만 페르시아만 배선 중단, 연료비 상승, 항만 혼잡에 따른 배선 제약으로 전년보다 이익이 줄었다고 밝혔다. 하반기 이익도 호르무즈 해협 폐쇄 영향으로 직전 전망보다 낮아질 것으로 보고, 견조한 수요에 맞춰 유연하게 배선하겠다고 했다. 부문 전망은 회계연도 내내 페르시아만과 홍해 항행이 불가능하다는 가정에 기초한다. 그룹 상반기 경상이익은 1,636억 엔(+42.8%)이며 연간 전망은 2,950억 엔으로 올렸다.", "eSum": "In its FY2026 second-quarter (April-September) materials released on 9 November, Japan's MOL said its car carrier business saw firm cargo movements but lower profit than a year earlier because of suspended Persian Gulf deployments, higher fuel costs and deployment limits from port congestion. It expects second-half car-carrier profit to fall short of its previous forecast because of the Strait of Hormuz closure and plans to deploy ships flexibly to meet firm demand. Segment outlooks assume the Persian Gulf and the Red Sea stay unavailable for the whole fiscal year. Group first-half ordinary profit rose 42.8% to JPY 163.6bn and the full-year forecast was raised to JPY 295.0bn.", "kImp": "경쟁 선사도 중동 항로 단절, 연료비, 항만 혼잡을 자동차선 수익의 핵심 부담으로 꼽아 WW 3분기 설명과 같은 그림이다. 홍해·호르무즈 우회가 회계연도 끝까지 이어진다는 가정이 업계 공통 전제로 굳어지고 있다.", "eImp": "A major rival also names the Middle East closures, fuel costs and port congestion as the main drags on car-carrier earnings, matching WW's Q3 message. The assumption that Red Sea and Hormuz diversions last the full fiscal year is becoming the industry baseline.", "url": "https://ir.mol.co.jp/en/ir/library/mrsfcfh/main/0/teaserItems1/0111115/linkList/03/link/%28E%292026.2Q%20Financial%20Highlights.pdf", "prio": 1}, {"code": "OPS", "date": "2026-11-04", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "WW 3분기 프레젠테이션: 바브엘만데브(홍해) 회피·호르무즈 정기항로 중단 유지, USTR 입항료 유예 1/9 이후 불확실, EU 중국 하이브리드 35만 대 쿼터 영향 '제한적'", "eTitle": "WW's Q3 Presentation Keeps Bab-el-Mandeb Avoided and Regular Hormuz Sailings Suspended, Calls the Outlook for USTR Port Fees Beyond 9 January Unclear and Sees Only a Modest Hit From a 350,000-Unit EU Quota on Chinese Hybrids", "kSum": "3분기 웹캐스트 자료에서 회사는 홍해 바브엘만데브 항로를 계속 피하고 호르무즈 해협 경유 정기 운항은 중단 상태라고 밝혔으며(복귀 일정 제시 없음), 파나마 운하 통항 제약도 위험 요인으로 꼽았다. 보고서는 호르무즈 봉쇄가 연료·투입비를 끌어올리고 연료 부족 시 감속이나 운항 중단이 필요할 수 있다고 적었고, 미국 USTR 301조 입항료 유예가 2027년 1월 9일까지 연장되더라도(현재는 연장안 단계, 현 유예는 11월 9일 만료) 그 이후는 불확실하다고 했다. EU가 검토 중인 중국산 하이브리드 수입 쿼터(연 35만 대, 4년)는 2026년 중국 수출 예상 약 900만 대 중 약 50만 대(5~6%)에 영향을 줄 수 있으나 수요 영향은 제한적일 것으로 봤다. 시장 모델은 2026년 말 약 300만 대의 선복 부족과 연 200만~400만 대의 비(非)로로 물량을 가정하고, 선대 증가는 2030년까지 이어질 것으로 봤다.", "eSum": "The Q3 webcast slides say the company still avoids the Red Sea's Bab-el-Mandeb route and that regular Strait of Hormuz sailings remain suspended, with no return timeline, and list Panama Canal transit constraints as a further risk. The report adds that the Hormuz closure is raising fuel and input costs and that fuel shortages could force speed reductions or stoppages, and says that even with the USTR Section 301 port-fee suspension extended to 9 January 2027 (still a proposal; the current suspension ends on 9 November) the outlook beyond that is unclear. A proposed four-year EU quota on Chinese hybrid imports of 350,000 units a year could affect about 0.5m of an expected 9.0m Chinese exports in 2026 (5-6%), which the company sees as a modest demand impact. Its market model assumes a capacity deficit of about 3m units at end-2026 and 2-4m units a year of non-RoRo volumes, with fleet growth continuing to 2030.", "kImp": "수에즈·호르무즈 복귀 신호가 없어 희망봉 우회 장거리 항해와 중동 고위험 해역 관리가 당분간 계속되며, 2027년 1월 이후 USTR 입항료 재부과 가능성에 대비해 미국 기항 배선 시나리오를 점검할 필요가 있다.", "eImp": "With no sign of a Suez or Hormuz return, long Cape routings and Middle East high-risk-area procedures continue for now, and US-call deployment scenarios should be checked in case USTR port fees return after 9 January 2027.", "url": "https://newsweb.oslobors.no/message/685571", "prio": 2}, {"code": "OPS", "date": "2026-10-26", "src": "Federal Register (USTR)", "title": "미 USTR, 외국 건조 자동차선 포함 섹션301 입항 수수료 유예 2개월 연장 제안…11월 9일 만료분을 2027년 1월 9일까지, 의견 10월 30일 마감", "eTitle": "USTR Proposes a Further Two-Month Suspension of Section 301 Port Fees, Including the Fee on Foreign-Built Vehicle Carriers, to 9 January 2027, With Comments Due 30 October", "kSum": "미국 무역대표부(USTR)는 10월 23일 공개하고 10월 26일 관보에 게재한 고시(91 FR 67388, 문서 2026-21755, 도켓 USTR-2026-0694)에서 중국의 해운·물류·조선 장악 관행에 대한 섹션301 대응조치의 유예를 2개월 더 연장하자고 제안했다. 이 조치는 2025년 11월 1일 미·중 정상 합의에 따라 2025년 11월 10일부터 1년간 유예돼 2026년 11월 9일 밤 11시59분(미 동부시간)에 끝날 예정이었으며, 제안안은 2026년 11월 10일 0시부터 2027년 1월 9일 밤 11시59분까지 다시 유예해 그 기간에는 2025년 4월 조치(같은 해 10월 수정) 부속서 I~III의 해상운송 서비스 수수료와 부속서 V.A의 중국산 안벽 크레인·하역장비 관세가 발생하지 않도록 한다. 부속서 III은 미국 외에서 건조된 자동차운반선이 미국 첫 기항 항만 입항 때 내는 수수료로, 2025년 4월 고시는 CEU 용량당 150달러로 정했으나 같은 해 10월 수정 고시에서 2025년 10월 14일부터 순톤당 46달러로 바뀌었다(Skuld). USTR은 중국과의 추가 협상을 위한 것이라고 밝혔고 의견은 10월 30일 오후 5시(미 동부시간)까지 comments.ustr.gov에서 받으며, E24는 2025년 11월 SEB 분석가가 이 수수료가 부과될 경우 왈레니우스 윌헬름센은 연 3억7,500만 달러, 회그 오토라이너스는 6,500만 달러를 부담할 것으로 추산했다고 보도했다.", "eSum": "In a notice made public on 23 October and published in the Federal Register on 26 October (91 FR 67388, document 2026-21755, docket USTR-2026-0694), the Office of the US Trade Representative proposed suspending its Section 301 actions on China's targeting of the maritime, logistics and shipbuilding sectors for two more months. The actions were suspended for one year from 10 November 2025 under the 1 November 2025 Trump-Xi trade deal and were due to resume after 11:59 pm Eastern Time on 9 November 2026; the proposal would extend the suspension from 12:00 am on 10 November 2026 to 11:59 pm on 9 January 2027, during which no fees would accrue under Annexes I-III of the April 2025 action (as modified in October 2025) and no duties under Annex V.A on Chinese ship-to-shore cranes and cargo-handling equipment. Annex III is the fee on non-US-built vehicle carriers due on entry at the first US port, first set in April 2025 at USD 150 per CEU of capacity and changed by the October 2025 modification to USD 46 per net ton from 14 October 2025 (Skuld). USTR said the extension would allow further negotiation with China and is taking comments at comments.ustr.gov until 5:00 pm Eastern Time on 30 October; E24 reported in November 2025 that an SEB analyst estimated the fees, if charged, could cost Wallenius Wilhelmsen about USD 375m and Höegh Autoliners about USD 65m a year.", "kImp": "확정되면 11월 10일 이후 미국 입항분에도 수수료가 붙지 않지만 유예가 1월 9일까지로 짧아, 미국 기항 자동차선의 항차 비용 산정, 용선계약상 수수료 부담 조항, 1월 10일 이후 미국 도착 일정을 미리 점검하고 10월 30일 의견수렴 뒤 나올 최종 고시를 확인해야 한다.", "eImp": "If adopted, US entries after 10 November would stay fee-free, but only until 9 January, so voyage cost estimates for US-bound car carriers, charter-party clauses allocating the fees and US arrival schedules from 10 January should be reviewed now, and the final notice expected after the 30 October comment deadline should be watched.", "url": "https://www.federalregister.gov/documents/2026/10/26/2026-21755/request-for-comments-on-further-suspension-of-section-301-action-chinas-targeting-of-the-maritime", "prio": 3}, {"code": "OPS", "date": "2026-10-09", "src": "Shippax", "title": "왈레니우스 SOL, 내빙 1A급 로로선 '레이크웨이 익스프레스' 발틱 스케줄 투입…홀멘 신규 장기계약으로 이게순드~킬 주 1회", "eTitle": "Wallenius SOL Adds the Ice-Class 1A Ro-Ro Lakeway Express to Its Baltic Schedule for a New Long-Term Holmen Contract, Sailing Weekly From Iggesund to Kiel", "kSum": "로로·페리 전문지 Shippax는 10월 9일 왈레니우스 SOL이 1만471GT, 차선 1,625m, 내빙등급 1A의 로로선 '레이크웨이 익스프레스(LAKEWAY EXPRESS)'를 발틱 스케줄에 추가했다고 보도했다. 이 배는 10월 1일 시작된 홀멘 보드 앤드 페이퍼(Holmen Board & Paper)와의 신규 장기계약에 따라 스웨덴 발트해 연안 예블레 북쪽의 이게순드에서 독일 킬까지 홀멘의 판지 수출화물을 주 1회 실어 나르며, 고가 코팅 판지는 주로 카세트에 실린다. 홀멘은 그동안 킬 임산물 터미널에 기항하는 SCA의 로로 서비스를 이용해 왔고 킬에 이미 물류망을 갖추고 있다. 선박은 지난겨울 주기관 디레이팅, 새 프로펠러 블레이드, 새 구상선수 장착으로 환경 부담을 줄이는 개조를 마쳤으며, 기사에는 매입인지 용선인지 나오지 않는다.", "eSum": "Ro-ro and ferry trade publication Shippax reported on 9 October that Wallenius SOL has added the 10,471 GT ro-ro LAKEWAY EXPRESS, with 1,625 lane metres and ice class 1A, to its Baltic schedule. She serves a new long-term contract with Holmen Board & Paper that started on 1 October, carrying Holmen's board exports weekly from Iggesund, north of Gävle on Sweden's Baltic coast, to Kiel, with the high-value coated board travelling mainly on cassettes. Holmen previously used SCA's ro-ro service calling at the Kiel forest products terminal and already has a logistics network in Kiel. Last winter the ship was converted to cut her environmental footprint with a de-rated main engine, new propeller blades and a new bulbous bow, and the article does not say whether she was bought or chartered.", "kImp": "왈레니우스 계열 로로 선사가 북유럽 임산물 장기계약으로 발틱 항로를 넓히는 사례로, 주기관 디레이팅·구상선수 교체 같은 에너지 절감 개조선은 악천후·결빙 해역에서의 최소 추진출력과 조종성 여유를 항해계획과 선원 교육에 반영할 필요가 있다.", "eImp": "It shows a Wallenius-linked ro-ro operator growing its Baltic trades on long-term Nordic forest-products contracts, and for ships retrofitted with engine de-rating and new bulbous bows, minimum propulsion power and manoeuvring margins in heavy weather and ice should be reflected in passage planning and crew training.", "url": "https://www.shippax.com/en/news/lakeway-express-joins-wallenius-sol.aspx", "prio": 1}, {"code": "OPS", "date": "2026-08-27", "src": "Kaiji Press", "title": "WW 윙세일 장착 자동차선 '티라나', 일본 첫 기항…요코하마 다이코쿠 부두, 연료 4~5% 절감", "eTitle": "Wallenius Wilhelmsen's Wing-Sail Car Carrier Tirranna Makes Her First Japan Call at Yokohama's Daikoku Pier, With Reported Fuel Savings of 4-5%", "kSum": "일본 해사프레스(Kaiji Press)에 따르면 오션버드 윙세일을 단 WW의 7,620대 적재 자동차선 '티라나(TIRRANNA, 2009년 건조)'가 윙세일 설치 후 처음 일본에 기항했으며, WW는 연료 소비가 4~5% 줄었다고 밝혔다. 요코하마항만공사(横浜港埠頭)에 따르면 선박은 8월 19일 요코하마항 다이코쿠 부두에 입항했고, 공사 사장 등이 윙세일 가동을 참관하며 WW 일본지점장·선장과 의견을 나눴다. WW는 약 1년간 상업운항을 하며 항로·기상·계절별 성능과 연료·CO2 절감 효과를 검증해 다른 선박 적용을 판단할 계획이다.", "eSum": "Kaiji Press reports that Wallenius Wilhelmsen's 7,620-car carrier Tirranna (built 2009), fitted with an Oceanbird wing sail, made her first Japan call since the installation, with WW citing a 4-5% cut in fuel consumption. Yokohama Port Corporation said the ship berthed at Daikoku Pier on 19 August, where its president and port officials watched the sail in operation and met WW's Japan branch manager and the master. WW will keep the ship in commercial service for about a year to test performance by route, weather and season and measure fuel and CO2 savings before deciding on use across other ships.", "kImp": "윙세일이 아시아 항로 상업운항에서 연료 4~5% 절감을 보인 만큼, 향후 풍력보조추진 개조를 검토할 때 아시아 항만의 에어드래프트·하역 크레인 간섭과 강풍 시 운용 절차를 함께 확인할 필요가 있다.", "eImp": "With the wing sail showing 4-5% fuel savings in commercial service to Asia, any future wind-assist retrofit review should also check air draft and cargo crane clearance at Asian ports and operating procedures in strong winds.", "url": "https://www.kaijipress.com/news/tramper/2026/08/203862/", "prio": 1}, {"code": "OPS", "date": "2026-08-20", "src": "FreightWaves", "title": "WalWil CEO '아시아발 선복 완판, 고객 우선순위 조정'…호르무즈·홍해 회피 지속", "eTitle": "Wallenius Wilhelmsen CEO Says Asia Capacity Is Fully Booked, Forcing Customer Prioritisation, as Hormuz and the Red Sea Stay Off-Limits", "kSum": "Lasse Kristoffersen CEO는 2분기 실적 설명회에서 아시아발 선대가 완전히 예약돼 고객 우선순위를 정해야 하고, 연 200만~400만 대(상단에 가까움)가 컨테이너 등 대체 수단으로 운송되고 있다고 말했다. 중국 차량 수출은 6·7월 각각 100만 대를 넘었고 중국발 현물운임·정기용선료는 2분기에 약 80% 올랐으며, PCTC 오더북은 기존 선대의 약 20~21%지만 2029년까지 조선소 슬롯이 차 신규 발주는 대체로 2030년 이후 인도된다. WalWil은 호르무즈 해협을 계속 회피하고 바브엘만데브·홍해 통항도 재개하지 않았으며, The Loadstar(9/4)에 따르면 일부 계약을 시장 상황에 맞게 재협상했고 향후 수년간 용선 가능한 선박이 거의 없다고 밝혔다.", "eSum": "On the Q2 call CEO Lasse Kristoffersen said the Asia-departing fleet was fully booked, forcing customer prioritisation, and that 2-4 million vehicles a year (probably near the high end) are moving in containers or other alternatives. Chinese vehicle exports topped 1 million units in both June and July, China spot and time-charter rates rose about 80% in Q2, and the PCTC orderbook is around 20-21% of the fleet but yards are committed through 2029, so new orders generally deliver from 2030. The company continues to avoid the Strait of Hormuz and has not resumed Bab el-Mandeb and Red Sea transits; The Loadstar reported on 4 September that it has renegotiated some contracts to reflect market conditions and sees hardly any ships available for charter in the next few years.", "kImp": "선복 완판과 홍해 회피(희망봉 우회) 장기화로 항해가 길어져 벙커링·선용품 보급, 선원 교대 시점, 입거 일정 확보가 빠듯해진다. 아시아발 배선 집중에 따른 기항지 변화와 장거리 항해 위험관리가 필요하다.", "eImp": "Full ships and a prolonged Red Sea avoidance mean longer voyages and tighter windows for bunkering, stores, crew changes and dry-docking. Concentrating deployment ex-Asia also changes port rotations and long-haul voyage risk profiles.", "url": "https://www.freightwaves.com/news/china-growth-straining-global-auto-shipping-capacity-liner-ceo", "prio": 2}, {"code": "OPS", "date": "2026-08-04", "src": "Wallenius Wilhelmsen", "title": "WalWil '바다 이야기': 호르무즈에 발 묶였던 '모닝 콘서트'의 귀환…위기 대응 회고", "eTitle": "Stories From the Sea: How Morning Concert Made Its Long Way Home After Months Held Up by the Hormuz Crisis", "kSum": "WalWil은 2월 중동 분쟁 발발 이후 페르시아만에 머물다 6월 30일 오만 수역을 거쳐 호르무즈 해협을 안전하게 빠져나온 자동차선 Morning Concert의 사례를 소개했다. 회사는 6월 30일 공시에서 선원 안전을 최우선으로 한 종합 평가 끝에 출항을 결정했다고 밝혔으며, 이번 글은 대기 기간 선원들의 상호 지원과 육상 조직의 조기 대응·위험성평가·다중 시나리오 계획·상시 선육 간 소통을 강조했다. 선장은 선원들이 서로를 돌보며 해야 할 일에 집중한 점이 가장 인상적이었다고 말했다.", "eSum": "Wallenius Wilhelmsen told the story of the car carrier Morning Concert, which had been inside the Persian Gulf since the conflict began in February and safely exited the Strait of Hormuz through Omani waters on 30 June. The company's 30 June notice said the decision to proceed followed a comprehensive assessment with crew safety as the top priority, and the feature highlights crew mutual support during the wait plus early mobilisation ashore, risk assessments, multi-scenario planning and constant ship-shore communication. The master said what impressed him most was how the crew kept looking after each other and stayed focused on the job.", "kImp": "분쟁 해역 장기 체류 상황에서는 선원 복지·정신건강, 보급, 선원 교대, 보안등급 운영이 장기 과제가 된다는 사례로, 비상대응계획(ERP)과 위험성평가 갱신 주기 점검에 참고할 만하다.", "eImp": "The case shows that being stuck in a conflict zone turns crew welfare, mental health, supplies, crew changes and security-level management into long-running tasks, a useful reference for reviewing emergency response plans and risk-assessment update cycles.", "url": "https://www.walleniuswilhelmsen.com/insights/stories-from-the-sea-morning-concerts-long-way-home", "prio": 2}, {"code": "OPS", "date": "2026-07-27", "src": "Breakbulk News", "title": "왈레니우스 윌헬름센, 존 트라볼타 소유였던 콴타스 보잉 707 분해 운송…'서모필레'호로 호주 항공박물관까지", "eTitle": "Wallenius Wilhelmsen Ships a Dismantled Ex-Qantas Boeing 707 Once Owned by John Travolta Aboard Thermopylae to Australia's HARS Aviation Museum", "kSum": "브레이크벌크뉴스는 7월 27일 왈레니우스 윌헬름센이 AAW 글로벌 로지스틱스와 함께 존 트라볼타가 소유했던 콴타스 보잉 707을 브런즈윅(Brunswick)에서 호주 HARS 항공박물관까지 브레이크벌크 화물로 운송하는 작업을 올해 초 마쳤다고 보도했다. 길이 약 40m의 기체는 분해해 운송했고 분리한 날개 폭만 6m에 달해 모든 양중·이동 작업에 정밀한 공학 검토가 필요했으며, M/V '서모필레(Thermopylae)'호 선적·하역에는 하역업체·선원·물류 계획자·중량물 전문가가 긴밀히 협업했다. 회사는 항공기가 전시용으로 재조립할 수 있는 상태로 박물관에 도착했다고 밝혔다.", "eSum": "Breakbulk News reported on 27 July that Wallenius Wilhelmsen and AAW Global Logistics earlier this year completed a breakbulk move of a former Qantas Boeing 707 once owned by John Travolta from Brunswick to the HARS Aviation Museum in Australia. The roughly 40-metre aircraft was dismantled for the voyage, with the separated wings alone six metres wide, so every lift and cargo movement needed careful engineering. Loading and discharge on the M/V Thermopylae required close coordination between stevedores, crew, planners and heavy-lift specialists, and the company said the aircraft arrived in good condition for reassembly and display.", "kImp": "형상이 특이한 비정형 화물은 고박 지점·하중 분산·롤트레일러 적재를 미리 계산해야 하므로, 화물고박지침서(CSM) 범위를 벗어나는 화물은 선적 전 고박 계산과 선장 확인을 거치도록 하는 것이 바람직하다(파리·도쿄 MOU 화물고박 집중점검 9~11월 시행 중).", "eImp": "Irregular cargo needs lashing points, load spreading and roll-trailer stowage calculated in advance, so cargo outside the Cargo Securing Manual should get pre-loading lashing calculations and master sign-off, especially during the Paris and Tokyo MoU cargo-securing inspection campaign running from September to November.", "url": "https://breakbulk.news/no-room-for-error-as-wallenius-wilhelmsen-ships-john-travoltas-historic-boeing-707-to-museum/", "prio": 1}, {"code": "OPS", "date": "2026-07-05", "src": "Maritime Executive", "title": "갤버스턴항 신규 화물 선석 개장…WalWil 'MS Toledo' 첫 기항", "eTitle": "Port of Galveston Opens a New Cargo Berth With Wallenius Wilhelmsen's MS Toledo as the First Caller", "kSum": "미국 갤버스턴항이 1억600만 달러를 들여 웨스트포트 화물단지를 확장하고 7월 2일 피어 39-40의 1,410피트 신규 선석을 개장했으며, 첫 기항선은 WalWil의 656피트 자동차선 MS Toledo였다. Toledo는 브라질·극동발 중장비 수백 대를 양하하고 브라질·호주행 건설·농업 장비를 선적했다. 사업에는 텍사스 교통부(TxDOT) 보조금 3,600만 달러가 들어갔고 부지가 약 30에이커 늘었다.", "eSum": "The Port of Galveston opened a new 1,410-foot cargo berth at Piers 39-40 on 2 July after a USD 106m expansion of its West Port Cargo Complex, with Wallenius Wilhelmsen's 656-foot car carrier MS Toledo as the first caller. Toledo discharged hundreds of pieces of heavy construction equipment from Brazil and the Far East and loaded construction and farm equipment for Brazil and Australia. The project, which added almost 30 acres, was funded from port revenues and a USD 36m Texas Department of Transportation grant.", "kImp": "미 걸프 연안 H&H 기항 인프라가 확충돼 중장비 하역 효율이 높아질 수 있으며, 신규 선석 첫 기항 때는 계류·램프 착지·하역 동선을 사전 협의해야 한다.", "eImp": "Expanded US Gulf Coast H&H infrastructure may improve heavy-equipment handling, though first calls at a new berth need advance checks on mooring, ramp landing and cargo flow.", "url": "https://maritime-executive.com/corporate/port-of-galveston-opens-new-berth-with-1st-cargo-vessel-call-july-2", "prio": 1}, {"code": "OPS", "date": "2026-05-21", "src": "Wallenius Wilhelmsen", "title": "WalWil, Wallenius SOL과 핀란드·스웨덴 북부 신규 무역로…브레머하펜 경유 글로벌망 연결", "eTitle": "Wallenius Wilhelmsen Adds a New Trade To and From Northern Finland and Sweden With Wallenius SOL, Linked via Bremerhaven", "kSum": "WalWil은 Wallenius SOL과의 협력으로 핀란드·스웨덴 북부를 브레머하펜 경유로 자사 글로벌 네트워크에 연결하는 신규 무역로를 열어 선복과 기항 범위를 늘렸다. 투르쿠도 브레머하펜 경유 주간 정기 운항으로 연결되며, 에스토니아 팔디스키는 두 회사를 통해 이용할 수 있다. 대상 화물은 승용차·롤링 장비·브레이크벌크이며, Splash(7/31)에 따르면 Wallenius Lines는 5월 SOL 그룹 지분 인수를 마쳐 Wallenius SOL의 단독 소유주가 됐다.", "eSum": "Through a new cooperation with Wallenius SOL, Wallenius Wilhelmsen opened a trade linking northern Finland and Sweden to its global network via Bremerhaven, adding capacity and port coverage. Turku is served by weekly sailings, also via Bremerhaven, and Paldiski in Estonia can be reached through both companies. The service carries cars, rolling equipment and breakbulk; according to Splash247, Wallenius Lines completed its buyout of SOL Group's stake in May to become sole owner of Wallenius SOL.", "kImp": "브레머하펜 환적을 통한 북유럽 피더 연계가 확대돼 환적 화물 증가에 따른 고박·손상 관리와 동절기 결빙 해역 연계 일정 관리가 중요해진다.", "eImp": "Expanded Nordic feeder links via Bremerhaven raise the share of transhipped cargo, making lashing, damage control and winter ice-season scheduling more important.", "url": "https://www.walleniuswilhelmsen.com/news/strengthening-our-network-new-trade-to-and-from-northern-finland-and-sweden", "prio": 2}, {"code": "OPS", "date": "2026-03-04", "src": "Wallenius Wilhelmsen", "title": "WalWil, 중동 전쟁으로 중동 지역 전 항차 잠정 중단", "eTitle": "Wallenius Wilhelmsen Temporarily Suspends All Sailings to the Middle East Because of the War", "kSum": "WalWil은 3월 4일 중동 전쟁으로 해당 지역행 모든 항차를 잠정 중단한다고 밝히고, 선원·선박·화물 안전을 최우선으로 상황을 계속 평가해 안전해지는 대로 재개하겠다고 했다. 이후 1분기 실적(5/6)에서 중동 관련 매출 비중은 2~3%이며 호르무즈 해협 안에 선박 1척이 있다고 했고, 2분기 발표자료(8/11)에서는 호르무즈 통항이 없으며 바브엘만데브는 '진입 금지 구역'이라고 설명했다.", "eSum": "On 4 March Wallenius Wilhelmsen temporarily suspended all sailings to the Middle East because of the war, saying the safety of crew, vessels and customers' cargo is its highest priority and that it will resume as soon as it is safe. Its Q1 release (6 May) put Middle East-linked revenue at 2-3% and noted one vessel inside the Strait of Hormuz, and the Q2 presentation (11 August) said there are no sailings through Hormuz and Bab el-Mandeb remains a no-go zone.", "kImp": "중동 기항 중단과 호르무즈·홍해 회피가 장기화되면서 걸프 지역 화물 처리, 선원 교대지 변경, 연료 수급 차질 가능성에 대한 대비가 필요하다.", "eImp": "With Middle East calls suspended and Hormuz and the Red Sea avoided for an extended period, plans are needed for Gulf cargo, alternative crew-change ports and possible bunker supply disruption.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-suspends-operations-in-the-middle-east", "prio": 3}]}, {"code": "EUKOR", "kTitle": "EUKOR", "eTitle": "EUKOR", "items": [{"code": "EUKOR", "date": "2026-10-15", "src": "PortalPortuario", "title": "칠레 경쟁법원, 자동차선 담합 피해 소비자 배상금 지급 승인…EUKOR 등에 과징금 확정된 사건, 외국 선사 4곳 상대 재판은 계속", "eTitle": "Chile's Competition Tribunal Approves Consumer Payouts From a CMC Settlement in the Car-Carrier Collusion Case Where EUKOR Was Fined, as Claims Against Four Foreign Carriers Continue", "kSum": "칠레 자유경쟁재판소(TDLC)가 아시아발 차량 해상운송 담합으로 피해를 본 소비자에게 개별 배상금 지급을 승인했다고 포르탈포르투아리오가 10월 15일 보도했다. 소비자단체 Arcam과 피고 6개 선사 중 하나인 칠레 CMC의 부분 화해(2025년 9월 11일 승인)에 따른 것으로, 2010~2014년 CMC가 운송한 기아차 구매자는 2026년 12월 23일까지 신청하면 차량당 최대 0.5UF를 받고 CMC는 25만달러를 출연한다. 담합 책임은 TDLC 판결(2019년 171호)과 2020년 8월 14일 대법원 판결로 확정돼 CMC·EUKOR Car Carriers·K라인·NYK에 과징금이 부과됐으며, 칠레 선사 2곳(CSAV·CMC)이 화해하면서 소비자 손해배상 재판은 외국 선사 4곳을 상대로 계속되고 있다.", "eSum": "Chile's Competition Tribunal (TDLC) has authorised individual payments to consumers harmed by collusion among carriers shipping vehicles from Asia, PortalPortuario reported on 15 October. The payouts come from a partial settlement between consumer group Arcam and CMC, one of six defendants, approved on 11 September 2025: buyers of Kia vehicles carried by CMC in 2010-2014 can claim up to 0.5 UF per vehicle until 23 December 2026 from a USD 250,000 fund. Liability was established in TDLC ruling 171/2019 and confirmed by the Supreme Court on 14 August 2020, which fined CMC, EUKOR Car Carriers, K Line and NYK, and with both Chilean carriers having settled, the damages case continues against four foreign carriers.", "kImp": "칠레에 이어 영국에서도 9월 과거 자동차선 담합 관련 소비자 배상 분배안(5,587만파운드)이 승인되는 등 후속 소송이 이어지고 있어, 운임·선복 정보 교류를 금지하는 경쟁법 준수 교육을 영업·운항 조직에 유지할 필요가 있다.", "eImp": "Follow-on cases over the past car-carrier cartel continue, with a UK tribunal also approving a GBP 55.87m consumer distribution plan in September, so competition-law training that bars sharing rate and capacity information should be maintained for commercial and operations staff.", "url": "https://portalportuario.cl/tdlc-autoriza-pago-de-beneficio-individual-por-caso-de-colusion-en-transporte-maritimo-de-vehiculos/", "prio": 1}, {"code": "EUKOR", "date": "2026-10-14", "src": "해운산업신문", "title": "\"톤세 수혜 국적선사 EUKOR, 실질적 국적선사인가\"…연 1,000억 원대 절세·배당성향 75% 지적한 기고", "eTitle": "Contributed Analysis Questions Whether Tonnage-Tax Beneficiary EUKOR Is Korean in Substance, Citing Estimated Tax Savings of Over KRW 100bn a Year and a Payout Ratio Raised to 75%", "kSum": "해운산업신문에 실린 기고(지주헌 제공)는 2002년 현대상선 자동차선 부문의 해외 매각으로 출범해 2025년 공정위 대기업집단에 편입된 유코카캐리어스가 최근 수년간 톤세제로 연 1,000억 원 이상의 세금을 아낀 것으로 추정했다. 2024년 현대차·기아 계약 연장으로 국내 수출물량 수송 비중이 40%에서 50%로 늘고 계약이 2029년 말까지 5년으로 길어졌지만, 2021년 이후 핵심 운영 기능이 최대주주 WW 쪽으로 옮겨갔다는 평가가 있다고 지적했다. 배당성향이 2022년 50%에서 2023년부터 75%로 올랐고 최근 100% 배당이 검토된 것으로 알려졌다며, 톤세제 재설계 논의 때 선박 보유 구조·조직 운영·이익 배분이 검증 대상이 될 것으로 내다봤다.", "eSum": "A contributed piece in Haeun Saneop Shinmun, provided by Ji Ju-heon, estimates that EUKOR, created in 2002 when Hyundai Merchant Marine sold its car-carrier arm abroad and added to the Fair Trade Commission's large business groups in 2025, has saved more than KRW 100bn a year in recent years under the tonnage tax. It notes the 2024 Hyundai-Kia renewal raised EUKOR's share of Korean export volumes from 40% to 50% and extended the contract to five years, to end-2029, but says core operating functions have shifted to majority owner Wallenius Wilhelmsen since 2021. Citing a payout ratio raised from 50% in 2022 to 75% from 2023 and reports that a 100% payout was considered, it expects ship ownership, organisation and profit distribution to be scrutinised if the tonnage tax is redesigned.", "kImp": "톤세제 재검토 논의는 국적선 유지·한국 선원 고용·국내 관리 기능 배치에 영향을 줄 수 있으므로, 그룹 선박관리사는 국적선 요건(국적 선원 승선 등) 준수 현황과 국내 선박관리 기능의 기여를 객관적 자료로 정리해 둘 필요가 있다.", "eImp": "Because a tonnage-tax review could affect Korean-flag retention, Korean crew employment and where management functions sit, group ship managers should keep objective records of Korean-flag compliance, such as national crew manning, and of the contribution of Korea-based ship management.", "url": "https://www.cargotimes.net/news/articleView.html?idxno=84859", "prio": 2}, {"code": "EUKOR", "date": "2026-08-27", "src": "에너지데일리", "title": "EUKOR·WW, 태백 청정메탄올 생산-유통-수요 다자간 MOU…연 1만5,000톤, 2029년 1월 상업생산 목표", "eTitle": "EUKOR and Wallenius Wilhelmsen Join a Taebaek Green Methanol MoU Linking Production, Trading and End Use, Targeting 15,000 Tonnes a Year From January 2029", "kSum": "8월 26일 서울 유코카캐리어스 본사에서 태백시·에코메탄올(플라젠 주도 특수목적법인)·현대코퍼레이션·발레니우스 빌헬름센 오션·EUKOR가 청정메탄올 다자간 업무협약을 맺었다. 에코메탄올이 태백 동점산업단지에서 산림잔재물을 이중유동층(DFB) 가스화해 연 1만5,000톤을 생산하면 현대코퍼레이션이 사들여 선사에 공급하고 선사가 선박연료로 쓰는 구조로, 총 1,200억 원을 들여 2026년 12월 착공·2029년 1월 상업생산을 목표로 한다. 생산 전에 유통사와 최종 수요자인 선사가 참여한 점이 의미로 꼽히지만, 기사는 생산량이 국내 메탄올 소비(연 약 200만 톤)의 0.75% 수준이며 생산원가·항만까지의 물류비·전과정평가(LCA)가 경제성의 관건이라고 분석했다.", "eSum": "On 26 August at EUKOR's Seoul head office, Taebaek City, EcoMethanol (a special purpose company led by Plagen), Hyundai Corporation, Wallenius Wilhelmsen Ocean and EUKOR signed a multilateral green methanol MoU. EcoMethanol plans to make 15,000 tonnes a year from forestry residues by dual fluidized bed gasification at Taebaek's Dongjeom industrial complex, with Hyundai Corporation buying it and supplying the carriers as ship fuel; the KRW 120bn plant targets construction from December 2026 and commercial output from January 2029. The article sees value in bringing the trader and end users in before construction, but notes the volume equals about 0.75% of Korea's roughly 2 million tonnes of annual methanol use and that production cost, transport to ports and life-cycle emissions will decide its economics.", "kImp": "2029년부터 국내산 청정메탄올 공급망이 열리면 국내 항만 메탄올 벙커링 가능성이 생기므로, 메탄올 이중연료선 연료 계획에 국내 공급 일정과 연료 품질·전과정(LCA) 인증 확인 절차를 미리 반영할 필요가 있다.", "eImp": "If a Korean green methanol supply chain opens from 2029, methanol bunkering at Korean ports becomes possible, so fuel planning for methanol dual-fuel ships should track the supply timeline and build in fuel quality and life-cycle certification checks.", "url": "https://www.energydaily.co.kr/news/articleView.html?idxno=202574", "prio": 2}, {"code": "EUKOR", "date": "2026-07-26", "src": "이데일리", "title": "EUKOR '아틱 턴' 평택 첫 입항 배경엔 카보타지 예외 연장…해수부, 외국적 자동차선 연안운송 허가 2028년 6월까지 3년 연장", "eTitle": "Behind EUKOR's First Arctic Tern Call at Pyeongtaek: Korea Extended Coastal-Carriage Permits for Foreign-Flag Car Carriers at Nine Ports by Three Years to June 2028", "kSum": "이데일리는 7월 26일 EUKOR의 9,300대급 메탄올 이중연료선 '아틱 턴'이 7월 22일 평택항에 첫 입항할 수 있었던 배경에 카보타지(외국 선박의 국내 항만 간 운송 금지, 선박법 제6조) 예외 허가 연장이 있었다고 보도했다. 평택항의 외국적 자동차운반선 수출입 자동차화물 연안운송 허가는 2025년 6월 30일 종료될 예정이었으나, 경기도의 건의를 받은 해양수산부가 평택항 등 전국 9개 항만의 허가기간을 2028년 6월 30일까지 3년 연장했다. 서울에 본사를 둔 EUKOR는 왈레니우스 윌헬름센 80%·현대차그룹 20% 지분 구조라 연안운송 시 카보타지 적용 대상이고, 현대글로비스도 운반선 대다수를 외국 선사에서 용선해 허가 종료 시 물류 비효율을 우려했으며, 평택항은 2025년 자동차 161만6,086대를 처리했다.", "eSum": "Edaily reported on 26 July that EUKOR's 9,300-car methanol dual-fuel Arctic Tern could make her first Pyeongtaek call on 22 July because Korea had extended an exemption from its cabotage ban under Article 6 of the Ship Act. Permits allowing foreign-flag car carriers to move export and import vehicles between Korean ports at Pyeongtaek were due to lapse on 30 June 2025, but after a request from Gyeonggi Province the Ministry of Oceans and Fisheries extended them for nine ports, including Pyeongtaek, by three years to 30 June 2028. EUKOR is based in Seoul but owned 80% by Wallenius Wilhelmsen and 20% by Hyundai Motor Group, so its coastal carriage falls under cabotage, and Hyundai Glovis also relies mostly on ships chartered from foreign owners; Pyeongtaek handled 1,616,086 vehicles in 2025.", "kImp": "울산 생산 차량을 평택 등에서 환적하는 연안 구간을 외국적 선박이 맡으려면 2028년 6월 30일까지 유효한 해수부 허가가 필요하므로, 허가 대상 항만·화물 조건과 만료 전 재연장 동향을 배선 계획과 함께 관리해야 한다.", "eImp": "Coastal legs by foreign-flag ships, such as moving Ulsan-built cars to Pyeongtaek for export, depend on ministry permits valid only until 30 June 2028, so the permitted ports and cargo conditions and any renewal before expiry should be tracked alongside deployment planning.", "url": "https://www.edaily.co.kr/News/Read?newsId=01879446645518456", "prio": 2}, {"code": "EUKOR", "date": "2026-07-23", "src": "아시아경제", "title": "EUKOR '아틱 턴', 평택항 첫 입항…9,300CEU 메탄올 이중연료선 아시아-유럽 항로 투입", "eTitle": "EUKOR's Arctic Tern Makes Her First Call at Pyeongtaek as the 9,300 CEU Methanol Dual-Fuel Ship Joins the Asia-Europe Rotation", "kSum": "경기평택항만공사에 따르면 유코카캐리어스(EUKOR)가 운항하는 셰이퍼급 1번선 '아틱 턴'이 7월 22일 평택항 국제자동차부두에 처음 입항했다. 길이 228m·폭 38m의 9,300CEU급 메탄올 이중연료선으로 아시아-유럽 자동차 운송 항로에 투입된다. 평택항은 2025년 자동차 161만6,086대를 처리해 전국 1위이며, 동부두 2~5번 선석(안벽 1,110m)이 3만~5만 DWT급 선박을 받는다. 자비에 르루아 EUKOR 대표는 평택항을 '회사에 매우 중요한 시장'이라고 했고, 김금규 공사 사장 직무대행은 대형·친환경 선박 유치 기반을 강화하겠다고 밝혔다.", "eSum": "Gyeonggi Pyeongtaek Port Corporation said EUKOR's Arctic Tern, the first Shaper Class ship, made her first call at Pyeongtaek's international car terminal on 22 July. The 228 m x 38 m, 9,300 CEU methanol dual-fuel ship serves EUKOR's Asia-Europe vehicle trade. Pyeongtaek handled 1,616,086 vehicles in 2025, the most of any Korean port, and its East Pier berths 2-5 (1,110 m of quay) take ships of 30,000-50,000 dwt. EUKOR CEO Xavier Leroi called Pyeongtaek a very important market for the company, and acting port corporation president Kim Geum-gyu pledged to strengthen support for larger and greener ships.", "kImp": "메탄올 이중연료 PCTC의 국내 기항이 시작된 만큼, 평택 등 국내 항만에서 메탄올 연료 탑재선의 입항 신고·위험물 안전관리 요건과 228m급 대형 PCTC의 접안·하역 계획을 항만당국과 미리 협의해 둘 필요가 있다.", "eImp": "As methanol dual-fuel PCTCs start calling Korean ports, entry reporting and dangerous-goods safety requirements for methanol-fuelled ships, and berthing and cargo plans for 228 m PCTCs, should be agreed in advance with port authorities such as Pyeongtaek.", "url": "https://view.asiae.co.kr/article/2026072312355325855", "prio": 2}, {"code": "EUKOR", "date": "2026-07-21", "src": "World Fuel", "title": "EUKOR '아틱 턴', 상하이항서 그린메탄올 2,800톤 첫 벙커링…선박 간 공급·하역 동시작업(SIMOPS)", "eTitle": "EUKOR's Arctic Tern Takes Its First 2,800 Tonnes of Green Methanol at Shanghai by Ship-to-Ship Transfer Run Alongside Cargo Operations", "kSum": "월드퓨얼(World Fuel)이 EUKOR를 대신해 주선하고 상하이국제항만그룹(SIPG) 산하 SIPG에너지가 공급해, 셰이퍼급 1번선 '아틱 턴'에 그린메탄올 약 2,800톤을 상하이항 와이가오차오 하이퉁(Haitong) 터미널에서 선박 간(STS) 방식으로 넣었다. 연료는 상하이 생활폐기물로 만든 ISCC-EU 인증 메탄올(탄소집약도 25gCO2e/MJ 미만)이며, 메탄올 벙커링선 '하이강즈위안(Hai Gang Zhi Yuan)'이 차량 하역과 동시에(SIMOPS) 공급했다. SIPG에너지는 중국 내 PCTC 대상 단일 SIMOPS 그린메탄올 벙커링 최대 기록이라고 밝혔고, 선박은 급유 뒤 아시아-유럽 처녀항해를 이어갔다.", "eSum": "World Fuel arranged, on EUKOR's behalf, and SIPG Energy physically supplied about 2,800 tonnes of green methanol to Arctic Tern, the first Shaper Class ship, at Haitong Terminal in Shanghai's Waigaoqiao area by ship-to-ship transfer. The ISCC-EU certified fuel, made in Shanghai from municipal solid waste with a carbon intensity below 25 gCO2e/MJ, came from the bunker vessel Hai Gang Zhi Yuan while vehicle cargo operations continued (SIMOPS). SIPG Energy called it the largest single SIMOPS green methanol bunkering for PCTCs in China, and the ship then resumed her maiden Asia-Europe voyage.", "kImp": "메탄올 STS 벙커링을 하역과 병행하는 SIMOPS가 실제 적용된 만큼, 메탄올 이중연료선은 기항 전 벙커링 체크리스트·위험성평가·동시작업 안전구역 관리와 공급처 인증(ISCC) 서류 확인 절차를 갖춰야 한다.", "eImp": "With methanol STS bunkering now carried out alongside cargo work, methanol dual-fuel ships need bunkering checklists, risk assessments, SIMOPS safety-zone controls and supplier certification (ISCC) document checks in place before each call.", "url": "https://www.worldfuel.com/news/eukor-sipg-energy-and-world-fuel-complete-first-green-methanol-bunkering-new/", "prio": 3}, {"code": "EUKOR", "date": "2026-04-07", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "WW·현대차그룹, EUKOR 지분 20% 풋·콜옵션 운송계약(2029년 말) 기간 중 행사 불가 합의…부채 8.97억→3.86억 달러", "eTitle": "Wallenius Wilhelmsen and Hyundai Motor Group Agree the Options on HMG's 20% EUKOR Stake Cannot Be Exercised While the Ocean Carrier Contract Runs to End-2029, Cutting the Booked Liability From USD 897m to USD 386m", "kSum": "WW는 4월 7일 오슬로증시 공시에서 현대차그룹(HMG)이 보유한 EUKOR 지분 20%(현대차 12%·기아 8%)에 대한 풋·콜옵션을, EUKOR-HMG 해상운송계약(OCC)이 HMG 물량의 최소 50%를 보장하며 유효한 동안(현 계약 2029년 12월 31일까지) 행사할 수 없도록 합의했다고 밝혔다. WW는 2025년 말 한국 법령상 산정 방식에 따른 추정 행사가로 8억9,700만 달러를 유동부채로 계상해 왔으나, 2분기 보고서에서 최초 행사 가능일(2031년 1월 1일) 기준 순현재가치로 재측정해 6월 말 3억8,600만 달러(비유동)로 줄였다. 3월 말(8억5,100만 달러) 대비 감소분 4억6,500만 달러는 자본에 직접 반영돼 자기자본비율이 39.4%에서 48.8%로 높아졌고, TradeWinds는 클락슨증권이 이번 합의로 약 4억8,000만 달러의 위험이 줄었다고 평가했다고 보도했다.", "eSum": "In an Oslo Børs notice on 7 April, WW said it and Hyundai Motor Group agreed that the put and call options on HMG's 20% stake in EUKOR (Hyundai 12%, Kia 8%) cannot be exercised while the EUKOR-HMG ocean carrier contract is in force with at least 50% of HMG's volumes, currently until 31 December 2029. WW had booked a current liability of USD 897m at end-2025 based on an estimated exercise price under a Korean legal methodology, and in its Q2 report it remeasured the liability at net present value to the earliest exercise date of 1 January 2031, cutting it to USD 386m (non-current) at end-June. The USD 465m reduction from end-March (USD 851m) went directly to equity, lifting the equity ratio from 39.4% to 48.8%, and TradeWinds reported that Clarksons Securities saw the deal removing about USD 480m of risk.", "kImp": "현대차그룹 지분 구조가 사실상 2030년까지 고정되고 그 조건이 HMG 물량 50% 이상 운송계약 유지인 만큼, EUKOR 선대의 정시성과 화물손상 예방 성과가 계약 유지와 직결되므로 관리선의 운항 신뢰성 지표 관리를 강화할 필요가 있다.", "eImp": "With the Hyundai ownership structure effectively fixed until 2030 on condition that at least 50% of HMG volumes stay under contract, schedule reliability and cargo-damage prevention on EUKOR ships are directly tied to keeping that contract, so ship reliability metrics deserve closer management.", "url": "https://newsweb.oslobors.no/message/670006", "prio": 3}]}, {"code": "BIZ", "kTitle": "계약·실적", "eTitle": "Contracts & Results", "items": [{"code": "BIZ", "date": "2026-11-26", "src": "RNZ·TransportTalk", "title": "월레니우스 윌헬름센, 2027년 한 해 일본→호주·뉴질랜드·피지·뉴칼레도니아 로로 서비스 중단 — '전 세계 차량 운송 선복 압박' 이유", "eTitle": "Wallenius Wilhelmsen Suspends Its Japan-Oceania RoRo Service for All of 2027 - Citing Capacity Pressure Across Global Vehicle Shipping", "kSum": "월레니우스 윌헬름센이 2027년 한 해 동안 일본에서 호주·뉴질랜드·피지·뉴칼레도니아로 가는 로로 서비스를 중단한다고 TransportTalk가 11월 24일 전했다. 회사는 네트워크와 가용 선복을 검토한 결과라고 설명했고, 수입업체에는 NCC Car Carriers의 서비스 공지로 먼저 통보됐다. RNZ는 11월 26일 회사가 전 세계 차량 운송 시장의 지속적인 선복 압박을 이유로 들었으며, 올해 약 3,500대였던 뉴질랜드 중고 전기차 수입이 내년 약 2,500대로 줄 수 있다고 보도했다.", "eSum": "Wallenius Wilhelmsen will suspend its RoRo services from Japan to Australia, New Zealand, Fiji and New Caledonia for the whole of 2027 after a review of its network and capacity, TransportTalk reported on 24 November; RNZ said on 26 November the company cited ongoing capacity pressures in global vehicle shipping, and used-EV arrivals in New Zealand could fall from about 3,500 this year to about 2,500.", "kImp": "선복 재배치로 자동차선 항로가 바뀌고 있다. 2027년 항로 변경에 따른 신규 기항지(항만 정보·PSC 이력·UKC)를 미리 점검할 것.", "eImp": "Capacity is being redeployed and car-carrier routes are changing. Pre-check new 2027 calls (port information, PSC history, UKC).", "url": "https://rnz.co.nz/news/business/2788927/why-buying-a-used-ev-could-get-harder-next-year", "prio": 3}, {"code": "BIZ", "date": "2026-11-25", "src": "World Shipping Council", "title": "세계선사협의회(WSC) '2030년께 재생연료 사용 가능 선박이 정기선 에너지 수요의 5분의 1 이상' — 컨테이너선·자동차선 투자가 재생 선박연료 시장 창출", "eTitle": "WSC: Dual-Fuel Fleet Set to Meet Over a Fifth of Liner Energy Demand by 2030 - Container Ship and Vehicle Carrier Investment Creates a Renewable Fuel Market", "kSum": "세계선사협의회(WSC)는 11월 25일 보고서에서 새 컨테이너선과 자동차운반선 투자가 재생 선박연료의 상당한 잠재 시장을 만들고 있다고 밝혔다. 2030년께에는 이미 운항 중이거나 발주된 재생연료 사용 가능 선박이 정기선 해운 전체 에너지 수요의 5분의 1 이상을 차지할 것으로 내다봤다.", "eSum": "A World Shipping Council report released on 25 November says investment in new container ships and vehicle carriers is creating a substantial potential market for renewable marine fuels; by around 2030, ships already operating or on order that can use them are expected to account for more than a fifth of liner shipping's energy demand.", "kImp": "이중연료 자동차선 관리가 일상이 된다. 메탄올·LNG 이중연료선의 벙커링 절차·승무원 IGF 교육 수요를 인력 계획에 반영할 것.", "eImp": "Managing dual-fuel car carriers is becoming routine. Build methanol/LNG bunkering procedures and IGF training demand into crewing plans.", "url": "https://www.worldshipping.org/", "prio": 2}, {"code": "BIZ", "date": "2026-11-25", "src": "gCaptain(Bloomberg)", "title": "미국, 과잉생산 이유로 중국·EU 등 대상 신규 관세 — 중국 20%(협상 결렬 시 40%), EU는 15% 상한 유지", "eTitle": "US Targets China, the EU and Others With New Tariffs Citing Overcapacity - China at 20%, Possibly 40%; EU Cap of 15% Respected", "kSum": "미국은 대법원이 위헌으로 판단한 포괄 관세를 되살리려는 트럼프 대통령의 방침에 따라 중국, EU 등 10여 개 경제권 제품에 새 관세를 부과할 계획을 발표했다고 블룸버그가 11월 25일 전했다. 중국산 세율은 기존 합의에 맞춰 20%로 오르며, 협상이 깨지면 40%로 두 배가 될 수 있다. EU에 대해서는 2025년 무역협정의 15% 상한을 지키는 것으로 보인다.", "eSum": "The US announced plans for new tariffs on goods from China, the EU and a dozen other economies as President Trump seeks to restore sweeping import taxes the Supreme Court found unconstitutional, Bloomberg reported on 25 November; China's rate would rise to 20%, possibly doubling to 40% if talks collapse, while the EU's 15% cap under the 2025 deal appears respected.", "kImp": "관세 변화는 미국행 자동차 물동량을 흔든다. 미국 항로 PCTC는 선적 일정 변동과 항만 체류 변화를 용선주 공지로 계속 확인할 것.", "eImp": "Tariff changes move US-bound car volumes. US-trade PCTCs should keep checking charterer notices for schedule and port-stay changes.", "url": "https://gcaptain.com/u-s-targets-china-eu-with-new-tariffs-citing-overcapacity/", "prio": 2}, {"code": "BIZ", "date": "2026-11-25", "src": "Baird Maritime", "title": "상하이와이가오차오조선, 한국해양진흥공사(KOBC)에 LNG 이중연료 PCTC 계획보다 4개월 앞당겨 인도", "eTitle": "SWS Delivers an LNG Dual-Fuel PCTC to Korea Ocean Business Corporation Four Months Ahead of Schedule", "kSum": "중국선박그룹(CSSC) 계열 상하이와이가오차오조선(SWS)이 한국해양진흥공사(KOBC)에 LNG 이중연료 자동차운반선(PCTC)을 계획보다 4개월 앞당겨 인도했다고 Baird Maritime이 11월 25일 전했다.", "eSum": "CSSC subsidiary Shanghai Waigaoqiao Shipbuilding delivered a new LNG dual-fuel PCTC to Korea Ocean Business Corporation four months ahead of schedule, Baird Maritime reported on 25 November.", "kImp": "한국 정책금융이 소유한 이중연료 PCTC가 늘고 있다. LNG 이중연료 자동차선 관리 수요에 대비해 IGF 코드 교육 이수 사관 풀과 가스연료 벙커링 절차를 준비할 것.", "eImp": "Korean state-backed dual-fuel PCTCs are increasing. Prepare an IGF-trained officer pool and LNG bunkering procedures for dual-fuel car carrier management demand.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/dry-cargo-vessel-news-roundup-november-25-australias-new-bass-strait-ro-ro-chinese-built-dual-fuel-pctcs-and-more", "prio": 2}, {"code": "BIZ", "date": "2026-11-24", "src": "Baird Maritime", "title": "싱가포르 쉬핑, 7,000CEU LNG 이중연료 PCTC 2척 2031년 3·6월 인도 — 보유 5척(3만2,410CEU) 중 80%가 경제수명 끝나가 선대 교체", "eTitle": "Singapore Shipping's Two 7,000-CEU LNG Dual-Fuel PCTCs Due March and June 2031 - 80% of Its Five-Ship, 32,410-CEU Fleet Nears the End of Economic Life", "kSum": "싱가포르 쉬핑(SSC)이 중국 광저우조선(GSI)에 발주한 LNG 이중연료 PCTC 2척은 각 7,000CEU 규모로, 2031년 3월 31일과 6월 30일 전후 인도될 예정이라고 Baird Maritime이 11월 24일 전했다. SSC는 PCTC 5척(합계 3만2,410CEU)을 보유하고 있으며, 최근 연차보고서에서 회장은 선대의 약 80%가 경제적 수명 끝에 다가가고 있다고 밝혔다. 가장 오래된 배는 1999년 건조 7,200CEU선과 2000년 건조 5,190CEU선이다. GSI와 SSC의 첫 거래로, 18년간 PCTC 소유·임대를 해 온 SSC 선대 교체의 핵심이다.", "eSum": "Singapore Shipping Corporation's two LNG dual-fuel PCTCs ordered at Guangzhou Shipyard International are 7,000 CEU each, due on or around 31 March and 30 June 2031, Baird Maritime reported on 24 November. SSC owns five PCTCs totalling 32,410 CEU; its chairman said about 80% of the fleet is nearing the end of its economic life, the oldest being a 1999-built 7,200 CEU ship and a 2000-built 5,190 CEU ship. It is the first deal between GSI and SSC.", "kImp": "1999~2000년대 초반 건조 PCTC가 대거 교체 시기에 들어섰다. 교체 전 마지막 몇 년 운항하는 노후 자동차선은 데크·램프 구조, 화재 탐지·소화 설비 상태를 중점 관리하고, 선주의 교체 일정에 맞춰 정비 투자 범위를 합의할 것.", "eImp": "PCTCs built around 1999-2000 are entering replacement. For old car carriers in their last trading years, focus on deck/ramp structure and fire detection/extinguishing, and agree maintenance spending with owners in line with their replacement timetable.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/singapore-shipping-orders-car-carriers", "prio": 2}, {"code": "BIZ", "date": "2026-11-20", "src": "Automotive Logistics", "title": "회그 오토라이너스, BYD 배터리 탑재 'Aurora 12호' — 암모니아 연료·태양광·축발전기 결합, 연 1,000톤 배출 감축 목표(2028년 5월 인도)", "eTitle": "Höegh Autoliners and BYD Bring Battery Systems to Aurora No. 12 - Combined With Ammonia Fuel, Solar Panels and a Shaft Generator, Targeting 1,000 t a Year Less Emissions (Delivery May 2028)", "kSum": "회그 오토라이너스는 차세대 자동차운반선 Aurora 12호에 BYD의 선박용 배터리 시스템을 탑재하고, 암모니아 추진·태양광 패널·축발전기와 결합한다고 밝혔다. 회사는 연간 1,000톤의 배출 감축을 목표로 하며 '지금까지 건조된 가장 연료 효율적이고 친환경적인 PCTC'가 될 것이라고 설명했다. 배는 2028년 5월 인도돼 상업 운항에 들어갈 예정이다.", "eSum": "Höegh Autoliners will integrate BYD marine battery systems on its next-generation car carrier Aurora No. 12, combining them with ammonia propulsion, solar panels and a shaft generator, and targeting annual emissions savings of 1,000 tonnes. The company says it will be the most fuel-efficient and environmentally friendly PCTC built to date. Delivery and commercial operation are scheduled for May 2028.", "kImp": "자동차선에 배터리·암모니아가 함께 들어오면서 화재·독성가스 위험이 겹친다. 신조 PCTC 관리 예정 시 배터리실 소화설비와 암모니아 누출 대응 절차를 인도 전 선원 교육에 넣을 것.", "eImp": "Batteries and ammonia together on car carriers combine fire and toxic-gas risks. If taking on new PCTCs, include battery-room fire protection and ammonia leak response in pre-delivery crew training.", "url": "https://automotivelogistics.media/news/hoeegh-autoliners-partners-with-byd-to-bring-battery-technology-to-aurora-car-carrier/2772594", "prio": 2}, {"code": "BIZ", "date": "2026-11-23", "src": "LNG Prime", "title": "싱가포르 쉬핑, 중국 광저우조선(GSI)에 LNG 이중연료 자동차운반선 2척 발주", "eTitle": "Singapore Shipping Orders Two LNG Dual-Fuel Car Carriers at China's Guangzhou Shipyard International", "kSum": "싱가포르 쉬핑(Singapore Shipping)이 중국 광저우조선국제(GSI)에 LNG 이중연료 자동차운반선(PCTC) 2척을 발주했다고 LNG Prime이 11월 23일 보도했다. GSI는 SFL·H-Line·HMM·시스팬·현대글로비스 등에 7,000~10,800대급 LNG 이중연료 PCTC를 잇달아 건조·인도해 왔다. 올해 상반기 PCTC 신규 발주의 80% 이상이 중국 조선소로 갔다는 집계도 있다.", "eSum": "Singapore Shipping has ordered two LNG dual-fuel pure car and truck carriers from China's Guangzhou Shipyard International (GSI), LNG Prime reported on 23 November. GSI has built and delivered series of 7,000- to 10,800-unit LNG dual-fuel PCTCs for SFL, H-Line, HMM, Seaspan and Hyundai Glovis; more than 80% of new PCTC orders in H1 2026 went to Chinese yards.", "kImp": "용선 시장에 LNG 추진 PCTC가 빠르게 늘고 있다. 자동차선 관리사는 LNG 연료 취급·벙커링 훈련과 IGF 코드 교육을 받은 사관 풀을 미리 확보해 둘 것.", "eImp": "LNG-fuelled PCTCs are joining the market fast. Car-carrier managers should build a pool of officers trained in LNG fuel handling, bunkering and the IGF Code ahead of time.", "url": "https://lngprime.com/asia/singapore-shipping-orders-two-lng-powered-pctcs-in-china/200439", "prio": 2}, {"code": "BIZ", "date": "2026-11-20", "src": "파이낸셜뉴스(메리츠증권)", "title": "\"부르는 게 값\" 자동차선 초호황 — 현대글로비스 PCTC 96척(2분기 말)→2029년 말 139척, 중국 수출 1,100만 대 중 400만 대는 컨테이너로", "eTitle": "Car Carriers Name Their Price - Hyundai Glovis to Grow From 96 PCTCs at End-Q2 to 139 by End-2029; 4 Million of China's 11 Million Exports Go by Container", "kSum": "메리츠증권 분석을 인용한 보도에 따르면 중국 자동차 수출은 2026년 1,100만 대를 넘고 2027년 1,300만~1,400만 대에 이를 전망이다. 올해 1,100만 대 가운데 자동차운반선(PCTC)으로 600만 대, 컨테이너선으로 400만 대가 실린다. 세계 PCTC 약 800척 중 25년 넘은 노후선이 200척(25%)이고, 중국 선대의 의미 있는 증가는 2030년 이후에나 가능하다고 봤다. 중국의 수출 차량 부가가치세 환급률이 2027년 4월부터 13%에서 9%로 낮아져 수출 앞당김 물량이 늘 수 있다. 현대글로비스의 PCTC 운영 선대는 2026년 2분기 말 96척에서 2026년 말 110척, 2027년 말 120척, 2028년 말 130척, 2029년 말 139척으로 늘어날 전망이다.", "eSum": "Citing Meritz Securities, the report says China's vehicle exports will exceed 11 million in 2026 and reach 13-14 million in 2027. Of this year's 11 million, 6 million move by PCTC and 4 million by container ship. Of about 800 PCTCs worldwide, 200 (25%) are over 25 years old, and a meaningful increase in China's own fleet is unlikely before 2030. China's VAT rebate on exported vehicles falls from 13% to 9% from April 2027, which could pull exports forward. Hyundai Glovis's operated PCTC fleet is expected to grow from 96 ships at the end of Q2 2026 to 110 by end-2026, 120 by end-2027, 130 by end-2028 and 139 by end-2029.", "kImp": "선대 4분의 1이 25년을 넘긴 상태에서 신조가 대거 들어온다. 자동차선 관리사는 노후선의 연장 운항(특별검사·전기차 화재 대비 보강)과 신조 인수 인력 배치를 같은 기간에 계획해야 한다.", "eImp": "A quarter of the fleet is over 25 while newbuildings arrive in numbers. Car carrier managers must plan life extension of older ships (special surveys, EV fire upgrades) and staffing for newbuild take-overs over the same period.", "url": "https://www.fnnews.com/news/202611200829194982", "prio": 2}, {"code": "BIZ", "date": "2026-11-19", "src": "MarketScreener", "title": "Höegh Autoliners, 3분기 배당 1억 400만 달러(주당 0.5219달러) 결의 — 11월 23일 배당락, 30일 지급", "eTitle": "Höegh Autoliners Declares a USD 104 Million Dividend (USD 0.5219 a Share) - Ex-Dividend 23 November, Paid 30 November", "kSum": "Höegh Autoliners 이사회는 11월 18일 총 1억 400만 달러, 주당 0.5219달러(약 5.0461노르웨이크로네)의 배당을 결의했다고 19일 공시했다. 배당 기준 마지막 거래일은 11월 20일, 배당락일은 23일, 기준일은 24일, 지급일은 30일이다. 3분기 EBITDA가 1억 1,600만 달러로 줄었는데도 높은 배당을 이어간 것이다.", "eSum": "Höegh Autoliners announced on 19 November that its board decided on 18 November to pay a dividend of USD 104 million in total, USD 0.5219 a share (about NOK 5.0461). The last day with entitlement is 20 November, the ex-dividend date 23 November, the record date 24 November and payment 30 November. The company kept a high payout despite third-quarter EBITDA falling to USD 116 million.", "kImp": "운항사는 이익이 줄어도 현금을 주주에게 돌려줄 만큼 여유가 있다. 선박관리사는 지금을 관리 계약 갱신·범위 확대 협상의 적기로 보고, 비용보다 안전·가동률 실적을 근거로 제시할 것.", "eImp": "Operators still have the cash to return to shareholders even as profits slip. Managers should treat this as a good time to renew or widen management contracts, leading with safety and uptime records rather than cost.", "url": "https://de.marketscreener.com/boerse-nachrichten/hoeegh-autoliners-asa-kuendigt-dividende-an-zahlbar-am-30-november-2026-ce785ed2d88bf727", "prio": 1}, {"code": "BIZ", "date": "2026-11-20", "src": "AutoTrader NZ", "title": "Wallenius Wilhelmsen, 일본-뉴질랜드 서비스 중단 예정 — 일본산 중고 전기차 수입가 상승 전망", "eTitle": "Wallenius Wilhelmsen to Suspend Its Japan-New Zealand Service - Used EVs Imported From Japan Expected to Cost More", "kSum": "뉴질랜드 자동차 매체 AutoTrader NZ는 Wallenius Wilhelmsen이 일본-뉴질랜드 간 자동차 운송 서비스를 일정 기간 중단할 예정이라고 11월 20일 전했다. 이에 따라 일본에서 들여오는 중고 전기차 가격이 내년에 오를 것으로 예상된다. 중단 이유와 기간은 기사 요약에 나오지 않았다.", "eSum": "New Zealand's AutoTrader NZ reported on 20 November that Wallenius Wilhelmsen will suspend its vehicle shipping service between Japan and New Zealand for a period. Used EVs imported from Japan are expected to cost more next year as a result. The reason and duration were not given in the summary.", "kImp": "오세아니아 노선 배선 변화 신호다. 자동차선 관리사는 배선 변경에 따른 신규 기항지(항만 정보·도선·검역 요건)를 미리 확인할 것.", "eImp": "This signals a change in Oceania deployment. Car carrier managers should check port information, pilotage and biosecurity requirements for any new ports resulting from redeployment.", "url": "https://autotrader.co.nz/news/shipping-change-set-to-push-up-used-ev-prices", "prio": 3}, {"code": "BIZ", "date": "2026-11-19", "src": "Baird Maritime", "title": "Höegh Autoliners 3분기 EBITDA 1억 1,600만 달러로 감소 — 운임은 올랐지만 중동 차질과 연료비가 발목, 중국 자동차 수출 69% 증가", "eTitle": "Höegh Autoliners' Q3 EBITDA Falls to USD 116 Million - Freight Rates Rose but Middle East Disruption and Fuel Costs Weighed; Chinese Vehicle Exports Up 69%", "kSum": "노르웨이 자동차선사 Höegh Autoliners가 11월 19일 발표한 2026년 3분기 상각 전 영업이익(EBITDA)은 1억 1,600만 달러로 1년 전 1억 5,500만 달러, 2분기 1억 2,200만 달러보다 줄었다. 매출은 3억 9,400만 달러, 순이익은 7,300만 달러(전년 8,600만 달러)다. 운송량은 약 400만 ㎥로 비슷했고 총 운임은 ㎥당 98.1달러로 2분기보다 5% 올랐다. 중동 항로 차질과 높은 연료비가 이익을 깎았고 유류할증료 인상이 일부를 메웠다. 회사는 4분기 EBITDA가 3분기를 조금 웃돌 것으로 보고 1억 400만 달러를 배당한다. 운항 선대는 자동차선 44척(자가 37척)이며 2029~2031년 인도분 LNG 이중연료선 6척을 더 발주해 신조 계획이 18척이 됐다. 최고경영자는 중국의 수출 규제 강화가 변수라고 했다.", "eSum": "Norwegian car carrier operator Höegh Autoliners reported third-quarter 2026 EBITDA of USD 116 million on 19 November, down from USD 155 million a year earlier and USD 122 million in the second quarter. Revenue was USD 394 million and net profit USD 73 million (USD 86 million a year ago). Volumes were steady at about 4 million cbm and the gross freight rate rose 5% on the quarter to USD 98.1 per cbm. Disruption on Middle East trades and high fuel prices cut earnings, partly offset by higher bunker surcharges. The company expects fourth-quarter EBITDA somewhat above the third and will pay a USD 104 million dividend. It operates 44 PCTCs, 37 of them owned, and has ordered six more LNG dual-fuel ships for 2029-2031, taking its newbuilding programme to 18. The chief executive flagged tightening Chinese export regulation as an uncertainty.", "kImp": "자동차선 시황은 물량과 운임이 좋아도 우회·연료비가 이익을 깎는 국면이다. 자동차선 관리사는 선주가 연료 소모와 항차 지연에 더 민감해진다는 점을 감안해 선체·프로펠러 청소 주기, 감속 운항 때의 기관 저부하 관리, 지연 원인 보고의 정확도를 챙길 것.", "eImp": "In car carriers, volumes and rates are strong but diversions and fuel costs are eroding profit. Managers should expect owners to be more sensitive to consumption and voyage delays, and attend to hull and propeller cleaning intervals, low-load engine management when slow steaming and accurate reporting of delay causes.", "url": "https://bairdmaritime.com/shipping/dry-cargo/pcc-pctc/hoegh-autoliners-quarterly-earnings-fall", "prio": 3}, {"code": "BIZ", "date": "2026-11-17", "src": "Ship Management International(NorthStandard)", "title": "NorthStandard, 2027/28 갱신 P&I·FD&D 일괄 3% 인상 — 보험료 수입 11억 7,000만 달러, 자유준비금 9억 7,800만 달러 전망", "eTitle": "NorthStandard Sets a 3% General Increase for P&I and FD&D at the 2027/28 Renewal - Premium Income of USD 1.17 Billion and Free Reserves Forecast at USD 978 Million", "kSum": "P&I 클럽 NorthStandard가 2027/28 보험연도 갱신에서 P&I와 FD&D 보험료를 각각 3% 일괄 인상한다고 발표했다. 올해 보험연도의 전체 보험료 수입은 11억 7,000만 달러로 지난해 9억 3,800만 달러에서 늘어, 2023년 합병 때 세운 10억 달러 목표를 넘는다. 자유준비금은 2027년 2월 20일까지 5,500만 달러 늘어 9억 7,800만 달러가 될 전망이다. 회계연도 합산비율 목표는 95%(전년 105%)지만 P&I 보험연도 기준으로는 100%를 넘을 것으로 봤다. 대형 사고와 국제그룹 풀 클레임 증가가 배경이다. 앞서 UK 클럽은 4.5%, Gard는 평균 4% 조정을 발표했고 Shipowners' 클럽은 인상하지 않는다.", "eSum": "P&I club NorthStandard has announced a 3% general increase for both P&I and FD&D premiums at the 2027/28 renewal. Overall premium income is set to reach USD 1.17 billion this insurance year, up from USD 938 million and above the USD 1 billion target set at the 2023 merger. Free reserves are projected to rise by USD 55 million to USD 978 million by 20 February 2027. The financial-year combined ratio target is 95%, against 105% last year, but the P&I policy-year ratio is expected to exceed 100% on higher large claims and International Group pool claims. The UK Club earlier announced 4.5% and Gard an average 4% adjustment, while the Shipowners' Club is holding at zero.", "kImp": "클럽마다 인상 폭이 0~4.5%로 갈렸다. 선박관리사는 선주의 2월 갱신 협상에 쓸 수 있도록 최근 5년 클레임 기록과 손실 방지 조치(선원 부상·질병, 화물, 접촉 사고)를 12월 안에 정리해 제공할 것.", "eImp": "Clubs' general increases range from zero to 4.5%. Managers should give owners a five-year claims record and loss prevention measures (crew injury and illness, cargo, contact damage) by the end of December for the February renewal negotiations.", "url": "https://www.shipmanagementinternational.com/news/wl99dnrp448ehp4-mcl97-efbrp-5r4g8-pyc95-bwnyg-se4sn-6rryx-ec7aw-4whce-n89h3-y6dr6-wfpcg-922xa-dwtan-ecc7p-w4gct-pazey-djjam-e8jwx-f3z72-w35te-mgzcz-gfem8-n8k5l-f4fab-9smrd-8hl6g-dzdbs-4mx8m-6p2j9", "prio": 2}, {"code": "BIZ", "date": "2026-11-17", "src": "DataPortuaria(gCaptain·Splash247 종합)", "title": "EU, 러시아 '그림자 선단' 제재 확대 — 개인 12명·기관 101곳 추가(선주·선박관리사·보험사·금융망), 두바이 관리사와 모스크바 보험사 포함", "eTitle": "EU Widens Sanctions on Russia's Shadow Fleet - 12 Individuals and 101 Entities Added Across Shipowners, Ship Managers, Insurers and Financial Networks, Including Dubai Managers and a Moscow Insurer", "kSum": "유럽연합이 러시아 그림자 선단과 연결된 개인 12명과 기관 101곳, 모두 113건을 제재 명단에 추가했다고 11월 17일 보도됐다. 대상은 선주, 선박관리사, 보험사, 금융망에 걸쳐 있으며 두바이에 있는 선박관리사들과 옛 소브콤플로트 선박의 선주, 모스크바의 보험사, 상트페테르부르크 석유 터미널이 포함됐다. 러시아 은행·금융기관 약 50곳도 들어갔다. 자산 동결과 여행 금지가 적용된다. EU는 이미 670척이 넘는 선박에 대해 역내 항만 입항과 해사 서비스 제공을 막고 있다.", "eSum": "Reports on 17 November say the EU has added 12 individuals and 101 entities, 113 listings in all, linked to Russia's shadow fleet. They span shipowners, ship managers, insurers and financial networks and include Dubai-based ship managers, owners of former Sovcomflot ships, a Moscow insurer and the Petersburg Oil Terminal, plus about 50 Russian banks and financial institutions. Asset freezes and travel bans apply. More than 670 vessels already face EU port and maritime service restrictions.", "kImp": "제재가 선박에서 '선박관리사·보험사'로 넓어졌다. 선박관리사는 신규 선주·기술관리 인수 선박의 과거 관리사·보험사·선급 이력을 제재 명단과 대조하는 심사를 인수 절차에 넣고, 협력업체(선원 공급, 부품, 대리점) 심사 주기도 줄일 것.", "eImp": "Sanctions have widened from ships to ship managers and insurers. Managers should add screening of a ship's past managers, insurers and class against sanctions lists to take-over procedures for new owners and vessels, and shorten the screening interval for suppliers such as crewing agents, parts vendors and port agents.", "url": "https://dataportuaria.com/en/destacadas/eu-expands-sanctions-on-russia-s-shadow-fleet-targeting-113-entities-66c9f8", "prio": 2}, {"code": "BIZ", "date": "2026-11-13", "src": "Baird Maritime", "title": "중국 초상륜선 첫 7,800CEU 메탄올 이중연료 자동차선 'CM Guangzhou' — 13개 데크·최대 8,102대, 난사에서 메탄올 2,300톤(바이오메탄올 1,400톤) 벙커링", "eTitle": "China Merchants' First 7,800 CEU Methanol Dual-Fuel Car Carrier CM Guangzhou - 13 Decks and Up to 8,102 Vehicles, Bunkering 2,300 Tonnes of Methanol (1,400 Tonnes Bio) at Nansha", "kSum": "초상에너지해운 소유, 초상로로 운항의 홍콩 선적 'CM Guangzhou'는 핀란드 델타마린 설계로 난징의 초상진링조선소가 지어 10월 10일 인도했다. 길이 199.9m, 폭 37.7m, 흘수 9.3m, 총톤수 76,400톤, 설계 속력 19노트이며 13개 데크에 최대 8,102대를 싣는다. 메탄올과 기존 연료를 모두 쓰는 이중연료 주기관, IMO Tier III, 고압 육상전원 설비를 갖췄다. 첫 항차에 난징에서 1,530대, 난사에서 신에너지차 4,000대 이상을 싣고 스페인·벨기에로 향했고 난사에서 메탄올 2,300톤(이 중 바이오메탄올 1,400톤)을 벙커링했다. 4척 시리즈의 1번선으로 CM Wuhan이 10월 16일 인도됐고 CM Shanghai·CM Dalian은 연말까지 취항한다.", "eSum": "Owned by China Merchants Energy Shipping and operated by China Merchants RoRo, the Hong Kong-flagged CM Guangzhou was designed by Deltamarin and delivered by China Merchants Jinling Shipyard on 10 October. It is 199.9 m long with a 37.7 m beam and 9.3 m draught, 76,400 gross tonnes and a 19-knot design speed, and carries up to 8,102 vehicles on 13 decks. It has a dual-fuel main engine for methanol or conventional fuel, IMO Tier III compliance and medium-voltage shore power. On its first voyage it loaded 1,530 vehicles at Nanjing and more than 4,000 new-energy vehicles at Nansha for Spain and Belgium, bunkering 2,300 tonnes of methanol there, 1,400 tonnes of it biomethanol. It leads a series of four: CM Wuhan was delivered on 16 October and CM Shanghai and CM Dalian are due in service by year-end.", "kImp": "메탄올 DF 자동차선이 실제 항차에서 바이오메탄올을 대량 벙커링하기 시작했다. 메탄올 DF선을 인수할 관리사는 벙커링 체크리스트, 저인화점 연료 교육(IGF), 메탄올 화재 탐지·소화 설비 점검 주기를 인수 전 절차서에 반영할 것.", "eImp": "Methanol dual-fuel car carriers are now bunkering biomethanol in volume on commercial voyages. Managers taking over methanol DF ships should have bunkering checklists, low-flashpoint fuel training (IGF) and inspection intervals for methanol fire detection and extinguishing systems in place before delivery.", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/cm-guangzhou-review-methanol-carrier", "prio": 2}, {"code": "BIZ", "date": "2026-11-14", "src": "Hellenic Shipping News(Neptune Group)", "title": "그리스 넵튠, LNG 이중연료 자동차선 'Nikos Travlos' 피레우스 입항 — 신조 계획 4척에서 10척으로 확대, 관리 선대 26척·발주 잔량 8척", "eTitle": "Greece's Neptune Welcomes Its LNG Dual-Fuel Car Carrier Nikos Travlos to Piraeus - Renewal Programme Grows From Four to Ten PCTCs, With 26 Ships Managed and Eight on Order", "kSum": "그리스 넵튠 그룹이 중국 푸젠 마웨이 조선소에서 인도받은 LNG 이중연료 자동차운반선 'Nikos Travlos'가 11월 14일 피레우스에 입항했다. 그리스 선적이며 선대 갱신 계획 '제네시스'의 2번선이다(1번선 Neptune Piraeus). 제네시스 계획은 4척에서 10척으로 늘어난다. 넵튠은 현재 26척을 관리하고 8척을 발주해 둔 상태다. 해운 외에 육상 운송과 항만 서비스를 묶은 물류 사업을 하며 남프랑스 포르라누벨에 첫 자동차 터미널을 두고 있다. 입항 행사는 창립 50여 년 기념 일정의 시작이기도 했다.", "eSum": "Neptune Group's LNG dual-fuel pure car and truck carrier Nikos Travlos, delivered by Fujian Mawei Shipyard in China, arrived in Piraeus on 14 November. Greek-flagged, it is the second ship of the Genesis renewal programme after Neptune Piraeus, and the programme is being expanded from four to ten PCTCs. Neptune manages 26 vessels with eight more on order, combines shipping with land transport and port services, and has its first car terminal at Port-La-Nouvelle in southern France. The ceremony also opened celebrations of more than 50 years in business.", "kImp": "유럽 근해 자동차선 시장에도 LNG DF 신조선이 들어온다. 자동차선 관리사는 근해·지중해 항로에서 선령 높은 선박의 경쟁력(연료비, EU ETS·FuelEU 부담, 화주 감사 평가)을 선박별로 다시 점검할 것.", "eImp": "LNG dual-fuel newbuildings are arriving in the European short-sea car carrier market as well. Car carrier managers should re-check, ship by ship, how older tonnage on short-sea and Mediterranean routes competes on fuel cost, EU ETS and FuelEU exposure and shipper audits.", "url": "https://www.hellenicshippingnews.com/neptune-group-welcomes-nikos-travlos-to-piraeus-honouring-its-founder-and-opening-a-new-chapter-of-growth/", "prio": 2}, {"code": "BIZ", "date": "2026-11-10", "src": "SAFETY4SEA", "title": "[후속] 미 USTR 중국 연계 선박 입항료 유예(2027년 1월 9일까지) 의견 수렴: 약 60건 접수, 업계 의견 갈려 — 유예 영구화 요구와 '미국 조선 육성 위해 필요' 반대 공존", "eTitle": "[Follow-up] USTR Consultation on Suspending Port Fees on China-Linked Ships to 9 January 2027 Draws About 60 Comments and Split Views - Calls to Make the Pause Permanent Sit Beside Arguments That the Fees Are Needed to Build US Shipbuilding", "kSum": "미 무역대표부(USTR)는 11월 10일 연방관보 공고로 중국 연계 해운에 대한 301조 해상 서비스 수수료 유예를 2027년 1월 9일까지 유지한다고 확인했다. 중국산 STS 크레인과 하역 장비에 대한 관세도 계속 유예된다. 의견 수렴에는 약 60건이 접수됐다. 유예 지지 측은 운임 상승과 상업적 혼란을 막는다고 주장했고 일부는 특정 수수료의 영구 유예를 요구했다. 반대 측은 컨테이너 제조를 포함한 미국 조선 육성에 수수료가 필요하며 유예가 이어지면 중국의 입지가 강해진다고 경고했다. 장비 관세는 따로 다루자는 제안도 있었으나 USTR은 받아들이지 않았다. 중국도 미국 연계 선박에 대한 특별 입항료 유예를 2027년 1월 10일까지 연장했다.", "eSum": "The USTR confirmed in a Federal Register notice on 10 November that its suspension of Section 301 maritime service fees on China-linked shipping runs to 9 January 2027; duties on Chinese ship-to-shore cranes and cargo-handling equipment also stay suspended. The consultation drew about 60 comments. Supporters of the pause said it avoids higher shipping costs and commercial disruption, and some urged permanent suspension of certain fees; opponents said the fees are needed to encourage US shipbuilding, including container manufacturing, and that continued suspension strengthens China's position. Some proposed handling the equipment tariffs separately, which the USTR has not adopted. China extended its reciprocal suspension of special port fees on US-linked ships to 10 January 2027.", "kImp": "유예 시한이 1월 9~10일로 다가오고 있다. 중국 건조선·중국 연계 선주 선박의 미국 기항을 관리하는 회사는 시한 이후 수수료 부과 시나리오와 납부 주체(선주·용선주)를 용선 계약에서 확인해 둘 것.", "eImp": "The pause expires on 9-10 January. Managers handling US calls by Chinese-built or China-linked ships should check the scenario for fees after that date and who pays (owner or charterer) under the charter party.", "url": "https://safety4sea.com/us-port-fee-consultation-reveals-conflicting-industry-priorities/", "prio": 2}, {"code": "BIZ", "date": "2026-11-10", "src": "Splash247", "title": "MSC 계열 Global Car Carriers, 중국에 자동차선 4척 추가 발주 — 신조 프로그램 26척으로 확대", "eTitle": "MSC-Controlled Global Car Carriers Adds Four Newbuildings in China, Taking Its Programme to 26 Vessels", "kSum": "MSC가 지배하는 Global Car Carriers가 중국 조선소에 자동차운반선 4척을 추가 발주해 신조 프로그램이 26척으로 늘었다. 컨테이너 최대 선사가 자동차선 선복을 빠르게 키우고 있는 흐름이다.", "eSum": "MSC-controlled Global Car Carriers has added four newbuildings in China, expanding its newbuilding programme to 26 vessels - another step in the largest container line's rapid build-up of car carrier tonnage.", "kImp": "신조 대량 인도는 2028년 전후 자동차선 공급 과잉 우려를 키운다. 노후선은 PSC·용선주 검사 성적과 하역설비 상태가 용선 유지의 차별화 요소가 된다.", "eImp": "Heavy deliveries add to oversupply concerns around 2028. For older tonnage, PSC and charterer inspection records and cargo-gear condition become the differentiators for staying on charter.", "url": "https://splash247.com/mscs-car-carrier-arm-adds-four-newbuilds-in-china/", "prio": 2}, {"code": "BIZ", "date": "2026-11-11", "src": "쉬핑뉴스넷", "title": "WW, 10월 이후 3년 계약 2건(약 17억 달러) 체결 — 건설기계·기계 제조사, 아시아 주요 완성차 업체(2년 연장 옵션); 3분기 순운임 −2%·물량 −3%, 2026년 EBITDA 16억 달러 전망 유지", "eTitle": "WW Signs Two Three-Year Contracts Worth About USD 1.7bn Since October - a Construction and Machinery Maker and a Major Asian Carmaker (With a Two-Year Option); Q3 Net Freight -2%, Volumes -3%, 2026 EBITDA Outlook of USD 1.6bn Kept", "kSum": "3분기 매출은 해상운송 부문 증가로 5% 늘어난 14억100만 달러였으나 조정 EBITDA는 10% 줄어든 4억2,800만 달러, 순이익은 24% 감소한 2억1,200만 달러였다. 해상 물량이 전년을 밑돌고 운임이 약세를 보인 영향으로 ㎥당 순운임은 2%, 운송량은 3% 하락했다. 회사는 2026년 연간 조정 EBITDA 전망 16억 달러를 유지했으며, 10월 이후 건설기계·기계 제조사와 아시아 주요 완성차 업체와 각각 3년 계약(합계 약 17억 달러, 한 건은 2년 연장 옵션)을 체결했다.", "eSum": "Q3 revenue rose 5% to USD 1,401m on higher ocean revenue, but adjusted EBITDA fell 10% to USD 428m and net profit fell 24% to USD 212m. Ocean volumes were below last year and rates softer: net freight per cbm was down 2% and volumes down 3%. The company keeps its 2026 adjusted EBITDA outlook at USD 1.6bn and, since October, has signed three-year contracts with a construction and machinery maker and a major Asian carmaker worth about USD 1.7bn in total, one with a two-year extension option.", "kImp": "운임·물량이 동반 약세로 돌아서면 선주는 운항 효율과 off-hire에 더 민감해진다. 자동차선 관리사는 비계획 운항정지 시간과 하역설비(램프·리프터블 데크) 신뢰성을 핵심 지표로 관리해야 한다.", "eImp": "When both rates and volumes soften, owners become more sensitive to efficiency and off-hire. Car carrier managers should treat unplanned unavailability and cargo-gear reliability (ramps, liftable decks) as headline indicators.", "url": "https://www.shippingnewsnet.com/news/articleView.html?idxno=72953", "prio": 3}, {"code": "BIZ", "date": "2026-11-04", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "왈레니우스 윌헬름센 3분기 조정 EBITDA 4억2,800만 달러(가이던스 4.2~4.5억 범위), 순이익 2억1,200만 달러 — 2026년 16억 달러 전망 유지, 2027년 물량 40% 계약", "eTitle": "Wallenius Wilhelmsen Posts Q3 2026 Adjusted EBITDA of USD 428m, Within Its USD 420-450m Guidance, and Net Profit of USD 212m, Keeps Its 2026 Outlook at About USD 1.6bn and Has About 40% of 2027 Volumes Contracted", "kSum": "3분기 매출 14억100만 달러(전분기比 +7%, 전년比 +5%), 조정 EBITDA 4억2,800만 달러(전분기比 +19%, 전년比 -10%; 해운 3.55억·물류 0.45억·정부 0.38억), 순이익 2억1,200만 달러(주주귀속 1.92억, EPS 0.45달러)로 10/6 트레이딩 업데이트 가이던스(4.2~4.5억) 범위 안이다. 수송량은 1,320만 cbm(전분기比 -3%), 순운임은 cbm당 64.4달러(+5%, 무역·고객 믹스 효과), 유류할증료 수입은 2억2,000만 달러(+44%)로 평균 연료가 톤당 852달러 상승분을 따라잡아 순연료비가 정상화됐으나 1~2분기 초과분은 회수하지 못했다. 2026년 조정 EBITDA 전망 약 16억 달러를 유지했고 2026년 선복은 전량 확정, 2027년 해운 물량 약 40% 계약, 분기 후 3년 계약 2건(총 약 17억 달러)을 '견조한 시장 수준' 운임으로 따냈으며 연말까지 2027~2029년 선복 대부분을 계약할 계획이다. 3분기 배당은 선언하지 않았고(3분기 중 상반기 배당 2.86억 달러 지급), 순차입금 21억1,900만 달러·레버리지 1.3배·자기자본비율 47.0%, 2027년 전망은 4분기 실적과 함께 낸다.", "eSum": "Q3 revenue was USD 1,401m (up 7% QoQ, 5% YoY) and adjusted EBITDA USD 428m (up 19% QoQ, down 10% YoY; Shipping 355m, Logistics 45m, Government 38m), with net profit of USD 212m (USD 192m to shareholders, EPS USD 0.45), inside the USD 420-450m trading-update range. Volumes were 13.2m cbm (down 3% QoQ) at a net freight rate of USD 64.4/cbm (up 5% on trade and customer mix), and fuel surcharges rose 44% to USD 220m, normalising net bunker cost at an average fuel price of USD 852/t, though the Q1-Q2 shortfall was not recovered. The 2026 outlook of about USD 1.6bn adjusted EBITDA is maintained, 2026 capacity is fully committed, about 40% of 2027 shipping volumes are contracted and two post-quarter three-year awards worth about USD 1.7bn were won at rates reflecting firm market conditions, with most 2027-2029 capacity expected to be contracted by year-end. No Q3 dividend was declared (USD 286m of H1 dividends was paid in the quarter); net debt is USD 2,119m, leverage 1.3x, equity ratio 47.0%, and 2027 guidance will come with the Q4 report.", "kImp": "운임은 오르고 선복은 2029년까지 장기계약으로 묶이는 구조라 그룹 선대는 고가동·짧은 항만 체류가 계속될 전망이며, 정비·검사 일정 확보와 연료비 변동에 따른 감속·연료 관리가 선박관리의 핵심 과제가 된다.", "eImp": "With rates rising and capacity locked into multi-year contracts to 2029, the group fleet faces sustained high utilisation and short port stays, making maintenance and survey windows and fuel and speed management central ship-management tasks.", "url": "https://newsweb.oslobors.no/message/685534", "prio": 3}, {"code": "BIZ", "date": "2026-11-02", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "왈레니우스 윌헬름센, 아시아 자동차 제조사와 3년간 약 7억 달러 해상운송 계약 체결 — 2년 연장 옵션, 전 항로 '멀티퓨얼' 조항 포함", "eTitle": "Wallenius Wilhelmsen Signs a Three-Year Shipping Contract Worth About USD 700m With a Leading Asian Auto Manufacturer, With a Two-Year Extension Option and a Multi-Fuel Approach Across All Trade Lanes", "kSum": "11월 2일 06:00 UTC 오슬로 증권거래소 공시(비규제 보도자료). 계약 상대는 '선도적 아시아 자동차 제조사'로 이름은 공개하지 않았고, 최초 3년 기간의 계약 가치는 약 7억 달러, 운임은 현재 시장 수준이며 상호 합의 시 2년 연장 옵션이 있다. 계약에는 모든 항로에 걸쳐 대체·저탄소 연료의 단계적 도입을 수용하도록 설계된 '멀티퓨얼 접근법'이 포함됐다. 11월 1일 최고고객책임자(CCO)로 취임한 존 펠리토는 \"고객과 쌓아온 실적과 신뢰 위에 세운 계약으로 핵심 물류 파트너로서의 입지를 강화한다\"고 말했다. 10월 28일 LNG 이중연료 9,900CEU 4+8척 발주, 10월 29일 장비 제조사와 10억 달러 이상의 3년 계약 2건에 이어 1주일 사이 세 번째 대형 발표다(ship.energy·Maritime Executive도 같은 내용 보도).", "eSum": "Announced via the Oslo Stock Exchange at 06:00 UTC on 2 November as a non-regulatory press release: a three-year contract with an unnamed leading Asian auto manufacturer valued at about USD 700m over the initial term, at rates in line with current market levels, with a two-year extension option subject to mutual agreement. The agreement embeds a multi-fuel approach across all trade lanes, designed to accommodate the gradual introduction of alternative and lower-emission fuels. Chief Customer Officer John Felitto, in the role since 1 November, said the deal builds on the track record and trust established with the customer and strengthens the company's position as a key logistics partner. It is the third major announcement in a week, after the 28 October order for four plus eight 9,900 CEU LNG dual-fuel PCTCs and the 29 October USD 1bn-plus three-year contracts with an equipment manufacturer.", "kImp": "9월 시장 업데이트에서 밝힌 2027년 재협상 대상 물량(약 40%)이 시장 수준 운임의 다년 계약으로 잠겨가는 흐름으로, 11월 4일 3분기 실적에서 계약 커버리지와 운임 전망이 핵심 관전 포인트가 된다. 전 항로 멀티퓨얼 조항은 바이오연료·메탄올·LNG 등을 선대 전반에서 번갈아 쓰는 운용을 전제로 하므로, 그룹 선박관리사에는 연료 전환 절차·벙커링 안전관리·배출 데이터 검증 체계를 미리 갖추라는 신호다.", "eImp": "The deal extends the pattern of locking in the roughly 40% of 2027 volumes flagged for renegotiation in September into multi-year contracts at market-level rates, making contract coverage and rate outlook the key points to watch at the Q3 results on 4 November. The all-lanes multi-fuel clause presumes fleet-wide switching among biofuel, methanol and LNG, which tells group ship managers to have fuel-changeover procedures, bunkering safety controls and emissions-data verification ready in advance.", "url": "https://newsweb.oslobors.no/message/685271", "prio": 3}, {"code": "BIZ", "date": "2026-10-29", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "왈레니우스 윌헬름센, 대형 장비 제조사와 3년 계약 2건 체결…총 10억 달러 이상(해운 약 9.5억·물류 약 1억 달러), 해운 운임은 직전 계약 수준", "eTitle": "Wallenius Wilhelmsen Signs Two Three-Year Contracts Worth More Than USD 1bn With a Leading Equipment Manufacturer, With Shipping Rates Similar to the Previous Deal", "kSum": "왈레니우스 윌헬름센(WW)이 10월 29일 오랜 거래 관계의 '선도적 장비 제조사'와 해운·물류 3년 계약 2건, 총 10억 달러 이상을 체결했다고 발표했다. 해운 계약은 약 9억5,000만 달러로 운임이 직전 3년 계약과 비슷한 수준이며, 물류 계약은 같은 기간 약 1억 달러다. 고객명·개시일·물량은 공개하지 않았으며, 존 펠리토 최고고객책임자(CCO)는 고객의 변화하는 해운·물류 수요를 깊이 이해하고 있고 글로벌 네트워크 규모, 안정적 선복, 운영 유연성으로 고객의 글로벌 공급망을 지원하겠다고 말했다. 전날 발표한 9,900CEU LNG 이중연료선 4척(옵션 8척) 발주에 이은 발표다.", "eSum": "Wallenius Wilhelmsen announced on 29 October two three-year shipping and logistics contracts with a leading equipment manufacturer, a long-standing customer, worth more than USD 1bn in total. The shipping contract is worth about USD 950m at rates similar to the previous three-year contract, and the logistics contract about USD 100m over the same period. The customer, start date and volumes were not disclosed; Chief Customer Officer John Felitto said the company's global network scale, reliable capacity and operational flexibility position it to support the customer's global supply chain. The announcement came a day after WW ordered four 9,900 CEU LNG dual-fuel PCTCs with options for eight more.", "kImp": "장비 화물의 3년 물량을 직전과 비슷한 운임으로 확보해, 11월 4일 3분기 실적 발표와 2027년 계약 물량 재협상을 앞두고 운임 하방 위험을 줄이는 신호다. 그룹 선대에서는 중량 롤링 장비·브레이크벌크 화물의 고박과 램프·데크 허용 하중 관리 등 화물 안전 관리 수요가 계속될 것으로 보인다.", "eImp": "Locking in three years of equipment-maker volumes at rates similar to the prior deal reduces rate downside ahead of Q3 results on 4 November and the renegotiation of 2027 contract capacity. For the group fleet it means continued demand for careful securing of heavy rolling and breakbulk cargo and close attention to ramp and deck load limits.", "url": "https://newsweb.oslobors.no/message/685049", "prio": 3}, {"code": "BIZ", "date": "2026-10-27", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "왈레니우스 윌헬름센, 11월 4일 3분기 실적 발표…보고서 07시(CET) 공시·08시30분 설명회, 대주주 윌헬름센 홀딩도 같은 날 발표", "eTitle": "Wallenius Wilhelmsen Will Publish Q3 2026 Results on 4 November at 07:00 CET With a Presentation at 08:30, the Same Day Wilh. Wilhelmsen Holding Reports", "kSum": "왈레니우스 윌헬름센은 10월 27일 오슬로증권거래소 공시에서 3분기 실적 보고서를 11월 4일(수) 오전 7시(CET, 한국시간 오후 3시)에 오슬로증권거래소와 회사 홈페이지에 게재하고, 같은 날 오전 8시30분(한국시간 오후 4시30분) 리사케르 본사(Strandveien 20)에서 라세 크리스토페르센 CEO와 비에르나르 북홀름 CFO가 투자자·대주단·애널리스트·언론 대상 설명회를 연다고 밝혔다. 설명회는 웹캐스트로 생중계되며 시청자 질문을 받고, 녹화본과 발표자료는 이후 홈페이지에 올라간다. 회사는 10월 6일 3분기 조정 EBITDA를 4억2,000만~4억5,000만 달러로 제시하고 2026년 연간 조정 EBITDA 약 16억 달러 전망을 재확인한 바 있다. 대주주인 윌헬름센 홀딩(Wilh. Wilhelmsen Holding)도 5월 18일 공시한 재무 일정에 따라 같은 날 3분기 보고서를 낸다.", "eSum": "In an Oslo Børs notice on 27 October, Wallenius Wilhelmsen said it will publish its Q3 2026 report on Wednesday 4 November at 07:00 CET (15:00 in Korea) on the Oslo Stock Exchange and its website, followed at 08:30 CET by a presentation for investors, lenders, analysts and media by CEO Lasse Kristoffersen and CFO Bjørnar Bukholm at its Lysaker head office (Strandveien 20). The presentation will be webcast live with questions taken from viewers, and a recording and slides will be posted afterwards. On 6 October the company guided Q3 adjusted EBITDA of USD 420-450m and reconfirmed its outlook of about USD 1.6bn adjusted EBITDA for 2026. Major shareholder Wilh. Wilhelmsen Holding is also due to publish its Q3 report on 4 November, according to the financial calendar it filed on 18 May.", "kImp": "실적 발표에서 2027년 용량 재협상(약 40%) 결과, 최대 12척 LNG 이중연료 대형선 추가 발주 확정 여부, 중동·홍해 항로와 미국 입항료 유예 대응 관련 업데이트가 나올지 주목되며, 그룹 선대의 신조 인도·배선 계획과 연료 전환 일정을 점검할 기회다.", "eImp": "The results may update the renegotiation of about 40% of 2027 capacity, whether up to 12 more large LNG dual-fuel ships are firmed, and the approach to Middle East and Red Sea routings and the US port-fee suspension, offering a read-across for group newbuilding deliveries, deployment and fuel-transition plans.", "url": "https://newsweb.oslobors.no/message/684881", "prio": 1}, {"code": "BIZ", "date": "2026-10-19", "src": "Wallenius Wilhelmsen (MFN / Nordic Trustee)", "title": "왈레니우스 윌헬름센 ESG 채권(WAWI02) 이자율, 1월 21일까지 9.06%로 재설정", "eTitle": "Wallenius Wilhelmsen Resets the Coupon on Its WAWI02 ESG Bond to 9.06% for 21 October 2026 to 21 January 2027", "kSum": "노르딕 트러스티가 채권 계약에 따라 왈레니우스 윌헬름센의 WAWI02 ESG 채권(ISIN NO0012495912) 이자율을 9.06%로 재설정했다고 10월 19일 공시했다. 적용 기간은 2026년 10월 21일부터 2027년 1월 21일까지다.", "eSum": "Nordic Trustee announced on 19 October, under the bond agreement, that the coupon on Wallenius Wilhelmsen's WAWI02 ESG bond (ISIN NO0012495912) has been reset to 9.06%. The rate applies from 21 October 2026 to 21 January 2027.", "kImp": "신조 프로그램 확대 속 그룹의 변동금리 채권 조달 비용 수준을 보여주는 참고 지표다.", "eImp": "It is a reference point for the group's floating-rate bond funding cost as its newbuilding programme grows.", "url": "https://mfn.se/ob/a/wallenius-wilhelmsen/wawi-interest-adjustment-451e64ac", "prio": 1}, {"code": "BIZ", "date": "2026-10-15", "src": "Wallenius Wilhelmsen", "title": "WalWil, 존 펠리토 물류 COO를 11월 1일부로 최고고객책임자(CCO) 선임…피아 쉬네르만 퇴임", "eTitle": "Wallenius Wilhelmsen Appoints John Felitto, COO Logistics, as Chief Customer Officer From 1 November as Pia Synnerman Departs", "kSum": "WalWil은 현 물류 부문 COO이자 그룹 경영진(GEM) 일원인 John Felitto를 2026년 11월 1일부로 최고고객책임자(CCO)로 선임해 Customer Growth 조직을 이끌게 했다. 전임 Pia Synnerman은 앞서 퇴사 의사를 밝혔으며 2027년 1월 1일까지 인수인계를 지원한다. Lasse Kristoffersen CEO는 공급망이 복잡해질수록 해상·물류·터미널 역량을 연결하는 것이 중요하다며 펠리토의 고객·상업·운영 경험을 선임 배경으로 들었다.", "eSum": "Wallenius Wilhelmsen has appointed John Felitto, currently COO Logistics and a member of Group Executive Management, as Chief Customer Officer from 1 November 2026, leading the Customer Growth organisation. He succeeds Pia Synnerman, who had announced her departure and will support the handover until 1 January 2027. CEO Lasse Kristoffersen cited Felitto's combined customer, commercial and operational experience, saying that linking ocean, logistics and terminal capabilities matters more as supply chains grow more complex.", "kImp": "영업 총괄이 물류 출신으로 바뀌면서 해상·육상 통합 솔루션 판매가 강화될 전망이다. 보도자료에는 물류 COO 후임 언급이 없다.", "eImp": "With a logistics executive taking over commercial leadership, integrated ocean-plus-land offerings are likely to be pushed harder. The release does not name a successor as COO Logistics.", "url": "https://www.walleniuswilhelmsen.com/news/john-felitto-appointed-chief-customer-officer-at-wallenius-wilhelmsen", "prio": 2}, {"code": "BIZ", "date": "2026-10-14", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "왈레니우스 윌헬름센, 사모발행 신주 1,714만5천주 등기 완료…총 4억4,025만주, 3분기 실적은 11월 4일 발표", "eTitle": "Wallenius Wilhelmsen Registers the 17.145 Million New Placement Shares, Taking Its Share Count to 440.2 Million Ahead of Q3 Results on 4 November", "kSum": "왈레니우스 윌헬름센은 10월 14일 오슬로증권거래소 공시에서 10월 6일 주당 168크로네에 배정한 사모발행 신주 1,714만5,000주(약 28억8,000만크로네, 약 3억달러)의 자본금 증가가 노르웨이 기업등기소에 등기됐다고 밝혔다. 등기 후 자본금은 2억2,892만9,967.76크로네, 발행주식 총수는 4억4,024만9,938주(액면 0.52크로네)로 기존보다 약 4% 늘었다. 회사가 공시한 2026년 재무일정상 3분기 실적은 11월 4일 발표된다.", "eSum": "Wallenius Wilhelmsen told the Oslo Stock Exchange on 14 October that the capital increase for the 17,145,000 private placement shares issued on 6 October at NOK 168 each (about NOK 2.88bn, or roughly USD 300m) has been registered with the Norwegian Register of Business Enterprises. Share capital is now NOK 228,929,967.76 divided into 440,249,938 shares of NOK 0.52, about 4% more shares than before. Under the company's published 2026 financial calendar, third-quarter results are due on 4 November.", "kImp": "10월 6일 발표한 LNG 이중연료 대형선 4척(옵션 8척)의 조선소 건조계약은 10월 22일 현재 공시되지 않았으므로, 11월 4일 3분기 실적에서 조선소·선가·인도 일정 공개 여부를 확인할 필요가 있다.", "eImp": "No shipyard contract for the four firm and eight optional large LNG dual-fuel ships announced on 6 October had been disclosed as of 22 October, so the 4 November Q3 results are the next point to check for yard, price and delivery details.", "url": "https://newsweb.oslobors.no/message/684044", "prio": 1}, {"code": "BIZ", "date": "2026-10-06", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "WalWil, 3분기 조정 EBITDA 4.2억~4.5억 달러 전망·연간 16억 달러 재확인…3억 달러 사모발행 완료", "eTitle": "Wallenius Wilhelmsen Guides Q3 2026 Adjusted EBITDA at USD 420-450m, Reconfirms About USD 1.6bn for 2026 and Completes a USD 300m Private Placement", "kSum": "WalWil은 10월 6일 트레이딩 업데이트에서 3분기 조정 EBITDA를 4억2천만~4억5천만 달러로 예상하고 2026년 연간 약 16억 달러 전망을 재확인했다. 같은 날 북빌딩을 거쳐 신주 1,714만5천 주를 주당 NOK 168에 발행해 약 3억 달러를 조달했으며, 최대주주 Wilh. Wilhelmsen Holding은 지분율(37.9%)만큼 청약을 약정했으나 285만 주(17%)를 배정받았고 Wallenius Lines AB는 참여하지 않았다. 이사회는 후속 공모(repair offering)를 하지 않기로 했고 증자는 10월 14일 등기돼 발행주식이 440,249,938주가 됐으며, 자금은 차입과 함께 신조 프로그램 전액과 일반 목적에 쓰인다.", "eSum": "In a 6 October trading update Wallenius Wilhelmsen guided Q3 2026 adjusted EBITDA at USD 420-450m and reconfirmed about USD 1.6bn for 2026. The same evening it placed 17.145m new shares at NOK 168 to raise about USD 300m; largest shareholder Wilh. Wilhelmsen Holding had pre-committed its 37.9% pro-rata share but was allocated 2.85m shares (17%), and Wallenius Lines AB did not take part. The board decided against a repair offering, the capital increase was registered on 14 October (440,249,938 shares), and the proceeds plus debt will fully fund the newbuild programme and general corporate purposes.", "kImp": "3분기 실적이 2분기(3.61억 달러)보다 개선될 전망이어서 연료비 급등의 BAF 회수 시차 부담이 완화되는 흐름이다. 신조 자금이 확보돼 2030년대 선대 교체 계획의 실행 가능성이 높아졌다.", "eImp": "The Q3 guidance, above Q2's USD 361m, points to recovery from the bunker-cost squeeze as BAF recoveries catch up. With funding in place, the 2030s fleet-renewal plan is more certain to proceed.", "url": "https://newsweb.oslobors.no/message/683650", "prio": 3}, {"code": "BIZ", "date": "2026-09-24", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "WalWil 마켓 업데이트: 아시아발 선복 완판·2027년 선복 40% 재계약 중…中 수출 1천만 대·로로 선복 부족 연 200만~400만 대", "eTitle": "Wallenius Wilhelmsen Market Update: Asia Capacity Sold Out and 40% of 2027 Capacity Under Renegotiation, With Chinese Exports Near 10 Million Units and a 2-4 Million-Unit RoRo Gap", "kSum": "WalWil은 9월 24일 리사케르 본사에서 자동차·하이앤헤비(H&H) 시장과 로로 선대 동향을 다룬 마켓 업데이트를 열고 발표자료를 공개했다(BofA·DNB Carnegie 외부 발표 포함). 자료는 2026년 중국 승용차 수출이 1천만 대를 넘을 수 있고 선복 부족으로 연 200만~400만 대가 컨테이너·LoLo·육로로 운송된다고 추정했으며, 조선소 리드타임 4~5년·상위 4개 조선소가 PCTC 발주의 약 70%를 차지해 2030년까지 공급이 제한되고 30년 해체 가정 시 선대 증가세가 둔화돼 '2030년 이후 추가 발주가 예상된다'고 밝혔다. 1년 정기용선료는 약 79~88% 올랐고 최근 신조선 2년 용선이 일 8만 달러에 체결됐으며, 셰이퍼급은 2028년까지 순차 편입된다. 해운 계약잔고 65억 달러(가중 2.9년)·물류 27억 달러(8.1년)와 2026년 조정 EBITDA 약 16억 달러 전망을 유지했고, 9월 17일 파레토 컨퍼런스 자료에는 '2026년 완판, 2027년 협상 진행 중'이라고 적었다. 일본해사신문을 인용한 쉬핑뉴스넷(9/29)에 따르면 WW는 이 자리에서 대부분 1년 계약인 중국 화주 계약이 갱신기를 맞아 2027년 선복의 40%를 재계약 중이라고 밝혔고, 아시아발 유럽행 스팟 운임은 CBM당 165달러를 넘어 전년(약 95달러)보다 79% 높다.", "eSum": "Wallenius Wilhelmsen held a market update at its Lysaker offices on 24 September covering the auto and high & heavy markets and RoRo fleet dynamics, with external presentations from BofA and DNB Carnegie. The deck said Chinese light-vehicle exports could exceed 10 million units in 2026, estimated 2-4 million units a year moving by container, LoLo or landbridge for lack of RoRo capacity, and noted yard lead times of 4-5 years with four yards holding about 70% of PCTC orders, so supply stays limited through 2030 and more orders may be expected for 2030 onwards as recycling at 30 years slows fleet growth. One-year time-charter rates are up roughly 79-88%, a recent two-year newbuild charter was fixed at USD 80k/day, and the Shaper Class enters the fleet through 2028; the company kept its USD 6.5bn shipping backlog (2.9 years), USD 2.7bn logistics backlog (8.1 years) and about USD 1.6bn 2026 adjusted EBITDA outlook, while its 17 September Pareto deck said 2026 is sold out with 2027 negotiations ongoing. According to Japan Maritime Daily, cited by Shipping News Net on 29 September, WW also said it was renegotiating contracts for 40% of its 2027 capacity as Chinese shippers' mostly one-year deals come up for renewal, with Asia-Europe spot rates above USD 165 per cbm, 79% higher than a year earlier (about USD 95).", "kImp": "선복 부족·용선료 강세가 2030년 무렵까지 이어질 전망이어서 고선령선이 높은 가동률로 계속 운항할 가능성이 크다. 노후선의 정비·검사 계획과 운항 신뢰성 관리가 수익성에 직결된다.", "eImp": "With tight capacity and strong charter rates expected to last until around 2030, older tonnage is likely to keep trading at high utilisation. Maintenance and survey planning for ageing ships is directly tied to earnings.", "url": "https://newsweb.oslobors.no/message/682966", "prio": 3}, {"code": "BIZ", "date": "2026-08-11", "src": "Wallenius Wilhelmsen", "title": "WalWil 2분기 조정 EBITDA 3.61억 달러…상반기 배당 2.58억 달러, 연간 16억 달러 전망 유지", "eTitle": "Wallenius Wilhelmsen Posts Q2 2026 Adjusted EBITDA of USD 361m, Pays a USD 258m H1 Dividend and Keeps Its 2026 Outlook at About USD 1.6bn", "kSum": "2분기 매출은 13억500만 달러(+4% QoQ), 조정 EBITDA 3억6,100만 달러(-7%), 순이익 1억3,800만 달러(-22%)로, 중동 분쟁 이후 연료비 급등(평균 톤당 770달러, +48%)이 주원인이며 회사는 BAF 조항으로 점진 회수할 계획이다. 상반기 배당은 주당 0.61달러(순이익 50%+특별배당 1억 달러, 총 2억5,800만 달러)로 2026년 조정 EBITDA 약 16억 달러 전망을 유지했고, CEO는 '사실상 완판이라 아시아발 고객 우선순위를 정해야 한다'고 말했다. 분기말 선대는 129척(소유 91척·장기용선 35척·단기용선 3척)이며 셰이퍼급 14척 잔여 신조 투자는 약 14억 달러(11척 인도 후 금융 확보), 물류 부문은 코로나 이전 이후 최고 분기(조정 EBITDA 4,600만 달러)를 기록했다. Shippax(8/14)는 6,500CEU 1년 용선료가 2025년 말 일 4만3천 달러에서 8만 달러 이상으로, 신형 7,000CEU 이중연료선은 9만 달러 이상으로 올랐다고 전했다.", "eSum": "Q2 revenue was USD 1,305m (up 4% quarter on quarter), adjusted EBITDA USD 361m (down 7%) and net profit USD 138m (down 22%), mainly because of higher bunker prices after the Middle East conflict (average USD 770/t, up 48%), which the company expects to recover over time through BAF clauses. The H1 dividend is USD 0.61 per share (50% of net profit plus a USD 100m extraordinary payout, USD 258m in total), the 2026 outlook of about USD 1.6bn was kept, and the CEO said the company is effectively sold out and must make tough customer prioritisations out of Asia. The fleet stood at 129 ships (91 owned, 35 long-term and 3 short-term chartered), about USD 1.4bn of capex remains on the 14 Shaper Class ships (post-delivery financing secured for 11), and Logistics had its best quarter since before Covid (adjusted EBITDA USD 46m); Shippax reported on 14 August that one-year rates for 6,500 CEU ships rose from USD 43,000/day at end-2025 to over USD 80,000/day, and above USD 90,000/day for new 7,000 CEU dual-fuel ships.", "kImp": "연료비가 실적을 좌우하는 국면이어서 경제운항·연료 품질 관리의 비용 효과가 커졌다. 완판·고가동 상태가 이어져 정비 기회 확보와 운항 신뢰성 유지가 핵심 과제다.", "eImp": "Fuel costs are now the main swing factor in earnings, raising the value of fuel-efficient operation and fuel-quality management. With ships sold out and highly utilised, securing maintenance windows and operational reliability is the key task.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-pays-high-dividends-in-a-strong-market", "prio": 3}, {"code": "BIZ", "date": "2026-06-24", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "WalWil, 유럽 완성차사와 운송계약 2031년 중반까지 3년 조기 연장…약 4.2억 달러", "eTitle": "Wallenius Wilhelmsen Extends a Shipping Contract With a Leading European Carmaker Into Mid-2031, Worth About USD 420m", "kSum": "WalWil은 유럽 주요 완성차 제조사(비공개)와의 해상운송 계약을 2028년 중반~2031년 중반으로 3년 조기 연장했다. 연장분 예상 가치는 약 4억2천만 달러(예상 물동량 기준)로 기존 계약 잔여가치 약 1억8천만 달러에 더해지며, 저배출 연료 사용이 포함됐다. 회사는 향후 5년간 지속 가능한 운임 수준의 수익 가시성을 확보했고 물류 등 가치사슬 전반으로 협력 확대를 모색한다고 밝혔다.", "eSum": "Wallenius Wilhelmsen agreed an early three-year extension, from mid-2028 to mid-2031, of a shipping contract with an unnamed leading European auto manufacturer. The extension is valued at about USD 420m based on forecast volumes, on top of about USD 180m remaining on the initial term, and includes low-emission fuels. The company said it secures earnings visibility at sustainable rate levels for the next five years and it aims to expand cooperation into other parts of the value chain, potentially logistics.", "kImp": "유럽 아웃바운드 물량이 2031년까지 확보돼 해당 항로 배선이 안정적으로 유지될 전망이며, 계약에 포함된 저배출 연료 사용 이행 관리가 운항 측 과제가 된다.", "eImp": "European outbound volumes are locked in to 2031, supporting stable deployment on those trades, while delivering the low-emission fuel commitment becomes an operational task.", "url": "https://newsweb.oslobors.no/message/676867", "prio": 3}, {"code": "BIZ", "date": "2026-05-06", "src": "Wallenius Wilhelmsen", "title": "WalWil 1분기 조정 EBITDA 3.89억 달러…연료비 급등에 2026년 전망 약 16억 달러로 하향", "eTitle": "Wallenius Wilhelmsen Posts Q1 2026 Adjusted EBITDA of USD 389m and Cuts Its 2026 Outlook to About USD 1.6bn on Fuel and Capacity Costs", "kSum": "1분기 매출은 12억5,300만 달러(-1% QoQ), 조정 EBITDA 3억8,900만 달러(-3%), 순이익 1억7,700만 달러였다. 2026년 조정 EBITDA 전망을 16억5천만~17억5천만 달러에서 약 16억 달러로 낮췄으며, 해운 부문의 순연료비·선복 비용 상승과 정부화물 부문의 부진한 출발을 이유로 들었다(이 전망은 8월·10월 재확인됐다). 중동 직접 매출 비중은 2~3%이고 호르무즈 해협 안에 선박 1척, 두바이 육상 사업은 활동이 제한됐으며, 연료비 부담은 2분기에 크게 반영된 뒤 BAF로 회수될 것이라고 밝혔다.", "eSum": "Q1 revenue was USD 1,253m (down 1% quarter on quarter), adjusted EBITDA USD 389m (down 3%) and net profit USD 177m. The company cut its 2026 adjusted EBITDA outlook from USD 1.65-1.75bn to about USD 1.6bn, citing higher net bunker and capacity costs in Shipping and a soft start for Government services; the outlook was reconfirmed in August and October. Direct Middle East exposure is 2-3% of revenue, one vessel was inside the Strait of Hormuz and the Dubai land operation had limited activity, while higher fuel costs were expected to weigh heavily on Q2 before being recovered through BAF clauses.", "kImp": "현재 유효한 연간 가이던스의 기준점으로, 연료비와 용선(선복) 비용이 실적 변동의 핵심 변수임을 보여준다. 용선 시장 경색으로 차입 선박 비용이 커진 만큼 운항 효율 관리 압력도 커졌다.", "eImp": "This set the annual guidance still in force and shows fuel and charter-in costs as the key earnings variables. With a tighter charter market raising the cost of chartered tonnage, pressure on operating efficiency grows.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-delivers-stable-q1-performance-in-uncertain-markets", "prio": 3}, {"code": "BIZ", "date": "2026-03-03", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "WalWil, 글로벌 자동차 유통사와 약 1.9억 달러 운송계약 갱신(2년+1년)", "eTitle": "Wallenius Wilhelmsen Renews a Shipping Contract With a Global Automotive Distributor Worth About USD 190m", "kSum": "WalWil은 글로벌 자동차 유통사(비공개)와 예상 순운임 약 1억9천만 달러 규모의 해상운송 계약을 갱신했다. 계약은 2년 확정에 1년 상호 연장 옵션이며, 멀티연료 사용에 대한 고정 할증료가 포함됐다. Pia Synnerman CCO는 고객의 재고 최적화 목표를 지원하는 맞춤형 서비스라고 설명했다.", "eSum": "Wallenius Wilhelmsen renewed a shipping contract with an unnamed global automotive distributor with an estimated net freight value of about USD 190m. The contract has a two-year firm period plus a one-year mutual extension option and includes a fixed surcharge for multi-fuel use. Chief Customer Officer Pia Synnerman said the tailor-made service supports the customer's inventory optimisation goals.", "kImp": "멀티연료(바이오·메탄올 등) 고정 할증 구조가 계약에 들어가는 흐름으로, 대체연료 사용 실적의 정확한 기록·증빙이 상업 계약 이행의 일부가 되고 있다.", "eImp": "Fixed multi-fuel surcharges are being written into contracts, so accurate recording and evidence of alternative-fuel use is becoming part of commercial contract delivery.", "url": "https://newsweb.oslobors.no/message/667320", "prio": 1}, {"code": "BIZ", "date": "2026-01-07", "src": "Wallenius Wilhelmsen (Oslo Børs)", "title": "왈레니우스 윌헬름센, 아시아 대형 자동차·중장비 제조사와 1년 해상운송 신규 계약…약 1억3천만 달러", "eTitle": "Wallenius Wilhelmsen Signs a New One-Year Shipping Contract With a Major Asian Vehicle and Heavy Equipment Manufacturer, Worth About USD 130m", "kSum": "왈레니우스 윌헬름센은 1월 7일 오슬로증권거래소 공시에서 아시아의 한 대형 자동차·중장비 제조사(사명 비공개)와 2026년부터 시작되는 1년 해상운송 계약을 맺었으며, 계약 물량 기준 예상 매출은 약 1억3,000만 달러라고 밝혔다. 피아 쉬네르만(Pia Synnerman) 최고고객책임자(CCO)는 이 계약이 아시아에서 더 성장하려는 회사의 목표를 뒷받침한다고 말했고, Splash247은 해당 고객과 일부 항로에서 이미 하고 있던 물류 협력을 보완해 거래 관계를 넓히는 계약이라고 전했다. 회사는 2025년 12월에도 유럽 고객과의 연장 계약 3건, 즉 5년 약 1억5,000만 달러 규모 공급망 솔루션 계약과 합계 5억 달러에 가까운 해상운송 계약 2건을 발표한 바 있다.", "eSum": "Wallenius Wilhelmsen told the Oslo Stock Exchange on 7 January that it has signed a one-year shipping contract, starting in 2026, with an unnamed leading Asian vehicle and heavy equipment manufacturer, estimated at about USD 130m based on the contracted volume. Chief Customer Officer Pia Synnerman said the deal supports the company's ambition to grow further in Asia, and Splash247 reported that it complements an existing logistics relationship with the customer in certain trades. It followed three extensions with European customers announced in December 2025: a five-year supply-chain solutions deal worth about USD 150m and two shipping extensions worth close to USD 500m combined.", "kImp": "아시아발 선복이 꽉 찬 상황에서 중장비(하이앤헤비) 화물이 늘면 고박 계획·갑판 및 램프 하중 관리의 중요성이 커지므로, 11월 30일까지 진행되는 파리·도쿄 MOU 화물고박 집중점검(CIC)에 맞춰 관리선의 화물고박 매뉴얼(CSM)과 고박 장비 상태를 점검할 필요가 있다. 1년 계약이라 2027년분은 다시 갱신해야 한다.", "eImp": "With Asia-departing capacity sold out, more heavy-equipment (high and heavy) cargo puts a premium on lashing plans and deck and ramp load limits, so cargo securing manuals and lashing gear on managed ships deserve a check during the Paris and Tokyo MoU cargo-securing campaign that runs to 30 November. As a one-year deal it will need renewing for 2027.", "url": "https://newsweb.oslobors.no/message/663178", "prio": 1}]}, {"code": "NOR", "kTitle": "노르웨이·스웨덴 현지", "eTitle": "Norway & Sweden Local", "items": [{"code": "NOR", "date": "2026-10-29", "src": "Skipsrevyen", "title": "Wallenius Wilhelmsen 이사회 의장 Rune Bjerke, '올해의 이사회 의장 2026' 수상 — 명확한 지배구조와 주주 이해 조정 평가", "eTitle": "Wallenius Wilhelmsen Chair Rune Bjerke Named 'Chair of the Year 2026' - Recognised for Clear Governance and Balancing Shareholder Interests", "kSum": "노르웨이 해운 전문지 Skipsrevyen에 따르면 5년째 Wallenius Wilhelmsen 이사회 의장을 맡고 있는 Rune Bjerke가 10월 27일 오슬로에서 '올해의 이사회 의장 2026'상을 받았다. 심사위원회는 회사의 강한 재무 실적과 함께 명확한 소유 지배구조, 이사회 운영, 서로 다른 주주 이해의 균형 있는 조정, 이사회·주주·경영진 사이 신뢰 구축을 이유로 들었다. 시상식에서 소개된 회사 실적은 2025년 매출 약 524억 크로네, 세전이익 약 115억 크로네이고, 시가총액은 10월 26일 기준 약 750억 크로네다. 회사 임직원은 28개국 약 9,500명이다.", "eSum": "Norwegian shipping magazine Skipsrevyen reports that Rune Bjerke, chair of Wallenius Wilhelmsen for five years, received the 'Chair of the Year 2026' award in Oslo on 27 October. The jury cited the company's strong financial results together with clear ownership governance, good board dynamics, balanced handling of different owner interests and building trust among board, owners and management. Figures cited were 2025 revenue of about NOK 52.4 billion and pre-tax profit of about NOK 11.5 billion, with a market value of about NOK 75 billion on 26 October. The company has about 9,500 employees in 28 countries.", "kImp": "참고. 대형 운항사의 지배구조 안정은 장기 관리 계약과 선대 정책의 연속성으로 이어진다. 선박관리사는 고객사의 이사회·경영진 구성 변화를 계약 위험 점검 항목으로 관리할 것.", "eImp": "For reference; governance stability at a major operator means continuity in long-term management contracts and fleet policy. Managers should track changes in clients' boards and management as part of contract risk reviews.", "url": "https://www.skipsrevyen.no/chair-of-the-year-2026-rune-bjerke-sjotransport-og-logistikk/han-er-arets-styreleder/2202692", "prio": 1}, {"code": "NOR", "date": "2026-11-17", "src": "gCaptain", "title": "노르웨이, 원자력 추진 해양작업지원선 개발에 2,000만 크로네 지원 — VARD·Island Offshore 컨소시엄, 5 MWe 소형 원자로 통합 동력계 시험", "eTitle": "Norway Puts NOK 20 Million Into a Nuclear-Powered Offshore Vessel Project - a Consortium With VARD and Island Offshore Will Test an Integrated Power System Around a 5 MWe Microreactor", "kSum": "노르웨이 정부가 조선사 VARD와 해양작업지원선(OSV) 운항사 Island Offshore가 참여한 컨소시엄에 2,000만 크로네(약 200만 달러)를 지원해 해양작업선용 통합 원자력 동력 시스템을 개발하게 했다. 사업은 Emerald Nuclear의 5 MWe급 소형 원자로(GEM)를 바탕으로 한다. 시험에서는 평상 운항, 급격한 전력 수요 변화, 계통 성능, 부하가 큰 조건, 선원과의 상호작용을 살핀다. Island Offshore는 원자력 에너지 시스템을 설치하는 첫 OSV 선주가 되겠다는 목표를 밝혔다.", "eSum": "Norway's government has awarded NOK 20 million (about USD 2 million) to a consortium including shipbuilder VARD and offshore vessel operator Island Offshore to develop an integrated nuclear power system for offshore vessels. The project is based on Emerald Nuclear's 5 MWe GEM microreactor. Testing will cover normal operations, rapid changes in power demand, system performance, stress conditions and crew interaction. Island Offshore says it aims to be the first OSV owner to install a nuclear energy system.", "kImp": "상선 원자력은 아직 시험 단계지만 정부 예산이 붙기 시작했다. 선박관리사는 당장 준비할 것은 없으나, 원자력 추진선의 선원 자격·기항 허가·보험 논의가 IMO와 선급에서 어떻게 진행되는지 기술 동향 목록에 올려 둘 것.", "eImp": "Nuclear propulsion for merchant ships is still at the test stage, but public money is now attached. Managers need not act yet, but should keep crew qualification, port entry and insurance discussions at the IMO and class on their technology watch list.", "url": "https://gcaptain.com/norway-backs-nuclear-powered-offshore-vessel-project/", "prio": 2}, {"code": "NOR", "date": "2026-11-12", "src": "Skipsrevyen", "title": "노르웨이 근해 해운, 2027년에 EU ETS로 약 9억8,800만 크로네 부담 — 선주협회 '불합리', 수입을 기후·에너지 조치로 환원 요구", "eTitle": "Norway's Short-Sea Fleet Faces an EU ETS Bill of About NOK 988m in 2027 - the Shipowners' Association Calls It Unreasonable and Wants the Revenue Returned to Climate and Energy Measures", "kSum": "노르웨이선주협회는 노르웨이 근해(short-sea) 선대가 2027년에 전년도 배출분으로 EU ETS에 약 9억8,800만 크로네를 내야 한다고 추산했다. 2025년 배출량, 탄소가격 90유로, 환율 유로당 11크로네를 가정한 값이다. 협회 회원사는 2026년 유럽에서 CO2 730만 톤(잠정)을 배출했고 그중 약 150만 톤이 근해 선박에서 나왔는데, 이는 노르웨이 국내 항공 전체보다 많다. 협회 CEO는 이 부담이 불합리하다고 했고, 협회는 수입을 기후·에너지 조치로 되돌리고 기존 선대의 에너지 효율 개선에 인센티브를 줄 것을 요구한다.", "eSum": "The Norwegian Shipowners' Association estimates that Norway's short-sea fleet must pay about NOK 988 million into the EU ETS in 2027 for the previous year's emissions, assuming 2025 emissions, a EUR 90 carbon price and NOK 11 to the euro. Members emitted 7.3 million tonnes of CO2 in Europe in 2026 (preliminary), about 1.5 million tonnes of it from short-sea ships - more than all domestic aviation in Norway. The association's CEO called the burden unreasonable; it wants the revenue returned to climate and energy measures and incentives for energy efficiency in the existing fleet.", "kImp": "ETS 비용은 선주와 용선주 사이 정산 문제이자 관리사의 보고 업무다. 선박관리사는 MRV 자료의 정확도(항차별 연료·거리·화물)와 EUA 정산 조항을 관리 계약에서 다시 확인할 것.", "eImp": "ETS cost is a settlement issue between owner and charterer and a reporting task for the manager. Managers should re-check the accuracy of MRV data (fuel, distance and cargo per voyage) and the EUA settlement clause in management agreements.", "url": "https://www.skipsrevyen.no/bergen-tankers-eu-ets-norges-rederiforbund/sa-mye-ma-naerskipsfarten-betale-til-eu-ets/2209628", "prio": 2}, {"code": "NOR", "date": "2026-11-12", "src": "Skipsrevyen", "title": "발레니우스 SOL, '발레니우스 링크'로 사명 변경 — 4월 발레니우스 라인스가 SOL 그룹 지분을 인수해 단독 소유, 선박은 정기 정비 때 새 도색", "eTitle": "Wallenius SOL Becomes Wallenius Link After Wallenius Lines Bought Out SOL Group in April - Ships to Be Rebranded During Planned Maintenance", "kSum": "북유럽 로로 선사 발레니우스 SOL이 11월 12일부로 '발레니우스 링크(Wallenius Link)'로 이름을 바꿨다. 2026년 4월 발레니우스 라인스가 SOL 그룹이 가진 지분을 사들여 단독 소유주가 된 데 따른 것이다. 회사는 새 이름이 기업과 전문성, 사람을 잇는 역할을 뜻하며 새 소유 구조가 안정성을 준다고 설명했다. 운항·전략·서비스·경영진은 그대로다. 선박은 정기 정비 때 새 이름과 도색으로 바뀌며 과도기에는 옛 브랜드와 새 브랜드가 함께 쓰인다.", "eSum": "Nordic ro-ro operator Wallenius SOL was renamed Wallenius Link on 12 November, following Wallenius Lines' agreement in April 2026 to buy SOL Group's shares and become sole owner. The company says the name reflects its role in connecting businesses, expertise and people, and that the new ownership brings stability. Operations, strategy, customer offering and management are unchanged. Ships will take the new name and livery during planned maintenance, with both brands in use during the transition.", "kImp": "사명·도색 변경은 선박 증서, 보험 증권, 항만 등록 정보의 명의 일치 문제로 이어진다. 선주 그룹 재편 때 선박관리사는 증서·계약서·ISPS 기록의 회사명 변경 목록을 먼저 만들어 둘 것.", "eImp": "A change of name and livery raises consistency issues across ship certificates, insurance and port registrations. When an owner group restructures, managers should first list every certificate, contract and ISPS record that carries the company name.", "url": "https://www.skipsrevyen.no/walleniud-sol-wallenius-link/skifter-navn-til-wallenius-link/2209848", "prio": 2}, {"code": "NOR", "date": "2026-11-06", "src": "Skipsrevyen", "title": "스웨덴 알파라발, 노르웨이 전자항해 업체 NAVTOR를 7억 달러 현금 인수", "eTitle": "Alfa Laval Agrees to Buy Norwegian E-Navigation Firm NAVTOR for USD 700m in Cash, With Closing Expected in Q1 2027", "kSum": "알파라발이 노르웨이 에예르순(Egersund) 소재 전자항해·선대 디지털 솔루션 업체 NAVTOR를 7억 달러 전액 현금으로 인수하는 확정 계약을 맺었다. NAVTOR는 2011년 설립, 13개 사무소 약 400명, 90여 개국 고객을 두고 2026년 매출 약 1억9,400만 달러를 예상한다. 알파라발 오션 사업부에 편입돼 StormGeo·Portchain과 통합되며, 거래 종결은 규제 승인을 거쳐 2027년 1분기로 예상된다. NAVTOR 내부 점검에서 규정·내부정책 준수 관련 사안이 발견됐으나 알파라발은 해결 가능하다고 밝혔다(HANSA도 같은 내용 보도).", "eSum": "Alfa Laval has signed a definitive agreement to acquire NAVTOR, the Egersund-based e-navigation and fleet digital solutions provider, for USD 700m in cash. NAVTOR, founded in 2011, has about 400 staff in 13 offices, customers in more than 90 countries and expects 2026 revenue of about USD 194m. It will join Alfa Laval's Ocean Division alongside StormGeo and Portchain, with closing expected in Q1 2027 subject to regulatory approvals. An internal review at NAVTOR found compliance matters, which Alfa Laval says it expects to be resolved.", "kImp": "전자해도(ENC)·항해계획 도구 공급사의 소유가 바뀌는 만큼, 선박관리사는 라이선스·지원 체계와 기상 라우팅(StormGeo) 연계 변화가 계약 조건에 미칠 영향을 지켜볼 필요가 있다.", "eImp": "With a major ENC and passage-planning supplier changing hands, ship managers should watch for changes to licensing, support and integration with StormGeo weather routing that could affect their contracts.", "url": "https://www.skipsrevyen.no/alfa-laval-navtor/selger-navtor-for-700-millioner-dollar/2207303", "prio": 2}, {"code": "NOR", "date": "2026-11-06", "src": "Sjøfartsdirektoratet", "title": "노르웨이 해사청 '해상안전 제로비전' 행동계획 77개 조치 중 60% 완료·진행 — 올해 상선 사망 4명", "eTitle": "Norwegian Maritime Authority Says 60% of the 77 Measures in Its Vision Zero Maritime Safety Action Plan Are Done or Under Way, With Four Deaths on Commercial Vessels This Year", "kSum": "2025년 1월 시행된 노르웨이 국가 해상안전 행동계획(제로비전)의 77개 조치 가운데 7개가 완료, 39개가 진행 중이며 31개는 아직 시작되지 않았다. 해사청은 올해 1,000건이 넘는 사고 보고를 받았고, 레저선박에서 26명, 상선에서 4명이 숨졌으며 인명사고의 35%가 병가로 이어졌다. Alf Tore Sørheim 청장은 진척에는 만족하지만 사고 수치가 아직 기대에 못 미친다며 조급하다고 말했다.", "eSum": "Of the 77 measures in Norway's national maritime safety action plan (Vision Zero), in force since January 2025, 7 are completed, 39 are under way and 31 have not started. The authority has received more than 1,000 accident reports this year, with 26 deaths on recreational craft and 4 on commercial vessels, and 35% of personal injuries leading to sick leave. Director Alf Tore Soerheim said the authority is satisfied with progress but impatient, as accident figures are still not where they should be.", "kImp": "노르웨이 기국·항만 당국의 안전 기조를 보여주는 자료로, 남은 31개 조치가 시행되면 상선 대상 규제나 점검이 추가될 수 있다.", "eImp": "The report shows the Norwegian authority's safety priorities, and the 31 measures not yet started may bring further rules or inspections for commercial vessels.", "url": "https://www.sdir.no/nyheter/nullvisjonen--fornoyde-men-utalmodige/", "prio": 1}, {"code": "NOR", "date": "2026-11-05", "src": "Placera (Finwire)", "title": "SEB·SB1 Markets, 3분기 실적 후 왈레니우스 윌헬름센 '매수'로 상향 — SEB 목표주가 NOK 205, SB1 NOK 195", "eTitle": "SEB and SB1 Markets Upgrade Wallenius Wilhelmsen to Buy After Q3, With Targets of NOK 205 and NOK 195", "kSum": "Finwire(Placera) 보도에 따르면 SEB는 11월 5일 왈레니우스 윌헬름센(WAWI) 투자의견을 '보유'에서 '매수'로 올리고 목표주가를 NOK 178에서 205로 상향했다. 같은 날 SB1 Markets도 '중립'에서 '매수'로 올리고 목표주가를 NOK 155에서 195로 높였다. 앞서 DNB Carnegie(애널리스트 Jørgen Lian)도 아시아 방문 뒤 자동차선 주식을 상향하며 WAWI를 '매수'로 올렸다(BilNorge·DN 보도).", "eSum": "According to Finwire on Placera, SEB upgraded Wallenius Wilhelmsen (WAWI) from hold to buy on 5 November and raised its target price from NOK 178 to NOK 205. SB1 Markets upgraded the stock from neutral to buy the same day, lifting its target from NOK 155 to NOK 195. DNB Carnegie analyst Joergen Lian had earlier upgraded the car-carrier stocks after an Asia trip, moving WAWI to buy (BilNorge, citing DN).", "kImp": "3분기 실적과 2027~29년 계약 확보 전망 뒤 증권가 시각이 일제히 긍정적으로 바뀌었다. 신조 투자 여력과 선대 확장 기조가 이어질 가능성이 크다는 신호다.", "eImp": "Broker sentiment turned broadly positive after Q3 and the outlook for contracting 2027-29 capacity, supporting the case for continued fleet investment and newbuilding spending.", "url": "https://www.placera.se/telegram/wallenius-wilhelmsen-seb-hojer-wallenius-wilhelmsen-till-kop-behall-riktkurs-205-norska-kronor-178-20261105", "prio": 2}, {"code": "NOR", "date": "2026-11-05", "src": "BilNorge", "title": "크리스토페르센 WW CEO \"중국 자동차 수출 야망 끝이 안 보인다\" — 3분기 중국 수출 전년 대비 50% 증가", "eTitle": "WW CEO Kristoffersen Says China's Car Export Ambitions Show No Sign of Ending, as Chinese Exports Rise 50% Year on Year in Q3", "kSum": "라세 크리스토페르센 CEO는 DN 인터뷰에서 중국 자동차 수출 증가가 역사적으로 유례가 없다며 수출 야망이 끝날 것 같지 않다고 말했다. 중국 자동차 수출은 올해 3분기 전년 동기 대비 50% 늘었고, 2026년 연간 약 1,000만 대로 추정된다. 그는 중국 업체들이 해외 현지 생산으로 옮겨가겠지만 그 구축에 시간이 걸려 그동안 수출은 계속 늘 것이라고 봤다. 회사는 연말까지 2027~2029년 선복 대부분을 계약으로 확보할 것으로 예상한다.", "eSum": "CEO Lasse Kristoffersen told DN that growth in Chinese car exports has no historical parallel and that the export ambitions do not seem to be ending. Chinese car exports rose 50% year on year in Q3 and are estimated at about 10 million units in 2026. He expects Chinese makers to move towards local production abroad, but says building that capacity takes time, so exports will keep growing meanwhile. The company expects to have most of its 2027-2029 capacity contracted by year-end.", "kImp": "중국발 수출 물량이 중기적으로 계속 늘 것이라는 경영진 판단은 아시아 출발 항로의 높은 선대 가동률과 빠듯한 운항 일정이 이어진다는 뜻이다. 선박관리 측면에서는 정비 시간 확보와 화물 고박 관리 부담이 커질 수 있다.", "eImp": "Management expects Chinese export volumes to keep growing over the medium term, which points to continued high utilisation and tight schedules on Asia-origin trades and less time for maintenance windows and cargo-securing checks.", "url": "https://www.bilnorge.no/handelshindringer-kina-kinesisk-bileksport/tror-pa-fortsatt-kina-ekspansjon/4186818", "prio": 2}, {"code": "NOR", "date": "2026-11-05", "src": "Placera", "title": "자동차선사 3일 새 투자의견 7건 상향 — Arctic NOK 200, DNB Carnegie NOK 210, 회그는 SEB NOK 207", "eTitle": "Seven Car-Carrier Upgrades in Three Days: Arctic Lifts Its Wallenius Wilhelmsen Target to NOK 200 and DNB Carnegie to NOK 210, While SEB Upgrades Höegh Autoliners to Buy With NOK 207", "kSum": "Placera는 11/2~5 사흘 동안 두 자동차선사에 대한 투자의견 상향이 7건이라고 정리했다. Wallenius Wilhelmsen은 Arctic이 11/3 매수로 올리며 목표가 NOK 191을 낸 뒤 11/5 NOK 200으로, DNB Carnegie는 11/3 보유→매수(NOK 150→205) 후 11/5 NOK 210으로 올렸고 Arctic·SEB·SB1·DNB Carnegie가 모두 매수다. 평균 목표가는 NOK 203로 주가 NOK 164 대비 23% 상승 여력이며, 연초 대비 주가는 62% 올랐다. Höegh Autoliners는 SEB가 중립→매수(NOK 132→207), Arctic이 매수, DNB Carnegie가 매도→보유로 올렸는데, 근거는 회그 자체보다 시장 여건과 WW 실적이며 회그는 11월 19일 실적을 낸다.", "eSum": "Placera counted seven rating upgrades on the two Oslo-listed car carriers between 2 and 5 November. For Wallenius Wilhelmsen, Arctic upgraded to buy with a NOK 191 target on 3 November and raised it to NOK 200 on 5 November, while DNB Carnegie upgraded to buy from hold with a NOK 205 target (from 150) on 3 November and lifted it to NOK 210 on 5 November; Arctic, SEB, SB1 Markets and DNB Carnegie now all rate it buy. The average target is NOK 203 against a NOK 164 share price, about 23% upside, after a 62% rise this year. For Höegh Autoliners, SEB upgraded to buy and lifted its target to NOK 207 from 132, Arctic moved to buy and DNB Carnegie to hold from sell, citing market conditions and the WW results rather than Höegh's own, ahead of its Q3 report on 19 November.", "kImp": "증권가가 2027년 계약 갱신과 아시아 수요를 근거로 자동차선 업황 강세를 다시 반영하고 있다. 회그의 11/19 실적이 업계 운임·선복 전망을 다시 확인할 다음 지점이다.", "eImp": "Brokers are pricing in a strong car-carrier cycle on the back of 2027 contract renewals and Asian demand. Höegh's 19 November results are the next check on industry rates and capacity.", "url": "https://www.placera.se/nyheter/bilrederierna-sju-hojda-rad-pa-tre-dagar-2026-11-05", "prio": 2}, {"code": "NOR", "date": "2026-11-05", "src": "Shippax", "title": "예테보리항 1~9월 신차 19만7천 대로 14% 증가…수입 29%·수출 10% 늘어", "eTitle": "Port of Gothenburg Handles 197,000 New Cars in January-September, Up 14%, With Imports Up 29% and Exports Up 10%", "kSum": "예테보리항의 2026년 1~9월 신차 처리량이 19만7천 대로 전년 동기 17만2천 대보다 14% 늘었다. 수입이 29%, 수출이 10% 증가해 항만에서 가장 높은 성장률을 보인 화물군 중 하나가 됐다. 단거리 로로 화물은 40만5천 유닛으로 2% 늘었고 여객은 약 114만 명으로 보합, 크루즈 기항은 55회에서 40회로 줄었다.", "eSum": "The Port of Gothenburg handled 197,000 new cars in January-September 2026, up 14% from 172,000 a year earlier. Imports rose 29% and exports 10%, making new cars one of the port's fastest-growing segments. Short-sea ro-ro units rose 2% to 405,000, passengers were flat at about 1.14 million and cruise calls fell from 55 to 40.", "kImp": "그룹이 12년 계약으로 운영하는 예테보리 자동차·로로 터미널(GIART)의 물량 기반이 커지고 있다는 신호로, 북유럽 기항 선박의 하역 일정·체선에 영향을 줄 수 있다.", "eImp": "Rising volumes underpin the Gothenburg auto and ro-ro terminal (GIART) that the group runs under a 12-year contract, and may affect cargo-handling schedules and waiting time for ships calling in Scandinavia.", "url": "https://www.shippax.com/en/news/more-new-cars-and-trailers-passing-through-gothenburg.aspx", "prio": 1}, {"code": "NOR", "date": "2026-11-05", "src": "Wallenius Marine", "title": "월레니우스 마린 크루 매니저, 스톡홀름 선원교회 이사회에 첫 여성 이사로 합류", "eTitle": "Wallenius Marine Crew Manager Elin Stenberg Becomes the First Woman on the Board of the Seafarers' Church in Stockholm", "kSum": "월레니우스 마린에서 스톡홀름 관리 선박 선원의 인사 업무를 맡는 크루 매니저 엘린 스텐베리가 1917년 설립된 스톡홀름 선원교회 이사회에 첫 여성 이사로 합류했다. 선원교회는 스톡홀름·뉘네스함·쇠데르텔리에 항에서 선박을 방문해 선원에게 실질적 도움과 상담을 제공한다. 그는 교회가 선원을 점검하지 않고 경청하고 돕는 곳이라며 오늘날 선원의 필요에 맞춰 변화해야 한다고 말했다.", "eSum": "Elin Stenberg, the Wallenius Marine crew manager who handles HR for crews on Stockholm-managed ships, has become the first woman on the board of the Seafarers' Church in Stockholm, founded in 1917. The church visits ships in Stockholm, Nynashamn and Sodertalje and offers seafarers practical help and personal support. She says the church listens and helps rather than inspecting, and should keep adapting to seafarers' needs today.", "kImp": "항만 선원복지 단체와의 연계는 MLC 2006의 선원 복지시설 접근과 정신건강 지원 측면에서 선박관리사가 활용할 수 있는 자원이다.", "eImp": "Links with port welfare organisations are a resource ship managers can use for seafarer access to shore welfare and mental-health support under MLC 2006.", "url": "https://www.walleniusmarine.com/blog/crew-management/elin-stenberg-joins-the-board-of-the-seafarers-church/", "prio": 1}, {"code": "NOR", "date": "2026-11-04", "src": "E24", "title": "E24: WW 3분기 '실적 하락' 보도 — 순이익 2.12억 달러(전년 2.8억), 크리스토페르센 CEO '2027년 이후 강한 입지 구축'", "eTitle": "E24 Reports a Year-on-Year Profit Fall at WW to USD 212m From USD 280m, as CEO Kristoffersen Says the Company Is Building a Strong Position for 2027 and Beyond", "kSum": "노르웨이 E24는 WW의 3분기 매출이 14억 달러(전년 13.3억)로 늘었지만 조정 EBITDA는 4.28억 달러(전년 4.77억), 순이익은 2.12억 달러(전년 2.8억)로 줄었다며 '실적 하락'으로 보도했다. 라세 크리스토페르센 CEO는 '사업 전반에서 좋은 수요와 결과로 강한 3분기를 냈다'며 '고객에게 제공하고 2027년과 그 이후를 위한 강한 입지를 쌓는 데 집중한다'고 말했고, 최근의 대형 계약이 이를 뒷받침한다고 했다. E24는 1년 전에는 미국 입항료(완화 전 4분기 약 1억 달러 비용 예상)가 실적을 지배했지만 지금은 유예 상태이며 1월 9일 이후는 불확실하다고 짚었다.", "eSum": "Norway's E24 framed WW's Q3 as a profit fall: revenue rose to USD 1.40bn from 1.33bn a year earlier, but adjusted EBITDA slipped to USD 428m from 477m and net profit to USD 212m from 280m. CEO Lasse Kristoffersen said the company delivered a strong quarter with good demand and results across the business and is focused on delivering for customers and building a strong position for 2027 and the years after, backed by its recent large contracts. E24 noted that a year ago US port fees dominated the report, with an expected Q4 cost of about USD 100m before mitigation, whereas the fees are now suspended to 9 January with the aftermath unclear.", "kImp": "현지 언론은 전년 대비 이익 감소에 주목하지만 회사는 장기계약 확보를 강조하고 있어, 4분기 2027년 가이던스와 USTR 결정이 다음 관전 포인트다.", "eImp": "Local media focus on the year-on-year profit dip while management stresses long-term contract cover, leaving the Q4 report's 2027 guidance and the USTR decision as the next markers to watch.", "url": "https://e24.no/boers-og-finans/i/589LGb/resultatfall-for-wallenius-wilhemsen-tjente-212-millioner-dollar", "prio": 2}, {"code": "NOR", "date": "2026-11-04", "src": "Norges Rederiforbund", "title": "노르웨이선주협회 하레이데 \"미국 중간선거, 노르웨이 산업계엔 안도의 한숨…예측 가능성 높아져\"", "eTitle": "Norwegian Shipowners' Association CEO Hareide Calls the US Midterm Result a Sigh of Relief for Norwegian Business, Saying It Makes the US a Bit More Predictable", "kSum": "노르웨이선주협회와 싱크탱크 Civita가 미국 중간선거 다음 날 연 조찬 세미나에서 크누트 아릴 하레이데 회장은 민주당의 상·하원 과반 확보가 기업 환경을 더 안정적으로 만들 것이라며 '이번 선거로 미국이 조금 더 예측 가능해졌다'고 말했다. 그는 트럼프의 관세 정책은 효과가 없었고 '잘못된 수단을 택했다'고 평가하면서도, 유럽·미국의 지나친 중국 의존 문제를 부각한 점은 인정했다. 노르웨이 선대가 가치 기준 세계 5위로 개방된 시장과 예측 가능한 무역 규칙에 의존한다는 점도 강조했다.", "eSum": "At a breakfast seminar with the think tank Civita the day after the US midterms, Norwegian Shipowners' Association CEO Knut Arild Hareide said the Democrats' control of both chambers should bring more stable conditions, adding that the election makes the US a bit more predictable. He said Trump's tariff policy had not worked and used the wrong tools, but credited him for highlighting Europe's and America's over-reliance on China. He stressed that Norway's fleet, the world's fifth largest by value, depends on open markets and predictable trade rules.", "kImp": "미국 의회 구도 변화는 USTR 입항료·관세 정책의 향방에 영향을 줄 수 있어, 대미 자동차선 운항 비용 전망을 볼 때 참고할 만하다.", "eImp": "The shift in Congress could influence the direction of USTR port fees and tariffs, which matters for the cost outlook of US-bound car carrier trades.", "url": "https://www.rederi.no/nyheter/knut-arild-hareide-om-usa-valget--et-lettelsens-sukk-for-norsk-naringsliv/", "prio": 1}, {"code": "NOR", "date": "2026-11-03", "src": "Norges Rederiforbund", "title": "노르웨이선주협회 등 유럽 6개국 선주협회, 5,000GT 이상 해양작업선의 EU ETS(2027년 예정) 편입 전에 맞춤형 MRV 규정부터 갖추라고 요구", "eTitle": "Norwegian Shipowners' Association and Five Other European Owner Groups Ask the EU to Put Tailored MRV Rules in Place Before Offshore Vessels Above 5,000 GT Enter the EU ETS, Planned for 2027", "kSum": "노르웨이선주협회는 덴마크·스웨덴·네덜란드·벨기에·프랑스 선주협회, IMCA, 유럽준설협회와 함께 EU에 서한을 보내 2027년부터 EU ETS 적용이 예정된 5,000GT 이상 해양작업선은 새 MRV 체계가 자리 잡기 전까지 배출권 의무를 미뤄야 한다고 요구했다. 이들은 같은 해양 작업이면 출항 항만과 관계없이 같은 CO2 비용을 물려 EEA 밖으로의 탄소 누출을 막고, 화물·여객·운송량·항차 기준 보고를 간소화된 보고로 바꾸라고 제안했다. 크누트 아릴 하레이데 회장은 '보고 규정이 쿼터 의무보다 먼저 와야 한다'며 이는 면제가 아니라 순서의 문제라고 했고, 노르웨이에서는 ETS가 미뤄져도 CO2세로 전액 부담한다고 덧붙였다.", "eSum": "The Norwegian Shipowners' Association, joined by the Danish, Swedish, Dutch, Belgian and French owner associations, IMCA and the European Dredging Association, has written to the EU asking that offshore vessels above 5,000 GT, due to enter the EU ETS from 2027, face no allowance obligation until a new tailored MRV framework is in place and working. They want identical offshore operations to carry the same CO2 cost whatever port they work from, to avoid carbon leakage outside the EEA, and voyage-based reporting on cargo, passengers and transport work replaced by simplified reporting. CEO Knut Arild Hareide said reporting rules must come before the quota obligation, stressing this is about sequencing rather than an exemption, and noted that in Norway such vessels would still pay the full CO2 tax if the ETS were delayed.", "kImp": "EU ETS·MRV 개정 논의가 선종별 보고 방식까지 넓어지고 있어, 그룹 선대의 MRV·ETS 보고 체계도 향후 규정 변경에 맞춰 점검할 필요가 있다.", "eImp": "The EU ETS and MRV revision is widening to ship-type-specific reporting, so emissions reporting set-ups across the group fleet should be reviewed as the rules change.", "url": "https://www.rederi.no/nyheter/-eus-rapporteringsregler-ma-tilpasses-offshoreskip/", "prio": 1}, {"code": "NOR", "date": "2026-11-02", "src": "Sjøfartsdirektoratet", "title": "노르웨이 당국 \"폐기물 인수증 챙겼나\"…300GT 이상 선박은 SafeSeaNet Norway에 등록해야", "eTitle": "Norwegian Authorities Remind Ships of 300 GT or More to Register Port Waste Delivery Receipts in SafeSeaNet Norway, Warning of Follow-Up at Inspections", "kSum": "노르웨이 환경청·해사청·연안청이 공동으로 선박 폐기물은 항만 수용시설에 인도하고 인도마다 폐기물 인수증으로 증빙해야 한다고 상기시켰다. 오염규정 제20장(§20-8a)에 따라 항만은 부속서 IV 표준 양식으로 인수증(선박·시설·시각·종류·수량)을 발급해야 하고, 300GT 이상 선박은 인도 후 그 내용을 SafeSeaNet Norway에 등록해야 한다(45m 미만 어선·레저선·역사선은 제외). 등록이 없으면 인도가 제대로 증빙되지 않은 것으로 볼 수 있으며 감독 시 후속 조치될 수 있다고 밝혔다.", "eSum": "Norway's Environment Agency, Maritime Authority and Coastal Administration jointly reminded ships that waste must be delivered to port reception facilities and every delivery documented with a waste receipt. Under Chapter 20 of the Pollution Regulation (section 20-8a), ports must issue the receipt on the standard Annex IV form, and ships of 300 GT or more must register its details in SafeSeaNet Norway after delivery, with fishing, leisure and historic vessels under 45 m exempt. Missing registration may mean the delivery is not properly documented and can be followed up at inspections.", "kImp": "노르웨이 기항 선박은 항만 폐기물 인수증 보관과 대리점을 통한 SafeSeaNet 등록 여부를 점검해, MARPOL 기록과 함께 PSC·감독 지적을 예방해야 한다.", "eImp": "Ships calling Norway should check that port waste receipts are kept and registered in SafeSeaNet via agents, alongside MARPOL records, to avoid findings at PSC or other inspections.", "url": "https://www.sdir.no/nyheter/har-du-husket-avfallskvitteringen/", "prio": 2}, {"code": "NOR", "date": "2026-11-02", "src": "Placera (Finwire)", "title": "SEB, 3분기 실적 발표 이틀 앞두고 왈레니우스 윌헬름센 목표주가 150→178 NOK 상향 — '보유' 의견 유지", "eTitle": "SEB Raises Its Wallenius Wilhelmsen Target Price to NOK 178 From 150 and Keeps a Hold Rating Two Days Before the Q3 Results", "kSum": "11월 2일 08:49 스웨덴 뉴스통신 Finwire 속보(Placera 게재, 노르드넷 뉴스피드에도 동일 속보). SEB가 WAWI 목표주가를 150 NOK에서 178 NOK로 올리고 '보유(behåll)' 의견을 유지했다. 새 목표가는 10월 사모 발행가 168 NOK를 소폭 웃도는 수준이며, 7억 달러 계약 공시와 같은 날 나왔다. 앞서 Pareto(204 NOK, 매수, 9월 14일), Nordea(200 NOK, 매수, 10월 15일), Clarksons(155 NOK, 중립)가 목표주가를 조정했고, 3분기 실적은 11월 4일 발표 예정으로 회사는 조정 EBITDA 4억2,000만~4억5,000만 달러를 가이던스로 제시한 상태다. 속보는 제목만 전해져 상향 근거는 공개되지 않았다.", "eSum": "A Finwire newswire flash carried by Placera at 08:49 on 2 November (also on the Nordnet news feed): SEB lifted its target price for Wallenius Wilhelmsen to NOK 178 from NOK 150 while reiterating a hold recommendation. The new target sits just above the NOK 168 price of October's private placement and came the same day as the USD 700m contract announcement. It follows Pareto (NOK 204, buy, 14 September), Nordea (NOK 200, buy, 15 October) and Clarksons (NOK 155, neutral), ahead of Q3 results due 4 November, for which the company has guided adjusted EBITDA of USD 420-450m. The flash carries the headline only, so SEB's reasoning is not public.", "kImp": "신조 확대와 연이은 계약에도 '보유'에 머문 것은 2027년 운임 재협상 결과와 연료·용선 비용 부담을 지켜보겠다는 신호다. 11월 4일 실적에서 제시될 2027년 계약 커버리지와 운임 전망이 선대 운용 계획과 투자 여력을 읽는 기준이 된다.", "eImp": "A hold stance despite the enlarged newbuild programme and a run of contracts signals that analysts want to see the outcome of 2027 rate renegotiations and the burden of fuel and charter costs. The 2027 contract coverage and rate outlook presented on 4 November will frame how the market reads fleet deployment plans and investment capacity.", "url": "https://www.placera.se/telegram/wallenius-wilhelmsen-seb-hojer-riktkursen-for-wallenius-wilhelmsen-till-178-norska-kronor-150-upprepar-behall-20261102", "prio": 1}, {"code": "NOR", "date": "2026-10-30", "src": "Wallenius Marine", "title": "왈레니우스 마린, 자동차운반선 '오토 웨이' 선원 복지 투자 소개…브리지 윙 밀폐·욕실 개보수·바닥 교체, 계약 4~6개월", "eTitle": "Wallenius Marine Profiles Crew Welfare on the Car Carrier Auto Way, Citing Enclosed Bridge Wings, Renovated Bathrooms and New Flooring, With Four-to-Six-Month Contracts", "kSum": "스웨덴 선박관리사 왈레니우스 마린(Wallenius Marine)은 10월 30일 블로그 글에서 2024년 인수한 자동차운반선 '오토 웨이(Auto Way)'의 선원 복지 사례를 소개했다. 이 선박은 기항이 잦은 유럽 항로에 투입돼 항구 간 항해가 대개 이틀 안팎일 만큼 일정이 빡빡하고, 다국적 선원 24명이 현재 4~6개월 계약으로 승선한다. 인수 뒤 브리지 윙을 밀폐하고 선실 욕실을 개보수했으며 거주구역 바닥을 전면 교체했고, 지난봄에는 사내 'Home Away from Home' 팀이 공용공간을 새로 꾸몄다. 10월 26일 글은 1930년대 소야(Soya) 그룹 창업자 올로프 왈레니우스의 부인 시녜 왈레니우스에서 시작된 이 팀이 선대 전체의 선실·공용공간 미술품·조명·직물을 고르고 재사용·재활용 자재를 쓰며 선박을 직접 찾아 선원 의견을 듣는다고 설명했다.", "eSum": "In a 30 October blog post, Swedish ship manager Wallenius Marine described crew welfare on Auto Way, a vehicle carrier it acquired in 2024. The ship trades on busy European routes with frequent port calls, where passages between ports often last only about two days, and carries a multinational crew of 24 on contracts that currently run four to six months. Since the acquisition the bridge wings have been enclosed, cabin bathrooms renovated and accommodation flooring replaced, and last spring the company's Home Away from Home team refreshed several communal spaces. A 26 October post explained that the team, a tradition begun in the 1930s by Signe Wallenius, wife of Soya Group founder Olof Wallenius, chooses artwork, lighting and textiles for cabins and communal areas across the fleet, favours reused and recycled materials and visits ships to hear crew feedback.", "kImp": "항차가 짧고 기항이 잦아 피로도가 높은 자동차선에서 거주환경 개선을 선원 유지·안전문화와 연결한 사례다. 선박관리사가 MLC 2006 거주·복지 관리와 선원 피로 관리 계획을 세울 때 비교 기준으로 삼을 만하다.", "eImp": "It links accommodation upgrades to crew retention and safety culture on a car carrier where short passages and frequent port calls drive fatigue, and offers a benchmark for ship managers' MLC 2006 accommodation and welfare management and fatigue planning.", "url": "https://www.walleniusmarine.com/blog/life-at-wallenius-marine/at-home-at-sea/", "prio": 1}, {"code": "NOR", "date": "2026-10-29", "src": "Skipsrevyen", "title": "노르웨이 기후환경부, 국가기관 선박 조달 때 저·무배출 선박 검토 요구…재래식 선박 선택 시 구체적 사유 제시해야", "eTitle": "Norway's Climate Ministry Will Require State Bodies Buying Vessels to Assess Low- and Zero-Emission Options and Justify Choosing a Conventional Ship", "kSum": "노르웨이 기후환경부가 국가기관이 선박을 조달할 때 저배출·무배출 선박을 검토하도록 하고, 재래식 선박을 고를 경우 구체적 사유를 제시하도록 요구하기로 했다고 Skipsrevyen이 10월 29일 아스트리드 호엠 국무차관을 인용해 보도했다. 이 지침은 저·무배출 선박 구매를 절대적으로 의무화하는 것은 아니다. 기사 본문은 유료여서 적용 선종, 법적 형식, 시행 시점은 확인되지 않았다.", "eSum": "Norway's Ministry of Climate and Environment will require state bodies procuring vessels to assess low- and zero-emission options and to give a specific justification if they choose a conventional ship, Skipsrevyen reported on 29 October, citing State Secretary Astrid Hoem. The guidance is not an absolute requirement to buy low- or zero-emission vessels. The full article is paywalled, so the vessel types covered, the legal form and the start date could not be confirmed.", "kImp": "노르웨이 공공 발주에서 친환경 선박 우선 원칙이 제도화되는 흐름으로, 연안·공공 선박의 저배출 기술 수요를 키울 전망이다. 원양 자동차선에 대한 직접 영향은 제한적이지만 노르웨이 해사 정책의 방향을 보여준다.", "eImp": "It institutionalises a green-first principle in Norwegian public vessel procurement and should lift demand for low-emission technology in coastal and public fleets. The direct impact on deep-sea car carriers is limited, but it signals the direction of Norwegian maritime policy.", "url": "https://www.skipsrevyen.no/astrid-hoem-gronn-skipsfart-klima-og-miljodepartementet/vil-kreve-begrunnelse-nar-gronne-fartoy-velges-bort/2203363", "prio": 1}, {"code": "NOR", "date": "2026-10-29", "src": "Det Norske Maskinistforbund", "title": "노르웨이 NOR 단체교섭, 페리 협약만 타결(총 4.4%·연금 기여율 4%)…오프쇼어 서비스·부이 적하·케이블·4호 협약은 결렬돼 국가조정으로", "eTitle": "Norway's NOR Wage Talks Settle Only the Ferry Agreement, With a 4.4% Frame and a 4% Pension Contribution, as Offshore Service, Buoy-Loading, Cable-Laying and Tariff 4 Talks Go to the National Mediator", "kSum": "노르웨이 기관사노조(DNMF)에 따르면 노르웨이선주협회와 선원 노조들은 10월 29일 새벽 Color Line이 적용받는 북해·발트해 운항 페리 협약에 합의했다. 합의안은 총 인상 범위 4.4%, 임금표 일반 인상 3.54%, 퇴직연금 기여율 3%에서 4%로 인상, 휴무 중 받아야 하는 교육의 보상을 교육일당 월급의 1/30에서 2/30으로 두 배 올리는 내용이다. 반면 오프쇼어 서비스, 부이 적하(bøyelast), 케이블 부설, 4호 협약(tariff 4) 교섭은 사용자 제안과 노조 요구의 격차가 커 결렬돼 국가조정관(Riksmekleren)에게 넘어갔고 조정 일정은 아직 정해지지 않았다. 선주협회의 팔 탕엔(Pål Tangen) 교섭국장은 페리 협약이 제조업 기준 인상(frontfaget)에 맞게 타결돼 만족한다면서도 오프쇼어 선대의 조정은 이례적으로 어려울 것이라고 말했다.", "eSum": "According to the Norwegian Union of Marine Engineers (DNMF), the Norwegian Shipowners' Association and the seafarer unions agreed overnight into 29 October on the ferry agreement for North Sea and Baltic trades, which covers Color Line. The deal has an overall frame of 4.4%, a general increase of 3.54% on the wage table, an occupational pension contribution raised from 3% to 4%, and double compensation for mandatory courses taken in off-duty time, from 1/30 to 2/30 of monthly pay per course day. Talks on the offshore service, buoy-loading, cable-laying and Tariff 4 agreements broke down because the gap between the employers' offer and the unions' demands was too large, and they now go to the National Mediator, with no date yet set. The association's negotiations director Pål Tangen said he was pleased the ferry deal matched the norm-setting manufacturing settlement but warned that mediation for the offshore fleet looks set to be unusually demanding.", "kImp": "NOR 협약은 노르웨이 일반 선적(NOR) 선박의 노르웨이 선원 임금·근로조건 기준이어서 NIS·외국적 원양 자동차선에 대한 직접 영향은 작다. 다만 연금 기여율·휴무 중 교육 보상 확대는 노르웨이 선원 인건비 상승 흐름을 보여주며, 오프쇼어 조정이 결렬되면 파업으로 번질 수 있는 구조다.", "eImp": "NOR agreements set pay and conditions for Norwegian seafarers on Norwegian Ordinary Register ships, so the direct effect on deep-sea car carriers under NIS or foreign flags is small. The higher pension contribution and better pay for off-duty training still point to rising Norwegian crew costs, and a failed mediation for the offshore fleet could escalate into strike action.", "url": "https://www.dnmf.no/nyhetsarkiv/enighet-for-color-line-brudd-pa-de-ovrige-nor-avtalene", "prio": 1}, {"code": "NOR", "date": "2026-10-28", "src": "Mer et Marine", "title": "노르웨이 노르딕 서클스, 해체선 강재를 건축자재로 재인증·재사용…에노바 최대 2억4,400만 크로네 지원, 회그 오토라이너스와 8척 계약", "eTitle": "Norway's Nordic Circles Plans to Recertify Steel From Scrapped Ships for Buildings, Backed by Up to NOK 244m From Enova and Holding a Deal With Höegh Autoliners Covering Eight Ships", "kSum": "프랑스 해사 매체 Mer et Marine은 10월 28일 노르웨이 기업 노르딕 서클스(대표 욘 야콥센)가 수명이 다한 선박의 강재를 녹이지 않고 회수·재인증해 건축용 표준 강재로 재사용하는 사업을 추진한다고 보도했다. 노르웨이 에너지전환기관 에노바는 10월 초 이 사업에 최대 2억4,400만 크로네 지원을 승인했다고 발표했으며, 노르딕 서클스와 테르트네스홀딩 계열 철강업체 알사케르 스톨을 포함한 총사업비는 5억2,000만 크로네(약 4,500만 유로)로, 4년 안에 노르웨이 서해안에 실증 공장을 세운 뒤 유럽으로 넓힐 계획이다. 야콥센 대표는 회그·하팍로이드·CMA CGM과 이미 계약했고 회그 오토라이너스와의 계약만 8척에 이른다고 밝혔으며, 선박 강재의 25~35%를 회수·재인증할 수 있고 인증 재사용 강재는 톤당 약 1,800달러로 해체 고철(약 800달러)보다 가치가 높다고 설명했다. 베르겐에서는 선박 강재를 일부 사용한 8층 사무용 건물이 시범사업으로 지어졌다.", "eSum": "French maritime news site Mer et Marine reported on 28 October that Norwegian company Nordic Circles, led by John Jacobsen, plans to recover steel from end-of-life ships, recertify it and reuse it as standard construction steel instead of melting it down. Norway's energy-transition agency Enova announced in early October that it had approved up to NOK 244m for the project, whose total budget including Nordic Circles and Tertnes Holding's steel firm Alsaker Stål is NOK 520m (about EUR 45m), with a demonstration plant planned on Norway's west coast within four years before expansion into Europe. Jacobsen said the company already has agreements with Höegh, Hapag-Lloyd and CMA CGM, with the Höegh Autoliners deal alone covering eight ships, that 25-35% of a ship's steel can be recovered and recertified, and that certified reused steel is worth about USD 1,800 a tonne against about USD 800 for scrap. A pilot eight-storey office building in Bergen has been built partly with ship steel.", "kImp": "북유럽 자동차선사가 노후선 해체를 강재 재사용 사업과 연계하는 흐름으로, 노후선 처분 시 홍콩협약·EU 선박재활용규정 요건과 함께 정확한 유해물질목록(IHM)과 해체 전 오염물질 제거 기록이 재사용 강재 인증의 전제가 될 수 있어 그룹의 선박 생애주기·재활용 서비스와 연계해 볼 만하다.", "eImp": "It shows a Nordic car-carrier owner tying end-of-life disposal to a steel-reuse business; for ageing ships, Hong Kong Convention and EU Ship Recycling Regulation requirements plus an accurate Inventory of Hazardous Materials and records of pre-demolition decontamination could become prerequisites for certifying reused steel, which fits with the group's own vessel lifecycle and recycling services.", "url": "https://www.meretmarine.com/fr/marine-marchande/economie-circulaire-nordic-circles-veut-reemployer-l-acier-des-navires-demanteles-dans-le-batiment", "prio": 1}, {"code": "NOR", "date": "2026-10-28", "src": "Japan Maritime Daily", "title": "회그 오토라이너스 '화주 스코프3 감축 돕는 그린 파트너 지향'…2027년 여름부터 암모니아 연료 자동차선 투입", "eTitle": "Höegh Autoliners Pitches Itself as a Green Partner Helping Shippers Cut Scope 3 Emissions and Plans Ammonia-Fuelled Car Carriers From Summer 2027", "kSum": "일본해사신문은 10월 28일자에서 노르웨이 자동차선사 회그 오토라이너스가 저환경부하 물류로 화주의 스코프3(타사 사업활동에서 발생하는 간접 온실가스) 배출 감축을 돕겠다는 방침이라고 보도했다. 회사는 자사 해상운송의 온실가스 배출 집약도가 업계 평균을 크게 밑돈다며 '고객이 선택하는 그린 파트너'를 목표로 내세웠고, 2027년 여름부터 암모니아 연료 자동차운반선을 투입해 환경부하를 더 줄일 계획이다. 유료 기사여서 무료로 공개된 앞부분만 반영했다.", "eSum": "Japan Maritime Daily reported on 28 October that Norway's Höegh Autoliners aims to help shipper customers cut their Scope 3 emissions, the indirect greenhouse gases from other companies' activities, through lower-impact logistics. The company says the GHG intensity of its sea transport is far below the industry average, aims to be a 'green partner' that customers choose, and plans to deploy ammonia-fuelled car carriers from summer 2027 to reduce its environmental impact further. The article is paywalled, so only the free opening is reflected.", "kImp": "경쟁사가 2027년 여름 암모니아 연료선 투입을 내세워 화주의 스코프3 감축 수요를 공략하고 있어, 메탄올·LNG 이중연료 신조를 늘리는 WalWil·EUKOR의 연료 전략이 화주 입찰에서 비교될 수 있다.", "eImp": "A rival is courting shippers' Scope 3 demand with ammonia-fuelled ships from summer 2027, so its fuel strategy may be compared in tenders with the methanol and LNG dual-fuel newbuilds of Wallenius Wilhelmsen and EUKOR.", "url": "https://www.jmd.co.jp/apl/article.php?no=319672", "prio": 1}, {"code": "NOR", "date": "2026-10-27", "src": "Shippax", "title": "컬러라인 ‘컬러 하이브리드’, 산데피오르~스트룀스타드 항해 중 큰 파도 세 차례 맞아 승객·선원 경상…폭풍 보엘로 속 결항 대상 아니었던 항차", "eTitle": "Color Line's Color Hybrid Is Hit by Three Large Waves on the Sandefjord-Strömstad Crossing, Leaving Several Passengers and Crew With Minor Injuries During Storm Boelo", "kSum": "로로·페리 전문지 Shippax는 10월 27일 노르웨이 VG를 인용해, 10월 26일 오전 10시 노르웨이 산데피오르를 떠나 스웨덴 스트룀스타드로 가던 컬러라인의 ‘컬러 하이브리드(COLOR HYBRID)’가 10시45분께 큰 파도 세 차례를 맞아 승객들이 넘어지고 유리와 식기가 깨졌다고 보도했다. 컬러라인 영업 담당 니나 몰란 안데르센은 VG에 ‘갑작스러운 거친 파도’였고 기상예보는 괜찮은 수준이었으며 승객과 선원 몇 명이 가벼운 부상을 입었을 뿐 중상자는 없다고 밝혔고, 텔레마르크사비사는 확인된 부상자를 4명으로 보도했다. 스트룀스타드 도착 때 구급차 여러 대가 대기했으며 일부 내부 설비가 손상됐지만 회사는 선박 상태가 양호하다고 했다. 이 항차는 폭풍 ‘보엘로’로 취소된 컬러라인 운항편에 포함되지 않았고, 회사는 탑승객에게 연락해 다른 항차 이용 기회를 주기로 했다.", "eSum": "Ro-ro and ferry trade publication Shippax reported on 27 October, citing Norway's VG, that Color Line's COLOR HYBRID, which left Sandefjord at 10:00 on 26 October for Strömstad in Sweden, was hit by three large waves at about 10:45, causing passengers to fall and glass and crockery to break. Color Line sales manager Nina Moland Andersen told VG the ship met sudden heavy seas after an acceptable forecast and that a few passengers and crew suffered minor injuries with no one seriously hurt, while Telemarksavisa reported four confirmed injured. Several ambulances met the ship in Strömstad, some interior fittings were damaged and the company said the ship is in good condition. The sailing was not among the Color Line departures cancelled because of Storm Boelo, and the company will contact the passengers and offer them a new trip.", "kImp": "예보가 양호해도 돌발 큰 파도로 인명피해가 날 수 있음을 보여주는 사례로, 동절기 황천 시즌을 앞두고 이동물 고박, 선내 이동 제한 안내, 황천 대비 점검표 운용을 재확인하고 자동차선은 화물 고박 상태(파리·도쿄 MOU 화물고박 집중점검 기간)와 갑판 작업 통제를 함께 점검할 필요가 있다.", "eImp": "It shows that sudden heavy seas can injure people even after an acceptable forecast; ahead of the winter season, securing of loose items, restrictions on moving about on board and heavy-weather checklists should be reconfirmed, and for car carriers cargo lashing (during the Paris and Tokyo MoU cargo-securing CIC) and control of deck work should be checked together.", "url": "https://www.shippax.com/en/news/waves-injure-passengers-and-crew-on-color-lines-sandefjordstromstad-crossing.aspx", "prio": 1}, {"code": "NOR", "date": "2026-10-27", "src": "Maritimt Magasin", "title": "노르웨이 연구위원회, 선박 원자력 추진 실증 ‘MarNuPS’에 2,000만 크로네 지원…2027년 올레순 인근 육상 시험, 2031~32년 해양지원선 탑재 목표", "eTitle": "The Research Council of Norway Grants NOK 20m to the MarNuPS Marine Nuclear Propulsion Pilot, With Land-Based Testing Near Ålesund From 2027 and an Offshore Vessel Targeted for 2031-32", "kSum": "노르웨이 해사지 Maritimt Magasin은 10월 27일 노르웨이 연구위원회가 에메랄드 뉴클리어 노르웨이가 이끄는 ‘선박 원자력 추진 시스템(MarNuPS) 파일럿’에 초기 자금 2,000만 크로네(약 200만 달러)를 지원한다고 보도했다. 1단계 총비용은 약 1억5,000만 크로네로 참여사들이 상당 부분을 자체 부담하며, 바르드(VARD)·바르드 일렉트로·아일랜드 오프쇼어·NTNU·임페리얼칼리지런던·마스킨디나미크가 선박 설계·통합, 전력관리·자동화, 운항, 모델링, 구조 건전성, 계측을 맡는다. 에메랄드의 5MWe급 ‘Gem’ 초소형 원자로를 에너지저장·전력변환·전력관리·자동화·선교 제어와 통합하는 것이 목표로, 2027년 올레순 외곽 스테테에 통합 시험시설을 세워 핵연료 대신 전기 가열로 실물 규모 선박 추진계통을 시험한다. 아일랜드 오프쇼어는 첫 탑재 선주가 돼 2031~2032년 선박 투입을 목표로 하고, 에메랄드는 2031년까지 노르웨이 대륙붕에서 첫 원자력 추진 해양 실증선을 띄우겠다는 계획이다.", "eSum": "Norway's Maritimt Magasin reported on 27 October that the Research Council of Norway is providing NOK 20m (about USD 2m) of initial funding to the Marine Nuclear Propulsion System (MarNuPS) Pilot led by Emerald Nuclear Norway. Stage 1 is estimated to cost about NOK 150m, with partners self-financing a large share; VARD, Vard Electro, Island Offshore, NTNU, Imperial College London and Maskindynamikk cover ship design and integration, power management and automation, vessel operations, modelling, structural integrity and instrumentation. The project will integrate Emerald's 5 MWe Gem microreactor with energy storage, power conversion, power management, automation and bridge control, and in 2027 set up an integrated test facility at Stette outside Ålesund to test a full-scale shipboard propulsion system using electric heating instead of nuclear fuel. Island Offshore aims to be the first owner to install the system, with vessel deployment targeted for 2031/32, and Emerald aims for the first nuclear-powered offshore demonstration vessel on the Norwegian Continental Shelf by 2031.", "kImp": "선박 원자력 추진이 노르웨이에서 육상 실증 단계로 들어가는 것으로, 상용화까지는 IMO 원자력 상선 안전규정 정비, 기국·항만국 수용, 핵물질 보안 체계가 선결 과제이고 선원 자격과 보안(ISPS를 넘어서는) 요건이 크게 달라질 수 있는 장기 과제로 지켜볼 만하다.", "eImp": "It moves marine nuclear propulsion to land-based testing in Norway; commercial use still depends on updated IMO rules for nuclear merchant ships, flag and port state acceptance and nuclear-security arrangements, which could change crew qualification and security requirements well beyond ISPS, making it a long-term issue to watch.", "url": "https://www.maritimt.com/will-fund-maritime-nuclear-energy-and-propulsion-project", "prio": 1}, {"code": "NOR", "date": "2026-10-27", "src": "Norges Rederiforbund", "title": "노르웨이선주협회·선원노조, NOR 5개 단체협약 2026년 정기 임금교섭 개시…10월 27~29일, 결렬 시 국가조정관", "eTitle": "Norwegian Shipowners' Association and Seafarer Unions Open the 2026 Main Wage Settlement for All Five NOR Agreements on 27-29 October, With Any Deadlock Going to the National Mediator", "kSum": "노르웨이선주협회(Norges Rederiforbund)와 해기사노조(NSOF)·선원노조(NSF)·기관사노조(DNMF)가 NOR 선박을 대상으로 한 2026년 정기 단체교섭(hovedtariffoppgjør)에 들어갔다. 교섭은 오프쇼어 서비스, 국제 페리, 케이블선, 부이 적하선(셔틀탱커), 근해해운(nærskipsfart) 선박용 4호 협약 등 5개 NOR 협약 전부가 대상이며, 오프쇼어 서비스선 협약에는 SAFE도 참여한다. 협상은 10월 27~29일 진행되고 합의하지 못하면 국가조정관(Riksmekleren)에게 넘어간다. 10월 29일 갱신된 협회 발표에 따르면 국제 페리 등 협약은 주 임금협상 수준으로 타결됐고, 오프쇼어 서비스선 협약은 결렬돼 국가조정관에게 넘어갔다(조정은 11월 말~12월 초 예상).", "eSum": "The Norwegian Shipowners' Association has opened this year's main collective wage settlement for NOR ships with the Norwegian Maritime Officers' Association (NSOF), the Norwegian Seafarers' Union (NSF) and the Norwegian Union of Marine Engineers (DNMF). It covers all five NOR agreements: offshore service, foreign-going ferries, cable ships, buoy-loading ships and Tariff 4 for short-sea shipping, with SAFE also taking part on the offshore service agreement. Talks run from 27 to 29 October, and if the parties cannot agree the settlement goes to the National Mediator (Riksmekleren). According to the association's update on 29 October, the ferry agreements were settled in line with the lead settlement, while the offshore service agreement broke down and goes to the National Mediator, likely in late November or early December.", "kImp": "오프쇼어·페리·근해선 중심의 NOR 협약 교섭이라 원양 자동차선에는 직접 적용되지 않지만, 노르웨이 선원 임금과 선원 정책 흐름을 가늠할 지표다.", "eImp": "The NOR agreements cover offshore, ferry, cable, shuttle tanker and short-sea ships rather than deep-sea car carriers, but the outcome is a gauge of Norwegian seafarer pay and crewing policy.", "url": "https://www.rederi.no/nyheter/nor-oppgjoret-2026/", "prio": 1}, {"code": "NOR", "date": "2026-10-26", "src": "Skipsrevyen", "title": "스웨덴 스테나, 노르웨이 페리선사 컬러라인 인수 합의…가격 비공개·2027년 1~2분기 완료 예정, 노르웨이 등록 선박 유지", "eTitle": "Sweden's Stena Agrees to Buy Norwegian Ferry Operator Color Line From the Sunde Family, With Completion Expected in Q1-Q2 2027 and Ships Staying on the Norwegian Register", "kSum": "노르웨이 해사지 Skipsrevyen은 10월 26일 컬러라인 보도자료를 인용해 스테나AB의 100% 자회사 스테나 레데리AB가 컬러라인과 자회사를 100% 보유한 컬러그룹AS 지분 전량을 올라브 닐스 순데 가문 소유의 ONS 인베스트II로부터 인수하기로 했다고 보도했다. 거래 금액은 공개되지 않았고 당국 승인이 필요하며, 완료는 2027년 1분기 말 또는 2분기로 예상되고 그때까지 양사는 따로 운영돼 운항·예약·거래처 관계에 변화가 없다. 스테나는 컬러라인을 독자 브랜드와 노르웨이 현지 경영진, 노르웨이 등록 선박을 유지하는 독립 사업으로 두고 탈탄소·기술·디지털화·고객서비스·물류에 투자할 계획이다. 스웨덴 Sjöfartstidningen에 따르면 거래 대상 선박은 오슬로~킬 항로의 컬러 판타지·컬러 매직, 크리스티안산·라르비크~히르츠할스의 슈퍼스피드 1·2, 산데피오르~스트룀스타드의 컬러 하이브리드 등 5척이다.", "eSum": "Norwegian maritime magazine Skipsrevyen reported on 26 October, citing a Color Line press release, that Stena Rederi AB, a wholly owned subsidiary of Stena AB, has agreed to buy all shares in Color Group AS, which owns 100% of Color Line and its subsidiaries, from ONS Invest II AS, owned by industrialist Olav Nils Sunde and his family. The price was not disclosed; the deal needs regulatory approval and is expected to complete around the end of Q1 2027 or in Q2 2027, with both companies operating separately until then and no change to sailings, bookings or customer and supplier relationships. Stena plans to run Color Line as an independent business with its own brand, local management in Norway and Norwegian-registered ships, investing in decarbonisation, technology, digitalisation, customer service and logistics. Sweden's Sjöfartstidningen lists five ships in the deal: Color Fantasy and Color Magic on Oslo-Kiel, Superspeed 1 and 2 on Kristiansand and Larvik to Hirtshals, and Color Hybrid on Sandefjord-Strömstad.", "kImp": "북유럽 페리 업계의 대형 재편으로, 인수 후에도 노르웨이 등록을 유지하겠다고 했지만 완료 뒤 기술관리·선원 운영 통합 방식과 노르웨이 선원 고용 조건 변화가 북유럽 해운 인력 시장에 어떤 영향을 줄지 지켜볼 필요가 있다.", "eImp": "It is a major reshaping of Nordic ferry shipping; Stena says the ships will stay Norwegian-registered, but how technical management and crewing are integrated after completion, and any change to Norwegian seafarer employment terms, will matter for the Nordic maritime labour market.", "url": "https://www.skipsrevyen.no/color-line-olav-nils-sunde-oppkjop/kjoper-color-line/2201554", "prio": 1}, {"code": "NOR", "date": "2026-10-26", "src": "Wallenius Marine", "title": "월레니우스 'Home Away from Home' 팀, 1930년대부터 이어온 선내 거주환경 꾸미기 전통 소개", "eTitle": "Wallenius Marine Profiles Its Home Away from Home Team, Which Continues a 1930s Tradition of Furnishing Ships' Cabins and Mess Rooms for Crews", "kSum": "월레니우스는 새 선박 투입 시 기술·운항과 함께 선내 생활을 우선순위로 두고, 'Home Away from Home' 팀이 선대 전반의 객실·공용공간에 미술품·조명·직물 등을 골라 배치한다. 이 전통은 1930년대 소야그룹 창업자 올로프 월레니우스의 부인 시그네 월레니우스에서 시작해 딸 마르가레타 월레니우스-클레베리가 50년 넘게 이어왔으며, 가문 구성원이 자재와 디자인을 승인한다. 팀은 스웨덴산·지속가능·내구성 원칙을 따르고 퇴역선 미술품과 재활용 직물·페트병 카펫 등을 재사용한다.", "eSum": "Wallenius treats life on board as a priority alongside technology and operations when a new ship enters service, and its Home Away from Home team selects artwork, lighting and textiles for cabins and communal spaces across the fleet. The tradition began in the 1930s with Signe Wallenius, wife of Soya Group founder Olof Wallenius, and was carried on for more than 50 years by her daughter Margareta Wallenius-Kleberg, with family members still approving materials and design. The team favours Swedish, sustainable and durable items and reuses artwork from retired ships, fabrics and carpets made from recycled bottles.", "kImp": "거주환경 개선은 선원 유지율과 MLC 2006 거주설비 기준 준수에 직결돼, 신조선 인수 시 거주구역 사양을 함께 점검할 근거가 된다.", "eImp": "Accommodation quality bears directly on crew retention and MLC 2006 accommodation standards, a reason to review living-space specifications at newbuilding delivery.", "url": "https://www.walleniusmarine.com/blog/crew-management/creating-a-home-away-from-home/", "prio": 1}, {"code": "NOR", "date": "2026-10-23", "src": "Sjøfartsdirektoratet", "title": "노르웨이 해사청, 경찰 온라인 사이버범죄 신고 창구 안내…선사·선박의 디지털 사고 해사청 보고 의무는 그대로", "eTitle": "Norwegian Maritime Authority Points Shipping Companies to the Police's New Online Data-Crime Reporting and Reminds Them That Digital Incidents Must Still Be Reported to the Authority", "kSum": "노르웨이 해사청(Sjøfartsdirektoratet)은 10월 23일 경찰이 데이터 유출·랜섬웨어·서비스거부(DoS) 공격 같은 데이터 범죄를 ID-porten 로그인으로 신고하는 디지털 창구를 열었고, 해사 부문 사이버 대응조직(Maritimt SRM)이 선사와 해사 기업에 이용을 권고한다고 밝혔다. 경찰은 사고 전모를 파악하기 전이라도 일찍 연락해야 흔적과 증거를 확보할 수 있다고 했으며, 노르웨이 기업보안위원회(NSR)의 2026년 미신고 실태조사에서는 디지털 보안사고를 겪은 기업 중 경찰에 신고한 곳이 12%에 그쳤다. 경찰 신고는 해사청 보고를 대체하지 않으며, 선박으로 번질 위험이 있거나 선박의 운항·안전에 영향을 주는 디지털 사고는 육상 시스템에서 시작된 경우까지 포함해 선사와 선박이 보고해야 한다. 보고 대상 공격은 24시간 운영되는 해사청 비상전화(+47 52 74 50 00)로 지체 없이 구두 통보한 뒤 디지털 사고 양식으로도 제출해야 하고, 정보는 연안청(Kystverket)·NORMA Cyber가 참여하는 Maritimt SRM과 공유되며, 디지털보안법 적용 기업은 국가보안청(NSM)에 사본을 보내는 별도 통보 의무가 있다.", "eSum": "The Norwegian Maritime Authority said on 23 October that the police have launched a digital service, using ID-porten login, for reporting data crime such as data breaches, ransomware and denial-of-service attacks, and that the maritime sector response environment (Maritimt SRM) urges shipping companies and other maritime businesses to use it. The police want early contact even without a full picture of the incident so that traces and evidence can be secured, and the Norwegian Business and Industry Security Council's 2026 survey found that only 12% of businesses hit by a digital security incident reported it to the police. A police report does not replace notifying the authority: shipping companies and ships must report digital incidents that risk spreading to vessels or affect a vessel's operation or safety, including incidents that start in onshore systems. Reportable attacks require immediate verbal notice to the authority's 24-hour emergency line (+47 52 74 50 00) followed by its digital incident form, with the information shared within Maritimt SRM, which includes the Coastal Administration and NORMA Cyber, while companies under the Digital Security Act have separate notification duties with a copy to NSM.", "kImp": "노르웨이 국적(NOR/NIS) 그룹 선박의 사이버 사고 대응 절차(ISM 기반 사이버 위험관리, IMO 결의 MSC.428(98))에 해사청 24시간 구두 통보·디지털 양식 제출과 육상 기원 사고 포함 기준을 반영하고, CSO 비상연락망을 최신으로 유지할 필요가 있다.", "eImp": "Cyber incident procedures for Norwegian-flag (NOR/NIS) ships in the group fleet should reflect the authority's 24-hour verbal notification and digital form, including incidents that start ashore, under ISM-based cyber risk management (IMO Resolution MSC.428(98)), and CSO contact lists should be kept current.", "url": "https://www.sdir.no/nyheter/enklere-a-anmelde-datakriminalitet/", "prio": 1}, {"code": "NOR", "date": "2026-10-23", "src": "Det Norske Maskinistforbund", "title": "노르웨이 기관사노조(DNMF) 조합원 설문: 10명 중 9명 가까이 '교육이 기술 변화를 못 따라간다' — 배터리·하이브리드(58.5%)·복합시스템 고장진단(50.9%) 교육 수요 최다", "eTitle": "Norwegian Marine Engineers' Union Survey Finds Nearly Nine in Ten Members Say Training Fails to Keep Pace With Technology, With Battery-Hybrid Systems and Complex Fault-Finding the Biggest Gaps", "kSum": "DNMF가 수산·연안해운(Kystrederiene)·NHO Sjøfart·고속선 부문 재직 조합원을 대상으로 실시한 설문 결과(응답자 수는 미공개). 69%는 교육·역량 개발 기회가 주로 정부가 의무화한(대부분 IMO 규정 기반) 과정에 한해 제공된다고 답했고, 10명 중 9명 가까이가 교육이 기술 발전을 따라가지 못하거나 부분적으로만 따라간다고 응답했다. 8명 중 10명은 교육 제안을 항상 또는 대체로 수락한다고 답해, 노조는 문제가 학습 의지가 아니라 필요한 시점에 적절한 교육이 제공되는지 여부라고 분석했다. 가장 큰 수요 분야는 배터리·하이브리드 기술(58.5%), 직무 특화 전문 과정(51.9%), 복합 시스템 고장진단(50.9%)이며, 자동화·대체연료·고전압·제조사 교육·IT/OT 및 사이버보안도 반복 언급됐다. 노조는 기관사가 새 설비를 기존 시스템과 함께 전체로 이해하고 운용·정비·고장 원인 규명까지 할 수 있어야 한다고 강조했다.", "eSum": "DNMF surveyed working members in the seafood/fishing, coastal shipping (Kystrederiene), NHO Sjøfart and fast-ferry sectors (respondent numbers not stated). 69% said courses and competence development are mainly offered only when formal, government-mandated and largely IMO-based requirements apply, and nearly nine in ten said training does not, or only partly, keeps pace with technological change. Eight in ten always or usually accept training when offered, so the union concludes the problem is the supply of relevant training when the need arises, not willingness to learn. The largest needs are battery and hybrid technology (58.5%), job-specific specialist courses (51.9%) and troubleshooting complex systems (50.9%), with automation, alternative fuels, high voltage, vendor-specific training and IT/OT cybersecurity also recurring. The union stresses that engineers must understand new equipment as part of the whole system and be able to operate, maintain and fault-find it.", "kImp": "메탄올·LNG 이중연료선과 배터리·고전압 설비가 늘어나는 자동차선 선대에도 같은 공백이 생길 수 있어, 법정 STCW 과정 외에 제조사 교육과 고장진단 훈련을 역량 매트릭스와 승선 전 교육에 반영하는 것이 선박관리사의 과제다.", "eImp": "The same gap can open on car-carrier fleets as methanol and LNG dual-fuel ships and battery and high-voltage installations proliferate, so building vendor training and fault-finding drills into competence matrices and pre-joining training beyond mandatory STCW courses is a task for ship managers.", "url": "https://www.dnmf.no/nyhetsarkiv/medlemsundersokelsen-hoy-kompetanse-krever-faglig-pafyll", "prio": 1}, {"code": "NOR", "date": "2026-10-22", "src": "SAFETY4SEA", "title": "FuelEU 풀링이 액화바이오메탄 사용 확대 — 월레니우스 라인즈·NYK 합작 UECC, 2025년 LBM으로 CO2e 7.5만t 이상 감축 추정", "eTitle": "FuelEU Pooling Boosts Liquefied Biomethane Uptake, With a Titan Study Estimating UECC's 2025 LBM Use Avoided Over 75,000 Tonnes of CO2e", "kSum": "LBM 공급사 Titan의 연구는 FuelEU Maritime의 풀링(pooling) 제도가 액화바이오메탄(LBM) 사용을 늘리고 있다고 분석했다. 사례로 Brittany Ferries와 UECC(월레니우스 라인즈·NYK 공동 소유)를 들며, UECC가 LBM으로 전과정 배출을 줄이고 FuelEU 준수 포지션을 관리하고 있다고 설명했다. Titan은 2025년 UECC에 공급한 LBM이 CO2 환산 7만5,000톤 이상의 배출을 회피한 것으로 추정했다.", "eSum": "A study by LBM supplier Titan finds that FuelEU Maritime pooling is driving greater use of liquefied biomethane. It cites Brittany Ferries and UECC, co-owned by Wallenius Lines and NYK, as operators using LBM to cut lifecycle emissions and manage their FuelEU compliance positions. Titan estimates the LBM it supplied to UECC in 2025 avoided more than 75,000 tonnes of CO2-equivalent emissions.", "kImp": "LNG 이중연료선이 늘어나는 그룹 선대에서도 바이오메탄 혼합과 FuelEU 풀링이 규제 대응 수단이 될 수 있어, 벙커링 절차·연료 품질 관리 준비가 필요하다.", "eImp": "As LNG dual-fuel tonnage grows across the group, biomethane blending and FuelEU pooling become practical compliance levers, so bunkering procedures and fuel-quality controls should be ready.", "url": "https://safety4sea.com/fueleu-pooling-boosts-biomethane-uptake-new-study-highlights/", "prio": 1}, {"code": "NOR", "date": "2026-10-21", "src": "Sjøfartsdirektoratet", "title": "노르웨이 국제선박등록부(NIS) 등록 톤수 1,799만GT로 사상 최대…1~10월 59척 등록·58척 말소", "eTitle": "Norway's NIS Register Reaches a Record 17.99 Million GT With 686 Ships, as 59 Ships Joined and 58 Left From January to October", "kSum": "노르웨이 해사청(Sjøfartsdirektoratet)은 10월 21일 9월 말 노르웨이 국제선박등록부(NIS)의 등록 선박이 686척, 총톤수 1,799만5,013GT로 사상 최대라고 밝혔다. 1~10월 59척이 등록되고 58척이 말소됐지만 유입 톤수(159만5,459GT)가 유출(82만745GT)을 크게 웃돌았고, 신규 등록의 절반가량이 신조선이었으며 톤수 증가분의 54% 이상은 유조선, 30% 이상은 LPG선이었다. 신규 24척은 선주 국적 요건 대신 노르웨이에서의 관리·운항으로 등록 자격을 얻었고, 말소 선박은 바하마(15척)·마데이라·마셜제도(각 7척)·몰타(6척) 등 17개 기국으로 옮겼으며, 해사청은 자동차선·컨테이너 시장 강세와 국제 등록부 간 치열한 경쟁을 언급했다.", "eSum": "The Norwegian Maritime Authority said on 21 October that the Norwegian International Ship Register (NIS) held 686 ships of 17,995,013 GT at the end of September, its highest tonnage ever. From January to October 59 ships joined and 58 left, but incoming tonnage of 1,595,459 GT outweighed the 820,745 GT that left; nearly half the new entries were newbuilds, and tankers and LPG carriers accounted for over 54% and 30% of the tonnage gain. Twenty-four new ships qualified through management and operation from Norway rather than owner nationality, departing ships went to 17 flags led by the Bahamas (15), Madeira and the Marshall Islands (7 each) and Malta (6), and the authority cited strong car carrier and container markets and fierce competition between international registers.", "kImp": "그룹 선대 일부가 NIS에 등록돼 있는 만큼, 기국 간 유치 경쟁 속에서 NIS의 정책·수수료·검사 제도 변화를 계속 살필 필요가 있다.", "eImp": "As part of the group fleet is registered in NIS, changes in NIS policy, fees and survey arrangements amid intensifying competition between flags are worth tracking.", "url": "https://www.sdir.no/nyheter/rekordhoy-tonnasje-i-nis/", "prio": 1}, {"code": "NOR", "date": "2026-10-21", "src": "Norges Rederiforbund", "title": "노르웨이선주협회 '그림자 선단 고착화 우려'…정보공유·국제공조·표적 조치 촉구", "eTitle": "Norwegian Shipowners' Association Warns the Shadow Fleet Risks Becoming Permanent and Urges Intelligence Sharing, International Cooperation and Targeted Measures", "kSum": "노르웨이선주협회(Norges Rederiforbund)는 10월 21일 영국-노르웨이 상공회의소(BNCC)와 정부·업계 조찬 회의를 열고, 2022년 러시아산 원유 가격상한제 이후 커진 그림자 선단이 해운을 규칙을 지키는 시장과 법 밖의 시장으로 영구 분열시킬 수 있다고 우려했다. 그림자 선단의 유조선은 1,000척이 넘고 영국은 600척 이상을 제재했으며, 노후·보험 미비 선박이 많아 사고나 기름 유출이 나면 선원과 다른 선박·연안국이 피해를 볼 수 있다고 협회는 지적했다. 리네 팔켄베르그 올레스타(Line Falkenberg Ollestad) 협회 지정학 책임자는 국제 해사 체계를 훼손하지 않으면서 그림자 선단과 싸워야 한다고 했고, 노르웨이 외교부 측은 러시아 국적으로 운항하는 선박이 늘어 단속이 복잡해졌다고 말했다.", "eSum": "The Norwegian Shipowners' Association, at a 21 October breakfast meeting with the British Norwegian Chamber of Commerce, government officials and industry, warned that the shadow fleet that grew after the 2022 price cap on Russian oil could split shipping permanently into a rule-based market and one operating outside the law. More than 1,000 tankers now sail in the shadow fleet and the UK has sanctioned over 600 vessels; the ships are older, often poorly insured and opaque, so an accident or oil spill could hurt seafarers, other ships and coastal states. Head of geopolitics Line Falkenberg Ollestad said the fleet must be fought without undermining the international maritime system, while Norway's foreign ministry noted that more of these ships now sail under the Russian flag, complicating enforcement.", "kImp": "노후·보험 미비 그림자 선단 유조선과의 근접 조우로 충돌·오염 위험이 커진 만큼, 관리선의 항로 위험평가와 AIS 미송신 선박 경계, 사고 시 보고 절차를 점검할 필요가 있다.", "eImp": "Closer encounters with old, poorly insured shadow-fleet tankers raise collision and pollution risk, so managed ships should revisit route risk assessments, vigilance for vessels not transmitting AIS and incident reporting procedures.", "url": "https://www.rederi.no/nyheter/bekymring-for-at-skyggeflaten-blir-permanent/", "prio": 1}, {"code": "NOR", "date": "2026-10-21", "src": "Sjöfartstidningen", "title": "스웨덴 조사선 ‘오션 서베이어’ 야간 좌초, 당직 항해사 ‘잠든 것 같다’ 시인…해상교통 과실 혐의로 기소", "eTitle": "Mate on Watch When Swedish Research Ship Ocean Surveyor Ran Aground at Night Is Charged With Negligence After Admitting He Must Have Fallen Asleep", "kSum": "스웨덴 해운지 Sjöfartstidningen은 10월 21일, 스웨덴 지질조사청(SGU) 소속 조사선 ‘오션 서베이어(Ocean Surveyor)’가 8월 발트해 작업을 마치고 스톡홀름 베르탄으로 돌아가던 중 새벽 1시께 스톡홀름 군도 뫼야섬 남동쪽에서 좌초한 사건으로 당직 항해사(styrman)가 해상교통 과실(vårdslöshet i sjötrafik) 혐의로 기소됐다고 보도했다. DN에 따르면 그는 혐의를 인정하며 ‘잠이 든 게 틀림없다’고 말했고, 20시~04시 당직을 서던 중이었으며 ‘긴 하루’였다고 진술했다. 선원들이 경보를 울려 해안경비대가 출동했고 부상자는 없었지만 이튿날 잠수 점검에서 우현 선체 손상과 침수가 확인됐으며, 타와 프로펠러는 이상이 없어 배수 뒤 자력으로 스톡홀름에 가 수리에 들어갔다. 스웨덴 SVT는 사고 당일인 8월 16일 길이 37m의 이 선박이 오후에 이초됐고 교통청 검사관이 현장에 나왔으며 사고조사위원회(SHK)가 조사에 나선다고 보도했다.", "eSum": "Swedish shipping weekly Sjöfartstidningen reported on 21 October that the mate on watch when the Geological Survey of Sweden (SGU) research vessel Ocean Surveyor ran aground at about 01:00 southeast of Möja in the Stockholm archipelago in August, while returning to Värtan in Stockholm after work in the Baltic, has been charged with negligence in maritime traffic. According to DN, he admits the offence, said he must have fallen asleep, had the 20:00-04:00 watch and described it as a long day. The crew raised the alarm, the Coast Guard attended and no one was hurt, but divers found starboard hull damage and water ingress the next day; with rudder and propeller intact, the water was pumped out and the ship went to Stockholm under her own power for repairs. Sweden's SVT reported on the day of the grounding, 16 August, that the 37-metre ship was refloated in the afternoon, a Transport Agency inspector attended and the Swedish Accident Investigation Authority (SHK) would investigate.", "kImp": "8시간 야간 당직 중 졸음이 좌초와 형사책임으로 이어진 사례로, 야간 견시 배치, BNWAS 작동 상태, 휴식시간 기록과 실제 피로도(긴 작업일 뒤 당직 투입 등) 관리를 점검하고 선원 교육 사례로 활용할 만하다.", "eImp": "It shows an eight-hour night watch ending in a grounding and criminal liability; night lookout manning, BNWAS operation, and rest-hour records versus actual fatigue (such as watches after a long working day) should be checked, and the case is useful for crew training.", "url": "https://www.sjofartstidningen.se/nyheter/styrman-somnade-atalas-foer-vardsloeshet-i-sjoetrafik/326044", "prio": 1}, {"code": "NOR", "date": "2026-10-20", "src": "HANSA", "title": "MSC의 오슬로 자동차선 자회사 GCC, 8,600 CEU LNG 이중연료 PCTC 2척 추가 발주…신조 프로그램 22척·18만2,800 CEU로 확대", "eTitle": "MSC's Oslo-Based Car Carrier Arm Global Car Carriers Orders Two More 8,600 CEU LNG Dual-Fuel PCTCs, Taking Its Newbuild Programme to 22 Ships and 182,800 CEU", "kSum": "독일 해사지 HANSA는 10월 20일 MSC의 오슬로 소재 자동차선 자회사 글로벌 카 캐리어스(GCC, 옛 그램 카 캐리어스)가 중국 저우산 창훙국제조선소에 8,600 CEU급 LNG 이중연료 PCTC 2척을 추가 발주해 2030년 인도받는다고 보도했다. 이로써 신조 프로그램은 8,600 CEU 18척과 7,000 CEU 4척 등 22척, 총 18만2,800 CEU로 늘었고 창훙·초상국 이정(Yizheng)·초상국 웨이하이·광저우조선(GSI)·마웨이 등 중국 조선소에서 2028~2030년 인도된다. 7월 12척이던 프로그램은 몇 주 전 8척 추가(Splash 보도 기준 20억 달러 이상)로 20척이 됐고 이번에 다시 늘었으며, 새 2척의 선가는 공개되지 않았다. MSC는 2024년 자회사 SAS Shipping Agencies Services를 통해 그램 카 캐리어스를 약 7억 달러에 인수해 상장폐지했고 2026년 5월 사명을 바꿨으며, 기존 선대는 2,000~7,000 CEU급 21척이다.", "eSum": "HANSA reported on 20 October that Global Car Carriers (GCC), MSC's Oslo-based car carrier subsidiary formerly known as Gram Car Carriers, has ordered two more 8,600 CEU LNG dual-fuel PCTCs from Zhoushan Changhong International Shipyard for delivery in 2030. Its newbuilding programme now stands at 22 ships, 18 of 8,600 CEU and four of 7,000 CEU, totalling 182,800 CEU and delivering in 2028-2030 from Changhong, China Merchants Yizheng, China Merchants Weihai, Guangzhou Shipyard International and Mawei. The programme stood at 12 ships in July and reached 20 a few weeks earlier with an eight-ship order that Splash valued at more than USD 2bn, and no price was given for the latest pair. MSC bought Gram Car Carriers in 2024 through SAS Shipping Agencies Services for about USD 700m, delisted it and renamed it in May 2026, and GCC's existing fleet numbers 21 car carriers of 2,000-7,000 CEU.", "kImp": "왈레니우스 윌헬름센(최대 26척)·회그(최대 26척)에 이어 MSC 계열도 2028~2030년 대형 LNG 이중연료선을 대거 투입하므로 LNG 연료 취급(IGF Code) 자격 해기사 확보 경쟁이 커지고 2028년 이후 용선 시장 수급도 달라질 수 있어, 교육·승선 인력 계획에 미리 반영할 필요가 있다.", "eImp": "With MSC's arm joining Wallenius Wilhelmsen (up to 26 ships) and Höegh (up to 26) in adding large LNG dual-fuel tonnage in 2028-2030, competition for officers qualified for LNG fuel handling under the IGF Code will sharpen and the charter-market balance after 2028 may shift, which training and manning plans should anticipate.", "url": "https://hansa.news/msc-subsidiary-gcc-expands-car-carrier-orders-to-22/", "prio": 2}, {"code": "NOR", "date": "2026-10-20", "src": "Norges Rederiforbund", "title": "노르웨이선주협회, 브뤼셀 EU 해사산업전략 세미나서 '경쟁력 있는 선대 없이는 해양안보도 없다'", "eTitle": "At a Brussels Seminar on the EU Industrial Maritime Strategy, Norwegian Shipowners Argue There Is No Maritime Security Without a Competitive European Fleet", "kSum": "노르웨이선주협회는 10월 20일 브뤼셀 노르웨이 하우스에서 'EU 산업 해사전략' 세미나를 열었다. 마리안네 시베르트센 네스(Marianne Sivertsen Næss) 수산·해양장관은 보호무역주의 확산을 경계하며 EU가 노르웨이의 내수시장이고 노르웨이가 30개 EEA 국가의 하나로 계속 인정받는 것이 중요하다고 했고, 집행위원회 DG MOVE의 마그다 콥친스카(Magda Kopczyńska) 총국장은 노르웨이가 유럽 해사 산업기반에 포함된다며 전략이 보호주의로 흘러서는 안 된다고 말했다. 크누트 아릴 하레이데(Knut Arild Hareide) 협회 CEO는 민간선박 공격·GPS 교란·디지털 위협·그림자 선단을 들어 '유럽에서 선대가 사라지면 해양안보도 없다'고 강조했으며, 노르웨이 정부는 새 해양정책 백서(stortingsmelding)를 준비 중이다.", "eSum": "The Norwegian Shipowners' Association hosted a 20 October seminar at Norway House in Brussels on the EU Industrial Maritime Strategy. Fisheries and Ocean Minister Marianne Sivertsen Næss warned against growing protectionism, calling the EU Norway's home market, and DG MOVE Director-General Magda Kopczyńska said Norway is part of Europe's maritime industrial base and the strategy should not turn protectionist. Association CEO Knut Arild Hareide cited attacks on civilian ships, GPS interference, digital threats and the shadow fleet, saying there is no maritime security if the fleet disappears from Europe, and the government is preparing a new maritime white paper.", "kImp": "EU 산업 해사전략에 보안 축이 들어가고 노르웨이의 산업기반 포함 여부가 쟁점이 된 만큼, 노르웨이 기반 그룹에 적용될 EU 규제(ETS·FuelEU·보안 요건)의 방향을 함께 지켜볼 필요가 있다.", "eImp": "With a security pillar now part of the EU maritime industrial strategy and Norway's place in that industrial base under discussion, the direction of EU rules affecting a Norway-based group, including ETS, FuelEU and security requirements, is worth following.", "url": "https://www.rederi.no/nyheter/--uten-en-konkurransedyktig-flate-ingen-maritim-sikkerhet/", "prio": 1}, {"code": "NOR", "date": "2026-10-16", "src": "Skipsrevyen", "title": "스테나라인, CLdN 로로선 '서머싯' 매입해 더블린~리버풀 투입…연말 왈레니우스 SOL 용선선 '툴레란드' 반선", "eTitle": "Stena Line Buys CLdN's Ro-Ro Somerset for Dublin-Liverpool and Will Return Wallenius SOL's Chartered Thuleland at Year-End", "kSum": "스테나라인이 그동안 용선해 온 CLdN의 로로선 서머싯(Somerset)을 사들여 '스테나 프레이터(Stena Freighter)'로 개명하고 더블린~리버풀 항로에 투입한다. 1999년 독일 Flender Werft에서 건조된 길이 183.4m, 2,504차선미터 규모 선박으로 10월 말 인도 후 도킹·도장을 거쳐 12월 초 취항할 예정이며 매입가는 공개되지 않았다. 이에 따라 스테나 스코샤·스테나 하이버니아가 로테르담~하리치 항로로 옮겨 용선선 미스트랄(Godby Shipping)과 툴레란드(Thuleland)를 대체하며, 스테나는 왈레니우스 SOL 소유 툴레란드를 연말에 반선한다.", "eSum": "Stena Line is buying the ro-ro Somerset from CLdN, which it previously chartered, and will rename her Stena Freighter for its Dublin-Liverpool route. The 1999 Flender Werft-built ship is 183.4 m long with 2,504 lane metres; handover is planned for later in October, followed by drydocking and painting, with service from early December, and the price was not disclosed. Stena Scotia and Stena Hibernia will move to Rotterdam-Harwich, replacing the chartered Mistral (Godby Shipping) and Thuleland, and Stena will return Wallenius SOL's Thuleland at year-end.", "kImp": "왈레니우스 SOL은 연말 툴레란드를 돌려받아 재배치나 재용선을 결정해야 하므로, 발트해 신규 장기 계약으로 늘어난 선대의 운용 계획에 변수가 생긴다.", "eImp": "Wallenius SOL gets Thuleland back at year-end and must redeploy or recharter her, adding a variable to fleet planning as it grows on new long-term Baltic contracts.", "url": "https://www.skipsrevyen.no/cldn-dublin-liverpool-roro-skip/kjoper-roro-skip-for-a-erstatte-to-skip/2196349", "prio": 1}, {"code": "NOR", "date": "2026-10-16", "src": "Sjöfartstidningen", "title": "스웨덴 선원노조, SRO의 연계협약 해지 비판 — 사관협회 협약 2027년 1월 31일 종료 예정", "eTitle": "Swedish Seafarer Unions Criticise SRO's Termination of Its Bridging Agreements, With the Officers' Agreement Set to Expire on 31 January 2027 Unless a Solution Is Found", "kSum": "스웨덴 선주단체 SRO가 Storsjöavtalet 연계(hängavtal) 협약을 해지하고 자체 중앙 단체협약을 추진하자, Sjöbefälsföreningen(사관협회)의 Peter Hellberg 대표는 기존 협약이 조정을 막지 않았고 늘 대화에 열려 있었다고 반박했다. Seko sjöfolk의 Kenny Reinhold 위원장은 SRO가 로컬 협상 제안을 활용하지 않았고 원하는 변경도 구체화하지 않았다고 비판했다. 사관협회는 SRO가 스웨덴 경영자총연합(Svenskt Näringsliv) 밖에 있어 직역연금·보험·전직지원이 해결되지 않았다고 우려했으며, 다른 합의가 없으면 사관협회 연계협약은 2027년 1월 31일 종료된다.", "eSum": "After Swedish shipowner group SRO gave notice on its bridging agreements tied to the Storsjöavtalet and sought its own central collective agreements, Sjöbefälsföreningen chief Peter Hellberg said the current agreements did not block adjustments and the union had always been open to dialogue. Seko sjöfolk chair Kenny Reinhold said SRO had not used offers of local negotiations or specified the changes it wants. The officers' union warned that because SRO sits outside the Confederation of Swedish Enterprise, occupational pensions, insurance and transition support remain unresolved. Unless another solution is agreed, the officers' bridging agreement ends on 31 January 2027.", "kImp": "스웨덴 선적 선대의 사관·부원 근로조건과 연금·보험 체계가 2027년 초 공백 위험에 놓인다. 스웨덴 선주 계열 선박을 운영하는 쪽은 협상 결과를 지켜봐야 한다.", "eImp": "Working conditions, pensions and insurance for officers and ratings on Swedish-flag ships face a possible gap from early 2027. Operators of ships owned by Swedish owners should follow the outcome of the talks.", "url": "https://www.sjofartstidningen.se/nyheter/facken-kritiserar-sros-uppsaegning-av-haengavtalen/325749", "prio": 1}, {"code": "NOR", "date": "2026-10-15", "src": "Finansavisen", "title": "노르데아, 왈레니우스 윌헬름센 목표가 171→200크로네 상향·매수 유지…클락슨은 155크로네로 올리되 '중립'", "eTitle": "Nordea Lifts Its Wallenius Wilhelmsen Target to NOK 200 From 171 and Reiterates Buy, While Clarksons Raises Its Target to NOK 155 but Stays Neutral", "kSum": "핀안사비센(Infront TDN Direkt)에 따르면 노르데아 마켓은 10월 15일 왈레니우스 윌헬름센 목표주가를 171크로네에서 200크로네로 올리고 매수 의견을 유지했다. 노르데아는 확대된 신조 프로그램과 3억달러 증자가 선복을 확보하고 2027~2030년 저평가된 배당 여력을 키운다며, 3분기 실적을 앞두고 선대의 40%에 걸친 진행 중인 갱신 국면이 수익 구성에 예상보다 크게 기여할 것으로 보고 2027·2028년 EBITDA 추정치를 각각 15%·22% 올렸다(블룸버그 컨센서스보다 15%·17% 높음). 앞서 클락슨 증권은 10월 13일 선가 상승과 증자에 따른 선대 투자 재원 강화를 이유로 목표가를 140크로네에서 155크로네로 올렸지만, 2027년 선대 증가가 수송 수요를 웃돌아 정기용선료가 내려갈 수 있고 주가가 이미 순자산가치(주당 약 160크로네)를 넘어섰다며 중립을 유지했다.", "eSum": "Nordea Markets raised its Wallenius Wilhelmsen target price to NOK 200 from NOK 171 on 15 October and kept its buy rating, Finansavisen reported via Infront TDN Direkt. Nordea said the enlarged newbuilding programme and the USD 300m placement secure capacity and strengthen an underappreciated 2027-2030 dividend potential, and that the ongoing renewal phase covering 40% of the fleet should lift the earnings mix more than assumed, raising its 2027 and 2028 EBITDA estimates by 15% and 22%, or 15% and 17% above Bloomberg consensus. Clarksons Securities had lifted its target to NOK 155 from NOK 140 on 13 October on higher ship values and stronger funding for fleet investment, but stayed neutral, warning that fleet growth may outpace transport demand in 2027 and pull time-charter rates down, and that the shares already trade above its NAV of about NOK 160.", "kImp": "애널리스트들이 신조 확대와 증자를 긍정적으로 보면서도 2027년 선대 공급 증가에 따른 용선료 하락 가능성을 경고한 만큼, 11월 4일 3분기 실적에서 계약 갱신 운임과 신조 인도에 맞춘 노후선 대체·용선 축소 계획을 함께 확인할 필요가 있다.", "eImp": "Analysts welcome the bigger newbuild programme and the placement but flag the risk of softer charter rates as fleet supply grows in 2027, so the 4 November Q3 report should be read for contract renewal rates and plans to retire older tonnage and cut charters as newbuilds arrive.", "url": "https://www.finansavisen.no/tdn/2026/10/15/06604158/wawi-nordea-hoyner-kursmal-til-200-171-gjentar-kjop", "prio": 2}, {"code": "NOR", "date": "2026-10-14", "src": "Norges Rederiforbund", "title": "노르웨이선주협회, 2027 예산안 반발…선원고용 보조금 상한 인하·CO2세 이중부담 환급 거부 '신뢰 위반'", "eTitle": "Norwegian Shipowners' Association attacks the 2027 budget over a seafarer grant cap cut and refusal to refund double CO2 charges", "kSum": "노르웨이선주협회는 10월 14일 의회 재정위원회 청문에서 정부의 2027년 예산안이 선원고용 보조금(tilskuddsordningen) 상한을 22만5,500크로네에서 22만3,400크로네로 낮추고 물가 연동도 하지 않는다며 철회를 요구했다. 2024~2025년 EU ETS 대상 국내 해운에 노르웨이 CO2세가 전액 중복 부과됐는데도 정부가 환급하지 않기로 했다며 환급도 촉구했으며(감면 세율은 2026년 3월 1일부터 시행), 크누트 아릴 하레이데 CEO는 이를 심각한 신뢰 위반이라고 했다. 협회는 7일 논평에서 2030년 NOx세 폐지, 선대 에너지효율 대책 검토, 하우게순 기관사관 교육과정 신설(1천만 크로네·30명)은 긍정적으로 평가했다.", "eSum": "At the Storting finance committee's hearing on 14 October, the Norwegian Shipowners' Association urged parliament to reverse the 2027 budget's cut to the seafarer employment grant cap, from NOK 225,500 to NOK 223,400, with no inflation adjustment. It also demanded refunds of the full Norwegian CO2 tax paid in 2024-2025 on top of EU ETS allowances by quota-obligated domestic shipping, which the government decided not to repay (a reduced rate took effect on 1 March 2026), and CEO Knut Arild Hareide called this a serious breach of trust. In its 7 October budget reaction the association welcomed plans to abolish the NOx tax from 2030, a study of fleet energy-efficiency measures and NOK 10m for a new marine engineer programme with 30 places in Haugesund.", "kImp": "노르웨이 선원 고용 지원이 실질적으로 줄면 노르웨이 국적 사관·수습생 채용 비용이 늘어 NOR/NIS 선박의 노르웨이 선원 운용에 부담이 된다. ETS와 자국 탄소세의 이중부담 논란은 용선 계약의 탄소비용 전가 조항을 점검할 필요성을 보여준다.", "eImp": "A real-terms cut in Norway's seafarer grant raises the cost of employing Norwegian officers and cadets on NOR/NIS ships, and the ETS-plus-national-CO2-tax dispute underlines the need to review carbon cost pass-through clauses in charter contracts.", "url": "https://www.rederi.no/nyheter/krever-tilbakebetaling-av-dobbel-co-avgift-og-sterkere-satsing-pa-tilskuddsordningen-for-norske-sjofolk/", "prio": 1}, {"code": "NOR", "date": "2026-10-14", "src": "Sjöfartstidningen", "title": "스웨덴 선주단체 SRO, 해기사·선원 노조와의 단체협약 연계협정(hängavtal) 해지 통보 — 자체 중앙협약 추진", "eTitle": "Swedish Shipowner Group SRO Gives Notice on Its Bridging Agreements With the Officers' and Seafarers' Unions as It Seeks Its Own Central Collective Agreements", "kSum": "스웨덴 선주단체 SRO(Sveriges Rederiorganisation) 회원사들이 해기사노조(Sjöbefälsföreningen)·Seko 선원노조와 맺은 연계협정(hängavtal)을 해지 통보했다. 해지 예고기간은 3개월이라 당장 바뀌는 것은 없다. SRO는 특히 탱커·특수선에 맞는 유연한 자체 중앙협약을 원하며, 경력 해기사가 노르웨이로 빠져나가는 것을 막으려 한다고 밝혔다. 해기사노조는 SRO와 중앙협약을 맺지 않겠다는 입장이다.", "eSum": "Member companies of the Swedish shipowner group SRO gave notice on their bridging agreements with the officers' union Sjobefalsforeningen and Seko's seafarers' section. The notice period is three months, so nothing changes immediately. SRO says it wants its own more flexible central agreements, especially for tanker and specialty shipping, and wants to stop experienced officers leaving for Norway. The officers' union has said it will not sign central agreements with SRO.", "kImp": "스웨덴 해기사의 노르웨이 유출과 임금체계 논쟁은 북유럽 선원 확보 경쟁이 치열하다는 점을 보여준다. 북유럽 선원을 쓰는 선박관리사에는 인건비와 인력 확보 변수가 될 수 있다.", "eImp": "The outflow of Swedish officers to Norway and the dispute over pay structures show how tight Nordic crew competition is, a factor in cost and crewing for managers using Nordic seafarers.", "url": "https://www.sjofartstidningen.se/nyheter/sro-saeger-upp-haengavtalen-maste-hitta-ny-ingang/325634", "prio": 1}, {"code": "NOR", "date": "2026-10-12", "src": "Soya Group", "title": "왈레니우스 라인스 모그룹 소야그룹, 대체연료·FuelEU 풀링 전문회사 'FLOW 마리타임' 출범", "eTitle": "Soya Group, the Family-Owned Group Behind Wallenius Lines and Wallenius Marine, Launches FLOW Maritime for Alternative-Fuel Management, Certification and FuelEU Pooling", "kSum": "스웨덴 소야그룹(Soya Group, 왈레니우스 라인스·왈레니우스 마린·왈레니우스 SOL이 속한 가족 소유 그룹)은 10월 12일 해운사의 대체연료 전환을 돕는 신규 회사 'FLOW 마리타임'을 출범했다. 대체연료 포트폴리오 관리, 공급망 전 과정의 인증·추적성, FuelEU 풀링, 환경속성 관리, 규제 준수 지원을 하나의 상업 모델로 묶어 제공하며, 대표(Managing Director)는 다니엘 겐트(Daniel Gent)다. 겐트 대표는 '연료 가격은 방정식의 일부일 뿐'이라며 대체연료 비용을 규제 준수 비용·배출 감축의 경제적 가치와 함께 따져야 한다고 말했다(Sjöfartstidningen 10월 16일 보도).", "eSum": "Soya Group, the family-owned Swedish group whose companies include Wallenius Lines, Wallenius Marine and Wallenius SOL, launched FLOW Maritime on 12 October to help shipowners capture the commercial, regulatory and environmental value of switching to alternative fuels. The company combines alternative-fuel portfolio management, certification and supply-chain traceability, FuelEU pooling, environmental attributes and regulatory compliance in one commercial model, and is led by Managing Director Daniel Gent. Gent said the fuel price is only one part of the equation and that alternative-fuel costs should be weighed against compliance costs and the value of emission cuts, Sjöfartstidningen reported on 16 October.", "kImp": "FuelEU 풀링·연료 인증 추적이 별도 사업이 될 만큼 규정 준수 부담이 커졌으므로, 관리선의 FuelEU 보고 데이터(BDN·지속가능성 증명) 품질 관리와 풀링 참여 구조를 미리 정리해 둘 필요가 있다.", "eImp": "FuelEU pooling and fuel-certification tracking have become a business in their own right, a sign of the growing compliance load, so the quality of FuelEU reporting data on managed ships (BDNs and proofs of sustainability) and the structure of any pooling arrangement should be settled early.", "url": "https://news.cision.com/se/soya-group/r/soya-group-lanserar-flow-maritime,c4407469", "prio": 1}, {"code": "NOR", "date": "2026-10-09", "src": "Höegh Autoliners (Oslo Børs)", "title": "회그 오토라이너스 9월 트레이딩 업데이트: 순운임 cbm당 82달러로 소폭 상승, 3분기 물동량 400만cbm 보합…중동 서비스·연료비 부담 지속", "eTitle": "Höegh Autoliners' September Trading Update Shows a USD 82 per cbm Net Rate and Flat Q3 Volume of 4.0 Million cbm, With Middle East Service and Fuel Costs Still Weighing on Earnings", "kSum": "노르웨이 자동차선사 회그 오토라이너스는 10월 9일 오슬로증권거래소 공시에서 9월 수송량(비례 기준)이 140만cbm, 3분기 전체는 400만cbm으로 2분기보다 0.1% 줄었다고 밝혔다. 9월 총운임은 cbm당 99.0달러(3분기 평균 98.8달러 대비 +0.2%), 순운임은 82.0달러(3분기 평균 81.1달러 대비 +1.1%)였고, 하이앤헤비·브레이크벌크(HH/BB) 비중은 9월 21%, 3분기 23%였다. 안드레아스 엥에르(Andreas Enger) CEO는 BAF(유류할증료) 보전이 점차 늘어 총운임이 올랐고 수요·전망은 견조하지만, 중동 서비스와 높은 연료비로 비용이 여전히 높아 이익을 누르고 있다고 말했다(E24도 '운임 상승·비용 압박 지속'으로 보도).", "eSum": "Höegh Autoliners told the Oslo Stock Exchange on 9 October that it carried 1.4 million cbm on a prorated basis in September and 4.0 million cbm in the third quarter, 0.1% less than in the second. The September gross rate was USD 99.0 per cbm, 0.2% above the Q3 average of USD 98.8, and the net rate USD 82.0, 1.1% above the Q3 average of USD 81.1, while high-and-heavy and breakbulk made up 21% of September volume and 23% for the quarter. CEO Andreas Enger said gross rates rose as BAF compensation gradually increased and demand stays robust, but costs remain elevated because of the Middle East service and higher fuel prices, which weigh on earnings.", "kImp": "경쟁사도 중동 서비스·연료비 부담을 BAF로 전가하는 단계여서, 그룹 선대의 연료 소모 관리(속력·트림·선체 상태)와 BAF 산정 근거 데이터의 정확성이 비용 경쟁력에 직결된다.", "eImp": "With the main rival also passing Middle East service and fuel costs through BAF, fuel-consumption management on group ships (speed, trim, hull condition) and accurate data behind BAF calculations bear directly on cost competitiveness.", "url": "https://newsweb.oslobors.no/message/683843", "prio": 1}, {"code": "NOR", "date": "2026-10-08", "src": "Sjöfartstidningen", "title": "월레니우스 마린, KTH·RISE·오션버드와 '풍력추진 최적 선형' 연구 착수…2029년까지 940만 크로나", "eTitle": "Wallenius Marine launches the WinPrOVeDD wind-propulsion ship design study with KTH, RISE and Oceanbird, running to 2029", "kSum": "Sjöfartstidningen에 따르면 월레니우스 마린은 스웨덴 왕립공대(KTH)·RISE·알파월 오션버드와 함께 선체·갑판 형상이 윙세일 등 풍력추진 효율에 미치는 영향을 분석하는 연구 'WinPrOVeDD(Wind Propulsion Oriented Vessel Deck Design)'를 시작했다. 총예산 약 940만 크로나 가운데 560만 크로나를 스웨덴 에너지청이 지원하며, 2029년까지 시뮬레이션과 풍동시험을 거쳐 설계 지침을 공개할 예정이다. 우르반 리샤이코 선박설계·신조·혁신 총괄은 화석연료 시대의 선박에 풍력 장치를 덧붙일 게 아니라 바람을 중심으로 미래 선박을 설계해야 한다고 말했다.", "eSum": "Wallenius Marine has launched WinPrOVeDD (Wind Propulsion Oriented Vessel Deck Design) with KTH, RISE and AlfaWall Oceanbird to study how hull and deck shapes affect the efficiency of wing sails and other wind systems, Sjöfartstidningen reported. The Swedish Energy Agency is funding SEK 5.6m of the roughly SEK 9.4m budget, and simulations and wind-tunnel tests running to 2029 will produce openly published design guidelines for designers, yards and owners. Urban Lishajko, head of ship design, newbuilding and innovation, said future ships must be designed around the wind rather than retrofitting wind technology onto fossil-era hulls.", "kImp": "오르셀 윈드 등 월레니우스 계열의 풍력추진 선형 개발과 맞닿은 연구로, 장기적으로 차세대 자동차선 설계 기준과 선상 운용 절차에 반영될 수 있다.", "eImp": "The study links to the Wallenius sphere's wind-propulsion designs such as Orcelle Wind and could feed into next-generation car-carrier design standards and onboard operating procedures over the long term.", "url": "https://www.sjofartstidningen.se/nyheter/sa-ska-fartyg-designas-foer-vinden/325381", "prio": 1}, {"code": "NOR", "date": "2026-10-07", "src": "Sjöfartstidningen", "title": "스웨덴 월레니우스 라인스, WW 3억 달러 증자 불참…\"소야그룹 포트폴리오 대비 투자 규모 커\"", "eTitle": "Sweden's Wallenius Lines sits out WW's USD 300m placement, citing the investment's size relative to Soya Group's portfolio", "kSum": "스웨덴 해운지 Sjöfartstidningen은 Wallenius Wilhelmsen이 LNG 이중연료 대형 자동차선 4척(2030년 인도) 발주 협상을 마무리 단계로 진행 중이며, 2031년부터 분기별 인도되는 8척 옵션까지 행사하면 신조 프로그램이 2032년까지 최대 26척이 된다고 보도했다. 2023~2024년 발주한 셰이퍼급 14척 중 7월 아틱 턴이 첫 인도돼 13척이 남았고, 재원은 3억 달러(약 30억 크로나) 사모 증자와 차입이다. 최대주주 빌헬름센 홀딩은 지분율(37.9%)만큼 청약을 약정했으나 유동성 확대를 위해 축소 배정될 수 있고, 소야그룹 소유 월레니우스 라인스는 전략은 지지하지만 소야그룹의 다른 보유자산 대비 투자 규모를 이유로 불참했다. E24에 따르면 주관사는 DNB 카네기·ABG 순달 콜리어·노르디아·SEB이며, 회사는 3분기 조정 EBITDA 4억2천만~4억5천만 달러와 연간 약 16억 달러 전망을 유지했다.", "eSum": "Sweden's Sjöfartstidningen reported that Wallenius Wilhelmsen is in advanced talks for four large LNG dual-fuel car carriers for 2030 delivery, with options for eight more delivered quarterly from 2031 that would take the newbuilding programme to as many as 26 ships through 2032. Of the 14 Shaper-class ships ordered in 2023-2024, Arctic Tern was delivered in July, leaving 13, and funding comes from a USD 300m (about SEK 3bn) private placement plus debt. Top shareholder Wilh. Wilhelmsen Holding committed to its 37.9% pro-rata share but could be scaled back to improve liquidity, while Soya Group's Wallenius Lines backs the strategy but stayed out, citing the investment's size relative to Soya Group's other holdings. E24 named DNB Carnegie, ABG Sundal Collier, Nordea and SEB as managers, and the company guided Q3 adjusted EBITDA at USD 420-450m while keeping about USD 1.6bn for 2026.", "kImp": "두 창업 주주 가운데 월레니우스 측만 증자에 빠져 지분 구조가 빌헬름센 쪽으로 기울 수 있어 그룹 지배구조 변화로 이어질지 주목된다. LNG 이중연료 대형선이 최대 12척 추가되면 LNG 연료 취급·벙커링 안전 교육과 관리 인력 수요가 크게 늘어난다.", "eImp": "With only the Wallenius side of the two founding owners sitting out, ownership may tilt toward Wilhelmsen, a governance shift worth watching, and up to 12 more large LNG dual-fuel ships would sharply raise demand for LNG fuel handling, bunkering safety training and management staff.", "url": "https://www.sjofartstidningen.se/nyheter/wallenius-wilhelmsen-vill-bygga-mer-kan-bli-26-nybyggen/325135", "prio": 3}, {"code": "NOR", "date": "2026-10-07", "src": "E24", "title": "WW 주가 7.2% 급락해 증자가(168크로네) 밑돌아…EU의 중국산 하이브리드 수입 제한 추진 보도 여파", "eTitle": "WW shares slump 7.2% below the NOK 168 placement price on reports of EU curbs on Chinese hybrid imports", "kSum": "E24에 따르면 Wallenius Wilhelmsen 주가는 10월 7일 7.2% 떨어진 165크로네로 마감해 6~7일 주당 168크로네에 3억 달러(약 29억 크로네)를 조달한 사모 증자 가격을 밑돌았다. EU 소식 전에도 약 4% 하락한 상태였는데, 블룸버그가 익명 소식통을 인용해 EU가 중국산 하이브리드차 수입을 제한하는 세이프가드를 준비 중이라고 보도하자 낙폭이 커졌고 회그 오토라이너스도 2.8% 떨어졌다. 이후 블룸버그는 10월 11일 EU와 중국이 중국산 하이브리드 수입을 첫 12개월 35만대(이후 연 6% 증가, 4년간)로 제한하는 데 합의했으며 12월 1일부터 시행될 수 있다고 보도했다.", "eSum": "Wallenius Wilhelmsen fell 7.2% to close at NOK 165 on 7 October, below the NOK 168 price of its USD 300m (about NOK 2.9bn) private placement run on 6-7 October, E24 reported. The stock was already down about 4% before Bloomberg reported, citing anonymous sources, that the EU is preparing safeguard measures to limit imports of Chinese hybrid cars, and Höegh Autoliners fell 2.8%. Bloomberg later reported on 11 October that the EU and China agreed to cap Chinese hybrid imports at 350,000 vehicles in the first 12 months, rising 6% a year over four years, possibly from 1 December.", "kImp": "중국발 유럽행 완성차는 아시아 선복 완판을 떠받치는 핵심 물량이어서 EU 수입 쿼터는 항로별 선복 배분과 운임에 하방 위험이 된다. 다만 쿼터가 연 35만대에서 늘어나는 구조라 단기 물량 충격은 제한적일 수 있어 실제 시행 내용을 지켜봐야 한다.", "eImp": "China-to-Europe car volumes are a core pillar of the sold-out Asian trades, so an EU import quota is a downside risk for trade allocation and rates; with the cap starting at 350,000 a year and rising, the near-term volume hit may be limited, and the final implementation needs watching.", "url": "https://e24.no/boers-og-finans/i/jvQbze/shippingaksje-faller-paa-flat-oslo-boers", "prio": 2}, {"code": "NOR", "date": "2026-10-07", "src": "Norges Rederiforbund", "title": "노르웨이 선주협회, 정부의 선대 에너지효율 정책수단 연구 계획 환영…'연구만으로는 배출 안 줄어, 내년 예산 반영 일정 필요'", "eTitle": "Norwegian Shipowners' Association Welcomes the Government's Plan to Study Energy-Efficiency Instruments for the Fleet but Warns That a Study Alone Will Not Cut Emissions", "kSum": "노르웨이 선주협회(Norges Rederiforbund)는 10월 7일 정부가 2027년 국가예산안에서 해사기후파트너십(Maritimt Klimapartnerskap) 참여 주체들의 건의를 받아 선대 에너지효율 개선을 위한 조치와 정책수단을 연구하겠다고 밝힌 것을 환영하면서도, 배출 감축은 긴 연구를 기다릴 수 없다고 했다. 업계는 2025년 12월 기존 선박의 에너지효율 개선을 위한 새 정책수단을 제안했고 정부는 이를 더 검토하겠다는 입장이며, 크누트 아릴 하레이데(Knut Arild Hareide) CEO는 '연구만으로는 배출이 줄지 않는다'며 2030년 기후목표를 위해 빠른 감축이 필요하다고 말했다. 협회는 내년 예산에 정책수단을 반영할 수 있는 명확한 일정, 보완 협약이나 에노바(Enova) 산하 별도 프로그램을 통한 재원(올해 예산안에서 에노바 예산은 줄었다), 모든 선종을 포괄하는 기술중립적 설계를 요구했다. 업계는 에너지효율 개선으로 2030년까지 국내 해운에서 CO2 환산 약 60만 톤을 줄일 수 있다고 보며, 기사는 DNV가 이런 조치로 2030년까지 세계 해운 배출을 최대 16% 줄일 수 있다고 추산한다고 전했다.", "eSum": "The Norwegian Shipowners' Association (Norges Rederiforbund) said on 7 October that it welcomes the government's statement in its 2027 state budget proposal that it will study measures and instruments for energy efficiency in the fleet, following input from the parties to the Maritime Climate Partnership, but warned that emission cuts cannot wait for a lengthy study. The industry proposed a new instrument for energy efficiency in existing vessels in December 2025, which the government says it will examine further, and CEO Knut Arild Hareide said that a study alone does not cut emissions and that the 2030 climate targets require fast cuts. The association asked for a clear timetable so the instrument can be adopted in next year's budget, funding through a supplementary agreement or a separate Enova programme (Enova's appropriations are being cut in this year's budget proposal), and a technology-neutral design covering all ship segments. The industry estimates energy efficiency could cut about 600,000 tonnes CO2-equivalent from domestic shipping by 2030, and the article cites a DNV estimate that such measures could reduce global shipping emissions by up to 16% by 2030.", "kImp": "이번 연구는 우선 노르웨이 국내 해운을 겨냥하지만 노르웨이 국적(NOR/NIS) 선박에 대한 에노바 지원이나 효율 정책이 넓어질지 지켜볼 필요가 있으며, 공기윤활·풍력보조 같은 효율 장비 투자와 CII 개선 계획을 세울 때 노르웨이 지원제도 변화를 함께 검토할 만하다.", "eImp": "The study targets Norwegian domestic shipping first, but it is worth watching whether Enova support or efficiency instruments extend to Norwegian-flag (NOR/NIS) ships, and changes to Norwegian support schemes are worth considering when planning efficiency investments such as air lubrication or wind assistance and CII improvement plans.", "url": "https://www.rederi.no/nyheter/regjeringen-vil-utrede-energieffektivisering-i-flaten/", "prio": 1}, {"code": "NOR", "date": "2026-10-05", "src": "Sjøfartsdirektoratet", "title": "노르웨이 해사청, 소형 작업선 크레인 안전 캠페인 영상 조회 40만 회 돌파…크레인 운전자 공인 안전교육 요구하는 양중 규정안도 의견수렴", "eTitle": "Norwegian Maritime Authority's Crane-Safety Campaign Film Passes 400,000 Views as a Draft Lifting Rule Would Require Certified Safety Training for Crane Operators", "kSum": "노르웨이 해사청(Sjøfartsdirektoratet)은 10월 5일, 9월 말 하우게순 ‘해사 주간’ 세미나에서 공개한 소형 작업선 크레인 작업 안전 캠페인 영상이 여러 플랫폼에서 조회 40만 회, 공유 1만 회를 넘었다고 밝혔다. 해사청 선임 엔지니어 비르테 릴 에스케비크가 기획하고 내부 영상 담당 에를렌드 비엘란이 제작했으며, 알사케르 피오르브루크의 작업선 ‘베수브(VESUV)’에서 ‘크레인을 못 다루는 두 사나이’를 유머러스하게 그렸다. 에스케비크는 시간 압박, 불분명한 역할, 부족한 교육, 미흡한 계획, 기술적 타협, 바쁜 일과에 대한 인간의 적응이 겹쳐 사고가 난다며 ‘실수는 정상’이라는 HOP(인적·조직 성과) 관점에서 시스템과 문화가 오류를 견디도록 만들어야 하고, 선사는 교육·책임 분담·절차를, 선원은 위험성평가를 주도하며 의심스러우면 작업을 중지해야 한다고 강조했다. 선박 양중장비·양중작업에 관한 새 규정안도 의견수렴을 거쳤으며, 크레인 운전자의 공인 안전교육과 인정 전문기관 활용을 요구하는 내용이다.", "eSum": "The Norwegian Maritime Authority said on 5 October that its humorous campaign film on crane-operation safety on small work boats, launched at a seminar during Maritime Week in Haugesund in late September, has passed 400,000 views and 10,000 shares across platforms. Initiated by senior engineer Birthe Lill Eskevik and produced in-house by Erlend Bjelland, it was shot on Alsaker Fjordbruk's work boat VESUV and features two men who cannot operate a crane. Eskevik said accidents arise from interacting factors such as time pressure, unclear roles, inadequate training, poor planning, technical compromises and human adaptation to a busy day; drawing on Human and Organisational Performance (HOP) thinking that it is normal to make mistakes, systems and culture should tolerate errors, owners should ensure training, clear responsibilities and routines, and crews should own risk assessments and stop work when in doubt. A proposed new regulation on lifting equipment and lifting operations on ships, which has been out for consultation, would require certified safety training for crane operators and the use of accredited expert bodies.", "kImp": "크레인 사고를 개인 실수가 아닌 조직 요인으로 보는 HOP 접근과 작업중지권 강조는 선내 양중작업(부식·선용품 적재 등)의 위험성평가와 교육에 그대로 적용할 수 있고, 노르웨이 양중 규정이 확정되면 노르웨이 선적선의 크레인 운전자 자격 요건이 바뀔 수 있다.", "eImp": "The HOP approach of treating crane accidents as organisational rather than individual failures, and the emphasis on stop-work authority, apply directly to risk assessments and training for shipboard lifting such as provisions and stores loading, and once the Norwegian lifting rule is adopted, crane-operator qualification requirements on Norwegian-flagged ships may change.", "url": "https://www.sdir.no/nyheter/sikkerhetsfilm-om-kranoperasjoner-gar-viralt/", "prio": 1}, {"code": "NOR", "date": "2026-09-23", "src": "Höegh Autoliners", "title": "회그 오토라이너스, 中 초상국그룹과 오로라급 6척 추가 건조계약 정식 서명…시리즈 18척·2029~31년 인도, 옵션 포함 최대 26척", "eTitle": "Höegh Autoliners Formally Signs the Contract for Six More Aurora Class Car Carriers With China Merchants, Taking the Series to 18 Ships for 2029-2031 Delivery and Up to 26 With Options", "kSum": "회그 오토라이너스는 9월 23일 보도자료에서 9월 22일 이탈리아 나폴리에서 열린 고위급 회동에서 초상국그룹(CMG)과 오로라급 6척 추가 건조계약에 정식 서명했다고 밝혔고, 서명식에는 먀오젠민 CMG 회장, 레이프 O. 회그 의장, 안드레아스 엥에르 CEO가 참석했다. 8월 25일 ‘추가 발주 결정’으로 공시했던 6척이 계약으로 확정되면서 오로라급은 모두 18척이 됐으며, 전량을 초상국중공업(장쑤)(CMHI)이 건조한다. 새 선박은 최대 9,100대를 싣는 LNG 이중연료선으로 DNV 암모니아 레디·메탄올 레디 부기호를 갖추고 기존 PCTC보다 차량 1대당 탄소배출을 최대 58% 줄이며 2029~2031년 인도된다. 같은 조건의 4척 옵션(8월 공시 기준 6개월 내 행사)과 4척 추가 슬롯도 확보해 최대 26척까지 늘릴 수 있고, 계약 금액은 공개하지 않았다.", "eSum": "In a 23 September release, Höegh Autoliners said it formally signed the contract for six additional Aurora class vessels with China Merchants Group (CMG) at a high-level meeting in Naples on 22 September, attended by CMG Chairman Miao Jianmin, Höegh Autoliners Chair Leif O. Høegh and CEO Andreas Enger. The signing firms up the six ships the company said on 25 August it had decided to order, taking the Aurora class to 18 ships, all built by China Merchants Heavy Industry (Jiangsu) (CMHI). The LNG dual-fuel ships carry up to 9,100 cars, hold DNV ammonia-ready and methanol-ready notations, cut carbon emissions per car by up to 58% versus conventional PCTCs and deliver in 2029-2031. Höegh also holds an option for four more ships on the same terms, exercisable within six months of the August announcement, plus slot reservations for four more, allowing up to 26 ships; the contract value was not disclosed.", "kImp": "북유럽 경쟁사의 LNG 이중연료 대형선 발주가 계약으로 확정돼 2029~2031년 자동차선 공급이 더 늘어나는 만큼, 그룹의 LNG 이중연료 대형선 추가 발주 계획과 함께 업계 전반에서 IGF 코드 교육을 마친 LNG 연료 취급 선원 수요가 커질 것에 대비해 선원 양성 계획을 미리 세울 필요가 있다.", "eImp": "With a Nordic rival's large LNG dual-fuel order now contracted, car-carrier supply will grow further in 2029-2031, and alongside the group's own plan for more large LNG dual-fuel ships, industry-wide demand for IGF Code-trained seafarers able to handle LNG fuel will rise, so crew development should be planned early.", "url": "https://www.hoeghautoliners.com/news/hoegh-autoliners-china-merchants-aurora-class-contract", "prio": 2}, {"code": "NOR", "date": "2026-09-22", "src": "Norges Rederiforbund", "title": "노르웨이선주협회, 해사 규정·노동법 질의용 AI 법률 서비스 출시…시범 참여자 93% '좋음'", "eTitle": "Norwegian Shipowners' Association launches an AI legal service for maritime regulation and labour-law questions", "kSum": "노르웨이선주협회는 노르웨이 AI 기업 Lawai와 함께 개발한 회원용 AI 기반 법률 서비스를 9월 22일 출시했다. 단체협약, 노동법, 보건·안전·환경(HSE), 개인정보, 주요 해사 및 대륙붕 규정을 다루며 협회의 단체협약·법률지침과 노르웨이 법령·판례를 바탕으로 질의 응답과 문서 분석을 한다. 3개월 시범운영에서 참여자의 93%가 답변 품질을 '좋음' 이상으로 평가했고, 협회는 기존 변호사 법률지원을 대체하지 않는 보완 도구라고 밝혔다.", "eSum": "The Norwegian Shipowners' Association launched an AI-based legal member service on 22 September, developed with Norwegian AI company Lawai. It covers collective agreements, labour law, health, safety and environment, privacy and key maritime and continental-shelf regulations, drawing on the association's agreements and legal guidance plus Norwegian laws, regulations and case law to answer questions and analyse documents. In a three-month pilot, 93% of participants rated answer quality good or very good, and the association said the tool supplements rather than replaces its lawyers.", "kImp": "선주협회가 규정·HSE 질의를 AI로 지원하기 시작해 노르웨이 기국(NOR/NIS) 선박의 규정 해석과 선원 노무 관리에 AI 활용이 넓어질 것임을 보여준다. 다만 법적 책임 문제로 최종 판단에는 전문가 검토가 필요하다.", "eImp": "AI support for regulatory and HSE questions at association level signals wider AI use in rule interpretation and crew labour matters for Norwegian-flagged (NOR/NIS) ships, though legal accountability still requires expert review of final answers.", "url": "https://www.rederi.no/nyheter/norges-rederiforbund-lanserer-ki-verktoy-for-maritim-naring/", "prio": 1}, {"code": "NOR", "date": "2026-09-18", "src": "Norges Rederiforbund", "title": "노르웨이선주협회, 인도 선박재활용 야드 2곳의 EU 승인 목록 추가 지지", "eTitle": "Norwegian Shipowners' Association backs adding two Indian ship recycling yards to the EU approved list", "kSum": "노르웨이선주협회는 EU 집행위원회가 인도 선박재활용 시설 2곳을 EU 승인 시설 목록에 추가하자고 제안했으며, 9월 21일 회원국 환경부 대표들에게 상정된 뒤 서면 절차로 결정된다고 9월 18일 밝혔다. BIMCO·ICS·INTERCARGO·INTERTANKO·세계해운협의회(WSC) 등 8개 국제 해운단체가 EU 환경·교통장관들에게 지지 서한을 보냈고 협회도 이를 지지했다. 해당 야드 이름은 공개되지 않았다.", "eSum": "The Norwegian Shipowners' Association said on 18 September that the European Commission has proposed adding two Indian ship recycling facilities to the European list of approved yards, with the proposal going to member-state environment representatives on 21 September before a written-procedure decision. Eight international bodies including BIMCO, ICS, INTERCARGO, INTERTANKO and the World Shipping Council sent a supporting letter to EU environment and transport ministers, which the association endorsed. The yards were not named.", "kImp": "EU 기국 선박은 EU 승인 목록의 야드에서만 해체할 수 있어 목록이 넓어지면 노후선 해체 선택지와 매각 조건이 개선될 수 있다. 선령이 높은 자동차선 선대의 해체 계획과 유해물질목록(IHM) 관리에 직접 관련된다.", "eImp": "EU-flagged ships may only be recycled at yards on the EU list, so a wider list would broaden disposal options and could improve recycling terms, directly relevant to disposal planning and Inventory of Hazardous Materials upkeep for an ageing car-carrier fleet.", "url": "https://www.rederi.no/nyheter/rederiforbundet-stotter-eu-godkjenning-av-indiske-verft/", "prio": 1}, {"code": "NOR", "date": "2026-09-14", "src": "E24", "title": "파레토, 회그 오토라이너스 '매수' 상향(목표가 202크로네)…\"BAF 완전 반영·내년 계약 83% 확보\"", "eTitle": "Pareto upgrades Höegh Autoliners to buy with a NOK 202 target, citing full BAF effect and 83% contract cover for next year", "kSum": "E24에 따르면 파레토증권의 아우구스트 클렘프 애널리스트는 9월 14일 회그 오토라이너스를 '보유'에서 '매수'로 올리고 목표주가를 202크로네(직전 종가 대비 약 13% 상승여력)로 제시했으며(블룸버그 보도), 주가는 이날 2.45% 오른 183.8크로네를 기록했다. 그는 유류할증료(BAF)가 이제 완전히 반영되고, 선복이 동난 시장이 계약 갱신에 유리하며, 내년 물량의 83%가 계약으로 확보됐다는 점을 들어 추정치를 높였다. 회그 주가는 2분기 배당 실망 이후 WW보다 15%포인트 뒤처져 있었다.", "eSum": "Pareto Securities analyst August Klemp upgraded Höegh Autoliners from hold to buy on 14 September with a NOK 202 target, about 13% above the previous close, E24 reported citing Bloomberg, and the shares rose 2.45% to NOK 183.8. He cited the bunker adjustment factor now taking full effect, a sold-out market that favours contract renewals and 83% contract coverage for next year, and raised his estimates. Höegh had lagged Wallenius Wilhelmsen by 15 percentage points since its disappointing Q2 dividend.", "kImp": "애널리스트들이 '완판 시장에서의 계약 갱신'을 자동차선사 실적의 핵심 변수로 보고 있어, 높은 계약 커버리지를 가진 WW도 갱신 계약에 운임 인상분을 반영할 여지가 크다는 시장 판단으로 읽힌다.", "eImp": "Analysts see contract renewals in a sold-out market as the key earnings driver for car carriers, implying that WW, with high contract cover, also has room to lock higher rates into renewals.", "url": "https://e24.no/boers-og-finans/i/k0V17Q/oslo-boers-loeftes-av-oekt-oljepris", "prio": 1}, {"code": "NOR", "date": "2026-09-14", "src": "Placera (Finwire)", "title": "파레토증권, 왈레니우스 윌헬름센 목표주가 166→204 NOK로 상향하고 '매수' 반복 — 같은 날 회그 오토라이너스도 매수로 상향", "eTitle": "Pareto Securities Raises Its Wallenius Wilhelmsen Target Price to NOK 204 From 166 and Repeats Buy, the Same Day It Upgrades Hoegh Autoliners", "kSum": "9월 14일 06:11 스웨덴 뉴스통신 Finwire 속보(Placera 게재). 파레토증권이 WAWI 목표주가를 166 NOK에서 204 NOK로 올리고 '매수(köp)' 의견을 반복했다. 같은 날 파레토는 회그 오토라이너스를 매수로 상향(목표가 202 NOK)했으며, 이는 WalWil이 9월 24일 시장 업데이트(아시아발 선복 매진, 2027년 물량 40% 재협상)를 열기 열흘 전이다. 이후 Nordea가 10월 15일 200 NOK(매수), SEB가 11월 2일 178 NOK(보유)로 목표주가를 올렸다. 속보는 제목만 전해져 상향 근거는 공개되지 않았다.", "eSum": "A Finwire newswire flash carried by Placera at 06:11 on 14 September: Pareto Securities raised its target price for Wallenius Wilhelmsen to NOK 204 from NOK 166 and repeated its buy recommendation. The same day Pareto upgraded Hoegh Autoliners to buy with a NOK 202 target, ten days before WalWil's 24 September market update that reported Asia capacity sold out and 40% of 2027 volumes under renegotiation. Nordea followed with NOK 200 (buy) on 15 October and SEB with NOK 178 (hold) on 2 November. The flash carries the headline only, so Pareto's reasoning is not public.", "kImp": "3분기 실적을 앞두고 북유럽 증권사들의 목표주가가 178~204 NOK 범위에 모여 있어, 실적 발표 후 주가 반응은 2027년 운임 전망과 신조 자금 계획에 대한 시장의 신뢰를 보여주는 지표가 된다.", "eImp": "With Nordic brokers' targets clustered between NOK 178 and 204 ahead of the Q3 report, the share reaction after the results will serve as a gauge of market confidence in the 2027 rate outlook and the funding plan for the newbuild programme.", "url": "https://www.placera.se/telegram/wallenius-wilhelmsen-pareto-securities-hojer-riktkursen-for-wallenius-wilhelmsen-till-204-norska-kronor-166-upprepar-kop-20260914", "prio": 1}, {"code": "NOR", "date": "2026-09-11", "src": "Svensk Sjöfart", "title": "스웨덴 해사청, 2027년 항로 이용료 총액 동결 제안…선주협회는 환영하면서 환경 인센티브 투명성 요구", "eTitle": "Sweden's Maritime Administration Proposes Keeping Total Fairway Dues Flat for 2027, and the Swedish Shipowners' Association Welcomes It but Seeks More Transparency on the Environmental Incentive", "kSum": "스웨덴 선주협회(Svensk Sjöfart)는 9월 11일 의견서에서 스웨덴 해사청(Sjöfartsverket)이 2027년 항로 이용료(farledsavgift) 총액을 동결하는 안을 내놓은 것을 환영했다. 안에 따르면 항로료는 물가지수(KPI-KS, 약 1% 상승 추정)만큼 조정되는 대신 환경 인센티브 납부분이 1% 줄고, CSI(Clean Shipping Index) 등급 선박의 할인율은 유지되며, 변경은 2027년 1월 1일 시행될 예정이다. 협회는 항로료가 2019년 이후 41% 올랐다며 KPI-KS가 1%를 넘으면 그만큼 인센티브 납부를 줄여 총액을 유지해야 하고, 해사청이 2026년 이전 약 5,000만 크로나에서 2026년 말 약 1,000만 크로나로 줄 것으로 본 환경 인센티브 관련 부채의 산정 근거를 밝혀야 한다고 요구했다. 저가 화물 기준을 톤당 1,200크로나에서 1,550크로나로 올리는 안은 지지하되 더 자주 재검토하고, 쇄빙 비용은 정부 예산으로 충당할 것을 주문했다.", "eSum": "In a consultation response on 11 September, the Swedish Shipowners' Association (Svensk Sjöfart) welcomed the Swedish Maritime Administration's proposal to keep the total level of fairway dues unchanged for 2027. Under the proposal the fairway fee would rise with the KPI-KS index (estimated at about 1%) while payments into the environmental incentive fall by 1%, discount rates for CSI-classed ships stay the same, and the changes would take effect on 1 January 2027. The association noted that fairway dues have risen 41% since 2019, asked that incentive payments be cut by the same amount if KPI-KS exceeds 1% so the total stays flat, and sought a clearer account of an incentive-related debt the administration expects to fall from about SEK 50m before 2026 to about SEK 10m by the end of 2026. It supported raising the low-value cargo threshold from SEK 1,200 to SEK 1,550 per tonne with more frequent reviews, and said icebreaking should be funded from government appropriations.", "kImp": "예테보리 등 스웨덴 기항 선박의 2027년 항비 예산은 항로료 총액 보합을 전제로 잡을 수 있지만, 환경 성능 할인 구조가 그대로이므로 CSI 등급 유지·갱신 여부를 함께 확인할 필요가 있다.", "eImp": "Port-cost budgets for 2027 calls in Sweden, such as Gothenburg, can assume broadly flat fairway dues, but because the environmental discounts remain in place it is worth checking that CSI ratings are kept current.", "url": "https://www.sweship.se/farledsavgifterna-forblir-oforandrade-for-2027/", "prio": 1}, {"code": "NOR", "date": "2026-09-10", "src": "Höegh Autoliners (Oslo Børs)", "title": "회그 오토라이너스 8월 트레이딩 업데이트: 순운임 cbm당 80.7달러·물량 120만cbm…\"계절적 물량 감소에도 운임 견조\"", "eTitle": "Höegh Autoliners' August Trading Update Shows a USD 80.7 per cbm Net Rate on 1.2 Million cbm, With Rates Steady Through the Seasonal Volume Dip", "kSum": "노르웨이 자동차선사 회그 오토라이너스(Höegh Autoliners)가 9월 10일 오슬로증권거래소에 공시한 8월 트레이딩 업데이트에 따르면 8월 수송량(안분 기준)은 약 120만cbm, 6~8월 3개월 누계는 410만cbm이었다. 8월 총운임은 cbm당 97.8달러로 3개월 평균(96.6달러)보다 1.3% 높았고, 순운임은 80.7달러로 3개월 평균(80.6달러)보다 0.1% 높았으며, 고중량·브레이크벌크(HH/BB) 비중은 24%였다. 안드레아스 엥에르(Andreas Enger) CEO는 8월에 통상적인 계절적 물량 감소가 있었지만 운임은 안정적이었고, 화물·항로 구성에 따른 월별 변동 속에 강한 시장이 이어지고 있다고 말했다.", "eSum": "Höegh Autoliners' August trading update, filed on the Oslo Børs on 10 September, showed prorated volume of about 1.2 million cbm in August and 4.1 million cbm for June to August. The gross freight rate was USD 97.8 per cbm, 1.3% above the three-month average of USD 96.6, and the net rate USD 80.7 per cbm, 0.1% above the three-month average of USD 80.6, with high and heavy and breakbulk cargo at 24% of volume. CEO Andreas Enger said August showed the usual seasonal dip in volumes while rates held steady, describing a strong market with monthly variations driven by cargo and trade mix.", "kImp": "경쟁사의 순운임이 cbm당 80달러 선에서 안정적으로 유지돼 자동차선 시장의 높은 운임 수준이 3분기에도 이어졌음을 보여준다. 11월 4일 WW 3분기 실적을 읽을 때 참고할 업계 지표다.", "eImp": "A competitor's net rate holding steady around USD 80 per cbm shows car carrier freight rates stayed high into the third quarter, a useful industry benchmark when reading WW's Q3 results on 4 November.", "url": "https://newsweb.oslobors.no/message/681931", "prio": 1}, {"code": "NOR", "date": "2026-09-02", "src": "Sjöfartstidningen", "title": "월레니우스, 폭스바겐 장기용선선 '웨이 포워드'에 오션버드 윙세일 2기 장착…2027년 설치", "eTitle": "Wallenius to fit two Oceanbird wing sails on the Volkswagen-chartered car carrier Way Forward in 2027", "kSum": "스웨덴 해운지 Sjöfartstidningen에 따르면 월레니우스 라인스가 소유하고 월레니우스 마린이 운항하는 자동차선 '웨이 포워드(Way Forward)'에 오션버드 윙세일 2기가 2027년 설치된다. 이 선박은 폭스바겐그룹에 장기용선 중인 2024년 11월 인도선(퓨처 웨이 자매선)으로, 바이오연료를 포함한 액체·기체 연료를 쓰는 이중연료 추진에 이미 IMO CII A등급을 받았다. 6월 21~24일 로테르담 다멘조선소에서 티라나(Tirranna)에 첫 실물 크기 윙560 시제품을 설치한 데 이은 첫 상업 적용이며, 요한 마트손 월레니우스 마린 CEO는 풍력추진이 해운의 미래에 중요한 역할을 할 것이라고 말했다.", "eSum": "Two Oceanbird wing sails will be installed in 2027 on the car carrier Way Forward, owned by Wallenius Lines and operated by Wallenius Marine on long-term charter to the Volkswagen Group, Sweden's Sjöfartstidningen reported. Delivered in November 2024 as a sister to Future Way, the ship has dual-fuel propulsion able to burn liquid and gaseous fuels including biofuels and already holds an IMO CII A rating. It is the first commercial application after the full-scale Wing560 prototype was fitted on Tirranna at Damen in Rotterdam on 21-24 June, and Wallenius Marine CEO Johan Mattsson said wind propulsion will play an important role in shipping's future.", "kImp": "윙세일이 시험선(티라나)에서 화주 전용 상업선으로 넘어가면서 세일 운용, 항내 접이 운용, 복원성 관리 등 풍력 보조추진선의 운항 절차와 선원 교육이 실무 과제가 된다. 화주(폭스바겐)의 탈탄소 요구가 기술 도입을 이끄는 구조다.", "eImp": "Wing sails are moving from a trial ship to a customer-dedicated commercial vessel, making operating procedures (sail handling, folding in port, stability) and crew training for wind-assisted ships a practical issue, with the shipper's (Volkswagen) decarbonisation demands driving adoption.", "url": "https://www.sjofartstidningen.se/nyheter/haer-aer-naesta-fartyg-som-far-oceanbirds-vingsegel/323160", "prio": 2}, {"code": "NOR", "date": "2026-09-01", "src": "Höegh Autoliners", "title": "회그 오토라이너스, 전 선대 38척에 GPS 교란 대응 항법장비 'PntGuard' 탑재…9월부터 설치", "eTitle": "Höegh Autoliners Equips All 38 Ships With SGM Technology's PntGuard Navigation-Resilience System Against GPS Jamming and Spoofing, Starting in September", "kSum": "회그 오토라이너스는 9월 1일 노르웨이 SGM테크놀로지와 5년 계약을 맺고 현 선대 38척과 계약기간 중 인도되는 신조선 전부에 GPS 재밍·스푸핑 대응 장비 'PntGuard'를 설치한다고 밝혔다. 이 장비는 GPS 신호가 교란될 때 독립적인 위치 정보를 제공하고 간섭이 감지되면 브리지에 경보를 주며, 항적을 독립적으로 검증·기록해 항해 검증과 규정 준수에 활용된다. 설치는 9월부터 시작됐으며, 세브요른 달(Sebjørn Dahl) COO는 GPS 재밍·스푸핑이 주요 항로 전반에서 점점 커지는 문제라고 말했다.", "eSum": "Höegh Autoliners said on 1 September it has signed a five-year contract with Norway's SGM Technology to fit its PntGuard system on its current 38-ship fleet and on newbuildings that enter service during the contract, with installation starting in September. PntGuard provides an independent position source when GPS is disrupted, alerts bridge teams when interference is detected and keeps an independently verified record of each ship's route for voyage verification and compliance. COO Sebjørn Dahl said GPS jamming and spoofing have become a growing challenge across major shipping routes.", "kImp": "GNSS 교란이 여러 해역에서 일상화한 만큼, 관리선도 ECDIS·레이더·자이로 위치 교차 확인, 교란 감지 시 보고·기록 절차와 선원 훈련을 점검하고 독립 위치확인 장비 도입을 검토할 필요가 있다.", "eImp": "With GNSS interference now routine in several regions, managed ships should review cross-checking of ECDIS, radar and gyro positions, reporting and logging of interference and crew training, and consider an independent positioning aid.", "url": "https://www.hoeghautoliners.com/news/hoegh-autoliners-to-equip-entire-fleet-with-new-navigation-resilience-technology", "prio": 1}, {"code": "NOR", "date": "2026-08-28", "src": "Göteborgs Hamn", "title": "예테보리항 상반기 신차 처리 17% 증가한 14만4천대…4분의 3이 수출", "eTitle": "Port of Gothenburg's new-vehicle volumes rise 17% to 144,000 in the first half, three-quarters of them exports", "kSum": "예테보리항은 2026년 상반기 신차 처리량이 14만4,000대로 전년 동기(12만4,000대)보다 17% 늘었고 이 중 약 4분의 3이 수출이었다고 8월 28일 발표했다. 증가는 유럽 역내외 항로 모두에서 나타났으며 로로 유닛은 2% 늘어난 27만8,000개, 컨테이너는 46만2,000TEU로 보합이었다. 항만 발표에는 언급이 없지만 이 항만의 차량·로로 터미널(GIART)은 Wallenius Wilhelmsen이 별도 법인을 통해 2026년 2월 2일부터 12년 계약으로 운영하고 있으며, 2025년 연간 신차 처리량은 25만1,000대였다.", "eSum": "The Port of Gothenburg said on 28 August that new-vehicle volumes rose 17% year on year to 144,000 in the first half of 2026, from 124,000, with about three-quarters exports and growth both within and beyond Europe. Ro-ro units rose 2% to 278,000 and containers were flat at 462,000 TEU. The release does not mention it, but the port's vehicle and ro-ro terminal (GIART) has been run by Wallenius Wilhelmsen through a separate company under a 12-year contract since 2 February 2026, and the port handled 251,000 new vehicles in 2025.", "kImp": "WW가 운영권을 넘겨받은 첫해 상반기에 차량 물동량이 두 자릿수로 늘어 터미널 사업과 북유럽 수출 화물 확보에 긍정적이다. 기항이 늘수록 터미널과 선박 간 램프 운용·고박 등 하역 안전 협업이 중요해진다.", "eImp": "Double-digit vehicle growth in WW's first half-year as terminal operator supports the terminal business and Nordic export cargo, and more calls make terminal-ship coordination on ramp operations and lashing safety more important.", "url": "https://www.mynewsdesk.com/goteborgs_hamn/pressreleases/surge-in-container-volumes-on-direct-services-between-the-port-of-gothenburg-and-asia-3463085", "prio": 1}, {"code": "NOR", "date": "2026-08-26", "src": "Sjøfartsdirektoratet", "title": "노르웨이, EU 집행위의 MRV·FuelEU 개정안 의견수렴…9월 22일 마감", "eTitle": "Norway consults on the European Commission's proposed MRV and FuelEU Maritime amendments, deadline 22 September", "kSum": "노르웨이 해사청은 EU 집행위원회가 7월 17일 제안한 MRV 규정(EU 2015/757)과 FuelEU 해운 규정(EU 2023/1805) 개정안에 대해 노르웨이 환경청이 기후환경부를 대신해 의견수렴을 시작했다고 8월 26일 밝혔다. 개정 목적은 선사 등 관련 주체의 이행 부담을 덜기 위한 것이며, 의견은 9월 22일까지 받았다.", "eSum": "The Norwegian Maritime Authority said on 26 August that the Norwegian Environment Agency, on behalf of the climate ministry, opened a consultation on the European Commission's 17 July proposal to amend the MRV Regulation (EU) 2015/757 and the FuelEU Maritime Regulation (EU) 2023/1805. The stated aim is to make compliance easier for shipping companies and other affected parties, with comments due by 22 September.", "kImp": "EU가 MRV·FuelEU 간소화에 착수해 배출 모니터링 계획과 검증 절차가 바뀔 수 있으므로 선박별 MRV 보고 체계와 FuelEU 준수 관리 절차의 개정 여부를 추적해야 한다.", "eImp": "With the EU moving to simplify MRV and FuelEU, monitoring plans and verification steps may change, so ship-level MRV reporting and FuelEU compliance procedures should be tracked for revisions.", "url": "https://www.sdir.no/nyheter/horing-om-mrv--og-fueleu-endringer/", "prio": 1}, {"code": "NOR", "date": "2026-08-25", "src": "Höegh Autoliners", "title": "회그 오토라이너스, 오로라급 LNG 이중연료선 6척 추가 발주…옵션 포함 최대 26척 가능", "eTitle": "Höegh Autoliners orders six more Aurora-class LNG dual-fuel car carriers, with options taking the programme to as many as 26 ships", "kSum": "노르웨이 경쟁사 회그 오토라이너스가 중국 CMHI(장쑤)에 오로라급 LNG 이중연료·무탄소 대비(DNV 암모니아·메탄올 레디) 선박 6척을 추가 발주해 신조 프로그램이 18척으로 늘었다고 8월 25일 공시했다. 척당 최대 9,100대를 싣고 2029~2031년 인도되며, 같은 조건의 옵션 4척(6개월 내 행사)과 4척 슬롯 예약(2027년 말까지 통보)을 더하면 최대 26척이 된다. 정식 계약은 9월 22일 나폴리에서 먀오젠민 차오상쥐(China Merchants)그룹 회장, 레이프 O. 회그 이사회 의장, 안드레아스 엥에르 CEO가 서명했으며 계약가는 공개되지 않았다. 엥에르 CEO는 2026~2028년 노르웨이선주협회 회장도 맡고 있다.", "eSum": "Norwegian rival Höegh Autoliners ordered six more Aurora-class LNG dual-fuel, zero-carbon-ready vessels with DNV ammonia- and methanol-ready notations from China Merchants Heavy Industry (Jiangsu), lifting its newbuilding programme to 18, it announced on 25 August. Each can carry up to 9,100 cars, with delivery in 2029-2031, and an option for four more on the same terms plus slot reservations for four further vessels could take the programme to 26. The contract was formally signed in Naples on 22 September by China Merchants Group chairman Miao Jianmin, Höegh chair Leif O. Høegh and CEO Andreas Enger, who is also president of the Norwegian Shipowners' Association for 2026-2028; no price was disclosed.", "kImp": "WW가 10월 밝힌 LNG 이중연료 신조 계획(옵션 포함 최대 26척)과 비슷한 규모여서 2029~2032년 대형 자동차선 공급이 두 노르웨이 선사를 중심으로 늘어난다. 중국 조선소 슬롯 경쟁과 LNG 추진선 운항 인력 수요가 함께 커질 전망이다.", "eImp": "The plan mirrors WW's October LNG dual-fuel programme of up to 26 ships including options, so large car-carrier supply in 2029-2032 will grow mainly through the two Norwegian operators, intensifying competition for Chinese yard slots and for crews qualified on LNG-fuelled ships.", "url": "https://www.hoeghautoliners.com/investors/ir-news/h-egh-autoliners-asa-h-egh-autoliners-orders-six-additional-aurora-class-vessels-680744", "prio": 2}, {"code": "NOR", "date": "2026-08-20", "src": "E24", "title": "경쟁사 회그 오토라이너스, 2분기 이익 감소·배당 대폭 삭감에 주가 11.9% 급락", "eTitle": "Rival Höegh Autoliners slumps 11.9% after lower Q2 earnings and a sharp dividend cut", "kSum": "E24에 따르면 회그 오토라이너스의 2분기 EBITDA는 1억2,200만 달러(전년 1억6,600만 달러, 예상 1억2,000만 달러), 세전이익은 8,500만 달러(전년 1억2,400만 달러)였다. 2분기 배당은 주당 0.0839달러(총 1,600만 달러)로 1분기 9,400만 달러, 2025년 4분기 9,900만 달러에서 급감했다. 회사는 중동 분쟁 이후 연료비 상승과 유류할증료(BAF) 회수까지의 5~6개월 시차가 2분기를 압박했다며 3분기 EBITDA도 2분기 수준으로 예상했고, 주가는 이날 11.86% 떨어졌다(발표 전 연초 대비 96% 상승, WW는 64%). 안드레아스 엥에르 CEO는 로로 해운 수요가 강하고 늘고 있다고 강조했다.", "eSum": "Höegh Autoliners posted Q2 EBITDA of USD 122m (USD 166m a year earlier, USD 120m expected) and pre-tax profit of USD 85m (USD 124m), E24 reported. The Q2 dividend fell to USD 0.0839 per share or USD 16m in total, from USD 94m in Q1 and USD 99m in Q4 2025. The company blamed higher fuel costs after the Middle East conflict and a five-to-six-month lag before bunker surcharge compensation, guided Q3 EBITDA in line with Q2, and its shares fell 11.86% on the day after a 96% year-to-date gain (WW: 64%), while CEO Andreas Enger stressed strong and growing roro demand.", "kImp": "유류할증료 회수 시차가 경쟁사 실적을 크게 깎은 만큼 연료비 급등기에는 운임 수준보다 연료 계약·BAF 조항이 수익을 좌우한다. 그룹 선대의 연료 효율 운항(감속·트림 최적화)과 벙커 품질 관리의 비용 효과가 커진다.", "eImp": "The surcharge lag that hit a direct competitor shows that fuel clauses and BAF mechanics, not headline rates, drive earnings in a fuel spike, raising the value of fuel-efficient operation (speed and trim optimisation) and bunker quality control across the group fleet.", "url": "https://e24.no/boers-og-finans/i/ExKPPA/resultatfall-for-hoegh-autoliners-reduserer-utbyttet", "prio": 2}, {"code": "NOR", "date": "2026-08-13", "src": "Sjøfartsdirektoratet", "title": "노르웨이 해사청, 무관용(Nullvisjon) 목표에 맞춰 선원·어업인 기본안전교육 과정 평가 착수 — TÜV Rheinland Safetec에 위탁", "eTitle": "Norwegian Maritime Authority Commissions TÜV Rheinland Safetec to Evaluate Basic Safety Training for Seafarers and Fishers in Line With Its Vision Zero Goals", "kSum": "노르웨이 해사청(Sjøfartsdirektoratet)은 선원·어업인 기본안전교육의 교과 과정을 개선하기 위해 TÜV Rheinland Safetec에 평가를 맡겼다. 해사청은 향후 STCW-F 개정으로 어업인 안전과정 갱신이 필요할 가능성이 크다고 밝혔고, 교육을 이수한 현직 선원·어업인을 대상으로 약 60분의 익명 Teams 인터뷰 참여자를 모집했다. 평가 일정과 완료 시점은 공개되지 않았다.", "eSum": "The Norwegian Maritime Authority has commissioned TUV Rheinland Safetec to evaluate the course plans for basic safety training for seafarers and fishers, in dialogue with industry and in support of its Vision Zero safety goals. It says upcoming STCW-F changes will likely require the fishers' safety course to be updated, and it sought serving seafarers and fishers for anonymous 60-minute Teams interviews. No timeline for the evaluation or resulting changes was given.", "kImp": "노르웨이 기국 선박의 안전교육 요건이 바뀔 수 있으므로, 노르웨이 기국 선원 교육 이력 관리에 향후 개정 내용을 반영할 필요가 있다.", "eImp": "Safety-training requirements for Norwegian-flag crews may change, so crew training records for Norwegian-flag ships should be checked against any revision.", "url": "https://www.sdir.no/nyheter/sikkerhetsopplaring-evalueres-i-trad-med-nullvisjonen/", "prio": 1}, {"code": "NOR", "date": "2026-08-12", "src": "Norges Rederiforbund", "title": "윌헬름센 쉽 매니지먼트, 노르웨이 '올해의 해사 수습교육 기업 2025' 선정", "eTitle": "Wilhelmsen Ship Management named Norway's Maritime Training Company of the Year 2025", "kSum": "노르웨이 해사역량재단(SNMK)은 바이킹 오션 크루즈 13척의 선원 관리를 맡고 있는 윌헬름센 쉽 매니지먼트(WSM)를 '올해의 해사 수습교육 기업(Årets Maritime Lærebedrift) 2025'로 선정했다. 시상은 노르웨이선주협회·NHO 해운이 아렌달 주간(Arendalsuka)에 연 행사에서 마리안네 시베르트센 내스 수산해양부 장관이 했으며, 라세 크바르스네스 한센 WSM 글로벌 해상인사 총괄이 받았다. 선정 이유로 선대 규모 대비 수습 자리 수, 체계적 교육계획과 정기 평가, 고급사관 멘토링, 경력의 날·학교 방문 등 채용 활동, 약 40개국 선원이 함께하는 다양성이 꼽혔다.", "eSum": "The Norwegian Maritime Competence Foundation (SNMK) named Wilhelmsen Ship Management, which crews Viking Ocean Cruises' 13 ships, Maritime Training Company of the Year 2025. Fisheries and Ocean Minister Marianne Sivertsen Næss presented the award at an Arendalsuka event organised by the Norwegian Shipowners' Association and NHO Sjøfart, and Global Head of Marine HR Lasse Kvarsnes Hansen accepted it. The board cited training positions relative to fleet size, structured training plans and assessments, senior officers acting as mentors, career-day and school outreach, and diversity, with crews from about 40 nationalities.", "kImp": "그룹 선박관리 부문의 수습·사관 양성 체계가 노르웨이 업계에서 공인받은 사례로, 사관 부족 속에서 멘토링과 구조화된 교육계획 중심의 육성 모델을 그룹 내 다른 거점의 교육 체계와 비교하는 기준으로 삼을 수 있다.", "eImp": "The award is industry recognition of the group ship-management arm's cadet and apprentice pipeline, offering a benchmark, built on mentoring and structured training plans, for officer development elsewhere in the group amid officer shortages.", "url": "https://www.rederi.no/nyheter/wilhelmsen-ship-management-karet-til-arets-maritime-larebedrift-2025/", "prio": 2}, {"code": "NOR", "date": "2026-08-11", "src": "E24", "title": "크리스토페르센 WW CEO \"사실상 완판…아시아 화주 우선순위 조정 불가피\"—노르디아, 목표가 164크로네로 상향", "eTitle": "WW CEO Kristoffersen says ships are effectively sold out, forcing tough customer prioritisation out of Asia, as Nordea lifts its target to NOK 164", "kSum": "E24는 Wallenius Wilhelmsen 2분기 실적(매출 13억1천만 달러로 예상치 13억3천만 달러 소폭 하회, 조정 EBITDA 3억6,100만 달러로 예상 3억4,200만 달러 상회, 세전이익 1억5,100만 달러로 예상 1억3,800만 달러 상회)을 전하며 라세 크리스토페르센 CEO가 \"사실상 완판돼 아시아발 화주 우선순위를 힘들게 정해야 한다\"고 말했다고 보도했다. 중동 전쟁에 따른 연료비 상승이 실적을 눌렀지만 아시아 수요로 선대는 완전 가동 중이며, 상반기 배당은 주당 0.61달러(약 24억5천만 크로네)다. 노르디아의 손드레 스네르스루드 애널리스트는 중국 수출 증가가 해상 자동차 운송을 근본적으로 바꿔 사상 최대 신조 발주분을 흡수하고 있고 선박 수익이 연초 대비 약 90% 올랐다고 평가했으며, 8월에 목표주가를 130크로네에서 164크로네로 올리고 매수를 유지했다. 주가는 연초 대비 WW가 57%, 경쟁사 회그가 90% 올랐다.", "eSum": "Reporting Wallenius Wilhelmsen's Q2 (revenue USD 1.31bn, slightly below the USD 1.33bn expected; adjusted EBITDA USD 361m against USD 342m expected; pre-tax profit USD 151m against USD 138m), E24 quoted CEO Lasse Kristoffersen as saying the company is effectively sold out and must make tough customer prioritisations out of Asia. Higher fuel costs from the Middle East war weighed on earnings, but Asian demand kept the fleet fully utilised, and the H1 dividend is USD 0.61 per share, about NOK 2.45bn. Nordea analyst Sondre Snersrud said China's export growth has fundamentally changed seaborne car shipping and absorbed record newbuild orders, with vessel earnings up nearly 90% year to date, and in August raised his target to NOK 164 from NOK 130 with a buy rating. WW shares were up 57% year to date and rival Höegh's 90%.", "kImp": "경영진이 직접 '완판·화주 선별'을 언급한 만큼 아시아 항로의 고가동과 빠듯한 기항 일정이 이어질 가능성이 크고, 이는 선원 피로 관리와 정비 시간 확보 등 운항 안전 부담으로 이어진다. 시장은 강한 운임이 신조 공급 증가를 흡수한다고 보고 있다.", "eImp": "With management openly citing a sold-out fleet and customer triage, high utilisation and tight port schedules on Asian trades are likely to persist, adding pressure on crew fatigue management and maintenance windows; analysts see firm rates absorbing new supply.", "url": "https://e24.no/boers-og-finans/i/L4alPq/resultatfall-for-wallenius-wilhelmsen-deler-ut-2-45-milliarder-kroner-i-utbytte", "prio": 2}, {"code": "NOR", "date": "2026-08-11", "src": "Höegh Autoliners (Oslo Børs)", "title": "회그 오토라이너스 7월 업데이트: 순운임 cbm당 80.6달러·물량 140만cbm…\"선복 완전 가동, 유류할증료 상승분 운임 반영 시작\"", "eTitle": "Höegh Autoliners' July Trading Update Shows 1.4 Million cbm at a USD 80.6 per cbm Net Rate, With Capacity Fully Used and Rising Fuel Surcharges Starting to Lift Gross Rates", "kSum": "회그 오토라이너스가 8월 11일 오슬로증권거래소에 공시한 7월 트레이딩 업데이트에 따르면 7월 수송량(안분 기준)은 약 140만cbm, 5~7월 누계는 410만cbm이었다. 7월 총운임은 cbm당 99.3달러로 3개월 평균(96.6달러)보다 2.8% 높았고, 순운임은 80.6달러로 3개월 평균(79.6달러)보다 1.2% 높았으며, HH/BB 비중은 24%였다. 엥에르 CEO는 선복을 완전히 가동하며 물량 흐름이 양호했고 오르는 유류할증료가 총운임에 반영되기 시작해 분기 말부터 전면 반영된다고 말했다. 회사는 고객에게 재청구할 에너지 비용 상승과 'MEG(중동 걸프) 분쟁'에 따른 일회성 화물 우회 관련 매출채권 증가로 단기 운전자본이 늘었다고 밝혔다.", "eSum": "Höegh Autoliners' July trading update, filed on the Oslo Børs on 11 August, showed prorated volume of about 1.4 million cbm in July and 4.1 million cbm for May to July. The gross rate was USD 99.3 per cbm, 2.8% above the three-month average of USD 96.6, and the net rate USD 80.6, 1.2% above the three-month average of USD 79.6, with high and heavy and breakbulk at 24% of volume. CEO Andreas Enger said capacity was fully utilised and that rising fuel surcharges were starting to show in gross rates, with full effect from quarter-end. Working capital was temporarily elevated by higher energy costs that will be recharged to customers and by receivables from one-off cargo rerouting linked to the MEG conflict.", "kImp": "중동 분쟁에 따른 화물 우회와 연료비 상승이 자동차선사의 운전자본과 할증료 구조에 어떻게 반영되는지 보여준다. 연료비 전가 시차는 자동차선 운항사 공통의 수익 변수다.", "eImp": "It shows how Middle East-related rerouting and higher fuel costs fed into a car carrier's working capital and surcharges; the lag in passing fuel costs on to customers is a profit driver common to all car carrier operators.", "url": "https://newsweb.oslobors.no/message/679373", "prio": 1}, {"code": "NOR", "date": "2026-08-10", "src": "Sjøfartsdirektoratet", "title": "FuelEU 해운 규정의 노르웨이 적용, 빨라야 2028년으로 재연기…노르웨이 항만은 당분간 '제3국' 취급", "eTitle": "FuelEU Maritime's entry into Norway and the EEA delayed to 2028 at the earliest, with Norwegian ports treated as third-country ports meanwhile", "kSum": "노르웨이 해사청은 기후환경부 발표에 따라 FuelEU 해운 규정(EU 2023/1805)의 EEA·노르웨이 편입이 빨라야 2028년 1월 1일로 늦춰졌다고 8월 10일 밝혔다. 그때까지 노르웨이 항만은 FuelEU상 제3국 항만으로 취급돼 노르웨이–EU 항만 간 항해 에너지는 절반만 계산되고 노르웨이 국내 및 비EU 구간은 제외된다. EU 항만을 운항하는 5,000GT 이상 화물·여객선의 노르웨이 선주는 이미 규정 적용 대상으로 각 EU 회원국에 배정돼 있다. 노르웨이선주협회 크누트 아릴 하레이데 CEO는 11일 지연 이유에 대한 명확한 설명이 없다며 EU 기후 규정과의 연계 약화와 EU 지원제도 접근 불확실성을 우려했다.", "eSum": "The Norwegian Maritime Authority said on 10 August that incorporation of the FuelEU Maritime Regulation (EU) 2023/1805 into the EEA Agreement and Norway will come on 1 January 2028 at the earliest. Until then Norwegian ports count as third-country ports, so only half the energy used on voyages between Norway and EU ports counts and domestic or non-EU legs are excluded, while Norwegian owners of cargo and passenger ships above 5,000 GT trading to EU ports are already covered and assigned to EU member states. Norwegian Shipowners' Association CEO Knut Arild Hareide said on 11 August the delay lacks a clear explanation and could weaken Norwegian owners' link to EU climate rules and support schemes.", "kImp": "노르웨이 기항이 많은 선박은 FuelEU 산정 범위가 EU 항만 위주로 달라지므로 기항 패턴별 준수량과 풀링 계획을 다시 점검해야 한다. 노르웨이 선주사별 FuelEU 행정 담당국(EU 회원국) 배정도 확인할 필요가 있다.", "eImp": "Ships calling Norway see their FuelEU scope shift toward EU ports, so compliance balances and pooling plans should be rechecked by trading pattern, along with which EU member state administers each Norwegian shipowner.", "url": "https://www.sdir.no/nyheter/utsetter-drivstoffkrav-for-luftfarten-og-maritim-transport/", "prio": 2}, {"code": "NOR", "date": "2026-08-05", "src": "Sjøfartsdirektoratet", "title": "파리·도쿄 MOU, 9~11월 '화물 고박' 집중점검(CIC) 공동 시행…노르웨이 해사청 안내", "eTitle": "Paris and Tokyo MoUs to run a joint concentrated inspection campaign on cargo securing from September to November", "kSum": "노르웨이 해사청은 파리 MOU와 도쿄 MOU가 9월 1일부터 11월 30일까지 화물 적재·고박에 관한 집중점검(CIC)을 공동 시행한다고 8월 5일 안내했다. 점검관은 공통 질문서로 화물유닛·화물운송유닛의 적재·적부·고박이 현행 SOLAS 요건에 맞는지 확인하며, 캠페인 기간 MOU별로 선박당 1회만 점검한다. 결함은 기록되고 정도에 따라 출항정지까지 이어질 수 있으며, 결과는 양 MOU 위원회에 보고된 뒤 IMO 논의에 활용된다.", "eSum": "The Norwegian Maritime Authority said on 5 August that the Paris and Tokyo MoUs will run a joint Concentrated Inspection Campaign on cargo securing from 1 September to 30 November. Inspectors will use a common questionnaire to check that loading, stowage and securing of cargo units and cargo transport units comply with current SOLAS requirements, inspecting each ship once per MoU during the campaign. Deficiencies will be recorded and can lead to detention, and the results will go to both MoU committees and feed into further IMO work.", "kImp": "차량·중장비를 싣는 자동차선은 고박 장비, 화물고박매뉴얼(CSM), 차량 고박 기록이 직접 점검 대상이 되므로 캠페인 기간 입항 전 고박 상태 점검과 선원 브리핑이 필요하다. 11월 말까지 아시아·유럽 기항이 잦은 선대의 PSC 결함 위험이 높아질 수 있다.", "eImp": "Car carriers are directly exposed because lashing gear, the Cargo Securing Manual and vehicle lashing records will be checked, so pre-arrival lashing checks and crew briefings are needed; PSC deficiency risk rises until end-November for fleets calling Asian and European ports.", "url": "https://www.sdir.no/nyheter/lasteskip-under-den-internasjonale-lupen/", "prio": 2}, {"code": "NOR", "date": "2026-07-10", "src": "E24", "title": "회그 오토라이너스, 아시아 완성차와 운송계약 2029년 12월까지 연장…약 3억 달러, 샤오모항 추가", "eTitle": "Höegh Autoliners extends an Asian carmaker contract to December 2029, worth about USD 300m and adding Xiaomo port", "kSum": "E24에 따르면 오슬로 상장 경쟁사 회그 오토라이너스가 이름을 밝히지 않은 대형 아시아 자동차 제조사와의 운송계약을 2029년 12월까지 연장했다. 개정 조건은 올해 5월 1일부터 적용되며, 예상 물량 기준 연장 기간 매출은 약 3억 달러로 추산된다. 계약으로 샤오모(Xiaomo)항이 회그의 아시아 서비스에 추가되며, 회사는 앞으로 1억 달러 이상 계약을 공시하겠다고 밝혔다. 안드레아스 엥에르 CEO는 수주잔고를 쌓으려는 노력의 일환이라고 말했다.", "eSum": "Oslo-listed rival Höegh Autoliners extended a contract with an unnamed major Asian carmaker to December 2029, E24 reported. Revised terms apply from 1 May this year, and the extension could add about USD 300m in revenue based on expected volumes. The deal adds the port of Xiaomo to Höegh's Asian service, the company said it will disclose future contracts worth more than USD 100m, and CEO Andreas Enger said the extension reflects efforts to build its order backlog.", "kImp": "아시아(중국) 화주들이 2029년까지 선복을 선점하는 장기계약 경쟁이 이어지고 있어 그룹의 아시아 선복 배분과 계약 갱신 협상에도 영향을 준다. 신규 기항지 추가는 선원의 항만 정보 숙지와 기항 준비 부담으로 이어진다.", "eImp": "Asian, particularly Chinese, shippers are locking in tonnage through 2029, which shapes the group's own Asian capacity allocation and renewal talks, while new port calls such as Xiaomo add port-familiarisation work for crews.", "url": "https://e24.no/bors/nyheter/a/304991?pinnedEntry=304991", "prio": 1}, {"code": "NOR", "date": "2026-07-09", "src": "Sjøfartsdirektoratet", "title": "노르웨이 해사청 ‘상반기 상업용 선박 사고 420건, 28% 증가’…사망 3명·인명사고 214건, 화재·폭발 43%·접촉사고 75% 늘어", "eTitle": "Norwegian Maritime Authority Reports 420 Accidents on Commercial Vessels in H1 2026, Up 28%, With Three Deaths, 214 Personal Injuries and Sharp Rises in Fires and Contact Damage", "kSum": "노르웨이 해사청은 7월 9일 2026년 상반기 노르웨이 상업용 선박(næringsfartøy, 어선 포함)에서 사고 420건과 준사고 191건이 등록됐고 사고 건수는 전년 동기보다 28% 늘었다고 밝혔다. 사망은 2건의 사고에서 3명으로 전년 동기보다 1명 많았으며, 1명은 벙커링을 기다리며 표류하던 화물선에서 바다에 빠졌고 2명은 어선 전복·침몰로 숨졌다. 선박 6척이 사고로 상실되고 6척이 중대 손상을 입었으며, 유형별로는 좌초가 37% 줄어든 반면 접촉사고 75%, 오염·배출 62%, 화재·폭발 43%가 각각 늘었고, 인명사고는 214건으로 전년 동기(169건)보다 많았으며 선내 추락·넘어짐과 충격·끼임이 가장 많았다. 증가는 특히 여객선과 화물선에 집중됐고, 알프 토레 쇠르하임 해사청장은 모든 사망사고는 한 건도 많다며 사망사고 제로(Nullvisjonen) 목표를 강조했다.", "eSum": "Norway's Maritime Authority said on 9 July that 420 accidents and 191 near-accidents were registered on Norwegian commercial vessels, including fishing vessels, in the first half of 2026, with the number of accidents up 28% on the same period of 2025. Three people died in two fatal accidents, one more than a year earlier: one person fell overboard from a cargo ship drifting while waiting for bunkering, and two died when a fishing vessel capsized and sank. Six vessels were lost and six seriously damaged; groundings fell 37%, while contact damage rose 75%, pollution and discharges 62% and fires and explosions 43%, and personal injuries rose to 214 from 169, with falls on board and impact or crush injuries the largest categories. The increase is mainly linked to passenger ships and cargo ships, and Maritime Director Alf Tore Sørheim said every fatal accident is one too many, underlining the zero-fatality vision.", "kImp": "벙커링 대기 중 표류 상태에서의 해상 추락 사망, 화재·폭발과 접촉사고 급증은 대기·표류 중 갑판 작업 통제, 접·이안 시 속력·예선 관리, 기관실 화재 예방 점검의 중요성을 보여주며 연말 안전 캠페인 소재로 활용할 만하다.", "eImp": "A fatal fall overboard while drifting to await bunkering and sharp rises in fires, explosions and contact damage underline the need to control deck work while drifting or waiting, manage speed and tugs during berthing and unberthing, and check engine-room fire prevention, and the figures suit a year-end safety campaign.", "url": "https://www.sdir.no/nyheter/tre-omkom-pa-naringsfartoy-i-forste-halvar/", "prio": 1}, {"code": "NOR", "date": "2026-07-02", "src": "Sjøfartsdirektoratet", "title": "노르웨이, 파리 MOU 화이트리스트 3위 유지…스웨덴은 12위→2위로 급등", "eTitle": "Norway keeps third place on the Paris MoU White List as Sweden jumps from 12th to 2nd", "kSum": "노르웨이 해사청은 7월 1일부터 적용되는 파리 MOU 화이트리스트(2025년 연례보고서 기반, 최근 3년 점검·출항정지 실적)에서 노르웨이가 3위를 유지했다고 밝혔다. 1~2위는 케이맨제도와 스웨덴, 4~5위는 덴마크와 일본이며, 노르웨이는 도쿄 MOU 고성과(High Performance) 등급과 미국 해안경비대 Qualship 21 자격도 유지했다. 스웨덴 선주협회(Svensk Sjöfart)는 8월 20일 스웨덴이 12위에서 2위로 올랐다고 별도 발표했다.", "eSum": "The Norwegian Maritime Authority said Norway kept third place on the Paris MoU White List that applies from 1 July, based on three years of inspection and detention data in the 2025 annual report. The Cayman Islands and Sweden rank ahead, with Denmark and Japan fourth and fifth, and Norway also stays in the Tokyo MoU High Performance category and the US Coast Guard Qualship 21 programme. The Swedish Shipowners' Association said separately on 20 August that Sweden climbed from 12th to 2nd.", "kImp": "노르웨이(NIS)·스웨덴 기국 선박은 PSC 선박위험도 산정에서 저위험 기국 요소를 인정받아 점검 빈도와 강도가 낮아질 수 있다. 다만 개별 선박의 결함·출항정지 이력도 함께 반영되므로 선내 PSC 대비 수준은 그대로 유지해야 한다.", "eImp": "Ships under the Norwegian (NIS) and Swedish flags get a low-risk flag factor in PSC ship risk profiles, which can mean fewer and lighter inspections, but individual deficiency and detention records still count, so onboard PSC readiness must be maintained.", "url": "https://www.sdir.no/nyheter/norge-holder-tredjeplassen-pa-paris-mous-white-list/", "prio": 2}, {"code": "NOR", "date": "2026-07-02", "src": "UECC", "title": "왈레니우스 라인스·NYK 합작 UECC, 7월 1일 해운에 확대된 영국 ETS 비용 2026년엔 할증료 없이 자체 부담", "eTitle": "UECC, Co-Owned by Wallenius Lines and NYK, Will Absorb UK ETS Costs in 2026 Rather Than Charge a Surcharge as the Scheme Extends to Shipping From 1 July", "kSum": "왈레니우스 라인스와 NYK가 공동 소유한 오슬로 소재 자동차·로로선사 UECC는 7월 2일 영국 배출권거래제(UK ETS)가 7월 1일부터 해운에 적용됐다고 밝혔다. 대상은 5,000GT 이상 화물선·여객선이며, 영국 국내 항해와 영국 항만 정박 중 배출량의 100%가 포함되고 대상 가스는 EU ETS와 같이 CO2·메탄·아산화질소다. 영국 항만에 정기 기항하는 UECC는 2016년 세계 최초의 LNG 이중연료 PCTC(Auto Eco·Auto Energy)를 도입하는 등 저배출 선박·대체연료에 먼저 투자한 덕분에 2026년에는 UK ETS 비용을 할증료로 청구하지 않고 자체 부담한다고 했다. 2026년 할증료 표에서 EU ETS는 적용, FuelEU Maritime과 UK ETS는 미적용으로 표시됐다.", "eSum": "UECC, the Oslo-based car carrier and ro-ro operator jointly owned by Wallenius Lines and NYK, said on 2 July that the UK Emissions Trading Scheme has covered shipping since 1 July 2026. The scheme applies to cargo and passenger ships of 5,000 GT and above and covers 100% of emissions on domestic UK voyages and at berth in UK ports, including CO2, methane and nitrous oxide in line with the EU ETS. UECC, which calls regularly at UK ports, said it will not charge a UK ETS surcharge in 2026 and will absorb the cost, citing earlier investment in low-emission ships and alternative fuels, including the world's first LNG dual-fuel PCTCs, Auto Eco and Auto Energy, in 2016. Its 2026 surcharge table lists EU ETS as applied and FuelEU Maritime and UK ETS as not applied.", "kImp": "영국 항만에 기항하는 5,000GT 이상 그룹 선박은 7월부터 정박 중 배출까지 UK ETS 대상이 되므로, EU MRV·ETS와 별도로 영국 기항 구간의 연료·배출 데이터 수집 방식과 보고 책임 주체를 운항사와 확인해 둘 필요가 있다.", "eImp": "Group ships of 5,000 GT and above calling at UK ports now have their at-berth emissions covered by the UK ETS, so fuel and emissions data collection for UK calls, separate from EU MRV and ETS, and the party responsible for reporting should be confirmed with the operator.", "url": "https://uecc.com/news/uk-ets-regulatory-approach/", "prio": 1}, {"code": "NOR", "date": "2026-04-13", "src": "Wallenius Lines", "title": "왈레니우스 라인스, SOL그룹 지분 인수로 발트해 로로선사 ‘왈레니우스 SOL’ 단독 소유…5월 당국 승인", "eTitle": "Wallenius Lines Buys SOL Group's Shares to Become Sole Owner of Baltic Ro-Ro Operator Wallenius SOL, With Regulatory Approval in May", "kSum": "왈레니우스 윌헬름센의 대주주인 스웨덴 왈레니우스 라인스는 4월 13일 SOL그룹이 보유한 왈레니우스 SOL 지분을 인수해 단독 소유주가 된다고 발표했으며, 거래는 스웨덴 경쟁청과 전략물자감독청(ISP)의 승인을 조건으로 했다. 왈레니우스 라인스는 5월 20일 관계 당국의 승인을 받았다고 밝혔고, 운항·전략 방향·서비스와 경영진·조직은 그대로 유지하며 장기계획 ‘Blueprint 2030’을 이어간다고 했다. 왈레니우스 SOL은 보트니아만·발트해·북해에서 스웨덴·핀란드 북부와 유럽 대륙, 영국을 잇는 로로 서비스를 운영하며, 지분 비율과 인수 금액은 공개되지 않았다. 에리크 뇌클레뷔에 왈레니우스 라인스 CEO는 단독 소유로 왈레니우스 SOL의 발전을 전체적인 관점에서 추진할 수 있게 됐다고 말했다.", "eSum": "Sweden's Wallenius Lines, a major shareholder in Wallenius Wilhelmsen, announced on 13 April that it would buy SOL Group's shares in Wallenius SOL and become its sole owner, subject to approval by the Swedish Competition Authority and the Inspectorate of Strategic Products (ISP). On 20 May Wallenius Lines said the relevant authorities had approved the deal, and that operations, strategic direction, offering, management and organisation would stay unchanged under the long-term Blueprint 2030 plan. Wallenius SOL runs ro-ro services in the Gulf of Bothnia, the Baltic and the North Sea, linking northern Sweden and Finland with the Continent and the British Isles; stake sizes and the price were not disclosed. Wallenius Lines CEO Erik Nøklebye said sole ownership allows a holistic approach to the company's continued development.", "kImp": "단독 소유 이후 왈레니우스 SOL이 바겐보르그 내빙 로로선 2척 인수, 홀멘 장기계약용 선박 투입 등 발트해 선대를 넓히고 있어, 내빙 로로선의 겨울철 결빙 해역 운항과 FuelEU 대응 등 북유럽 단거리 로로 운영 동향을 함께 지켜볼 만하다.", "eImp": "Since becoming sole owner, Wallenius SOL has been growing its Baltic fleet, buying Wagenborg's two ice-class ro-ros and adding a ship for a long-term Holmen contract, so its winter ice operations and FuelEU approach are worth following as a guide to Nordic short-sea ro-ro practice.", "url": "https://walleniuslines.com/current-topics/news/2026-04-13-wallenius-lines-becomes-sole-owner-of-wallenius-sol", "prio": 2}, {"code": "NOR", "date": "2026-03-04", "src": "Sjöfartstidningen", "title": "월레니우스 라인스·NYK 합작 UECC, 진링서 3,000CEU급 PCTC 2척 추가 발주…2028년 초 인도", "eTitle": "UECC, co-owned by Wallenius Lines and NYK, orders two 3,000 CEU PCTCs at China Merchants Jinling for early-2028 delivery", "kSum": "스웨덴 해운지 Sjöfartstidningen에 따르면 오슬로 기반 UECC(월레니우스 라인스·NYK 합작)가 3월 2일 중국 China Merchants Jinling(난징) 조선소와 3,000CEU급 PCTC 2척 건조계약을 맺었다. LNG 이중연료·배터리 하이브리드 추진에 육상전원, 발라스트 최소화 설계, 9개 차량갑판, 160톤 선미램프(길이 169.5m)를 갖추며 2028년 초 인도 예정이다. 앞서 발주한 4,500CEU급 2척(2028년 인도)과 합쳐 같은 조선소에서 4척이 건조되며, 인도 후 UECC는 LNG·이중연료 배터리 하이브리드선 9척을 보유하게 된다.", "eSum": "Oslo-based UECC, jointly owned by Wallenius Lines and NYK, signed on 2 March for two 3,000 CEU PCTCs at China Merchants Jinling Shipyard in Nanjing, Sweden's Sjöfartstidningen reported. The LNG dual-fuel battery-hybrid ships feature shore power, a largely ballast-free design, nine car decks and a 160-tonne stern ramp on a 169.5 m hull, with delivery planned for early 2028. Together with two 4,500 CEU units already ordered for 2028, UECC will have four newbuilds at the yard and nine LNG or dual-fuel battery-hybrid vessels once they are delivered.", "kImp": "유럽 단거리 자동차선에서도 LNG·배터리 하이브리드 신조가 확산돼 EU ETS·FuelEU 대응 연료 전략과 고중량 화물 대응 선형이 업계 표준이 되는 흐름을 보여준다. 월레니우스 계열 선대의 중국 조선소 의존도도 함께 높아지고 있다.", "eImp": "LNG and battery-hybrid newbuilds are spreading into European short-sea car carrying, showing EU ETS and FuelEU-driven fuel strategies and heavy-cargo-capable designs becoming the norm, while the Wallenius sphere relies increasingly on Chinese yards.", "url": "https://www.sjofartstidningen.se/uecc-lagger-order-pa-tva-biltransportfartyg/", "prio": 1}]}, {"code": "WIL", "kTitle": "윌헬름센 그룹", "eTitle": "Wilhelmsen Group", "items": [{"code": "WIL", "date": "2026-11-09", "src": "Wilh. Wilhelmsen Holding (Oslo Børs)", "title": "윌헬름센 홀딩, 자사주 최대 22만 주 역경매 방식 공개매수 개시 — 11/10 마감", "eTitle": "Wilh. Wilhelmsen Holding Launches a Reverse Book-Building Tender Offer to Buy Back Up to 220,000 A and B Shares, Closing on 10 November", "kSum": "Wilh. Wilhelmsen Holding이 11월 9일 09:00 CET부터 10일 16:30 CET까지 주주들의 매도 희망 수량·가격을 받는 역경매(reverse book building) 방식으로 A·B주 합계 최대 220,000주를 매입한다고 공시했다(내부자 정보). 최종 가격은 11월 10일께 정하며 거래일은 11일, 결제일은 13일께다. 매입 주식은 소각하거나 임직원 주식제도에 쓰며, 기존 배당 가이던스에는 영향이 없다고 밝혔다. 발행주식은 4,235만 주, 보유 자사주는 853,103주(A 663,078·B 190,025)이고 Clarksons Securities가 단독 주관한다.", "eSum": "Wilh. Wilhelmsen Holding said it will buy back up to 220,000 A and B shares through a reverse book-building tender, taking sell offers from 09:00 CET on 9 November to 16:30 CET on 10 November. The price will be set on or about 10 November, with trade on about 11 November and settlement on about 13 November. The shares will be cancelled or used for the employee share programme, and the company says the buyback does not affect its dividend guidance. It has 42.35 million shares in issue and holds 853,103 treasury shares, and Clarksons Securities is sole bookrunner.", "kImp": "3분기 실적·추가배당에 이은 주주환원 조치로 그룹 지주사의 현금 여력을 보여준다. 선박관리 사업 자체에 미치는 직접 영향은 없다.", "eImp": "A further shareholder-return step after the Q3 results and extra dividend, showing the group parent's cash headroom. It has no direct effect on the ship management business.", "url": "https://newsweb.oslobors.no/message/685963", "prio": 2}, {"code": "WIL", "date": "2026-11-04", "src": "Wilh. Wilhelmsen Holding (Oslo Børs)", "title": "윌헬름센 홀딩 3분기: EBITDA 6,100만 달러(전년비 +47%)·순이익 1.54억 달러, 선박관리 매출 4,000만 달러로 '관리 선대 안정'", "eTitle": "Wilh. Wilhelmsen Holding Q3 2026: EBITDA Up 47% to USD 61m and Net Profit of USD 154m, With Ship Management Income of USD 40m From a Stable Managed Fleet", "kSum": "윌헬름센 홀딩의 3분기 총수입은 3.27억 달러(전년비 +5%), EBITDA 6,100만 달러(+47%), 지배주주 순이익 1.54억 달러(주당 3.70달러)다. 해사서비스 부문은 수입 2.38억 달러(+7%)·EBITDA 4,000만 달러(+69%, 마진 17%)로, Ships Service 1.45억 달러(+7%, 가격 인상·물량 증가), Port Services 5,100만 달러(+16%, 화물작업·husbandry 호조), Ship Management 4,000만 달러(전년비 -4%, 전분기비 +3%; '관리 선대 안정, 기초 실적 안정')였고 영업권 손상 800만 달러가 있었다. 뉴에너지(NorSea) 수입 8,800만 달러·EBITDA 2,400만 달러, 전략지분 이익 1.26억 달러(왈레니우스 윌헬름센 지분이익 7,200만 달러, 현대글로비스 5,100만 달러)이며 Qube 지분은 9,200만 달러에 매각됐다. 현금 3.7억 달러·순현금 3.52억 달러·자기자본비율 76%이고, 2차 배당 주당 8.50크로네를 11월 19일 지급한다(배당락 11/11).", "eSum": "Wilh. Wilhelmsen Holding reported Q3 total income of USD 327m (+5% y/y), EBITDA of USD 61m (+47%) and net profit to equity holders of USD 154m (EPS USD 3.70). Maritime Services earned USD 238m (+7%) with EBITDA of USD 40m (+69%, 17% margin): Ships Service USD 145m (+7%, price increases and volumes), Port Services USD 51m (+16%, cargo operations and husbandry) and Ship Management USD 40m (-4% y/y, +3% q/q, with a stable fleet under management), after a USD 8m goodwill impairment. New Energy (NorSea) earned USD 88m with USD 24m EBITDA, and Strategic Holdings contributed USD 126m, including USD 72m from Wallenius Wilhelmsen and USD 51m from Hyundai Glovis, while the Qube stake was sold for USD 92m. Cash stood at USD 370m, net cash at USD 352m and the equity ratio at 76%; a second dividend of NOK 8.50 per share is paid on 19 November (ex-date 11 November).", "kImp": "그룹 선박관리 부문 매출이 전년보다 줄고 '관리 선대 안정'으로 표현돼 성장 목표 대비 신규 수주가 아직 수치로 나타나지 않았다. 지주사는 해사서비스 수요가 연말까지 안정적이라고 보면서도 중동 상황, 입항료, 자동차선 선대 증가를 전략지분의 부담 요인으로 꼽았다.", "eImp": "The group ship-management unit's income fell year on year with a 'stable' managed fleet, so its growth ambition is not yet visible in the numbers. The holding company expects stable Maritime Services demand for the rest of 2026 but flags the Middle East, port fees and car-carrier fleet growth as headwinds for its strategic holdings.", "url": "https://newsweb.oslobors.no/message/685632", "prio": 3}, {"code": "WIL", "date": "2026-11-04", "src": "Skipsrevyen", "title": "윌헬름센 계열 NorSea, Vår Energi와 옵션 포함 12년 물류·기지 계약 및 장기 부지 계약 갱신", "eTitle": "Wilhelmsen's NorSea Renews Its Vår Energi Logistics and Base Contract for Up to 12 Years Including Options, Plus a Long-Term Property Deal at Dusavik and Hammerfest", "kSum": "윌헬름센이 99.7% 보유한 NorSea가 Vår Energi와 옵션 포함 12년짜리 통합 물류·기지 서비스 계약을 맺었다; 노르웨이 대륙붕의 Vår Energi 자체 운영 포트폴리오를 Dusavik(스타방에르)·Hammerfest 기지에서 지원하며 부두·터미널, 보관·자재관리, 해상 조정 업무를 포함한다. 별도 장기 부지 계약으로 Dusavik와 Hammerfest Polarbase의 기지·창고·야적장을 활동량에 맞춰 조정해 쓸 수 있다. 계약 금액은 공개되지 않았고, May Britt Lilletvedt NorSea Logistics CEO는 '분명한 신뢰의 표시'라고 말했다.", "eSum": "NorSea, 99.7% owned by Wilhelmsen, signed a 12-year integrated logistics and base-services contract including options with Vår Energi, covering its self-operated Norwegian shelf portfolio from the Dusavik (Stavanger) and Hammerfest bases, including quay and terminal services, storage, materials handling and offshore coordination. A separate long-term property agreement gives Vår Energi flexible base, storage and outdoor areas at Dusavik and Polarbase in Hammerfest. The value was not disclosed; NorSea Logistics CEO May Britt Lilletvedt called the renewal a clear vote of confidence.", "kImp": "윌헬름센 뉴에너지 부문(NorSea)의 장기 매출 기반이 강화돼 그룹의 해운 외 수익 다변화가 이어진다.", "eImp": "The deal secures long-term revenue for Wilhelmsen's New Energy segment, supporting the group's earnings outside shipping.", "url": "https://www.skipsrevyen.no/norsea-var-energi/inngar-12arig-avtale-med-var-energi/2205828", "prio": 2}, {"code": "WIL", "date": "2026-11-04", "src": "Wilh. Wilhelmsen Holding (Oslo Børs)", "title": "윌헬름센 홀딩, 주당 8.50크로네 추가 현금배당 결정…11월 19일 지급", "eTitle": "Wilh. Wilhelmsen Holding Approves an Additional Cash Dividend of NOK 8.50 per Share, Payable on 19 November", "kSum": "윌헬름센 홀딩 이사회가 4월 30일 정기주총의 수권에 따라 주당 8.50크로네의 추가 현금배당을 11월 4일 승인했다. 권리 포함 마지막 거래일은 11월 10일, 배당락일 11월 11일, 기준일 11월 12일, 지급일은 11월 19일이다. 3분기 실적과 같은 날 공시됐다.", "eSum": "Wilh. Wilhelmsen Holding's board approved an additional cash dividend of NOK 8.50 per share on 4 November, under the authority granted by the 30 April AGM. The last day including the right is 10 November, the ex-date 11 November, the record date 12 November and payment 19 November. It was announced alongside the Q3 results.", "kImp": "그룹 지주사가 자동차선 호황에 따른 현금흐름을 주주환원에 쓰고 있다는 신호로, 그룹 서비스 사업의 투자 여력과 함께 지켜볼 지표다.", "eImp": "It signals the group holding company is passing car-carrier cash flow on to shareholders, a measure to watch alongside its capacity to invest in group service businesses.", "url": "https://newsweb.oslobors.no/message/685633", "prio": 1}, {"code": "WIL", "date": "2026-10-30", "src": "Wilhelmsen", "title": "윌헬름센 쉽스서비스, 화기작업 안전 캠페인 'AimZero'로 SAFETY4SEA 이니셔티브상…ShipTek '해양 서비스 우수상'까지 2관왕", "eTitle": "Wilhelmsen Ships Service Wins SAFETY4SEA's Initiative Award for Its AimZero Hot-Work Safety Campaign and ShipTek's Excellence in Marine Services Award", "kSum": "윌헬름센 쉽스서비스(WSS)는 10월 30일 두 개의 업계 상을 받았다고 발표했다. 아테네에서 열린 SAFETY4SEA 시상식에서 화기작업(hot work) 안전 캠페인 'AimZero'로 'SAFETY4SEA Initiative Award 2026'을 받았는데, 이 캠페인은 점검·교육·더 안전한 장비·안전문화 강화를 통해 사고 대응을 사후에서 사전 예방으로 바꿔 '해상 화기작업 무재해(Zero Harm)'를 이루는 것을 목표로 한다. 두바이에서 열린 ShipTek Awards 2026에서는 인력·전문성·서비스와 선박용 제품·솔루션에 대한 고객·파트너의 신뢰를 인정받아 '해양 서비스 우수상(Excellence in Marine Services Award)'을 받았다. 앞서 윌헬름센 포트서비스도 ShipTek International Awards 2026에서 올해의 선박대리점상을 받았다.", "eSum": "Wilhelmsen Ships Service said on 30 October it has received two industry awards. At the SAFETY4SEA awards in Athens it won the SAFETY4SEA Initiative Award 2026 for AimZero, a hot-work safety campaign that aims for zero harm from hot work at sea by moving from reactive to proactive incident prevention through inspections, training, safer equipment and a stronger safety culture. At the ShipTek Awards 2026 in Dubai it received the Excellence in Marine Services Award, recognising customer and partner trust in its people, expertise, services and marine products and solutions. Sister company Wilhelmsen Port Services had earlier been named Ship Agency of the Year at the ShipTek International Awards 2026.", "kImp": "화기작업은 선상 화재·폭발의 대표적 원인으로, 그룹 서비스사가 점검·교육·장비를 묶은 예방형 캠페인을 운영하고 있다는 점은 선박관리사가 화기작업 허가(PTW)·화재감시·장비 관리 절차를 점검할 때 참고가 된다. 캠페인 자료나 교육 지원을 활용하는 방안도 검토할 만하다.", "eImp": "Hot work is a leading cause of shipboard fires and explosions, and a group service company running a prevention campaign that bundles inspections, training and equipment is a useful reference for ship managers reviewing hot-work permits, fire watches and equipment control. Drawing on the campaign's material or training support may also be worth considering.", "url": "https://www.wilhelmsen.com/media-news-and-events/news/2026/two-industry-awards-recognise-wilhelmsen-ships-service/", "prio": 1}, {"code": "WIL", "date": "2026-10-07", "src": "Wilhelmsen", "title": "Wilhelmsen Port Services, ShipTek 2026 '올해의 선박대리점' 수상", "eTitle": "Wilhelmsen Port Services Named Ship Agency of the Year at the ShipTek International Awards 2026", "kSum": "Wilhelmsen Port Services(WPS)가 10월 6일 싱가포르에서 열린 ShipTek International Awards 2026에서 '올해의 선박대리점(Ship Agency of the Year)'으로 선정됐다. 회사는 운영 성과·컴플라이언스·디지털화 노력이 인정받은 결과라고 밝혔다. WPS는 2,200개 항만에서 연간 10만 건 이상의 기항을 처리하며 대리점·허즈번더리·크루즈·운하 통항 지원 서비스를 제공한다.", "eSum": "Wilhelmsen Port Services (WPS) was named Ship Agency of the Year at the ShipTek International Awards 2026 in Singapore on 6 October. The company said the award recognises its work on operational performance, compliance and digitalisation. WPS handles more than 100,000 port calls a year across 2,200 ports, offering ship agency, husbandry, cruise and canal transit support services.", "kImp": "그룹 대리점 네트워크의 서비스 품질이 외부 평가를 받은 것으로, 기항지 대리점 선정과 항만국 검사 대응 협업 시 참고할 만하다.", "eImp": "The award signals strong service quality in the group's agency network, a useful reference when selecting port agents and coordinating port-call and inspection support.", "url": "https://www.wilhelmsen.com/media-news-and-events/news/2026/wilhelmsen-port-services-named-ship-agency-of-the-year/", "prio": 1}, {"code": "WIL", "date": "2026-10-06", "src": "Wilh. Wilhelmsen Holding (Oslo Børs)", "title": "윌. 윌헬름센 홀딩, 왈레니우스 윌헬름센 3억 달러 사모 발행에 지분비율(37.9%) 청약 사전 약정 — 최종 배정은 신주의 17%(285만 주)로 축소돼 지분 소폭 희석", "eTitle": "Wilh. Wilhelmsen Holding Pre-Commits to Its 37.9% Pro-Rata Share of Wallenius Wilhelmsen's USD 300m Private Placement but Is Allocated 2.85 Million Shares, 17% of the New Shares, Slightly Diluting Its Stake", "kSum": "10월 6일 윌. 윌헬름센 홀딩(WWI) 공시(내부정보). WAWI 최대주주인 WWI는 같은 날 발표된 3억 달러 규모 사모 발행에 보유 지분 비율 37.9%만큼 최종 발행가로 청약하기로 사전 약정했으며, 유동성·투자자 다변화·수요의 질을 위해 배정이 축소될 수 있음을 밝혔다. 또 DNB Carnegie와 주식대여 계약을 맺어 배정 주식에서 자기 지분비율분을 뺀 수량을 대여, 신주 등기 전 DVP 결제를 지원한다. 같은 날 밤 WAWI의 완료 공시에 따르면 신주 1,714만5,000주가 주당 168 NOK에 발행됐고 WWI 배정은 285만 주(신주의 17%)로 지분비율보다 적어 WWI의 WAWI 지분은 소폭 희석된다. 조달 자금은 차입과 함께 LNG 이중연료 4+8척을 포함해 최대 26척(인도 2026년 3분기~2032년)의 신조 프로그램 전액을 충당하며, 불참 주주 대상 후속 공모는 하지 않기로 했다. 등기 후 WAWI 주식 수는 4억4,024만9,938주다.", "eSum": "In a 6 October inside-information filing, Wilh. Wilhelmsen Holding (WWI), Wallenius Wilhelmsen's largest shareholder, said it had pre-committed to subscribe for its 37.9% pro-rata share of WAWI's USD 300m private placement at the final offer price, while accepting a possible scale-back to support liquidity, investor diversity and quality of demand, and that it had entered a share lending agreement with DNB Carnegie to facilitate delivery-versus-payment settlement before the capital increase is registered. WAWI's completion notice the same night showed 17,145,000 new shares issued at NOK 168, with WWI allocated 2,850,000 shares, 17% of the new shares, below its pro-rata entitlement and thus slightly diluting its stake. Together with debt, the proceeds fully fund the newbuild programme of up to 26 vessels delivering from Q3 2026 to 2032, including the four plus eight LNG dual-fuel ships, and no subsequent offering will be held for shareholders who did not participate. WAWI's share count after registration is 440,249,938.", "kImp": "윌헬름센 그룹이 최대주주 지위는 유지하면서도 신조 자금의 상당 부분을 외부 투자자에게 열어준 구조로, 왈레니우스 라인스의 불참과 함께 WalWil 주주 구성이 조금 더 분산됐다. 그룹 선박관리 계열에는 26척 신조 프로그램의 자금 조달이 확정됐다는 점이 2027~2032년 관리 선대 전망의 기반이 된다.", "eImp": "The Wilhelmsen group keeps its position as largest shareholder while opening a large part of the newbuild funding to outside investors, and together with Wallenius Lines sitting out, WalWil's ownership becomes slightly more dispersed. For the group's ship-management arms, the fully funded 26-vessel programme anchors the outlook for the managed fleet from 2027 to 2032.", "url": "https://newsweb.oslobors.no/message/683651", "prio": 2}, {"code": "WIL", "date": "2026-10-05", "src": "Splash247", "title": "케냐 반다리 해양아카데미, Wilhelmsen Ship Management에 실습생 승선 슬롯 확대 요청", "eTitle": "Kenya's Bandari Maritime Academy Asks Wilhelmsen Ship Management for More Sea-Time Slots and a Role in Cadet Selection", "kSum": "케냐 Bandari Maritime Academy가 Wilhelmsen Ship Management(WSM)와 케냐 선원 훈련·고용 확대를 논의하며 승선실습 슬롯 증원과 실습생 선발·면접 참여 확대를 요청했다. 아카데미는 승선 경력이 교육과 자격 취득 사이의 주요 장벽이라고 밝혔다. WSM은 실습생 프로그램으로 승선 경험을 제공하고 우수자를 채용해 왔으며, 탱커·벌커·컨테이너선·가스선·자동차선 관리선대에 케냐 실습생·부원·사관을 배치한 바 있다.", "eSum": "Kenya's Bandari Maritime Academy is discussing expanded training and employment of Kenyan seafarers with Wilhelmsen Ship Management (WSM), asking for more sea-time slots and a bigger role in selecting and interviewing cadets. The academy says practical sea experience is one of the main barriers between training and certification. WSM already offers onboard experience through its cadetship programme, hires successful trainees, and has placed Kenyan cadets, ratings and officers across a managed fleet of tankers, bulkers, containerships, gas carriers and car carriers.", "kImp": "선원 공급원 다변화(아프리카 인력) 논의로, 실습생 승선 확대 시 선상 교육 담당·멘토링 체계와 실습 슬롯 배분 계획이 필요하다.", "eImp": "The talks point to diversifying crew supply towards African seafarers; expanding cadet berths would require onboard training officers, mentoring structures and planned allocation of cadet slots.", "url": "https://splash247.com/kenyan-academy-eyes-more-wilhelmsen-sea-time-slots/", "prio": 1}, {"code": "WIL", "date": "2026-09-15", "src": "Wilhelmsen", "title": "Wilhelmsen Port Services·싱가포르 MPA, 항만기항 디지털화 'On-Job Study' 프로그램 시작", "eTitle": "Wilhelmsen Port Services and Singapore's MPA Launch an On-Job Study Programme to Advance Port-Call Digitalisation", "kSum": "Wilhelmsen Port Services(WPS)와 싱가포르 해사항만청(MPA)이 8월 27일 양측 간 첫 체계적 'On-Job Study' 프로그램을 시작했다. MPA 직원들이 WPS 담당자와 함께 풀 에이전시·화물작업·허즈번더리 업무를 현장에서 관찰하며 기항 관리 방식, 운영 플랫폼 활용, 이해관계자 간 상호작용을 파악한다. 목표는 AI·디지털 도구·페이퍼리스 솔루션으로 효율·안전·정보 흐름을 개선할 기회를 찾는 것이다.", "eSum": "Wilhelmsen Port Services (WPS) and the Maritime and Port Authority of Singapore (MPA) launched their first structured On-Job Study programme on 27 August. MPA officers join WPS staff to observe full agency, cargo operations and husbandry work first-hand, learning how port calls are managed, how operational platforms are used and how agencies interact with ecosystem partners. The aim is to find where AI, digital tools and paperless solutions could improve efficiency, safety and information flow.", "kImp": "싱가포르 기항 절차의 디지털화(전자 서류·데이터 연계)가 빨라질 수 있어, 선박 측 기항 서류·보고의 전자화 대응 준비가 필요하다.", "eImp": "Port-call digitalisation in Singapore may accelerate, so ships should be ready for paperless documentation and data exchange when calling there.", "url": "https://www.wilhelmsen.com/media-news-and-events/news/2026/wilhelmsen-port-services-and-the-maritime-and-port-authority-of-singapore-launch-on-job-study-programme-to-advance-maritime-digitalisation/", "prio": 1}, {"code": "WIL", "date": "2026-09-14", "src": "Japan Maritime Daily", "title": "윌헬름센 쉽 매니지먼트, 신조~해체 '선박 생애주기' 관리체계 구축…관리 선대 약 320척에서 2~3년 내 450척 목표", "eTitle": "Wilhelmsen Ship Management Builds a Newbuilding-to-Recycling Lifecycle Service and Aims to Grow From About 320 to 450 Managed Ships Within Two to Three Years", "kSum": "일본해사신문(JMD)은 9월 14일자 1면에서 윌헬름센 쉽 매니지먼트(WSM)가 신조부터 해체까지 선박 생애주기 전반의 관리 서비스 체계를 구축하고 있으며, 신조·개조·재활용 프로젝트 관리를 맡는 자회사와 IT 자회사를 세워 기능을 강화했다고 보도했다. 복잡해지는 규제 대응 등 선주 수요를 흡수하겠다는 구상으로, 현재 약 320척인 관리 선대를 2~3년 안에 450척으로 늘리는 것이 목표다. WSM은 하콘 렌츠(Haakon Lenz) CEO의 방일에 맞춰 9월 11일 도쿄에서 최근 사업 진척, 미래 연료 안전운항, 선원 배승 현황을 설명하는 기자회견을 연다고 8월 24일 보도자료로 알렸다. 해사프레스(Kaiji Press)가 10월 6일 실은 렌츠 CEO 인터뷰에 따르면 WSM은 장래 선원 부족에 대비해 지난해 4월 케냐에 배승 거점을 열어 아프리카에 새 거점을 마련했고, 전 세계 12곳에 매닝센터를 두고 있으며 현재 케냐 선원은 약 50명이다.", "eSum": "Japan Maritime Daily reported on its front page on 14 September that Wilhelmsen Ship Management (WSM) is building a management service covering a ship's whole lifecycle from newbuilding to scrapping, having set up a subsidiary for newbuilding, conversion and recycling project management and an IT subsidiary to strengthen its capabilities. The aim is to capture shipowner demand as regulation grows more complex, and WSM wants to grow its managed fleet from about 320 ships today to 450 within two to three years. WSM had announced in a 24 August press release a Tokyo press conference on 11 September, timed to CEO Haakon Lenz's visit to Japan, covering recent business progress, safe operation with future fuels and the state of crew deployment. In an interview published by Kaiji Press on 6 October, Lenz said WSM opened a crewing base in Kenya in April last year, giving it a new base in Africa, to prepare for future seafarer shortages; WSM runs 12 manning centres worldwide and currently employs about 50 Kenyan seafarers.", "kImp": "그룹 선박관리 조직이 신조 감독·개조·재활용을 아우르는 생애주기 서비스와 선대 확대를 추진하는 만큼, 신조 인수·대형 개조·선박 재활용 단계의 표준 절차를 그룹 서비스와 연계해 정비하고 케냐 등 신규 배승 거점 선원의 승선 전 교육·적응 프로그램을 준비할 필요가 있다.", "eImp": "As the group's ship management arm builds lifecycle services from newbuilding supervision to conversion and recycling while expanding its fleet, standard procedures for newbuild acceptance, major conversions and recycling should be aligned with these group services, and pre-joining training and onboarding for seafarers from new crewing bases such as Kenya should be prepared.", "url": "https://www.jmd.co.jp/apl/article.php?no=318644", "prio": 2}, {"code": "WIL", "date": "2026-09-14", "src": "Wilh. Wilhelmsen Holding (Oslo Børs)", "title": "윌헬름센 홀딩, 직원 주식 프로그램으로 자사주 A주 11,964주를 주당 NOK 824.61에 이전 완료", "eTitle": "Wilh. Wilhelmsen Holding Completes the Transfer of 11,964 Treasury A Shares to Employees at NOK 824.61 Under Its Employee Share Programme", "kSum": "Wilh. Wilhelmsen Holding은 9월 14일 직원 주식 프로그램에 따라 보유 자사주 중 WWI A주 11,964주를 주당 NOK 824.6075에 직원들에게 이전했다고 공시했다(프로그램 공지는 9월 10일). 이전 후 자사주 잔량은 A주 663,078주, B주 190,025주다.", "eSum": "Wilh. Wilhelmsen Holding said it completed the transfer of 11,964 of its own WWI class A shares to employees on 14 September at NOK 824.6075 per share under its employee share programme, first announced on 10 September. After the transfer it holds 663,078 A shares and 190,025 B shares in treasury.", "kImp": "그룹 지주사가 직원 지분 참여를 매년 이어가는 흐름으로, 11월 역북빌딩 자사주 매입과 함께 자본 정책의 연속성을 보여준다.", "eImp": "The annual employee share scheme, alongside the November reverse book-building buy-back, shows a consistent capital policy at the group holding company.", "url": "https://newsweb.oslobors.no/message/682287", "prio": 1}, {"code": "WIL", "date": "2026-09-13", "src": "Wilhelmsen", "title": "Wilhelmsen Ships Service, 선박 냉매 관리 '3단계 실무 접근법' 제시…저GWP 전환·누설 관리", "eTitle": "Wilhelmsen Ships Service Sets Out a Three-Step Practical Approach to Responsible Refrigeration on Ships", "kSum": "Wilhelmsen Ships Service(WSS)는 키갈리 개정의정서, 개정 EU F-가스 규정, 미국 AIM법으로 고GWP 냉매 규제가 강화되고 있다며 선박용 '책임 있는 냉매 관리' 3단계(저GWP 냉매 채택, 누설 최소화·회수, 효율·추적성 개선)를 제시했다. 냉매 누설은 직접 Scope 1 배출이며 밀폐구역에서 공기를 밀어내 선원 안전을 위협할 수 있다고 지적했다. 정기 전자식 누설점검, UV 추적, 정비·폐기 전 회수, 공급부터 반납까지의 기록 관리를 권고했다.", "eSum": "Wilhelmsen Ships Service (WSS) set out a three-step approach to responsible refrigeration on ships (adopting lower-GWP refrigerants, minimising leaks and recovering gas, and improving efficiency and traceability) as the Kigali Amendment, the revised EU F-Gas Regulation and the US AIM Act tighten controls on high-GWP refrigerants. It notes that refrigerant leaks are direct Scope 1 emissions and can displace air in confined spaces, endangering crew. It recommends routine electronic leak checks, UV tracing, recovery before maintenance or disposal, and documentation from supply through return.", "kImp": "냉동·공조 설비의 냉매 누설 점검과 기록은 배출 보고와 밀폐구역 안전 모두에 걸리는 HSEQ 항목으로, 정비 절차와 냉매 기록 관리 점검에 활용할 수 있다.", "eImp": "Refrigerant leak checks and record-keeping touch both emissions reporting and enclosed-space safety, making them a useful HSEQ checkpoint for maintenance routines and refrigerant records.", "url": "https://www.wilhelmsen.com/ships-service/refrigeration-solutions/responsible-refrigeration-a-practical-approach-for-ships/", "prio": 1}, {"code": "WIL", "date": "2026-08-12", "src": "Wilhelmsen", "title": "윌헬름센 홀딩 2분기 EBITDA 6,200만 달러(+30% YoY)·순이익 1.47억 달러…해양서비스 수입 7% 증가", "eTitle": "Wilh. Wilhelmsen Holding Posts Q2 2026 EBITDA of USD 62m, Up 30% Year on Year, and Net Profit of USD 147m", "kSum": "Wilh. Wilhelmsen Holding의 2분기 총수입은 3억2천만 달러(+2% YoY), EBITDA 6,200만 달러(+30% YoY, +23% QoQ), 순이익 1억4,700만 달러(주당 3.49달러)였다. 해양서비스(Maritime Services) 수입은 2억2,800만 달러(+7% YoY), 뉴에너지는 NorSea 호조로 9,100만 달러(+8% QoQ), 전략지분·투자 이익은 WalWil 지분법 이익 감소로 8,500만 달러로 줄었다. 정기주총은 주당 NOK 20 배당을 승인하고 이사회에 최대 NOK 8.50 추가 배당 권한을 부여했으며, 회사는 중동 분쟁·무역 환경 등 불확실성이 크다고 밝혔다.", "eSum": "Wilh. Wilhelmsen Holding reported Q2 2026 total income of USD 320m (up 2% year on year), EBITDA of USD 62m (up 30% year on year and 23% quarter on quarter) and net profit of USD 147m (EPS USD 3.49). Maritime Services income rose 7% to USD 228m, New Energy income was USD 91m (up 8% quarter on quarter on strong NorSea activity), and Strategic Holdings and Investments profit fell to USD 85m mainly on a lower share of Wallenius Wilhelmsen profits. The AGM approved a NOK 20.00 dividend and authorised up to NOK 8.50 more, while the company flagged considerable uncertainty from the Middle East conflict and the trade environment.", "kImp": "선박관리·선용품·대리점 등 해양서비스 부문이 성과개선 프로그램 속에 성장하고 있어, 그룹 차원의 서비스 효율화·원가관리 압력도 이어질 전망이다.", "eImp": "Maritime Services, which includes ship management, ships service and agency, keeps growing under performance-improvement programmes, implying continued group pressure on service efficiency and cost control.", "url": "https://www.wilhelmsen.com/media-news-and-events/financial-news/2026/results-for-the-second-quarter-2026/", "prio": 2}, {"code": "WIL", "date": "2026-08-03", "src": "헤럴드경제", "title": "윌헴슨 쉽스 서비스, 한국해양대에 1억4천만원 상당 용접기·가스분배 시스템 기증…선사·선박관리사 실무교육에도 활용", "eTitle": "Wilhelmsen Ships Service Donates About KRW 140 Million of Welding and Gas-Distribution Training Equipment to Korea Maritime & Ocean University, Also for Industry Training", "kSum": "선박 용품·서비스 기업 윌헴슨 쉽스 서비스(Wilhelmsen Ships Service)가 국립한국해양대학교에 약 1억4,000만원(9만7,565.10달러) 상당의 교육 기자재를 현물 기증했다고 헤럴드경제가 8월 3일 보도했다. 가스 분배 시스템, TIG·아크 용접기, 플라즈마 절단기와 안전장비 일체로, 가스처리설비가 있는 종합연구관에 설치돼 학생 실습·연구에 쓰인다. 양 기관은 이 장비를 해기사 양성뿐 아니라 국내 선주사·선박관리회사 임직원의 기술 실무교육에도 공동 활용하기로 했다.", "eSum": "Wilhelmsen Ships Service has donated in-kind training equipment worth about KRW 140 million (USD 97,565.10) to Korea Maritime & Ocean University, Herald Business reported on 3 August. The kit, a gas distribution system, TIG and arc welders, a plasma cutter and safety gear, is installed in the research building that houses the university's gas processing facility for student practice and research. The two sides agreed to use it not only to train future officers but also for hands-on technical courses for staff of Korean shipowners and ship managers.", "kImp": "용접·절단은 사고 위험이 큰 화기작업이므로, 이 장비를 활용한 업계 실무교육 과정이 열리면 기관부 승선 전 교육이나 화기작업(Hot Work) 안전교육과 연계하는 방안을 검토할 만하다.", "eImp": "Welding and cutting are high-risk hot work, so if industry courses using this equipment open they could serve as pre-joining training for engine crews or be linked to hot-work safety training.", "url": "https://biz.heraldcorp.com/article/10828742", "prio": 1}, {"code": "WIL", "date": "2026-07-30", "src": "MarineLink (Reuters)", "title": "이집트 정부, 다미에타항 FSRU '에너고스 윈터' 화재 원인은 드론 공격이라고 확인…윌헬름센 쉽 매니지먼트 관리 설비, 인명피해 없어", "eTitle": "Egypt Confirms a Drone Caused the Fire on the FSRU Energos Winter at Damietta, a Unit Managed by Wilhelmsen Ship Management, With No Injuries Reported", "kSum": "마린링크가 전재한 로이터 보도에 따르면 이집트 내각은 7월 30일, 전날 지중해 다미에타항에서 가스 선박 2척을 휩싼 화재가 드론에 의한 것이라고 처음 공식 확인했으며 배후를 자처한 세력은 없고 조사가 이어지고 있다. 거래 소식통들은 저장용량 13만8,250㎥의 부유식 저장·재기화설비(FSRU) '에너고스 윈터(Energos Winter)'가 드론에 맞았고 불이 '가스로그 살렘(Gaslog Salem)'으로 번졌다고 전했으며, 기사에 따르면 에너고스 윈터는 미국 에너고스 인프라스트럭처 소유로 기술·안전·상업 운영을 윌헬름센 그룹의 싱가포르 소재 자회사 윌헬름센 쉽 매니지먼트가 맡고 있다. 이집트 석유부는 소방·보안팀이 즉시 대응해 사상자는 없었다고 밝혔다. 아흐람 온라인(9월 30일)에 따르면 교통장관은 드론이 재기화 배관과 보조 탱크를 맞혔다고 했고, 설비는 항구 밖으로 예인돼 수리에 들어갔으며 이집트는 요르단 아카바항의 대체 재기화선을 확보했고, 이번 중단으로 여름 성수기 이집트 재기화 용량의 약 17%가 빠졌다(이 FSRU는 2025년 10월부터 5년·연 3,600만 달러 용선으로 투입).", "eSum": "Egypt's cabinet confirmed on 30 July that a drone caused the fire that engulfed two gas vessels at the Mediterranean port of Damietta the previous day, the first official confirmation of an attack, with no party claiming responsibility and investigations continuing, according to a Reuters report carried by MarineLink. Trading sources said the 138,250 cbm FSRU Energos Winter was hit and the fire spread to Gaslog Salem; the report said Energos Winter is owned by US-based Energos Infrastructure and that its technical, safety and commercial operations are managed by Wilhelmsen Ship Management, the Wilhelmsen Group's Singapore-based subsidiary. Egypt's petroleum ministry said firefighting and security teams responded immediately and there were no injuries or fatalities. Ahram Online reported on 30 September that the drone hit a regasification pipe and an auxiliary tank, the unit was towed out of port for repairs while Egypt secured a replacement regasification vessel at Aqaba, and the outage removed about 17% of Egypt's regasification capacity in peak summer demand; the FSRU had started in Egypt in October 2025 on a five-year charter worth USD 36m a year.", "kImp": "항내 계류 중인 가스 설비가 드론에 맞은 사례로, 중동 분쟁 인근 항만(동지중해·홍해)에 기항하는 그룹 선박은 선박보안평가와 보안계획(SSP)에 드론 공격 시나리오(화재·가스 누출 대응, 긴급 이안·소개 절차)를 반영하고, CSO가 기국·UKMTO 경보와 전쟁위험 보험 지정해역 변동을 수시로 확인해야 한다.", "eImp": "This is a case of a gas unit being hit by a drone while moored in port, so group ships calling at ports near the Middle East conflict (Eastern Mediterranean, Red Sea) should add drone-attack scenarios, including fire and gas-release response and emergency unberthing or evacuation, to ship security assessments and plans, and CSOs should track flag-state and UKMTO advisories and changes to war-risk listed areas.", "url": "https://www.marinelink.com/news/egypt-confirms-drone-hit-damietta-gas-541629", "prio": 2}, {"code": "WIL", "date": "2026-04-29", "src": "Wilh. Wilhelmsen Holding (Oslo Børs)", "title": "윌헬름센 홀딩, 에다윈드 SOV·CSOV 선대 매각 완료…순현금 약 5,500만 달러 유입", "eTitle": "Wilh. Wilhelmsen Holding Says Edda Wind Has Completed the Sale of Its SOV/CSOV Fleet, Bringing About USD 55m Net Cash", "kSum": "Wilh. Wilhelmsen Holding은 Edda Wind ASA가 SOV·CSOV 선대(신조 포함)를 Partners Group 포트폴리오사 North Star와 Navigare Capital Partners 계열사에 매각 완료했다고 공시했다(3월 4일 매각 계약 공시). 2020년 이후 투자액을 감안한 Wilhelmsen의 순현금 유입은 약 5,500만 달러, 2분기 회계상 순효과는 2,700만 달러이며, Wilhelmsen New Energy가 Edda Wind 지분 37.76%를 간접 보유한다. 1척은 선행조건이 충족될 때까지(2026년 4분기 예상) Edda Wind 소유로 남는다.", "eSum": "Wilh. Wilhelmsen Holding said Edda Wind ASA completed the sale of its SOV/CSOV fleet, including newbuildings, to North Star, a Partners Group portfolio company, and an affiliate of Navigare Capital Partners, following agreements announced on 4 March. Wilhelmsen expects net cash flow of about USD 55m after its total investment in Edda Wind since 2020 and a net positive accounting effect of USD 27m in Q2; Wilhelmsen New Energy indirectly owns 37.76% of Edda Wind. One vessel stays with Edda Wind until conditions precedent are met, expected in Q4 2026.", "kImp": "그룹 홀딩사의 해상풍력 지원선 투자 회수가 이뤄져, 포트폴리오가 해양서비스·로로 해운 중심으로 재편되는 흐름이다.", "eImp": "The holding company has realised its offshore-wind service vessel investment, part of a portfolio reshaping towards maritime services and RoRo shipping.", "url": "https://newsweb.oslobors.no/message/671902", "prio": 1}, {"code": "WIL", "date": "2026-04-16", "src": "Wilhelmsen", "title": "Wilhelmsen Ship Management, 선박 생애주기 전문회사 '사이클러스 마린' 출범…LR과 선박재활용 MoU", "eTitle": "Wilhelmsen Ship Management Launches Vessel Lifecycle Company Cyclus Marine, Which Then Signs a Ship Recycling MoU With Lloyd's Register", "kSum": "Wilhelmsen Ship Management(WSM)는 신조, 입거, 라이딩 크루, 레트로핏, 개조, 재활용을 하나의 브랜드로 묶은 독립 선박 생애주기 회사 Cyclus Marine을 출범시켰다(GM Gabriel Yeo, 싱가포르·함부르크·쿠알라룸푸르·아테네). 기존 WSM 전문 인력이 그대로 옮겨 WSM과 긴밀히 통합 운영된다. Cyclus Marine은 4월 22일 Lloyd's Register와 재활용 시설 평가 프레임워크 개발, 감사, 인력 교육, 책임 있는 재활용 확산을 위한 MoU를 맺었다.", "eSum": "Wilhelmsen Ship Management (WSM) launched Cyclus Marine, a standalone vessel lifecycle company bringing newbuilding, dry-docking, riding crews, retrofits, conversions and recycling under one brand, led by general manager Gabriel Yeo from Singapore, Hamburg, Kuala Lumpur and Athens. Existing WSM teams move across and the company stays closely integrated with WSM. On 22 April Cyclus Marine signed an MoU with Lloyd's Register to develop a framework for assessing recycling facilities, carry out audits, support workforce training and promote responsible recycling.", "kImp": "노후선 재활용과 신조 감독·개조가 그룹 내 전문회사로 일원화돼, 고선령선 처분 시 재활용 야드 선정·감사를 그룹 서비스로 활용할 수 있다.", "eImp": "With recycling, newbuild supervision and conversions consolidated in a group specialist, disposal of ageing ships can draw on in-house support for recycling-yard selection and audits.", "url": "https://www.wilhelmsen.com/media-news-and-events/press-releases/2026/wilhelmsen-ship-management-launches-dedicated-vessel-lifecycle-company-cyclus-marine/", "prio": 2}, {"code": "WIL", "date": "2026-04-01", "src": "Wilhelmsen", "title": "WSM·MPC캐피탈, 선박 IT 합작사 '워터웨이 IT' 출범…약 400척·70개 고객", "eTitle": "Wilhelmsen Ship Management and MPC Capital Launch Waterway IT, a 50/50 Onboard Vessel IT Joint Venture Covering About 400 Ships", "kSum": "MPC Capital과 Wilhelmsen Ship Management의 50:50 합작사 Waterway IT가 4월 1일 독립 선박 IT 공급사로 출범해 두 회사의 선박 IT 사업을 하나의 글로벌 플랫폼으로 통합했다. 출범 시 약 400척, 고객 약 70곳, IT 전문가 45명 규모이며 함부르크·오슬로·쿠알라룸푸르·마닐라·벵갈루루에서 24시간 지원한다. 모듈형 선박 IT 스택, 하이브리드 통신, 사이버보안을 완전 관리형 서비스로 제공한다(CEO Sondre Mortensvik).", "eSum": "Waterway IT, a 50/50 joint venture between MPC Capital and Wilhelmsen Ship Management, began operating on 1 April as an independent onboard vessel IT provider combining both partners' vessel IT activities on one global platform. It starts with about 400 vessels, some 70 customers and 45 IT professionals, with hubs in Hamburg, Oslo, Kuala Lumpur, Manila and Bangalore providing 24/7 support. It offers a modular vessel IT stack, hybrid connectivity and cybersecurity as a fully managed service, led by CEO Sondre Mortensvik.", "kImp": "관리선의 선상 IT·통신·사이버보안 공급 체계가 합작사로 바뀌는 것으로, 선박 사이버 위험관리(IACS UR E26/E27 등) 이행 시 공급사 책임 범위를 명확히 할 필요가 있다.", "eImp": "Onboard IT, connectivity and cybersecurity for managed ships now come from a joint venture, so supplier responsibilities should be clarified when implementing cyber-risk requirements such as IACS UR E26/E27.", "url": "https://www.wilhelmsen.com/media-news-and-events/press-releases/2026/waterway-it-a-new-global-platform-for-onboard-vessel-it/", "prio": 2}]}, {"code": "ESG", "kTitle": "친환경·기술", "eTitle": "Decarbonisation & Tech", "items": [{"code": "ESG", "date": "2026-11-25", "src": "Splash247", "title": "CMA CGM 사데 회장 '2050 넷제로 목표 달성 어려워' 인정 — IMO 환경 협상 며칠 앞두고", "eTitle": "CMA CGM's Saadé Concedes the 2050 Net Zero Target Is Out of Reach - Days Before Crucial IMO Environmental Negotiations", "kSum": "해운 탈탄소의 대표적 지지자였던 CMA CGM의 로돌프 사데 회장이 2050년 넷제로 목표 달성이 어렵다고 인정했다고 Splash247이 11월 25일 전했다. IMO의 중요한 환경 협상을 며칠 앞둔 시점이다.", "eSum": "One of shipping's most vocal decarbonisation proponents, CMA CGM's Rodolphe Saadé, has conceded its 2050 net zero ambitions are unlikely to be realised, just days ahead of crucial IMO environmental negotiations, Splash247 reported on 25 November.", "kImp": "대형 선사도 목표를 재조정하고 있다. IMO 협상(MEPC) 결과에 따라 CII·연료 규정 일정이 바뀔 수 있으니 SEEMP Part III 계획을 결과 발표 뒤 다시 검토할 것.", "eImp": "Even big lines are resetting targets. CII and fuel-rule timelines may shift after the IMO talks, so review SEEMP Part III plans after the outcome.", "url": "https://splash247.com/cma-cgms-saade-concedes-2050-net-zero-target-is-out-of-reach/", "prio": 2}, {"code": "ESG", "date": "2026-11-24", "src": "SAFETY4SEA·Marine Insight", "title": "해운단체 8곳, 유럽의회 본회의 앞두고 인도 알랑 선박해체장 2곳 EU 목록 등재 승인 촉구 — 환경위원회는 11월 4일 반대 결의", "eTitle": "Eight Shipping Associations Urge MEPs to Approve Two Indian Recycling Yards Ahead of This Week's Plenary - ENVI Committee Objected on 4 November", "kSum": "해운단체 8곳이 이번 주 유럽의회 본회의 표결을 앞두고 인도 알랑의 선박해체장 2곳(Shree Ram Vessel Scrap, YSI Recyclers)을 EU 선박재활용 승인 목록에 올리는 집행위원회 안을 승인해 달라고 의원들에게 요청했다고 SAFETY4SEA가 11월 24일 전했다. 유럽의회 환경위원회는 11월 4일 비칭(beaching) 방식을 문제 삼아 등재에 반대하는 결의를 채택했다. 본회의 결의는 집행위를 법적으로 구속하지 않으며 최종 결정은 회원국 몫이다.", "eSum": "Eight shipping associations urged MEPs to approve the Commission's proposal to add two Alang yards (Shree Ram Vessel Scrap and YSI Recyclers) to the EU list of ship recycling facilities ahead of this week's plenary vote, SAFETY4SEA reported on 24 November. Parliament's ENVI committee objected on 4 November over beaching; the plenary resolution does not bind the Commission and member states have the final say.", "kImp": "EU 기국 노후선의 해체 선택지가 이 표결에 달려 있다. 해체 예정 선박은 선박재활용 유해물질목록(IHM) 갱신 상태를 확인하고, 선주와 해체 장소·시기 결정 전에 EU 목록 결과를 확인할 것.", "eImp": "End-of-life options for EU-flagged ships depend on this vote. Check IHM status on ships due for recycling and confirm the EU list outcome before owners decide on the yard and timing.", "url": "https://www.marineinsight.com/european-parliament-committee-votes-against-approving-2-alang-shipbreaking-yards-to-recycle-eu-ships/", "prio": 2}, {"code": "ESG", "date": "2026-11-23", "src": "gCaptain", "title": "스페인, 2027년 7월부터 항만·내수·지정 정박지서 스크러버 세정수 배출 전면 금지 — 개방·폐쇄·하이브리드 모두, 국적 불문", "eTitle": "Spain to Ban Ship Scrubber Wastewater Discharges From July 2027 - Open-Loop, Closed-Loop and Hybrid, in Ports, Internal Waters and Designated Anchorages, Any Flag", "kSum": "스페인은 2027년 7월 1일부터 자국 내수, 항만 구역, 지정 정박지에서 선박 배기가스 세정장치(스크러버)의 세정수 배출을 금지한다. 11월 20일 공포된 왕령 1006/2026은 국적과 관계없이 모든 민간 선박에 적용되며, 개방형·폐쇄형·하이브리드 스크러버를 모두 포함한다. 이 조치는 북동대서양 해양환경 보호를 맡는 OSPAR 위원회의 2025년 결정을 이행하는 것으로, 기존 지역 환경 규정보다 범위가 넓다.", "eSum": "Spain will ban washwater discharges from exhaust gas cleaning systems (scrubbers) in its internal waters, port areas and designated anchorages from 1 July 2027. Royal Decree 1006/2026, published on 20 November, applies to all civilian vessels regardless of flag and covers open-loop, closed-loop and hybrid systems. It implements a 2025 OSPAR Commission decision and goes beyond existing regional requirements.", "kImp": "스크러버 선박의 스페인 기항 운영 방식이 바뀐다. 2027년 7월 이전에 스페인 입항 전 연료 전환(저유황유) 절차, 연료 재고 계획, 스크러버 작동 기록 관리를 선박별로 준비할 것.", "eImp": "Scrubber-fitted ships calling in Spain will need a different routine. Before July 2027, prepare ship-by-ship procedures for changing over to compliant fuel before Spanish waters, fuel stock planning and scrubber operation records.", "url": "https://gcaptain.com/spain-to-ban-ship-scrubber-wastewater-discharges-starting-july-2027/", "prio": 2}, {"code": "ESG", "date": "2026-11-23", "src": "SAFETY4SEA", "title": "영국·EU 배출권거래제(ETS) 연계 합의 — 영국 탄소가격, 2028년부터 국제 해운까지 확대", "eTitle": "UK and EU Agree to Link Their Emissions Trading Systems - UK Carbon Pricing to Extend to International Shipping From 2028", "kSum": "영국과 유럽연합(EU)이 양측 배출권거래제(ETS)를 연계하기로 합의했으며, 새 조항에 따라 영국의 탄소 가격 부과가 2028년부터 국제 해운으로 확대된다고 SAFETY4SEA가 11월 23일 전했다. 영국 ETS는 2026년 7월 1일부터 국내 해상 운송을 대상에 포함했으나 영국 관련 해운 배출량의 약 15%만 다뤄 왔다. 이번 연계로 양측 배출권을 서로 인정하는 길이 열리고 탄소국경조정제도(CBAM) 부담도 줄어들 전망이다.", "eSum": "The UK and the EU have agreed to link their emissions trading systems, with new provisions extending UK carbon pricing to international shipping from 2028, SAFETY4SEA reported on 23 November. The UK ETS has covered domestic maritime emissions since 1 July 2026, about 15% of UK-related shipping emissions. The link opens the way to mutual recognition of allowances and relief from carbon border adjustment charges.", "kImp": "영국 기항선은 2028년부터 EU ETS와 별도로 영국 배출권도 사야 할 수 있다. 영국 항로 비중이 큰 선주별로 2028년 탄소비용 추정과 배출 모니터링(MRV) 데이터 준비 일정을 미리 세울 것.", "eImp": "Ships trading to the UK may need UK allowances as well as EU ones from 2028. Estimate 2028 carbon costs for owners with significant UK trade and plan the monitoring (MRV) data they will need.", "url": "https://safety4sea.com/", "prio": 3}, {"code": "ESG", "date": "2026-11-18", "src": "Hellenic Shipping News(Everllence)", "title": "Everllence, 8S50ME-GI Mk10.7 엔진 첫 수주 — CLdN의 6,700 레인미터 로로선 2척용, 2028년 7월 시험대 운전 예정", "eTitle": "Everllence Wins the First Order for Its 8S50ME-GI Mk10.7 Engine - for Two 6,700-Lane-Metre RoRo Ships for CLdN, With Testbed Running Scheduled for July 2028", "kSum": "엔진 제작사 Everllence(옛 MAN Energy Solutions)가 메탄(LNG) 이중연료 2행정 엔진 8S50ME-GI Mk10.7의 첫 주문을 받았다. 룩셈부르크 로로 선사 CLdN이 발주한 6,700 레인미터급 로로선 2척에 들어가며, 엔진 시험대 운전은 2028년 7월로 잡혔다. Mk10.7 세대 ME-GI 엔진은 올해 6월 노르웨이 자동차선 선주의 8,600 CEU 자동차운반선 4척(6S60ME-GI Mk10.7)에서 첫 주문이 나온 뒤 로로선으로 적용이 넓어지고 있다. 제작사는 이 엔진의 장점으로 높은 연료 효율과 매우 낮은 메탄 슬립을 든다.", "eSum": "Engine designer Everllence (formerly MAN Energy Solutions) has won the first order for its 8S50ME-GI Mk10.7 methane dual-fuel two-stroke engine. It will power two 6,700-lane-metre RoRo vessels ordered by Luxembourg operator CLdN, with testbed running scheduled for July 2028. The Mk10.7 generation of the ME-GI took its first order in June for four 8,600 CEU car carriers (6S60ME-GI Mk10.7) for a Norwegian car carrier owner and is now spreading into RoRo tonnage. The maker cites high fuel efficiency and very low methane slip.", "kImp": "로로·자동차선 신조의 주기관이 LNG 이중연료 새 세대로 옮겨 가고 있다. 자동차선 관리사는 고압 가스 분사(ME-GI) 기관의 가스 공급 계통 정비, 가스 운전 자격 선원 확보, 제작사 교육 일정을 2028~2029년 인도분 기준으로 미리 잡을 것.", "eImp": "Main engines for new RoRo and car carrier tonnage are moving to the next LNG dual-fuel generation. Car carrier managers should plan fuel gas supply system maintenance, gas-qualified crew and maker training for high-pressure gas injection (ME-GI) engines against 2028-2029 deliveries.", "url": "https://www.hellenicshippingnews.com/everllence-secures-first-order-for-8s50me-gi-mk10-7-engine/", "prio": 3}, {"code": "ESG", "date": "2026-11-18", "src": "Hellenic Shipping News(Clean Shipping Alliance)", "title": "스크러버 업계 단체 CSA, 그린란드의 세정수 배출 금지에 '실망' — 위험성 평가 근거에 의문, IMO MEPC.1/Circ.899 절차 준수 요구", "eTitle": "Scrubber Industry Group CSA 'Disappointed' by Greenland's Washwater Discharge Ban - Questions the Risk Assessment and Points to IMO MEPC.1/Circ.899", "kSum": "배기가스 세정장치(스크러버) 사용 선사 단체인 Clean Shipping Alliance(CSA)가 그린란드의 스크러버 세정수 배출 금지 결정에 실망을 나타냈다. CSA는 금지의 근거가 된 위험성 평가에 의문을 제기하며, 배출 제한을 검토할 때 따르도록 한 IMO 지침 MEPC.1/Circ.899를 들었다. 그린란드 의회는 이달 초 만장일치로, 개방형 스크러버 배출을 2027년 7월 1일부터 항만·내수·영해에서 금지하고 폐쇄형·하이브리드형은 2029년 7월 1일부터 금지하는 단계적 방안을 지지했다. 북동대서양 15개국(OSPAR)도 2027년 7월부터 항만·내수에서 개방형 배출을 금지한다.", "eSum": "The Clean Shipping Alliance, which represents shipowners using exhaust gas cleaning systems, says it is disappointed by Greenland's ban on scrubber washwater discharges. It questions the risk assessment behind the ban and points to IMO circular MEPC.1/Circ.899, the guidance for assessing discharge restrictions. Greenland's parliament unanimously backed a phased ban earlier this month: open-loop discharges are prohibited in ports, internal waters and the territorial sea from 1 July 2027, and closed-loop and hybrid systems from 1 July 2029. Fifteen north-east Atlantic states (OSPAR) also ban open-loop discharges in ports and internal waters from July 2027.", "kImp": "업계가 반발해도 금지 해역은 늘고 있다. 선박관리사는 스크러버 장착선의 항해 계획에 해역별 배출 금지 목록(시행일 포함)을 넣고, 금지 해역 진입 전 연료 전환 시점과 저유황유 재고 기준을 절차로 정할 것.", "eImp": "The industry objects, but the list of no-discharge waters keeps growing. Managers should carry an area-by-area list of discharge bans with start dates in passage planning for scrubber-fitted ships and set the changeover point and compliant-fuel stock levels before entering each area.", "url": "https://www.hellenicshippingnews.com/clean-shipping-alliance-disappointed-on-greenlands-scrubber-ban/", "prio": 2}, {"code": "ESG", "date": "2026-11-18", "src": "Hellenic Shipping News(ENGINE)", "title": "로테르담 LSMGO 한 주 새 톤당 102달러 하락 — 디젤 사이클 저속기관 기준으로 LNG·바이오LNG보다 싸져", "eTitle": "Rotterdam LSMGO Falls USD 102 a Tonne in a Week - Now Cheaper Than LNG and Bio-LNG for Diesel-Cycle Slow-Speed Engines", "kSum": "ENGINE의 연료 전환 비교에 따르면 로테르담 저유황경유(LSMGO) 가격이 한 주 사이 톤당 102달러 내려, 디젤 사이클 저속 이중연료 기관에서는 LSMGO가 LNG와 액화 바이오메탄(LBM)보다 싸졌다. 이중연료선의 연료 선택이 주간 가격 변동에 따라 뒤집힐 수 있음을 보여 준다.", "eSum": "ENGINE's fuel switch snapshot shows Rotterdam LSMGO down USD 102 a tonne in a week, making it cheaper than LNG and liquefied biomethane for diesel-cycle slow-speed dual-fuel engines. The comparison shows how weekly price moves can flip the fuel choice on dual-fuel ships.", "kImp": "이중연료선의 '어느 연료가 싼가'는 주 단위로 바뀐다. 선박관리사는 연료 선택을 가격만이 아니라 EU ETS·FuelEU 비용과 메탄 슬립까지 넣은 항차별 비교표로 용선자에게 제시할 수 있게 준비할 것.", "eImp": "Which fuel is cheaper on a dual-fuel ship changes week to week. Managers should be ready to give charterers a per-voyage comparison that includes EU ETS and FuelEU costs and methane slip, not price alone.", "url": "https://www.hellenicshippingnews.com/fuel-switch-snapshot-lsmgo-undercuts-lng-and-lbm-for-diesel-ss-engines/", "prio": 2}, {"code": "ESG", "date": "2026-11-17", "src": "Hellenic Shipping News(Platts)", "title": "LNG 벙커 가격: 로테르담 톤당 1,630달러(-8달러), 싱가포르는 로테르담보다 41달러 낮아져 — JKM 근월물이 1월물(MMBtu당 29.60달러)로 넘어간 영향", "eTitle": "LNG Bunker Snapshot: Rotterdam at USD 1,630 a Tonne (-USD 8) and Singapore Now USD 41 Below It - Mostly Because the Front-Month JKM Rolled to January at USD 29.60/MMBtu", "kSum": "11월 17일 기준 LNG 벙커 가격은 로테르담(ARA)이 톤당 1,630달러로 한 주 전보다 8달러 내렸다. 싱가포르는 일주일 전 로테르담보다 109달러 비쌌으나 이번 주에는 41달러 싸졌다. 싱가포르 하락 폭 91달러의 대부분은 기준이 되는 JKM 근월물이 12월물에서 1월물로 넘어간 데 따른 것이다. 1월물 JKM은 MMBtu당 29.60달러(톤당 1,539달러)이고 싱가포르 벙커 프리미엄은 0.96달러(톤당 50달러)다. 미·이란 평화 협상 기대가 중동 우려를 덜었고, 유럽은 추위와 노르웨이 가스전 정비로 TTF가 올랐으며, 아시아는 중국 수요 약세와 카타르의 호르무즈 수출 재개 움직임이 가격을 눌렀다.", "eSum": "On 17 November LNG bunkers in Rotterdam (ARA) were USD 1,630 a tonne, down USD 8 on the week, while Singapore swung from a USD 109 premium to USD 41 below ARA. Most of Singapore's USD 91 fall reflects the front-month JKM rolling from December to January; January JKM is USD 29.60/MMBtu (USD 1,539 a tonne) and Singapore's premium over it is USD 0.96/MMBtu (USD 50 a tonne). Hopes for US-Iran talks eased Middle East concern, TTF rose on colder weather and Norwegian maintenance, and weaker Chinese interest and Qatar's push to export via Hormuz weighed on Asian prices.", "kImp": "LNG 이중연료선은 항만 간 가격 역전에 따라 벙커링 항을 바꿀 여지가 생겼다. 선박관리사는 LNG DF선의 항차별 연료 선택(LNG·유류) 손익과 벙커링 항 후보를 용선자에게 주간 단위로 제시할 것.", "eImp": "Price reversals between hubs give LNG dual-fuel ships room to switch bunkering ports. Managers should give charterers a weekly view of fuel choice economics (LNG versus oil) and candidate bunkering ports for each LNG dual-fuel voyage.", "url": "https://www.hellenicshippingnews.com/lng-bunker-snapshot-singapore-price-drops-as-jkm-moves-to-january/", "prio": 2}, {"code": "ESG", "date": "2026-11-17", "src": "Hellenic Shipping News(Lloyd's Register)", "title": "[기관 보고서] LR '선상 탄소포집, 실용적 경로인가' — 현재 아민 방식 포집률 30~40%, 연료 소모 15~30% 증가. 포집률 70%·연료 15% 증가 때 CO₂ 약 44% 감축", "eTitle": "[Institution report] Lloyd's Register on Onboard Carbon Capture: Amine Systems Capture 30-40% Today at a 15-30% Fuel Penalty - at 70% Capture and a 15% Penalty, Tank-to-Wake CO2 Falls About 44%", "kSum": "로이드선급(LR) 보고서에 따르면 현재 선박에 설치된 실규모 아민 방식 선상 탄소포집(OCCS) 설비의 포집률은 30~40%이고, 더 큰 시범 설비는 70% 안팎을 목표로 한다. 지금 설비는 연료 소모를 15~30% 늘린다. 포집률 70%에 연료 15% 증가를 가정하면 탱크-투-웨이크 CO₂는 약 44% 줄어든다. 규제 면에서 EU ETS는 적격 저장·활용 시설에 인도된 포집 CO₂를 인정하지만 FuelEU Maritime에는 아직 반영되지 않았고 IMO는 국제 체계를 만드는 중이다. 사례로 Eastern Pacific Shipping의 Pacific Cobalt(2024년 첫 선급 승인 상업 설치)와 Solvang의 Clipper Eris(포집률 약 70% 목표 실규모 시험)를 들었다.", "eSum": "A Lloyd's Register report says full-scale amine-based onboard carbon capture systems capture about 30-40% of CO2 today, with larger pilots targeting around 70%, and raise fuel consumption by 15-30%. At 70% capture with a 15% penalty, tank-to-wake CO2 falls by about 44%. The EU ETS can recognise captured CO2 delivered to qualifying storage or utilisation, FuelEU Maritime does not yet include OCCS, and the IMO is developing a global framework. Cases cited are Eastern Pacific Shipping's Pacific Cobalt, the first classed commercial installation in 2024, and Solvang's Clipper Eris, testing a full-scale system targeting about 70%.", "kImp": "포집률보다 '순 감축률'과 포집 CO₂의 하역처가 사업성을 가른다. 선박관리사는 기존선 개조 검토 때 연료 증가분, 아민 취급 안전, 액화 CO₂ 저장·하역 항만, 그리고 IMO 안전 지침 일정을 함께 놓고 선주에게 비교표를 낼 것.", "eImp": "Net abatement and where captured CO2 can be landed matter more than the headline capture rate. When reviewing retrofits, managers should give owners a comparison that sets out the fuel penalty, amine handling safety, liquid CO2 storage and reception ports, and the IMO safety guideline timetable.", "url": "https://www.hellenicshippingnews.com/onboard-carbon-capture-a-practical-pathway-for-shipping/", "prio": 2}, {"code": "ESG", "date": "2026-11-11", "src": "The Maritime Executive", "title": "풍력 로로선 Neoliner Origin, 취항 1년 연료 절감 70%(2026년)·평균 66% — 9왕복 6만 2,000해리, CO₂ 1만 1,228톤 회피. 목표 80%에는 못 미쳐", "eTitle": "Wind-Powered Ro-Ro Neoliner Origin Reports a 70% Fuel Reduction in 2026 and 66% on Average Since Entering Service - Nine Round Trips, 62,000 Miles and 11,228 Tonnes of CO2 Avoided, Short of the 80% Target", "kSum": "프랑스 선사 네오라인의 136m 풍력 로로선 Neoliner Origin이 2025년 10월 취항 뒤 1년 실적을 공개했다. GLEC 기준 대비 연료 절감은 2026년 70%, 취항 이후 평균 66%로 목표 80%에는 못 미쳤다. 회피한 CO₂는 1만 1,228톤이다. 몽투아르-생피에르미클롱-볼티모어-핼리팩스 대서양 횡단 9왕복, 6만 2,000해리 이상을 운항하며 화물 1,845대(약 1만 2,063톤)와 여객 170여 명을 실었다. 샹티에 드 라틀랑티크가 설계한 SolidSail 돛 2기를 쓴다. 2027년 목표는 78% 이상이며 2027년 2월 정비가 예정돼 있다.", "eSum": "French owner Neoline has published first-year results for its 136 m wind-powered ro-ro Neoliner Origin, in service since October 2025. Fuel savings against the GLEC reference were 70% in 2026 and 66% on average since entry into service, short of the 80% target, avoiding 11,228 tonnes of CO2. The ship made nine transatlantic round trips of more than 62,000 nautical miles between Montoir-de-Bretagne, Saint-Pierre-et-Miquelon, Baltimore and Halifax, carrying 1,845 units (about 12,063 tonnes) and over 170 passengers, using two SolidSail rigs designed by Chantiers de l'Atlantique. The 2027 target is at least 78%, with maintenance due in February 2027.", "kImp": "풍력 주추진 로로선의 1년 실측치가 처음 나왔다. 자동차선 관리사는 풍력 보조 장치를 검토하는 선주에게 실측 절감률, 돛 정비 주기, 항로·계절별 편차를 근거 자료로 제시할 수 있다.", "eImp": "These are the first full-year measurements for a primarily wind-powered ro-ro. Car carrier managers can give owners considering wind-assist the measured savings, rig maintenance intervals and the variation by route and season.", "url": "https://maritime-executive.com/article/wind-powered-ro-ro-neoliner-origin-proves-70-fuel-reduction-in-first-year", "prio": 3}, {"code": "ESG", "date": "2026-11-14", "src": "Hellenic Shipping News(Platts)", "title": "미 FMC 위원장 'IMO 넷제로 프레임워크, 몇 주 안에 합의 가능·최종 문안은 2027년' — IMO 회의 11월 23일~12월 4일, 미국은 연 530억~2,650억 달러 비용 추산", "eTitle": "US FMC Chair: IMO Could Reach Consensus on Its Net-Zero Framework Within Weeks, With Final Text in 2027 - IMO Meets 23 November to 4 December and the US Puts the Cost at USD 53-265 Billion a Year", "kSum": "미 연방해사위원회(FMC) 로라 디벨라 위원장은 11월 11일 IMO가 몇 주 안에 넷제로 프레임워크에 대한 합의를 이룰 수 있고 최종 문안은 2027년에 나올 것으로 본다고 말했다. IMO는 11월 23일부터 12월 4일까지 회의를 연다. 회원국들은 지난해 미국의 반대 속에 채택을 1년 미뤘다. 초안은 2028년부터 선박 온실가스 배출에 의무 부담금을 매기는 내용이며 미국은 해운 비용을 연 530억~2,650억 달러로 추산한다. 10월 로테르담 평균 벙커 가격은 저유황유 GJ당 17.90달러, LNG 28.78달러, 바이오 LNG 51.71달러였다. 위원장은 2050년 LNG·바이오 LNG가 세계 벙커 수요의 60% 이상을 맡을 수 있다고 전망했다.", "eSum": "US Federal Maritime Commission chair Laura DiBella said on 11 November that the IMO could reach consensus on its Net-Zero Framework within weeks, with final text expected in 2027. The IMO meets from 23 November to 4 December after member states delayed adoption by a year amid US opposition. The draft would impose a mandatory charge on shipping's greenhouse gas emissions from 2028, which the US estimates would cost the industry USD 53-265 billion a year. October bunker prices in Rotterdam averaged USD 17.90/GJ for 0.5% sulphur fuel oil, USD 28.78 for LNG and USD 51.71 for bio-LNG; she projects LNG and bio-LNG could meet more than 60% of bunker demand by 2050.", "kImp": "반대해 온 미국 쪽에서 '합의 가능' 신호가 나왔다. 선박관리사는 2028년 부담금 시작을 전제로 선박별 연료 GHG 집약도와 부담금 추정치를 선주 예산 자료에 넣고, 대체 방식(연료 표준 중심)으로 바뀔 경우의 시나리오도 함께 준비할 것.", "eImp": "A signal that agreement is possible has come from the side that opposed it. Managers should put per-ship fuel GHG intensity and levy estimates into owners' budget papers on a 2028 start, with a second scenario in case an alternative fuel-standard-led design is adopted.", "url": "https://www.hellenicshippingnews.com/imo-may-codify-alternative-net-zero-bunker-rules-in-2027-us-fmc-2/", "prio": 2}, {"code": "ESG", "date": "2026-11-13", "src": "Ship Management International", "title": "예테보리항, 2027년 2분기부터 대규모 액화바이오가스(LBG) 벙커링 — 저장 200톤·연 250GWh, 약 50척 분량", "eTitle": "Port of Gothenburg to Offer Large-Scale Liquefied Biogas Bunkering From the Second Quarter of 2027 - 200 Tonnes of Storage and About 250 GWh a Year, Enough for Roughly 50 Vessels", "kSum": "노르디온 에네르기가 예테보리항에 짓는 바이오가스 액화 플랜트의 첫 주요 설비인 LBG 저장 탱크(500㎥)가 설치됐다. 가동하면 최대 200톤을 저장하고 연간 약 250GWh를 공급해 선박 약 50척에 벙커링할 수 있다. 준공은 2027년 2분기 예정이다. 이미 LBG를 쓰는 정기 기항 선사와 발주 잔량에 있는 LBG 연료선이 수요처이며, ST1 바이오크라프트가 설비 용량 일부를 예약했다.", "eSum": "The 500 m3 LBG storage tank, the first major component of the biogas liquefaction plant Nordion Energi is building at the Port of Gothenburg, has been set in place. Once running, the plant can store up to 200 tonnes and deliver about 250 GWh a year, enough to bunker roughly 50 vessels; completion is scheduled for the second quarter of 2027. Demand comes from regularly calling lines already using LBG and from LBG-fuelled ships on order, and ST1 Biokraft has reserved part of the capacity.", "kImp": "LNG 이중연료선이 FuelEU 초과 달성분을 만들 수 있는 공급 거점이 북유럽에 하나 더 생긴다. 선박관리사는 예테보리 기항 LNG DF선의 바이오 LNG 벙커링 절차(품질 증빙, 지속가능성 인증서, 혼합 비율 기록)를 미리 준비할 것.", "eImp": "Another northern European supply point for LNG dual-fuel ships to generate FuelEU over-compliance. Managers should prepare bio-LNG bunkering procedures for LNG DF ships calling at Gothenburg: quality evidence, proof of sustainability and blend-ratio records.", "url": "https://www.shipmanagementinternational.com/news/wl99dnrp448ehp4-mcl97-efbrp-5r4g8-pyc95-bwnyg-se4sn-6rryx", "prio": 2}, {"code": "ESG", "date": "2026-11-14", "src": "Hellenic Shipping News(InfluenceMap)", "title": "InfluenceMap: 해운업계, IMO 넷제로 프레임워크는 지지하지만 세부에서 갈린다 — ICS는 탄소가격 톤당 10~20달러·2040년 연료 집약도 30% 감축, WSC는 2030년 약 74달러, MEPC 85는 11월 30일 개막", "eTitle": "InfluenceMap: Shipping Backs an IMO Climate Deal but Not Its Details - ICS Wants a Carbon Price of USD 10-20 and a 30% Fuel-Intensity Cut by 2040, WSC About USD 74 in 2030, Ahead of MEPC 85 From 30 November", "kSum": "싱크탱크 InfluenceMap은 업계가 IMO 넷제로 프레임워크(NZF)를 폭넓게 지지하면서도 탄소가격·연료 기준·배출 산정 방식에서 갈려 11월 30일 시작하는 MEPC 85 전에 내용이 약해질 수 있다고 분석했다. 세계 선대의 80% 이상을 대표하는 ICS와 정기선 선복의 90%를 대표하는 WSC는 2025년 NZF를 지지했지만 이후에는 이름을 직접 거론하지 않고 있다. ICS는 CO2 환산 톤당 10~20달러의 탄소가격과 2040년 연료 집약도 30% 감축(NZF는 65%)을, WSC는 2030년 톤당 약 74달러와 더 엄격한 산정을 제안한다. Ipieca와 SEA-LNG는 화석연료 배출 산정치를 낮춰 LNG의 이행 부담을 덜자는 입장이다. ICS·WSC·SEA-LNG·ECSA는 EU의 FuelEU Maritime과 ETS에도 반대해 왔다.", "eSum": "Think tank InfluenceMap finds broad industry support for the IMO Net-Zero Framework but splits on carbon pricing, fuel standards and emissions accounting that could weaken it before MEPC 85 opens on 30 November. ICS (over 80% of the world fleet) and WSC (90% of liner capacity) backed the NZF in 2025 but have since avoided naming it. ICS proposes a carbon price of USD 10-20 per tonne of CO2e and a 30% fuel-intensity cut by 2040 against the NZF's 65%; WSC proposes about USD 74 per tonne in 2030 and stricter accounting. Ipieca and SEA-LNG seek lower counted fossil emissions, easing LNG compliance. ICS, WSC, SEA-LNG and ECSA have also pushed against FuelEU Maritime and the EU ETS.", "kImp": "미국이 '채택 불가'를 공언한 데 이어 업계 단체의 요구도 갈려 MEPC 85 결과는 예측하기 어렵다. 선박관리사는 선주별 연료 전환 계획을 NZF 원안, 완화안, 지역 규제(EU ETS·FuelEU)만 남는 경우의 세 갈래로 나눠 비용 표를 준비할 것.", "eImp": "With the US calling the framework unadoptable and trade bodies split, the MEPC 85 outcome is hard to call. Managers should prepare cost tables for each owner under three cases: the NZF as drafted, a diluted version, and regional rules (EU ETS, FuelEU) alone.", "url": "https://www.hellenicshippingnews.com/shipping-sector-backs-an-international-maritime-organization-imo-climate-deal-but-not-all-of-the-details/", "prio": 2}, {"code": "ESG", "date": "2026-11-12", "src": "Ship Management International", "title": "LA·롱비치항 '청정 선박연료 타당성 평가' 발표 — 단·중기 유력 연료는 LNG와 메탄올, 2030년 연 수요 LNG 6.5만~11.5만 톤·메탄올 6.4만~25만 톤, 연말까지 공동 제안요청", "eTitle": "Ports of Long Beach and Los Angeles Publish a Clean Marine Fuel Feasibility Assessment - LNG and Methanol Seen as Most Viable, With 2030 Demand of 65,000-115,000 Tonnes of LNG and 64,000-250,000 Tonnes of Methanol and a Joint RFP by Year-End", "kSum": "롱비치항과 로스앤젤레스항이 11월 12일 '청정 선박연료 타당성 평가'를 냈다. 단기·중기에 가장 현실적인 청정 연료로 LNG와 메탄올을 꼽았다. 산페드로만 두 항만에는 해마다 약 4,000척이 기항하며, 2030년 연간 수요는 LNG 6만5,000~11만5,000톤, 메탄올 6만4,000~25만 톤에 이를 수 있다고 봤다. 보고서는 초기 메탄올 사용 인센티브, 시범 급유 사업, 기존 저장 시설 활용, 안전·인허가 규정 명확화를 단계적으로 추진하라고 권고한다. LNG는 새 저장 시설보다 지금의 선박 간 급유 방식을 선호했다. 대체연료 벙커링 공동 제안요청서(RFP)는 연말까지 나올 예정이다.", "eSum": "The Ports of Long Beach and Los Angeles released a Clean Marine Fuel Feasibility Assessment on 12 November, identifying LNG and methanol as the most viable clean marine fuels in the near and medium term. About 4,000 vessels call at the San Pedro Bay ports each year, and annual demand by 2030 could reach 65,000-115,000 tonnes of LNG and 64,000-250,000 tonnes of methanol. The study recommends a phased approach: incentives for early methanol use, pilot fuelling projects, use of existing storage and clearer safety and permitting rules. For LNG it favours existing ship-to-ship fuelling over new storage. A joint request for proposals on alternative fuel bunkering is expected by year-end.", "kImp": "LA·롱비치가 메탄올·LNG 급유 체계를 갖추면 미 서안 기항 이중연료 자동차선의 연료 계획이 달라진다. 연말 공동 제안요청과 해안경비대 인허가 요건을 추적할 것.", "eImp": "If Los Angeles and Long Beach build methanol and LNG fuelling, fuel planning changes for dual-fuel car carriers calling the US West Coast. Track the year-end joint RFP and Coast Guard permit requirements.", "url": "https://www.shipmanagementinternational.com/news/wl99dnrp448ehp4-mcl97-efbrp-5r4g8-pyc95-bwnyg-se4sn-39j56", "prio": 2}, {"code": "ESG", "date": "2026-11-13", "src": "Höegh Autoliners", "title": "회그 오토라이너스, BYD 에너지스토리지와 선박용 배터리 협력 — 오로라급 12번선에 탑재해 2028년 5월 인도, 연 약 1,000톤 CO2e 감축", "eTitle": "Höegh Autoliners and BYD Energy Storage Agree to Fit Marine Batteries on Aurora No. 12 for Delivery in May 2028 - a Cut of About 1,000 Tonnes of CO2e a Year", "kSum": "회그 오토라이너스와 BYD 에너지스토리지가 11월 9일 안탈리아 COP31 중국관에서 전략·기술 협력 계약을 맺었다. 오로라급 12번선에 BYD 배터리 시스템을 탑재하며, 이 선박은 2028년 5월 인도돼 상업 운항을 시작한다. 회사는 연간 약 1,000톤의 CO2 환산 배출이 줄 것으로 본다. 배터리 용량은 공개되지 않았다. 오로라급은 2026년 8월 추가 발주로 18척이 됐고 옵션을 행사하면 26척까지 늘 수 있다. CEO는 이 선박이 쓸 수 있는 친환경 기술을 모두 담았고 첫날부터 암모니아로 운항할 수 있다고 밝혔다.", "eSum": "Höegh Autoliners and BYD Energy Storage signed a strategic and technical cooperation agreement on 9 November at the China Pavilion at COP31 in Antalya to install BYD batteries on Aurora No. 12, due for delivery and commercial service in May 2028. The company expects a cut of about 1,000 tonnes of CO2e a year; battery capacity was not disclosed. The Aurora programme stands at 18 ships after an August 2026 order and options could take it to 26. The CEO said the ship combines every available green technology and can run on ammonia from day one.", "kImp": "경쟁 선사가 암모니아 레디에 배터리까지 얹은 신조선을 2028년에 투입한다. 자동차선 관리사는 배터리 하이브리드선의 화재 대응·고전압 자격·정비 계약 구조를 미리 파악해 차세대 선박 인수 경쟁력으로 삼을 것.", "eImp": "A competitor is adding batteries to an ammonia-ready newbuilding for 2028. Car carrier managers should study fire response, high-voltage competence and maintenance contracts for battery-hybrid ships as a credential for taking over next-generation tonnage.", "url": "https://www.hoeghautoliners.com/news/hoegh-autoliners-and-byd-bring-marine-battery-systems-on-board-creating-the-greenest-deep-sea-car-carrier-ever", "prio": 3}, {"code": "ESG", "date": "2026-11-14", "src": "Hellenic Shipping News", "title": "EPS, 이중연료 자동차운반선 Lake Victoria에 첫 트럭-선박(TTS) LNG 벙커링 — 미국 로드아일랜드 데이비스빌, 누적 LNG 벙커링 700회 넘어", "eTitle": "Eastern Pacific Shipping Completes Its First Truck-to-Ship LNG Bunkering on the Dual-Fuel Vehicle Carrier Lake Victoria at Davisville, Rhode Island - After More Than 700 LNG Bunkerings", "kSum": "싱가포르 이스턴퍼시픽시핑(EPS)이 운항하는 이중연료 자동차운반선 Lake Victoria가 미국 로드아일랜드 데이비스빌에서 탱크로리로 LNG를 받는 트럭-선박 벙커링을 마쳤다. EPS로서는 첫 사례다. 공급량과 공급사는 공개되지 않았다. EPS는 전 세계에서 700회가 넘는 LNG 벙커링을 해 왔으며, 트럭 방식은 전용 벙커선이나 고정 설비가 없는 항만·선석에서도 LNG를 받을 수 있어 운항 유연성을 높인다고 설명했다.", "eSum": "The dual-fuel vehicle carrier Lake Victoria, operated by Singapore-based Eastern Pacific Shipping, has completed a truck-to-ship LNG bunkering at Davisville, Rhode Island - EPS's first. Quantity and supplier were not disclosed. EPS has carried out more than 700 LNG bunkerings worldwide and says truck delivery adds flexibility by allowing LNG to be supplied at suitable ports and berths without dedicated bunker vessels or fixed infrastructure.", "kImp": "LNG 이중연료 자동차선이 늘면서 벙커선이 없는 자동차 전용 부두에서의 트럭 벙커링이 현실적 선택지가 된다. 관리사는 트럭 벙커링용 적합성 평가, 동시작업(SIMOPS·하역 병행) 위험평가, 항만 당국 허가 절차를 절차서에 추가해 둘 것.", "eImp": "As LNG dual-fuel car carriers multiply, truck bunkering at car terminals without bunker vessels becomes a practical option. Managers should add compatibility assessment, SIMOPS risk assessment with cargo work, and port authority permitting for truck bunkering to their procedures.", "url": "https://www.hellenicshippingnews.com/eastern-pacific-shipping-expands-lng-bunkering-options-with-first-truck-to-ship-delivery/", "prio": 2}, {"code": "ESG", "date": "2026-11-12", "src": "gCaptain · Maritime Executive", "title": "풍력 주추진 RoRo선 Neoliner Origin, 취항 1년 연료 66% 절감(2026년 70%) — 9왕복·6만2,000해리, 엔진 정지 상태 최고 16.6노트", "eTitle": "Wind-Powered Ro-Ro Neoliner Origin Cuts Fuel 66% in Its First Year (70% in 2026) - Nine Round Trips, 62,000 nm and 16.6 Knots Under Sail Alone", "kSum": "프랑스 Neoline의 136m급 RoRo 화물선 Neoliner Origin이 2025년 10월 취항 후 1년 실적을 공개했다. SolidSail 돛을 주추진으로 쓰는 이 선박은 프랑스 몽투아르–생피에르미클롱–볼티모어–핼리팩스(2026년 9월 제브뤼헤 추가) 항로에서 9왕복, 6만2,000해리 이상을 운항하며 화물 약 1만2,000톤(1,845유닛)과 승객 170여 명을 실었다. GLEC 선대 기준 대비 연료를 평균 66%, 2026년에는 70% 줄여 연료 3,502톤과 CO2 약 1만1,228톤을 절감했다. 돛만으로 15노트 이상을 자주 냈고 6월에는 엔진을 끈 채 16.6노트를 기록했다. 돛 문제로 전체 전개가 제한된 기간이 있었으며, 2027년 2월 정비 후 78% 이상 절감을 목표로 한다.", "eSum": "France's Neoline has published first-year results for the 136 m ro-ro cargo ship Neoliner Origin, in service since October 2025. Using a SolidSail rig as primary propulsion on a route from Montoir-de-Bretagne to Saint-Pierre-et-Miquelon, Baltimore and Halifax (Zeebrugge added in September 2026), she made nine round trips and more than 62,000 nm with about 12,000 tonnes of cargo (1,845 units) and over 170 passengers. Fuel use was 66% below the GLEC fleet reference on average and 70% in 2026, saving 3,502 tonnes of fuel and about 11,228 tonnes of CO2. She regularly exceeded 15 knots under sail and reached 16.6 knots in June with the engine off. Sail problems limited full-sail operation; after maintenance in February 2027 the target is at least 78%.", "kImp": "풍력 보조·주추진이 RoRo에서 실측 성과를 내기 시작했다. 자동차선 관리사는 화주의 저탄소 수송 요구에 대비해 돛 장치의 점검·정비 주기, 승무원 교육, 기상 항로 운용 사례를 수집해 둘 필요가 있다.", "eImp": "Wind propulsion is producing measured results on ro-ro tonnage. Car carrier managers should collect cases on rig inspection and maintenance cycles, crew training and weather-routing practice ahead of shipper demand for low-carbon transport.", "url": "https://gcaptain.com/wind-powered-cargo-ship-neoliner-origin-cuts-fuel-consumption-70-in-first-year/", "prio": 2}, {"code": "ESG", "date": "2026-11-13", "src": "Maritime Executive · Hellenic Shipping News(Platts)", "title": "미 FMC 위원장 'IMO 넷제로 프레임워크는 채택될 수 없다' — MEPC 11월 30일 개막 앞두고 자발적·기술중립 대안 제시, 대안 성문화는 2027년 전망", "eTitle": "US FMC Chair: the IMO Net-Zero Framework 'Cannot Be Adopted' - Voluntary, Technology-Neutral Alternative Pushed Ahead of MEPC on 30 November, With Any Alternative Likely Codified in 2027", "kSum": "로라 디벨라 미 연방해사위원회(FMC) 위원장은 11월 13일 뉴욕 IBIA 연례회의에서 미국은 IMO 넷제로 프레임워크(NZF)를 '해운에 대한 세금'으로 보고 계속 반대한다며 'NZF는 채택될 수 없고 집행되지도 않을 것'이라고 말했다. 미국은 상업적으로 현실적이고 기술 중립적인 해법, 자발적·시장 기반 이행, 가용성과 가격을 기준으로 한 단일 배출집약도 목표(늦어도 2035년 재검토), LNG·바이오LNG·에탄올·바이오디젤 인정을 내세운다. FMC는 IMO 기금이 해운에 연 530억~2,650억 달러 부담을 줄 것으로 추산했다. 디벨라 위원장은 11월 11일에는 일본·파나마 등이 낸 대안을 바탕으로 수주 안에 합의가 가능하지만 성문화는 2027년이 될 것이라고 말했다. MEPC는 11월 30일 런던에서 열리고 다음 주 NZF 특별회기가 이어진다.", "eSum": "FMC chair Laura DiBella told the IBIA annual conference in New York on 13 November that the US still firmly opposes the IMO Net-Zero Framework, which it calls a tax on shipping, and that it 'cannot be adopted' and 'will never be enforced'. Washington wants commercially realistic, technology-neutral solutions, voluntary market-based compliance, a single emission-intensity target set by availability and affordability (reviewed by 2035 at the latest) and recognition of LNG, bio-LNG, ethanol and biodiesel. An FMC analysis puts the cost of the IMO fund at USD 53-265 billion a year. On 11 November she said consensus on an alternative, building on proposals from Japan, Panama and others, could come within weeks but codification is likely in 2027. MEPC opens in London on 30 November, followed by an extraordinary session on the NZF.", "kImp": "IMO 중기조치의 형태와 시행 시점이 다시 불확실해졌다. 관리사는 EU ETS·FuelEU처럼 이미 확정된 지역 규제 대응을 우선하고, 연료 전환·개조 투자 판단 자료에는 NZF 원안과 대안 시나리오를 함께 넣어 선주에게 보고할 것.", "eImp": "The shape and timing of the IMO mid-term measures are uncertain again. Managers should prioritise settled regional rules (EU ETS, FuelEU) and give owners fuel-switch and retrofit cases that cover both the original NZF and the alternative scenarios.", "url": "https://maritime-executive.com/article/us-says-imo-must-move-beyond-nzf-while-seeking-common-sense-approach", "prio": 2}, {"code": "ESG", "date": "2026-10-21", "src": "Speedcast", "title": "스피드캐스트·소야IT, 왈레니우스 윌헬름센 로로선 41척에 스타링크·원웹 듀얼 LEO 통신 구축 완료…설치는 전량 원격", "eTitle": "Speedcast and Soya IT Marine Solutions Complete a Dual-LEO Starlink and OneWeb Connectivity Upgrade on 41 Wallenius Wilhelmsen Ro-Ro Vessels, Installed Entirely Remotely", "kSum": "위성통신·IT 서비스사 스피드캐스트(Speedcast)는 10월 21일(미국 휴스턴) 소야IT 마린솔루션즈(Soya IT Marine Solutions)와 함께 왈레니우스 윌헬름센이 운항하는 로로선 41척의 통신 업그레이드를 마쳤다고 발표했다. 글로벌 WAN에 스타링크·유텔샛 원웹(OneWeb) 듀얼 저궤도(LEO) 위성, 이리듐 서티스(Iridium Certus), LTE 백업을 결합했고, 선박이 항구에 몇 시간만 머무는 점을 고려해 설치·커미셔닝을 모두 원격으로 진행했다. 이로써 브리지에서 업무용 소프트웨어에 관리형으로 접속할 수 있고 선원은 휴무 시간에 스트리밍·SNS를 쓸 수 있게 됐다. 소야IT(왈레니우스 라인스·왈레니우스 마린이 속한 스웨덴 소야그룹 계열)는 2월 41척 위성통신 교체 계획을 발표한 바 있다.", "eSum": "Speedcast said on 21 October (Houston) that it and Soya IT Marine Solutions have completed a connectivity upgrade on 41 ro-ro vessels operated by Wallenius Wilhelmsen. The package combines a global WAN, Starlink and Eutelsat OneWeb dual-LEO service, Iridium Certus and LTE backup, and was installed and commissioned entirely remotely because the ships spend only a few hours in port at a time. Bridges now have managed access to enterprise software and crews can use streaming and social media off duty. Soya IT, part of the Swedish Soya Group whose companies include Wallenius Lines and Wallenius Marine, announced the 41-ship satcom plan in February.", "kImp": "선단 상시 고대역폭 연결은 원격 기술지원·디지털 보고·선원 복지를 높이지만 선내 IT/OT 노출도 키우므로, 관리선 전반의 사이버 위험관리(IMO MSC-FAL.1/Circ.3)와 계정·방화벽 관리 절차를 함께 점검해야 한다.", "eImp": "Always-on high-bandwidth links improve remote technical support, digital reporting and crew welfare but widen the onboard IT/OT attack surface, so cyber risk management under IMO MSC-FAL.1/Circ.3, account control and firewall procedures should be reviewed across managed ships.", "url": "https://www.speedcast.com/newsroom/press-releases/2026/soya-it-marine-solutions-selects-speedcast-to-deliver-connectivity-services-supporting-fleetwide-digital-enablement-project-for-wallenius-wilhelmsen/", "prio": 2}, {"code": "ESG", "date": "2026-09-16", "src": "환경미디어", "title": "태백 청정메탄올 플랜트, 한국종합기술과 EPC 협약…EUKOR·WW 등 수요처 확보 후 연내 착공 절차 돌입 계획", "eTitle": "Taebaek Clean Methanol Project Company ECO Methanol Signs an EPC MOU With Korea Engineering Consultants for Its 15,000-Tonne Plant, Whose Offtake Partners Include EUKOR and Wallenius Wilhelmsen", "kSum": "태백 청정메탄올 사업 특수목적법인(SPC) 에코메탄올이 9월 16일 한국종합기술과 기본·상세설계, 주요 기자재 구매·조달, 시공, 책임 시운전까지 포함하는 EPC 업무협약을 체결했다. 플랜트는 태백 동점산업단지에서 미활용 폐바이오매스를 가스화해 연간 약 1만5,000톤의 고순도 메탄올을 생산하며, 에코메탄올은 8월 유코카캐리어스·발레니우스 빌헬름센·현대코퍼레이션·태백시와 공급·물류 다자간 협약을 맺어 수요처를 먼저 확보했다. 회사는 설계와 본계약을 서둘러 연내 착공 절차에 들어갈 계획이지만, 이번 발표에서 구체적 투자 규모·착공일·공사 기간·원료 확보량은 공개하지 않았다.", "eSum": "On 16 September ECO Methanol, the special purpose company behind the Taebaek clean methanol project, signed an EPC MOU with Korea Engineering Consultants covering basic and detailed design, procurement of major equipment, construction and commissioning. The plant at Taebaek's Dongjeom industrial complex will gasify unused waste biomass into about 15,000 tonnes a year of high-purity methanol, and in August the company signed a multilateral supply and logistics MOU with EUKOR, Wallenius Wilhelmsen, Hyundai Corporation and Taebaek city to secure demand first. It plans to finalise design and the main contract quickly and begin construction procedures within 2026, but did not disclose the investment, start date, construction period or feedstock volumes in this announcement.", "kImp": "EUKOR 메탄올 이중연료선의 국내산 그린메탄올 조달원이 설계·시공 단계로 한 걸음 나아갔다. 착공일과 원료 확보가 아직 확정되지 않아 실제 벙커링 공급 시점은 계속 확인할 필요가 있다.", "eImp": "A domestic green methanol source for EUKOR's methanol dual-fuel ships has moved a step closer to design and construction. With the start date and feedstock still unconfirmed, the timing of actual bunkering supply needs continued tracking.", "url": "https://www.ecomedia.co.kr/news/newsview.php?ncode=1065589260850992", "prio": 1}, {"code": "ESG", "date": "2026-09-11", "src": "Maritime Executive", "title": "오션버드 CEO 인터뷰: 티라나 첫 윙세일 '순조로운 인도'…2027년 말까지 약 100척 풍력보조 설치 전망", "eTitle": "Oceanbird CEO Amrit Bhullar Says Tirranna's First Wing Delivery Went Smoothly and About 100 More Ships Will Fit Wind Assistance by End-2027", "kSum": "Wallenius와 Alfa Laval의 합작사 Oceanbird의 Amrit Bhullar CEO는 WalWil PCTC Tirranna에 설치한 첫 강체 윙세일이 순조롭게 인도됐고, 팬·회전부가 없어 정비 부담이 적으며 선원들은 소음이 없다고 전했다고 말했다. 그는 대체연료 진척이 더뎌 2027년 말까지 약 100척이 풍력보조 추진을 설치할 것으로 내다봤다. 다음 윙 2기는 스웨덴 란스크로나에서, 이후 물량은 중국에서 생산하며 PCTC→로로→탱커 순으로 시장을 넓히고 StormGeo·Wallenius Marine과 최적화 도구를 개발 중이다.", "eSum": "Amrit Bhullar, CEO of Oceanbird, the Wallenius and Alfa Laval joint venture, said the first rigid wing delivered to the Wallenius Wilhelmsen PCTC Tirranna went smoothly, needs little maintenance because it has no fans or rotating parts, and is silent according to the crew. She expects about 100 more ships to install wind-assisted propulsion by the end of 2027, partly because alternative fuels are advancing slowly. The next two wings will be built in Landskrona, Sweden, with later orders delivered from China, as Oceanbird targets PCTCs first, then ro-ros and tankers, and develops optimisation tools with StormGeo and Wallenius Marine.", "kImp": "윙세일 상용화가 빨라지면 PCTC 개조 시 공기흘수·시야·갑판 작업 안전 등 운항 절차 변경이 수반되므로, 티라나 실선 데이터 검증 결과를 주시할 필요가 있다.", "eImp": "As wing sails commercialise, PCTC retrofits will bring changes in air draft, bridge visibility and deck-work safety, so the verified Tirranna performance data is worth watching.", "url": "https://maritime-executive.com/article/interview-amrit-bhullar-ceo-of-oceanbird-1", "prio": 1}, {"code": "ESG", "date": "2026-09-02", "src": "Ship & Bunker", "title": "왈레니우스 SOL, B100 바이오연료 사용 확대로 FuelEU 잉여 확보…풀링·이월로 선대 전체 활용", "eTitle": "Wallenius SOL Steps Up B100 Biofuel Use From Terneuzen to Build a FuelEU Maritime Surplus It Can Share Across Its Fleet", "kSum": "스웨덴 해운사 왈레니우스 SOL(Wallenius SOL)은 9월 1일 링크드인을 통해 선박 1척을 고급 FAME 기반 B100 바이오연료로 전환했고 이를 B클래스 선박으로 넓히고 있으며, 네덜란드 테르뇌전(Terneuzen)에서 정기적으로 바이오연료를 공급받고 있다고 밝혔다(Ship & Bunker 9월 2일 보도). B100은 선내 사용 에너지의 Well-to-Wake 온실가스 집약도를 낮춰 FuelEU Maritime 잉여(surplus)를 만들고, 이 잉여는 풀링·뱅킹·차입 등 유연성 장치로 선대 전체에서 활용할 수 있다. 왈레니우스 SOL은 로로선·콘로선·피더선 등 9척을 운항한다.", "eSum": "Swedish carrier Wallenius SOL said in a LinkedIn post on 1 September that it has switched one vessel to advanced FAME-based B100 and is extending the approach to its B-Class ships, backed by regular biofuel deliveries at Terneuzen in the Netherlands, Ship & Bunker reported on 2 September. B100 cuts the well-to-wake greenhouse gas intensity of the energy used on board, generating a FuelEU Maritime compliance surplus that can be used across the wider fleet through pooling, banking and borrowing. The company runs nine ships, including ro-ro, con-ro and feeder vessels.", "kImp": "B100 같은 고농도 바이오연료는 저장 안정성·미생물·필터 막힘·저온 유동성 관리가 필요하므로, 관리선에 도입할 때는 엔진 제조사 승인, 연료 시험·저장 절차와 FuelEU 증빙(지속가능성 증명·BDN) 관리를 함께 준비해야 한다.", "eImp": "High-blend biofuels such as B100 need management of storage stability, microbial growth, filter clogging and cold-flow behaviour, so introducing them on managed ships requires engine-maker approval, fuel testing and storage procedures and proper FuelEU evidence such as proofs of sustainability and BDNs.", "url": "https://shipandbunker.com/news/emea/836504-wallenius-sol-to-step-up-biofuel-use-for-fueleu-compliance", "prio": 1}, {"code": "ESG", "date": "2026-08-23", "src": "Maritime Executive", "title": "글로벌 로로 커뮤니티(GRC), 온실가스 데이터 거버넌스 기구 'GRC Council' 출범", "eTitle": "Global Ro-Ro Community Establishes the GRC Council to Govern GHG Emissions Data for Ro-Ro Shipping", "kSum": "2024년 설립된 글로벌 로로 커뮤니티(GRC)가 GRC 방법론과 데이터 처리 규칙을 지속 검토·개선하는 자율 거버넌스 기구 GRC Council(GRCC)을 출범시켰다. GRC 참여사는 세계 자동차선 선복의 약 80%를 차지하며, ClassNK가 독립 검증기관으로 거버넌스 프레임워크 개발을 지원했고 ClassNK의 Hiroshi Ochi가 부의장에 선출됐다. FuelEU Maritime, IMO 온실가스 규제, 기업 Scope 3 공시 요구가 배경이며, WalWil은 2025년 5월 자사 발표 기준 GRC 회원사다.", "eSum": "The Global Ro-Ro Community (GRC), founded in 2024, has set up the GRC Council (GRCC), a self-governing body that will keep reviewing and improving the GRC Methodology and data handling rules. GRC participants cover about 80% of global car carrier capacity; ClassNK, an independent verifier, helped develop the governance framework, and ClassNK's Hiroshi Ochi was elected vice-chair. FuelEU Maritime, IMO GHG measures and corporate Scope 3 disclosure are the drivers, and Wallenius Wilhelmsen is a GRC member according to its May 2025 release.", "kImp": "완성차 화주의 Scope 3 보고에 쓰이는 로로선 배출 산정 방식이 업계 표준으로 굳어지는 것으로, 선박 연료·운항 데이터의 정확성과 검증 가능성 관리가 더 중요해진다.", "eImp": "Emissions accounting for Ro-Ro ships used in carmakers' Scope 3 reporting is being standardised, making accurate and verifiable fuel and voyage data from ships more important.", "url": "https://maritime-executive.com/corporate/international-governance-body-established-to-support-the-use-of-ghg-emissions-data-in-the-ro-ro-shipping-industry", "prio": 1}, {"code": "ESG", "date": "2026-07-31", "src": "Ship & Bunker", "title": "실버스트림 공기윤활시스템 설치 164척 돌파…왈레니우스 윌헬름센 셰이퍼급 1번선 '아틱 턴'에도 탑재", "eTitle": "Silverstream's Air Lubrication Fleet Passes 160 Installations to Reach 164 Vessels, Including Wallenius Wilhelmsen's First Shaper Class Ship Arctic Tern", "kSum": "공기윤활 시스템 업체 실버스트림 테크놀로지스(Silverstream Technologies)는 최근 그리말디의 '그란데 오리엔테'와 왈레니우스 윌헬름센의 '아틱 턴' 인도로 운항 중인 설치 선박이 164척이 돼 160척을 넘었다고 7월 30일 밝혔다(Ship & Bunker 7월 31일 보도). 이 시스템은 선체 하부에 공기 거품층을 만들어 마찰저항을 줄여 연료 소모와 배출을 낮추며, 크루즈선·컨테이너선·LNG선·로로선·로팩스·PCTC로 채택이 넓어졌다. 노아 실버슈미트(Noah Silberschmidt) CEO는 연료비 상승에 대한 헤지로 연료 소모를 즉시 줄이는 해법을 찾는 선주가 늘고 있다고 말했다.", "eSum": "Silverstream Technologies said in an emailed update on 30 July that deliveries of Grimaldi's Grande Oriente and Wallenius Wilhelmsen's Arctic Tern had taken its air lubrication system past 160 installations to 164 vessels in service, Ship & Bunker reported on 31 July. The system lays a carpet of air bubbles under the hull to cut frictional resistance, fuel use and emissions, and is now used on cruise ships, container ships, LNG carriers, ro-ro and ro-pax vessels and PCTCs. CEO and founder Noah Silberschmidt said owners increasingly want solutions that cut fuel consumption immediately as a hedge against rising fuel costs.", "kImp": "셰이퍼급 1번선에 공기윤활 시스템이 설치된 만큼, 공기 압축기·공기 방출 유닛 정비 계획과 선체·도장 상태 관리, 성능 모니터링 기준을 인수 단계부터 마련해야 실제 연료 절감 효과를 확인할 수 있다.", "eImp": "With air lubrication fitted on the first Shaper Class ship, maintenance plans for compressors and air release units, hull and coating care and performance-monitoring baselines should be set from delivery to verify actual fuel savings.", "url": "https://shipandbunker.com/news/world/649168-silverstream-fuel-saving-air-lubrication-system-surpasses-160-vessel-installations", "prio": 1}, {"code": "ESG", "date": "2026-03-11", "src": "Wallenius Wilhelmsen", "title": "WalWil, 에퀴노르와 2년 바이오메탄올 공급계약…앤트워프·제브뤼헤에서 공급", "eTitle": "Wallenius Wilhelmsen Signs a Two-Year Bio-Methanol Supply Deal With Equinor for Deliveries in Antwerp and Zeebrugge", "kSum": "WalWil은 노르웨이산 매스밸런스 바이오메탄올을 벨기에 앤트워프·제브뤼헤에서 자사 선박에 공급받는 2년 계약을 Equinor와 체결했다. 연료는 ISCC EU 인증을 받았고 회사는 CO2 배출을 95% 줄인다고 밝혔으며, 2027년부터 일부 고객 대상 넷제로 엔드투엔드 시범 서비스와 연계된다. 물량은 '상당한 규모'라고만 공개됐다.", "eSum": "Wallenius Wilhelmsen signed a two-year contract with Equinor for mass-balanced bio-methanol produced in Norway, delivered to its ships in Antwerp and Zeebrugge in Belgium. The fuel is ISCC EU certified and said to cut CO2 emissions by 95%, and the deal is linked to a net-zero end-to-end pilot service for some customers from 2027. Volumes were described only as significant.", "kImp": "그룹 메탄올 추진선의 유럽 측 연료 거점이 확보돼, 앤트워프·제브뤼헤에서의 메탄올 벙커링 절차와 공급자 서류(BDN·지속가능성 증명) 관리 체계가 필요하다.", "eImp": "A European bunkering point is now secured for the group's methanol-capable ships, so methanol bunkering procedures and supplier documentation (BDNs and sustainability certificates) in Antwerp and Zeebrugge need to be in place.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-signs-two-year-fuel-agreement-with-equinor-for-supply-of-bio-methanol", "prio": 2}]}, {"code": "LOG", "kTitle": "물류·터미널", "eTitle": "Logistics & Terminals", "items": [{"code": "LOG", "date": "2026-11-26", "src": "HANSA", "title": "월레니우스 윌헬름센 평택국제로로터미널(PIRT), 1,000만 번째 차량 처리 — 전기차 중심 '아시아 자동차 허브' 확대 구상", "eTitle": "Wallenius Wilhelmsen's Pyeongtaek International RoRo Terminal Handles Its Ten-Millionth Vehicle - Plans to Grow as an Asian Auto Hub Focused on EVs", "kSum": "월레니우스 윌헬름센이 운영하는 평택국제로로터미널(PIRT)이 1,000만 번째 차량을 처리했으며, 이를 계기로 지난주 동아시아 자동차 물류에서의 위상을 키우기 위한 중장기 계획을 공개했다고 HANSA가 11월 26일 전했다. 특히 성장하는 전기차 시장에 초점을 맞춘다.", "eSum": "Wallenius Wilhelmsen's Pyeongtaek International RoRo Terminal (PIRT) marked its ten-millionth vehicle last week and outlined medium-to-long-term plans to expand its role in East Asian automotive logistics, focusing on the growing EV market, HANSA reported on 26 November.", "kImp": "평택 전기차 물량이 계속 늘어난다. 평택 기항선은 전기차 화재 대응 장비·절차(데크 순찰, 소화 담요, 격리 구역)를 수시 점검할 것.", "eImp": "EV volumes at Pyeongtaek keep growing. Ships calling there should regularly check EV fire-response equipment and procedures (deck patrols, fire blankets, isolation areas).", "url": "https://hansa-online.de/haefen/wallenius-wilhelmsen-will-pyeongtaek-zum-asiatischen-autohub-ausbauen/313212", "prio": 3}, {"code": "LOG", "date": "2026-11-24", "src": "gCaptain(The Loadstar)", "title": "머스크·ONE, 첫 '남북항로 글로벌 얼라이언스' 결성 추진 — 동서항로 제미니와 별개로 남미·아프리카 항로 협력", "eTitle": "Maersk and ONE Eye a Landmark Global North-South Alliance - Container Shipping's First Liner Alliance Covering North-South Trades", "kSum": "컨테이너 업계 첫 남북항로 글로벌 얼라이언스가 머스크와 ONE을 중심으로 모양을 갖추고 있다고 The Loadstar가 전했다. 선사들은 그동안 남북항로를 항로별 개별 협력으로 다뤄 왔다. 머스크의 자연스러운 상대는 제미니 파트너 하팍로이드지만, CSAV가 하팍로이드 지분 30%를 갖고 있어 남미 서안 네트워크를 합치면 같은 칠레·페루 화주를 두 기존 강자가 함께 맡게 되는 문제가 있어 ONE이 거론된다고 분석했다.", "eSum": "Container shipping's first global liner alliance covering north-south trades appears to be taking shape around Maersk and ONE, The Loadstar reported. Lines have treated north-south trades as separate arrangements; Hapag-Lloyd, Maersk's Gemini partner, is ruled out partly because CSAV owns 30% of it, so combining West Coast South America networks would join two incumbents serving the same Chilean and Peruvian exporters.", "kImp": "얼라이언스 재편은 기항 패턴·항만 체류 시간을 바꾼다. 남미 서안·아프리카 항로 자동차선·벌크선은 컨테이너 터미널 혼잡 변화가 선석 대기에 미치는 영향을 대리점 보고로 확인할 것.", "eImp": "Alliance changes alter port rotations and berth times. Car carriers and bulkers on West Coast South America and African trades should watch, via agents, how container terminal congestion affects berth waiting.", "url": "https://gcaptain.com/maersk-and-one-eye-landmark-global-north-south-shipping-alliance/", "prio": 2}, {"code": "LOG", "date": "2026-11-20", "src": "gCaptain", "title": "LA·롱비치 항만 보안 인력 파업 시한 임박 — 110여 단체 타결 촉구, 해당 터미널은 롱비치 화물 85%·LA 33% 처리", "eTitle": "More Than 110 Trade Groups Urge a Deal as the LA-Long Beach Port Strike Deadline Nears - the Terminals Handle 85% of Long Beach and 33% of Los Angeles Cargo", "kSum": "태평양해사협회(PMA)와 국제항만창고노조(ILWU) 26지부 사이의 협상이 타결되지 않으면서 약 250명의 항만 보안 인력 파업 시한(토요일 0시 1분)이 다가오자, 110개가 넘는 무역 단체가 조속한 타결을 촉구했다. 영향을 받는 터미널은 롱비치 화물의 85%, 로스앤젤레스 화물의 33%를 처리한다.", "eSum": "With no agreement between the Pacific Maritime Association and ILWU Local 26, which represents about 250 port security workers, and a strike deadline of 12:01 a.m. on Saturday, more than 110 trade groups urged a deal. The affected terminals handle 85% of Long Beach cargo and 33% of Los Angeles cargo.", "kImp": "파업 여부에 따라 기항 일정이 바뀔 수 있다. 미 서안 기항 예정선은 대리점을 통해 터미널 운영 상황을 매일 확인하고, 대기 정박에 대비한 보급·선원 교대 계획을 조정할 것.", "eImp": "Port schedules may change depending on the outcome. Ships due on the US West Coast should check terminal status daily through agents and adjust supply and crew-change plans for possible waiting time.", "url": "https://gcaptain.com/more-than-110-trade-groups-urge-deal-as-la-long-beach-port-strike-deadline-nears/", "prio": 2}, {"code": "LOG", "date": "2026-11-19", "src": "The Maritime Executive", "title": "파나마 감사원장, 항만 운영권 연장 관련 형사 고발 — 2021년 25년 연장 과정의 '부정'을 문제 삼아 해사청 전 이사진과 CK허치슨 자회사 겨냥", "eTitle": "Panama's Comptroller General Files a Criminal Complaint Over the Port Concession - Targeting Former Maritime Authority Board Members and CK Hutchison's Subsidiary Over 'Irregularities' in the 2021 Extension for 25 Years", "kSum": "파나마 감사원장이 발보아·크리스토발 항만 운영권과 관련해 검찰에 형사 고발장을 냈다. 대상은 2014~2023년 파나마 해사청 이사진과 청장들, 그리고 약 30년 동안 운영권을 쥐어 온 CK허치슨 자회사 Panama Ports Company다. 감사는 1997년부터 이어진 계약 가운데 2014~2024년 10년을 살폈고, 고발의 중심은 2021년 운영권을 25년 더 늘린 결정이다. 파나마 법원은 올해 초 이 운영권을 무효로 했고 두 터미널의 운영은 머스크 계열 APM 터미널과 MSC 계열 TiL에 맡겨졌다.", "eSum": "Panama's Comptroller General has filed a criminal complaint with the Public Prosecutor's Office over the Balboa and Cristobal port concession. It targets Panama Maritime Authority board members from 2014 to 2023, the authority's general administrators and Panama Ports Company, the CK Hutchison subsidiary that held the concession for nearly 30 years. The audit covered ten years, 2014-2024, of a contract dating to 1997, and the complaint centres on the 2021 decision to extend it for a further 25 years. Panama's courts annulled the concession earlier this year, and operations at the two terminals were assigned to Maersk's APM Terminals and MSC's TiL.", "kImp": "운하 양 끝 터미널의 운영 주체와 법적 분쟁이 계속 바뀐다. 선박관리사는 파나마 기항선의 대리점·터미널 연락처와 요율 변경을 확인하고, 분쟁이 선박 억류나 기국 업무 지연으로 번지는지 지켜볼 것.", "eImp": "The operators of the terminals at both ends of the canal and the legal disputes around them keep changing. Managers should confirm agent and terminal contacts and tariff changes for Panama calls and watch whether the dispute spills into ship arrests or delays in flag state services.", "url": "https://maritime-executive.com/article/panama-cites-irregularities-in-criminal-complaint-over-port-concession", "prio": 2}, {"code": "LOG", "date": "2026-11-18", "src": "Ocean Press Korea(Linerlytica)", "title": "컨테이너선 용선료 강세 지속 — 5,600 TEU급 하루 6만 6,000달러(전년 대비 약 10%↑), 전 선형 7~23% 상승, 1,700 TEU 피더선은 3만 2,000달러", "eTitle": "Container Ship Charter Rates Stay Firm - USD 66,000 a Day for 5,600 TEU Ships (Up About 10% on the Year), All Sizes Up 7-23% and 1,700 TEU Feeders at USD 32,000", "kSum": "해운 분석업체 라이너리티카에 따르면 컨테이너선 용선시장 강세가 이어지고 있다. CMA CGM은 5,610 TEU급 선박을 3년 6개월 동안 장기 용선했고, 같은 급 용선료는 하루 6만 6,000달러로 지난해보다 10%쯤 올랐다. 모든 선형의 용선료가 7~23% 상승했으며 1,700 TEU급 피더선은 하루 3만 2,000달러다. MSC는 5,550 TEU급 선박을 사들여 선복량을 746만 TEU로 늘렸다. 대형 선사들이 운임 고점을 겪은 뒤에도 선대 확장 기조를 이어 가고 있다는 설명이다.", "eSum": "Linerlytica reports continuing strength in the container ship charter market. CMA CGM has taken a 5,610 TEU ship for three and a half years, with ships of that size at USD 66,000 a day, about 10% higher than a year ago. Charter rates are up 7-23% across all sizes and 1,700 TEU feeders fetch USD 32,000 a day. MSC bought a 5,550 TEU ship, taking its fleet to 7.46 million TEU. The largest carriers are still expanding even after the rate peak.", "kImp": "용선 기간이 3년 넘게 길어지면 그 사이 입거·개조 일정을 넣기 어렵다. 선박관리사는 장기 용선 선박의 정기검사와 에너지 절감 개조 시기를 용선 계약 협상 단계에서 선주에게 미리 제시할 것.", "eImp": "When charters run beyond three years it becomes hard to fit in drydockings and retrofits. Managers should put special survey and energy-saving retrofit windows to owners while the charter is still being negotiated.", "url": "https://www.oceanpress.co.kr/news/article.html?no=31814", "prio": 2}, {"code": "LOG", "date": "2026-11-15", "src": "gCaptain(Bloomberg)", "title": "LA·롱비치항 10월 수입 컨테이너 100만 500 TEU — 9월 사상 최대에 근접, 물동량 LA +20% 이상·롱비치 +11%. 1월 미·중 휴전 만료 전 선적 앞당기기", "eTitle": "Los Angeles and Long Beach Import 1,000,500 TEU in October, Just Below September's Record - Volumes Up Over 20% at LA and 11% at Long Beach as Importers Front-Load Before a US-China Truce Expires in January", "kSum": "미국 최대 무역 관문인 로스앤젤레스·롱비치항의 10월 수입 컨테이너가 합계 100만 500 TEU로 9월의 사상 최대치 바로 아래였다. 적·공 컨테이너를 합친 처리량은 지난해 같은 달보다 LA가 20% 이상, 롱비치가 11% 늘었다. 무역 정책 변화, 유통업체 재고 보충, 소비 지출, 인공지능 관련 화물이 요인으로 꼽혔다. 수입업체들은 1월에 끝나는 미·중 무역 휴전 전에 선적을 앞당기고 있다. 롱비치항은 2027년 초까지 바쁠 것으로 보지만 전미소매협회(NRF)는 1월 수입이 전년보다 3% 줄 것으로 전망했다.", "eSum": "Combined imports at Los Angeles and Long Beach reached 1,000,500 TEU in October, just below September's record. Total loaded and empty volumes rose more than 20% year on year at Los Angeles and 11% at Long Beach, driven by trade-policy shifts, retailer restocking, consumer spending and AI-related cargo, with importers front-loading before a US-China trade truce expires in January. Long Beach expects busy conditions into early 2027, though the National Retail Federation forecasts January imports down 3% on the year.", "kImp": "미 서안 혼잡은 정박 대기와 선원 교대 지연으로 이어진다. 선박관리사는 LA·롱비치 기항선의 대기 일수, 대기 중 배출 규제(정박 중 육전·저속 구역) 준수, 교대 일정 여유를 점검할 것.", "eImp": "West Coast congestion turns into anchorage time and delayed crew changes. Managers should check waiting days for Los Angeles and Long Beach calls, compliance with at-berth and speed-zone emission rules while waiting, and slack in crew-change plans.", "url": "https://gcaptain.com/imported-goods-keep-surging-through-southern-california-ports/", "prio": 2}, {"code": "LOG", "date": "2026-11-14", "src": "gCaptain(Bloomberg)", "title": "남아공 자동차 산업, 더반항 적체로 타격 — 선박 대기시간 1월 이후 약 2배, 부품사 Metair '적체 20일 육박' 경고 뒤 하루 만에 시가총액 절반 가까이 증발", "eTitle": "South Africa's Auto Industry Hit by Worsening Durban Port Delays - Vessel Waiting Times Have Roughly Doubled Since January and Supplier Metair Lost Nearly Half Its Value in a Day After Warning of Backlogs Near 20 Days", "kSum": "남아공 최대 컨테이너 터미널인 더반 게이트웨이 터미널의 선박 대기시간이 민간 운영사가 넘겨받은 1월 이후 약 2배로 늘었다고 교통부 장관이 밝혔다. 폭스바겐·포드·토요타에 납품하는 부품사 Metair는 항만 적체가 20일에 가깝다고 경고했고 주가는 하루에 절반 가까이 떨어졌다. 운영사는 필리핀 ICTSI의 새 운영 시스템 도입이 원인이었으며 지금은 안정됐다고 설명한다. 자동차부품제조협회(NAACAM)는 적체와 지연의 영향이 완성차 생산 가치사슬 전반에 퍼져 있다고 했다. 남아공 자동차 산업은 값싼 아시아산 수입차와 미국 관세 부담도 함께 안고 있다. Splash247도 더반 컨테이너 지연이 20일에 가깝다고 전했다.", "eSum": "Vessel waiting times at Durban Gateway Terminal, South Africa's largest container terminal, have roughly doubled since a private operator took over in January, the transport minister said. Metair, a supplier to Volkswagen, Ford and Toyota, warned of backlogs approaching 20 days and lost nearly half its market value in a day. The operator blames a new operating system from Manila-based ICTSI and says it has since stabilised. Components association NAACAM says congestion is affecting the whole automotive manufacturing chain; the sector also faces cheap Asian imports and US tariffs. Splash247 also reports Durban container delays near 20 days.", "kImp": "부품 컨테이너가 늦으면 완성차 생산과 수출 선적 일정이 함께 밀린다. 더반 기항 자동차선을 관리하는 회사는 선적 물량·ETB 변동을 대리점과 매일 확인하고, 대기 중 묘박지 안전(주묘·보안)과 연료·청수 여유를 점검할 것.", "eImp": "Late component boxes push back both vehicle production and export loading. Managers of car carriers calling Durban should confirm cargo readiness and ETB daily with agents and check anchorage safety (dragging, security) and fuel and fresh-water margins while waiting.", "url": "https://gcaptain.com/south-africas-auto-industry-threatened-by-worsening-port-delays/", "prio": 3}, {"code": "LOG", "date": "2026-11-12", "src": "gCaptain", "title": "LA항 10월 102만6,872 TEU로 월간 기록 — 수입 +25%, 워치맨 노조 협상 11월 20일까지 연장, 철도 화물 9일 이상 지연", "eTitle": "Port of Los Angeles Handles a Record 1,026,872 TEU in October - Imports Up 25%, Watchmen Talks Extended to 20 November, Rail Cargo Waiting Nine Days or More", "kSum": "로스앤젤레스항의 10월 처리량은 102만6,872 TEU로 10월 기준 최고이자 역대 두 번째로 많았다. 적재 수입은 53만8,620 TEU(+25%), 적재 수출은 11만4,981 TEU(−7%), 공컨테이너는 사상 최대인 37만3,271 TEU였다. 1~10월 누적은 910만8,497 TEU로 전년보다 5% 많다. PMA와 ILWU 로컬 26(해상 경비원 약 250명)은 협상을 11월 20일까지 연장했고, 로컬 13·63은 피켓 라인을 존중하겠다고 밝혔다. 철도 연계 수입 화물은 LA 약 9,500개, 롱비치 5,063개가 9일 이상 대기 중이다.", "eSum": "The Port of Los Angeles handled a record October volume of 1,026,872 TEU, its second-busiest month ever: loaded imports 538,620 TEU (+25%), loaded exports 114,981 TEU (-7%) and a record 373,271 empty TEU. January-October volume of 9,108,497 TEU is 5% above last year. The PMA and ILWU Local 26 (about 250 maritime watchmen) extended talks to 20 November, with Locals 13 and 63 saying they would honour picket lines. About 9,500 rail-bound imports at Los Angeles and 5,063 at Long Beach have waited nine days or more.", "kImp": "LA·롱비치 워치맨 노조 협상이 11월 20일까지 연장됐다. 미 서안 자동차 터미널(포트휴니미·롱비치·샌디에이고 등) 기항선은 파업 시 대기·항만 변경 가능성을 염두에 둘 것.", "eImp": "Watchmen talks at Los Angeles and Long Beach are extended to 20 November. Ships calling US West Coast car terminals should allow for waiting or port changes if a stoppage follows.", "url": "https://gcaptain.com/port-of-los-angeles-sets-october-cargo-record-as-strike-threat-and-rail-delays-loom/", "prio": 2}, {"code": "LOG", "date": "2026-11-10", "src": "gCaptain", "title": "미 브런즈윅항 자동차 처리능력 확충 — 4번째 RoRo 선석 2027년 12월 개장(10,800 CEU 초과 선박 수용), 10월 한 달 50척 처리", "eTitle": "Port of Brunswick Expands Auto Capacity - a Fourth Ro-Ro Berth Opens in December 2027 for Carriers Above 10,800 CEU, After 50 Vessel Calls in October Alone", "kSum": "조지아항만공사(GPA)가 브런즈윅 Colonel's Island의 RoRo 선석 3개에서 10월 한 달에만 50척을 처리했다. 공정 60%인 4번째 RoRo 선석은 2027년 12월 개장 예정으로 10,800 CEU를 넘는 자동차선을 받을 수 있다. 향후 10년간 약 50억 달러 규모 인프라 계획의 일부이며, 현대차 메타플랜트(2031년까지 8,500명), 리비안(50억 달러), 아우디 첫 미국 공장(40억 달러) 등 조지아 내 완성차 투자가 물량을 끌어올리고 있다.", "eSum": "The Georgia Ports Authority handled 50 vessels in October alone at Brunswick's three ro-ro berths on Colonel's Island. A fourth ro-ro berth, 60% complete, is due to open in December 2027 and will take carriers of more than 10,800 CEU, as part of a nearly USD 5bn infrastructure plan over the next decade. Volumes are driven by carmaker investment in Georgia, including Hyundai's Metaplant (8,500 jobs by 2031), Rivian (USD 5bn) and Audi's first US plant (USD 4bn).", "kImp": "브런즈윅 기항 빈도와 대형선 투입이 늘 전망이다. 기항 선박은 신규 선석의 램프 허용하중·안벽 높이·계류 배치를 포트 어세스먼트에 반영하고, USCG 검사 대비 상태를 유지할 것.", "eImp": "Expect more frequent calls and larger ships at Brunswick. Update port assessments for ramp loads, quay height and mooring layout at the new berth, and stay ready for USCG examinations.", "url": "https://gcaptain.com/port-of-brunswick-expands-auto-shipping-capacity-as-georgia-manufacturing-booms/", "prio": 2}, {"code": "LOG", "date": "2026-10-09", "src": "Port Technology International", "title": "ENGIE, 제브뤼헤에 풍력터빈 8기(42.6MW) 착공…WalWil 로로터미널에 3기", "eTitle": "ENGIE Starts Work on Eight Wind Turbines (42.6 MW) at Zeebrugge, Three of Them at Wallenius Wilhelmsen's RoRo Terminal", "kSum": "ENGIE가 2026년 10월 제브뤼헤에서 풍력터빈 8기(총 42.6MW) 공사를 시작하며 이 중 3기는 Wallenius Wilhelmsen 로로터미널, 5기는 ICO 부지에 들어선다. 터빈 설치는 2027년 하반기, 발전은 2028년 초 시작돼 연간 약 115GWh(약 3만3천 가구 사용량)를 생산할 예정이다. ENGIE·앤트워프-브뤼헤항·Portfineco가 공동 출자하고 합작사 Seagull I이 운영한다.", "eSum": "ENGIE is starting work in October 2026 on eight wind turbines totalling 42.6 MW at Zeebrugge, three at the Wallenius Wilhelmsen RoRo terminal and five at International Car Operators (ICO). Installation begins in the second half of 2027, with generation from early 2028 and output of about 115 GWh a year, roughly the use of 33,000 households. ENGIE, Port of Antwerp-Bruges and Portfineco are financing the project jointly, and the Seagull I joint venture will operate the turbines.", "kImp": "제브뤼헤 터미널의 재생전력 확보는 그룹의 터미널 탈탄소·넷제로 엔드투엔드 서비스 목표에 기여한다. 향후 육전 설비가 확대되면 기항선의 육전 연결 준비가 필요해질 수 있다.", "eImp": "Renewable power at the Zeebrugge terminal supports the group's terminal decarbonisation and net-zero end-to-end service goals. If shore power is expanded there, calling ships will need to be ready for shore connection.", "url": "https://www.porttechnology.org/news/sustainability-and-decarbonisation/engie-expands-wind-power-capacity-at-port-of-zeebrugge/", "prio": 1}, {"code": "LOG", "date": "2026-10-02", "src": "DAFF (Australia)", "title": "호주 DAFF, BMSB 시즌 중 Wallenius Wilhelmsen Logistics NV 검역처리업체 '정지'…WW '제브뤼헤 열처리 한정'", "eTitle": "Australia's DAFF Suspends Wallenius Wilhelmsen Logistics NV as an Offshore Treatment Provider; WW Says Only Zeebrugge Heat Treatment Is Affected", "kSum": "호주 농림수산부(DAFF)는 산업공지 169-2026(10월 2일)에서 '중대한 부적합' 확인을 이유로 Wallenius Wilhelmsen Logistics NV(AEI: BE4005SB)를 처리업체 목록에서 '정지'로 지정했다. 정지일부터는 정지 이전 발급분을 포함해 해당 업체의 처리증명서를 인정하지 않으며, 운송 중인 화물도 호주 도착 시 생물보안 조치를 받을 수 있다. Daily Cargo News(10/7)에 따르면 WW는 정지가 벨기에 제브뤼헤 시설의 열처리 서비스에만 적용되고 다른 서비스는 계속 이용 가능하다고 해명했다.", "eSum": "In Industry Advice Notice 169-2026 of 2 October, Australia's Department of Agriculture, Fisheries and Forestry (DAFF) listed Wallenius Wilhelmsen Logistics NV (AEI: BE4005SB) as suspended on its list of treatment providers after identifying critical non-compliance. From the suspension date DAFF will not accept its treatment certificates, including those issued before the change, and consignments in transit may be directed for biosecurity action on arrival. According to Daily Cargo News on 7 October, WW said the suspension applies only to heat-treatment services at its Zeebrugge facility in Belgium and other services remain available.", "kImp": "BMSB 시즌(9월~4월) 유럽발 호주행 차량·기계 화물의 처리증명서가 거부되면 도착 후 재처리·지시 조치로 하역 지연과 체선이 생길 수 있다. 호주 기항선은 적재 화물의 처리증명 유효성 확인과 DAFF 지시 대응 절차를 사전 점검할 필요가 있다.", "eImp": "If treatment certificates for Europe-origin vehicles and machinery are rejected during the BMSB season, on-arrival directions or re-treatment can delay discharge and extend port stays. Ships calling Australia should pre-check certificate validity for their cargo and rehearse DAFF direction procedures.", "url": "https://www.agriculture.gov.au/biosecurity-trade/import/industry-advice/2026/169-2026", "prio": 2}, {"code": "LOG", "date": "2026-10-01", "src": "Flows", "title": "왈레니우스 윌헬름센, 제브뤼헤 '오르셀 터미널' 3단계(최종) 확장 인허가 신청…스헬더 터널 공사 도크 정리에 맞춰 전체 49헥타르로", "eTitle": "Wallenius Wilhelmsen Applies for a Permit to Complete the Third and Final Phase of Its Orcelle Terminal in Zeebrugge, Taking It to the Full 49 Hectares as the Scheldt Tunnel Construction Dock Is Cleared", "kSum": "벨기에 물류 전문지 Flows는 10월 1일 왈레니우스 윌헬름센이 제브뤼헤에서 오스터벨 연결도로(Oosterweelverbinding)의 스헬더 터널(Scheldetunnel) 공사용 도크가 정리되는 데 맞춰 오르셀 터미널(Orcelle Terminal) 완공을 계획하고 있다고 보도했다. 회사는 세 번째이자 마지막 확장 단계를 진행해 터미널을 전체 49헥타르로 넓히기 위한 인허가를 신청한다.", "eSum": "Belgian logistics outlet Flows reported on 1 October that Wallenius Wilhelmsen plans to complete its Orcelle Terminal in Zeebrugge as the construction dock used for the Scheldt Tunnel of the Oosterweel Link (Oosterweelverbinding) is being cleared. The company is applying for a permit for the third and final phase, which would bring the terminal to its full 49 hectares.", "kImp": "제브뤼헤는 그룹 자동차선의 유럽 핵심 기항지여서 터미널이 49헥타르로 넓어지면 장치장 혼잡과 선석 대기 완화가 기대되지만, 공사 기간에는 터미널 내 동선과 통제구역이 바뀔 수 있으므로 기항 선박의 선박·항만 보안(ISPS) 연계 사항과 하역 안전 절차를 현지 대리점을 통해 확인할 필요가 있다.", "eImp": "Zeebrugge is a key European call for group car carriers, so a terminal expanded to 49 hectares could ease yard congestion and berth waiting, but traffic routes and restricted areas may change during construction, so ship-port security (ISPS) interfaces and cargo-handling safety arrangements should be confirmed through local agents.", "url": "https://www.flows.be/havens/2026/10/wallenius-wilhelmsen-nadert-laatste-fase-terminaluitbreiding-zeebrugge/", "prio": 1}, {"code": "LOG", "date": "2026-08-25", "src": "Shippax", "title": "WalWil 자회사 ARC, 美 수송사령부 '합동 글로벌 해상수송 용선' 계약 수주(2031년까지, 한도 27억 달러)", "eTitle": "ARC Among Three US RoRo Operators Awarded USTRANSCOM's Joint Global Sealift Charter Contract Running to August 2031", "kSum": "미국 수송사령부(USTRANSCOM)가 7개 선사에 합동 글로벌 해상수송 용선(Joint Global Sealift Charter) 계약을 발주했으며, 로로/PCTC 운항사로는 American Roll-On Roll-Off Carrier(ARC), Farrell Lines, Liberty Global Logistics가 포함됐다. 계약 기간은 2026년 9월 1일~2031년 8월 31일, 예상 규모 12억 달러·누적 한도 27억 달러의 IDIQ 고정가 방식으로, 개별 태스크오더를 통해 단기 정기·항해용선이 발주된다. 참여 조건은 VISA 협정에 등록돼 최근 2년 내 국방부 화물을 운송한 로로·다목적·자동차선 보유다.", "eSum": "US Transportation Command (USTRANSCOM) awarded its Joint Global Sealift Charter contract to seven companies, with American Roll-On Roll-Off Carrier (ARC), Farrell Lines and Liberty Global Logistics as the RoRo/PCTC operators. The indefinite-delivery, indefinite-quantity fixed-price contract runs from 1 September 2026 to 31 August 2031, with an estimated face value of USD 1.2bn and a cumulative ceiling of USD 2.7bn, and short-term time and voyage charters are placed through individual task orders. Eligibility requires at least one RoRo, multi-purpose or vehicle carrier enrolled in VISA that has carried Department of War cargo within the past two years.", "kImp": "정부화물 부문(ARC)의 2031년까지 수주 틀이 마련돼, 군수화물 운송에 투입되는 그룹 선박의 보안·위험물 취급 요건 대응이 지속 과제가 된다.", "eImp": "ARC's government-cargo business now has a framework through 2031, so security and dangerous-goods handling requirements for group ships in military service remain an ongoing task.", "url": "https://www.shippax.com/en/news/three-us-based-roro-operators-awarded-new-joint-global-sealift-charter-contracts.aspx", "prio": 2}, {"code": "LOG", "date": "2026-08-21", "src": "ARC (American Roll-On Roll-Off Carrier)", "title": "WW 자회사 ARC, 미 연방재난관리청(FEMA) 재난구호 크로스독·사고지원기지 IDIQ 계약 수주…9월 21일부터 기본 1년+옵션 2년", "eTitle": "WalWil's ARC Group Wins a FEMA IDIQ Contract for National Cross-Dock and Incident Support Base Services, Running One Year From 21 September Plus Two Option Years", "kSum": "왈레니우스 윌헬름센의 미국 정부화물 자회사 ARC(American Roll-On Roll-Off Carrier) 그룹은 8월 21일 미 연방재난관리청(FEMA)으로부터 재난 대응용 전국 크로스독·사고지원기지(ISB) 지원 IDIQ(무한정 납품·수량) 계약(No. 70FB7026D00000002)을 따냈다고 밝혔다. 물·발전기 같은 구호물자를 들어오는 트레일러에서 GPS 추적 차량으로 수시간 안에 옮겨 싣는 크로스독과 빈 트레일러 야드 관리, ISB 운영, 운송·시설·관리·인력 지원이 포함된다. 계약기간은 2026년 9월 21일부터 기본 1년에 1년 옵션 2회이며, 최대 3건의 IDIQ 계약을 주는 복수 낙찰 방식으로 금액은 공개되지 않았다.", "eSum": "ARC Group, Wallenius Wilhelmsen's US government cargo subsidiary American Roll-On/Roll-Off Carrier Group, said on 21 August that FEMA has awarded it an indefinite delivery/indefinite quantity contract (No. 70FB7026D00000002) for national cross-dock and incident support base services in disaster response. The work covers moving relief supplies such as water and generators from inbound trailers onto a GPS-tracked fleet, often within hours, plus empty trailer yard management, incident support base operations and transport, facility, management and personnel support. The contract runs for a one-year base period from 21 September 2026 with two one-year options under a multiple-award vehicle of up to three IDIQ contracts, and its value was not disclosed.", "kImp": "ARC가 해상 로로 수송을 넘어 육상 재난물류로 미국 정부 계약을 넓히고 있어, 그룹 정부화물 부문의 수익 기반이 다변화되는 흐름으로 볼 수 있다.", "eImp": "ARC is extending its US government work from ro-ro sealift into land-side disaster logistics, broadening the earnings base of the group's government services segment.", "url": "https://www.arcshipping.com/news/arc-group-awarded-fema-contract-to-accelerate-disaster-relief-supply-deliveries/", "prio": 1}, {"code": "LOG", "date": "2026-02-02", "src": "Wallenius Wilhelmsen", "title": "WalWil, 예테보리 'GIART' 자동차·로로 터미널 12년 운영 개시…6월 공식 개장", "eTitle": "Wallenius Wilhelmsen Begins Operating the Gothenburg International Auto & RoRo Terminal (GIART) Under a 12-Year Contract", "kSum": "WalWil은 2월 2일 예테보리항의 GIART(Gothenburg International Auto & RoRo Terminal) 12년 운영 계약을 개시했다. 터미널은 선석 2개, 28만8천㎡ 부지, 철도 연결, 출고 전 검사(PDI) 시설과 EV 충전 인프라를 갖췄으며 단계적 고도화로 부가가치 처리 서비스를 늘린다. 6월 8일 공식 개장 행사를 열었고 북유럽·발트 지역 허브로 운영 중이다.", "eSum": "Wallenius Wilhelmsen began official operations at the Gothenburg International Auto & RoRo Terminal (GIART) on 2 February under a 12-year contract with the Port of Gothenburg. The terminal has two quay positions, 288,000 square metres of space, rail connectivity, pre-delivery inspection facilities and EV charging, with phased upgrades planned to expand value-added processing. An opening celebration was held on 8 June, and the terminal serves as a hub for the Nordics and Baltics.", "kImp": "북유럽 핵심 자동차 터미널 운영권을 그룹이 확보해 해상-터미널 연계 운영이 가능해졌으며, 예테보리 기항선의 선석·하역 조정을 그룹 안에서 할 수 있는 이점이 있다.", "eImp": "Securing a key Nordic car terminal enables integrated sea-terminal operations, with berth planning and cargo handling for Gothenburg calls coordinated within the group.", "url": "https://www.walleniuswilhelmsen.com/news/wallenius-wilhelmsen-begins-official-operations-at-the-gothenburg-terminal", "prio": 2}]}]};